    : null;

const detalles =
  Array.isArray(output?.detalles)
    ? output.detalles
    : null;


// ======================================================
// 2. HELPERS
// ======================================================

function texto(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numero(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function normalizarTexto(valor) {
  const t =
    texto(valor);

  if (!t) {
    return '';
  }

  return t
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}


function casiIgual(a, b, tolerancia = 0.01) {
  const na = numero(a);
  const nb = numero(b);

  if (
    na === null ||
    nb === null
  ) {
    return false;
  }

  return Math.abs(na - nb) <= tolerancia;
}


function claveMedida(ancho, alto) {
  const a = numero(ancho);
  const h = numero(alto);

  if (
    a === null ||
    h === null
  ) {
    return null;
  }

  return `${a}x${h}`;
}


// ======================================================
// 3. OBTENER MENSAJE ACTUAL
// ======================================================
//
// Priorizamos Resolver contexto comercial porque es
// precisamente la entrada utilizada por el extractor.
//
// ======================================================

let contexto = {};

try {
  contexto =
    $('Resolver contexto comercial')
      .first()
      .json ?? {};
} catch (_) {
  contexto = {};
}


const mensajeActual =
  texto(
    contexto.mensaje_actual ??
    contexto.turno_texto ??
    null
  ) ?? '';

const mensajeNormalizado =
  normalizarTexto(mensajeActual);


// ======================================================
// 4. EXTRAER MEDIDAS EXPLÍCITAS DEL MENSAJE
// ======================================================
//
// Soporta:
// 8x11
// 8 x 11
// 8 por 11
// 8,5 x 10
// 8 de ancho por 11 de alto
//
// Esto NO pretende entender toda la conversación.
// Solo detectar medidas explícitas para evitar que la IA
// devuelva datos completamente diferentes.
//
// ======================================================

function extraerMedidasExplicitas(textoEntrada) {
  const resultado = [];

  if (!textoEntrada) {
    return resultado;
  }

  const limpio =
    textoEntrada
      .replace(/,/g, '.')
      .toLowerCase();

  // --------------------------------------------------
  // Caso explícito:
  // "11 de alto por 8 de ancho"
  // "8 de ancho por 11 de alto"
  // --------------------------------------------------

  const regexEtiquetado =
    /(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?\s*de\s*(ancho|alto)\s*(?:por|x)\s*(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?\s*de\s*(ancho|alto)/gi;

  let match;

  while (
    (match = regexEtiquetado.exec(limpio)) !== null
  ) {
    const valor1 = Number(match[1]);
    const tipo1 = match[2];
    const valor2 = Number(match[3]);
    const tipo2 = match[4];

    let ancho = null;
    let alto = null;

    if (tipo1 === 'ancho') {
      ancho = valor1;
    }

    if (tipo1 === 'alto') {
      alto = valor1;
    }

    if (tipo2 === 'ancho') {
      ancho = valor2;
    }

    if (tipo2 === 'alto') {
      alto = valor2;
    }

    if (
      Number.isFinite(ancho) &&
      Number.isFinite(alto)
    ) {
      resultado.push({
        ancho_cm: ancho,
        alto_cm: alto
      });
    }
  }

  // --------------------------------------------------
  // Caso común:
  // 8x11
  // 8 x 11
  // 8 por 11
  // --------------------------------------------------

  const regexComun =
    /(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?\s*(?:x|por)\s*(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?/gi;

  while (
    (match = regexComun.exec(limpio)) !== null
  ) {
    const ancho = Number(match[1]);
    const alto = Number(match[2]);

    if (
      !Number.isFinite(ancho) ||
      !Number.isFinite(alto)
    ) {
      continue;
    }

    const yaExiste =
      resultado.some(m =>
        casiIgual(m.ancho_cm, ancho) &&
        casiIgual(m.alto_cm, alto)
      );

    if (!yaExiste) {
      resultado.push({
        ancho_cm: ancho,
        alto_cm: alto
      });
    }
  }

  return resultado;
}


const medidasExplicitas =
  extraerMedidasExplicitas(
    mensajeActual
  );


// ======================================================
// 5. FORMAS PERMITIDAS
// ======================================================

const formasPermitidas = [
  'RECTANGULAR',
  'CUADRADA',
  'CIRCULAR',
  'IRREGULAR',
  'NO_ESPECIFICADA',
  null
];


// ======================================================
// 6. VALIDACIÓN
// ======================================================

let valid = true;
let reason = null;


// ------------------------------------------------------
// 6.1 Debe existir output
// ------------------------------------------------------

if (!output) {
  valid = false;

  reason =
    'La IA no devolvió un objeto output válido.';
}


// ------------------------------------------------------
// 6.2 Debe existir detalles[]
// ------------------------------------------------------

else if (!Array.isArray(detalles)) {
  valid = false;

  reason =
    'El campo detalles no existe o no es un array.';
}


// ------------------------------------------------------
// 6.3 No debe estar vacío
// ------------------------------------------------------

else if (detalles.length === 0) {
  valid = false;

  reason =
    'La IA devolvió detalles vacío.';
}


// ------------------------------------------------------
// 6.4 Límite de seguridad
// ------------------------------------------------------

else if (detalles.length > 10) {
  valid = false;

  reason =
    'La IA devolvió demasiados detalles de cotización.';
}


// ------------------------------------------------------
// 6.5 Validar cada detalle
// ------------------------------------------------------

else {

  for (
    let i = 0;
    i < detalles.length;
    i++
  ) {

    const d =
      detalles[i];

    const numeroDetalle =
      i + 1;


    // ----------------------------------------------
    // Debe ser objeto
    // ----------------------------------------------

    if (
      !d ||
      typeof d !== 'object' ||
      Array.isArray(d)
    ) {
      valid = false;

      reason =
        `El detalle ${numeroDetalle} no es un objeto válido.`;

      break;
    }


    // ----------------------------------------------
    // CAMPOS OBLIGATORIOS
    // ----------------------------------------------

    const camposObligatorios = [
      'cantidad',
      'producto',
      'nombre',
      'sabor',
      'ancho_cm',
      'alto_cm',
      'forma'
    ];

    for (const campo of camposObligatorios) {
      if (!(campo in d)) {
        valid = false;

        reason =
          `Falta el campo obligatorio "${campo}" en el detalle ${numeroDetalle}.`;

        break;
      }
    }

    if (!valid) {
      break;
    }


    // ----------------------------------------------
    // CANTIDAD
    // ----------------------------------------------

    if (
      d.cantidad !== null &&
      typeof d.cantidad !== 'number'
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} no es numérica.`;

      break;
    }


    if (
      typeof d.cantidad === 'number' &&
      (
        !Number.isFinite(d.cantidad) ||
        !Number.isInteger(d.cantidad)
      )
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} debe ser un número entero.`;

      break;
    }


    if (
      typeof d.cantidad === 'number' &&
      d.cantidad < 1000
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} es menor al mínimo comercial de 1000.`;

      break;
    }


    // ----------------------------------------------
    // PRODUCTO
    // ----------------------------------------------

    if (
      d.producto !== null &&
      typeof d.producto !== 'string'
    ) {
      valid = false;

      reason =
        `El producto del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // NOMBRE
    // ----------------------------------------------

    if (
      d.nombre !== null &&
      typeof d.nombre !== 'string'
    ) {
      valid = false;

      reason =
        `El nombre del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // SABOR
    // ----------------------------------------------

    if (
      d.sabor !== null &&
      typeof d.sabor !== 'string'
    ) {
      valid = false;

      reason =
        `El sabor del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // ANCHO
    // ----------------------------------------------

    if (
      d.ancho_cm !== null &&
      typeof d.ancho_cm !== 'number'
    ) {
      valid = false;

      reason =
        `El ancho_cm del detalle ${numeroDetalle} no es numérico.`;

      break;
    }


    if (
      typeof d.ancho_cm === 'number' &&
      (
        !Number.isFinite(d.ancho_cm) ||
        d.ancho_cm <= 0
      )
    ) {
      valid = false;

      reason =
        `El ancho_cm del detalle ${numeroDetalle} debe ser mayor a 0.`;

      break;
    }


    // ----------------------------------------------
    // ALTO
    // ----------------------------------------------

    if (
      d.alto_cm !== null &&
      typeof d.alto_cm !== 'number'
    ) {
      valid = false;

      reason =
        `El alto_cm del detalle ${numeroDetalle} no es numérico.`;

      break;
    }


    if (
      typeof d.alto_cm === 'number' &&
      (
        !Number.isFinite(d.alto_cm) ||
        d.alto_cm <= 0
      )
    ) {
      valid = false;

      reason =
        `El alto_cm del detalle ${numeroDetalle} debe ser mayor a 0.`;

      break;
    }


    // ----------------------------------------------
    // FORMA
    // ----------------------------------------------

    if (
      !formasPermitidas.includes(d.forma)
    ) {
      valid = false;

      reason =
        `La forma del detalle ${numeroDetalle} no es válida.`;

      break;
    }


    // ----------------------------------------------
    // CONSISTENCIA RECTANGULAR / CUADRADA
    // ----------------------------------------------
    //
    // No hacemos esto para CIRCULAR porque 8x8 circular
    // es perfectamente válido.
    //
    // ----------------------------------------------

    if (
      typeof d.ancho_cm === 'number' &&
      typeof d.alto_cm === 'number'
    ) {

      if (
        d.forma === 'CUADRADA' &&
        !casiIgual(
          d.ancho_cm,
          d.alto_cm
        )
      ) {
        valid = false;

        reason =
          `El detalle ${numeroDetalle} está marcado como CUADRADA pero ancho_cm y alto_cm son diferentes.`;

        break;
      }

      if (
        d.forma === 'RECTANGULAR' &&
        casiIgual(
          d.ancho_cm,
          d.alto_cm
        )
      ) {

        // Permitimos rectangular cuadrada físicamente,
        // porque comercialmente podría existir un troquel
        // rectangular de lados iguales.
        //
        // Por tanto NO invalidamos.
      }
    }


    // ----------------------------------------------
    // ALUCINACIÓN BÁSICA EN NOMBRE / SABOR
    // ----------------------------------------------
    //
    // Si nombre o sabor vienen informados pero NO aparecen
    // en el mensaje actual ni existe contexto que los respalde,
    // es sospechoso.
    //
    // No invalidamos producto aquí porque puede venir de la
    // memoria comercial previa.
    //
    // ----------------------------------------------

    for (const campo of ['nombre', 'sabor']) {

      const valor =
        texto(d[campo]);

      if (!valor) {
        continue;
      }

      const valorNormalizado =
        normalizarTexto(valor);

      const apareceEnMensaje =
        valorNormalizado !== '' &&
        mensajeNormalizado.includes(
          valorNormalizado
        );

      // Recuperamos contexto comercial completo para ver
      // si realmente estaba previamente guardado.

      const contextoTexto =
        normalizarTexto(
          JSON.stringify(
            contexto.contexto_comercial ?? {}
          )
        );

      const apareceEnContexto =
        valorNormalizado !== '' &&
        contextoTexto.includes(
          valorNormalizado
        );

      if (
        !apareceEnMensaje &&
        !apareceEnContexto
      ) {
        valid = false;

        reason =
          `El campo ${campo} del detalle ${numeroDetalle} contiene información no respaldada por el mensaje ni por el contexto.`;

        break;
      }
    }

    if (!valid) {
      break;
    }
  }
}


// ======================================================
// 7. VALIDAR COBERTURA DE MEDIDAS EXPLÍCITAS
// ======================================================
//
// Si el cliente escribió explícitamente:
// 8x11 y 8x8
//
// el extractor no puede devolver solo una.
//
// Solo aplicamos esta regla cuando encontramos
// dos o más pares explícitos en el mensaje.
//
// ======================================================

if (
  valid &&
  medidasExplicitas.length >= 2
) {

  const medidasExtraidas =
    detalles
      .map(d => ({
        ancho_cm:
          numero(d.ancho_cm),

        alto_cm:
          numero(d.alto_cm)
      }))
      .filter(m =>
        m.ancho_cm !== null &&
        m.alto_cm !== null
      );


  for (const medidaEsperada of medidasExplicitas) {

    const encontrada =
      medidasExtraidas.some(m =>
        casiIgual(
          m.ancho_cm,
          medidaEsperada.ancho_cm
        ) &&
        casiIgual(
          m.alto_cm,
          medidaEsperada.alto_cm
        )
      );

    if (!encontrada) {
      valid = false;

      reason =
        `El cliente indicó explícitamente la medida ${claveMedida(
          medidaEsperada.ancho_cm,
          medidaEsperada.alto_cm
        )}, pero el extractor no la incluyó en detalles.`;

      break;
    }
  }
}


// ======================================================
// 8. DETECTAR POSIBLE REDUCCIÓN DE PEDIDO MÚLTIPLE
// ======================================================
//
// Cuando existen dos o más medidas explícitas,
// esperamos al menos tantos detalles como medidas
// distintas.
//
// ======================================================

if (
  valid &&
  medidasExplicitas.length >= 2 &&
  detalles.length < medidasExplicitas.length
) {
  valid = false;

  reason =
    `El mensaje contiene ${medidasExplicitas.length} medidas explícitas, pero el extractor devolvió solo ${detalles.length} detalle(s).`;
}


// ======================================================
// 9. SALIDA
// ======================================================

return [
  {
    json: {

      valid,

      reason,

      detalles:
        valid
          ? detalles
          : [],

      cantidad_detalles:
        Array.isArray(detalles)
          ? detalles.length
          : 0,

      medidas_explicitas_mensaje:
        medidasExplicitas,

      cantidad_medidas_explicitas:
        medidasExplicitas.length,

      validado_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// APLICAR MÍNIMO DE IMPRESIÓN
// PEGASO ADHESIVOS - V2.4
// ======================================================
//
// V2.4: corta la cotizacion automatica (antes de insertar
// nada) si algun detalle normalizado llega a 6000 o mas.
// La derivacion normal ocurre en "Resolver contexto
// comercial"; esto solo cubre extracciones divergentes.
//
// ======================================================

const MINIMO_IMPRESION = 1000;
const MULTIPLO_IMPRESION = 1000;
const CANTIDAD_DERIVACION_HUMANA = 6000;

const input = $input.first().json;

const detalles = input.detalles;


// ======================================================
// VALIDACIÓN
// ======================================================

if (!Array.isArray(detalles)) {

  return [
    {
      json: {
        valid: false,
        error:
          'No se encontraron detalles válidos para cotización.',
        detalles: []
      }
    }
  ];

}


// ======================================================
// NORMALIZAR
// ======================================================

const detallesNormalizados =
  detalles.map((detalle) => {

    const cantidadRecibida =
      detalle.cantidad;

    const cantidadNumerica =
      Number(cantidadRecibida);


    // --------------------------------------------------
    // SIN CANTIDAD
    // --------------------------------------------------
    //
    // Pegaso no pregunta cantidad para iniciar cotización.
    // Se utiliza el mínimo determinístico de 1000.
    //
    // --------------------------------------------------

    if (
      cantidadRecibida === null ||
      cantidadRecibida === undefined ||
      cantidadRecibida === '' ||
      !Number.isFinite(cantidadNumerica) ||
      cantidadNumerica <= 0
    ) {

      return {

        ...detalle,

        cantidad_original:
          cantidadRecibida ?? null,

        cantidad:
          MINIMO_IMPRESION,

        cantidad_asumida:
          true,

        minimo_aplicado:
          true

      };

    }


    // --------------------------------------------------
    // MÍNIMO + MÚLTIPLOS DE 1000
    // --------------------------------------------------

    const cantidadFinal =
      Math.max(
        MINIMO_IMPRESION,
        Math.ceil(
          cantidadNumerica /
          MULTIPLO_IMPRESION
        ) *
        MULTIPLO_IMPRESION
      );


    const cantidadFueAjustada =
      cantidadFinal !== cantidadNumerica;


    return {

      ...detalle,

      cantidad_original:
        cantidadNumerica,

      cantidad:
        cantidadFinal,

      cantidad_asumida:
        false,

      minimo_aplicado:
        cantidadFueAjustada

    };

  });


const detallesMayoristas =
  detallesNormalizados.filter(
    d => d.cantidad >= CANTIDAD_DERIVACION_HUMANA
  );

if (detallesMayoristas.length > 0) {

  throw new Error(
    `Cotizacion automatica bloqueada: ${detallesMayoristas
      .map(d => d.cantidad)
      .join(', ')} etiquetas (${CANTIDAD_DERIVACION_HUMANA} o mas) ` +
    'requieren DERIVAR_HUMANO.'
  );

}


const minimoAplicado =
  detallesNormalizados.some(
    d => d.minimo_aplicado === true
  );


const algunaCantidadAsumida =
  detallesNormalizados.some(
    d => d.cantidad_asumida === true
  );


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      valid:
        true,

      detalles:
        detallesNormalizados,

      cantidad_detalles:
        detallesNormalizados.length,

      minimo_impresion:
        MINIMO_IMPRESION,

      multiplo_impresion:
        MULTIPLO_IMPRESION,

      minimo_aplicado:
        minimoAplicado,

      cantidad_asumida:
        algunaCantidadAsumida,

      nota_minimo:
        'La cantidad mínima de impresión es de 1000 etiquetas por diseño o tamaño y trabajamos en múltiplos de 1000. Si cambia una letra o palabra ya se considera otro diseño.'

    }
  }
];

return [
  {
    json: {
      valid: false,
      success: false,
      can_quote: false,
      status: 'AI_EXTRACTION_FAILED',
      error_code: 'ALL_AI_FAILED',
      message: 'No se pudo interpretar el pedido. Los modelos de IA no pudieron extraer datos válidos.',
      details: [],
      cantidad_detalles: 0,
      source: 'NONE'
    }
  }
];

// ============================================================
// PREPARAR DATOS PARA COTIZACIÓN
// PEGASO ADHESIVOS - V2.3
// ============================================================
//
// Entrada:
// input.detalles[]
//
// Para P4:
// - producto NO es obligatorio
// - material NO es obligatorio
// - necesitamos cantidad + ancho + alto
//
// ============================================================

const input = $input.first().json;

const detalles = input.detalles;


// ============================================================
// VALIDACIÓN
// ============================================================

if (
  !Array.isArray(detalles) ||
  detalles.length === 0
) {

  return [
    {
      json: {

        success: false,
        can_quote: false,

        status:
          'NO_DETAILS',

        message:
          'No existen detalles válidos para generar la cotización.',

        detalles: [],

        cantidad_detalles: 0,

        debug: {

          tipo_detalles:
            typeof detalles,

          es_array:
            Array.isArray(detalles),

          cantidad:
            Array.isArray(detalles)
              ? detalles.length
              : null,

          keys:
            Object.keys(input)
        }

      }
    }
  ];

}


// ============================================================
// NORMALIZAR
// ============================================================

const detallesValidos =
  detalles

    .filter(
      d =>
        d &&
        typeof d === 'object'
    )

    .map(d => {

      const cantidad =
        Number(
          d.cantidad ?? 0
        );

      const anchoCm =
        Number(
          d.ancho_cm ?? 0
        );

      const altoCm =
        Number(
          d.alto_cm ?? 0
        );


      return {

        cantidad,

        producto:
          d.producto != null &&
          String(d.producto).trim() !== ''
            ? String(d.producto).trim()
            : null,

        nombre:
          d.nombre != null &&
          String(d.nombre).trim() !== ''
            ? String(d.nombre).trim()
            : null,

        sabor:
          d.sabor ?? null,

        ancho_cm:
          anchoCm,

        alto_cm:
          altoCm,

        forma:
          String(
            d.forma ??
            'RECTANGULAR'
          ).toUpperCase(),

        cantidad_original:
          d.cantidad_original !== null &&
          d.cantidad_original !== undefined &&
          Number.isFinite(
            Number(d.cantidad_original)
          )
            ? Number(d.cantidad_original)
            : null,

        cantidad_asumida:
          d.cantidad_asumida === true,

        minimo_aplicado:
          d.minimo_aplicado === true

      };

    })


    // ========================================================
    // VALIDACIÓN COMERCIAL
    // ========================================================

    .filter(
      d =>
        Number.isFinite(d.cantidad) &&
        d.cantidad > 0 &&

        Number.isFinite(d.ancho_cm) &&
        d.ancho_cm > 0 &&

        Number.isFinite(d.alto_cm) &&
        d.alto_cm > 0
    );


// ============================================================
// VALIDACIÓN FINAL
// ============================================================

if (detallesValidos.length === 0) {

  return [
    {
      json: {

        success: false,
        can_quote: false,

        status:
          'NO_VALID_DETAILS',

        message:
          'Los detalles recibidos no contienen datos válidos para cotizar.',

        detalles: [],

        cantidad_detalles: 0,

        debug: {

          detalles_recibidos:
            detalles.length,

          detalles_validos:
            0,

          detalles_entrada:
            detalles
        }

      }
    }
  ];

}


// ============================================================
// SALIDA
// ============================================================

return [
  {
    json: {

      success:
        true,

      can_quote:
        true,

      status:
        'READY_FOR_QUOTATION',

      detalles:
        detallesValidos,

      cantidad_detalles:
        detallesValidos.length,

      minimo_impresion:
        input.minimo_impresion !== undefined
          ? Number(input.minimo_impresion)
          : 1000,

      multiplo_impresion:
        input.multiplo_impresion !== undefined
          ? Number(input.multiplo_impresion)
          : 1000,

      minimo_aplicado:
        input.minimo_aplicado === true,

      cantidad_asumida:
        input.cantidad_asumida === true,

      nota_minimo:
        input.nota_minimo ??
        null

    }
  }
];

// ======================================================
// EXPANDIR DETALLES
// ======================================================
//
// Entrada directa:
//   "EDT Datos del detalle"
//   - cotizacion_id
//   - cliente_id
//
// Detalles comerciales:
//   "Preparar datos cotización"
//   - detalles[]
//
// Salida:
//   1 item por cada detalle de la cotización
//
// IMPORTANTE:
//   producto NO es obligatorio.
//   Si nombre y producto vienen vacíos, se genera un
//   nombre técnico usando medidas + forma.
//
// Ejemplo:
//   5x5 + CIRCULAR
//   -> "Etiqueta 5x5 cm circular"
// ======================================================


// ======================================================
// 1. DATOS DE LA COTIZACIÓN
// ======================================================

const input = $input.first().json;

const cotizacionId =
  input.cotizacion_id != null
    ? Number(input.cotizacion_id)
    : null;

const clienteId =
  input.cliente_id != null
    ? Number(input.cliente_id)
    : null;


// ======================================================
// 2. RECUPERAR DETALLES PREPARADOS
// ======================================================

let datosPreparados = {};

try {
  datosPreparados =
    $('Preparar datos cotización').first().json ?? {};
} catch (error) {
  datosPreparados = {};
}

const detalles =
  Array.isArray(datosPreparados.detalles)
    ? datosPreparados.detalles
    : [];


// ======================================================
// 3. VALIDACIONES
// ======================================================

if (
  cotizacionId === null ||
  !Number.isFinite(cotizacionId) ||
  cotizacionId <= 0
) {
  throw new Error(
    'EXPANDIR DETALLES: cotizacion_id es obligatorio.'
  );
}

if (
  !Array.isArray(detalles) ||
  detalles.length === 0
) {
  throw new Error(
    'EXPANDIR DETALLES: no existen detalles preparados para calcular.'
  );
}


// ======================================================
// 4. HELPERS
// ======================================================

function limpiarTexto(valor) {
  if (valor === null || valor === undefined) {
    return null;
  }

  const texto = String(valor).trim();

  return texto !== ''
    ? texto
    : null;
}


function numeroTexto(valor) {
  const numero = Number(valor);

  if (!Number.isFinite(numero)) {
    return '';
  }

  return Number.isInteger(numero)
    ? String(numero)
    : String(numero);
}


function formaParaNombre(forma) {

  switch (forma) {

    case 'CIRCULAR':
      return 'circular';

    case 'RECTANGULAR':
      return 'rectangular';

    case 'CUADRADA':
      return 'cuadrada';

    case 'REDONDEADA':
      return 'con puntas redondeadas';

    case 'TROQUELADA':
      return 'troquelada';

    case 'IRREGULAR':
      return 'irregular';

    case 'NO_ESPECIFICADA':
      return '';

    default:
      return String(forma)
        .trim()
        .toLowerCase();
  }
}


function generarNombreTecnico(
  anchoCm,
  altoCm,
  forma
) {

  const ancho =
    numeroTexto(anchoCm);

  const alto =
    numeroTexto(altoCm);

  const formaTexto =
    formaParaNombre(forma);

  const medida =
    `${ancho}x${alto} cm`;

  if (formaTexto) {
    return `Etiqueta ${medida} ${formaTexto}`;
  }

  return `Etiqueta ${medida}`;
}


// ======================================================
// 5. EXPANDIR
// ======================================================

return detalles.map((detalle, index) => {

  const cantidad =
    Number(detalle.cantidad ?? 0);

  const anchoCm =
    Number(detalle.ancho_cm ?? 0);

  const altoCm =
    Number(detalle.alto_cm ?? 0);

  const cantidadOriginal =
    Number(
      detalle.cantidad_original ??
      detalle.cantidad ??
      0
    );

  const forma =
    String(
      detalle.forma ??
      'RECTANGULAR'
    )
      .trim()
      .toUpperCase();


  // ====================================================
  // VALIDACIÓN DEL DETALLE
  // ====================================================

  if (
    !Number.isFinite(cantidad) ||
    cantidad <= 0
  ) {
    throw new Error(
      `EXPANDIR DETALLES: cantidad inválida en detalle ${index}.`
    );
  }

  if (
    !Number.isFinite(anchoCm) ||
    anchoCm <= 0
  ) {
    throw new Error(
      `EXPANDIR DETALLES: ancho_cm inválido en detalle ${index}.`
    );
  }

  if (
    !Number.isFinite(altoCm) ||
    altoCm <= 0
  ) {
    throw new Error(
      `EXPANDIR DETALLES: alto_cm inválido en detalle ${index}.`
    );
  }


  // ====================================================
  // PRODUCTO Y NOMBRE
  // ====================================================

  const producto =
    limpiarTexto(detalle.producto);

  const nombreOriginal =
    limpiarTexto(detalle.nombre);

  // Prioridad:
  //
  // 1. nombre explícito
  // 2. producto
  // 3. nombre técnico generado
  //
  // producto puede permanecer null.

  const nombre =
    nombreOriginal ??
    producto ??
    generarNombreTecnico(
      anchoCm,
      altoCm,
      forma
    );


  // ====================================================
  // SALIDA DEL DETALLE
  // ====================================================

  return {
    json: {

      cotizacion_id:
        cotizacionId,

      cliente_id:
        clienteId,

      detalle_index:
        index,

      cantidad,

      // Producto no es obligatorio.
      producto,

      // Nombre sí queda resuelto para diseño.
      nombre,

      sabor:
        detalle.sabor ?? null,

      ancho_cm:
        anchoCm,

      alto_cm:
        altoCm,

      forma,

      cantidad_original:
        Number.isFinite(cantidadOriginal)
          ? cantidadOriginal
          : cantidad,

      minimo_aplicado:
        detalle.minimo_aplicado === true

    }
  };

});

// ======================================================
// RECUPERAR DETALLES CALCULADOS
// ======================================================

const detalles =
  $('Calcular precio detalle').all();


if (
  !detalles ||
  detalles.length === 0
) {

  throw new Error(
    'No existen detalles calculados para actualizar.'
  );

}


return detalles.map(
  (item) => {

    return {

      json: {
        ...item.json
      }

    };

  }
);

// ======================================================
// RESOLVER CATÁLOGO PEGASO
// ======================================================
// Entrada:
//   1 item por detalle desde "EXPANDIR DETALLES"
//
// Objetivo:
//   - Resolver producto_id del catálogo Pegaso
//   - Resolver material_id
//   - Determinar si requiere cotización manual
//
// IMPORTANTE:
// "mora", "frutilla", "queso", etc. NO son producto_id.
// producto_id representa el trabajo gráfico de Pegaso.
// ======================================================

const items = $input.all();

// ======================================================
// CATÁLOGO MATERIALES
// ======================================================

const MATERIALES = {
  P4: {
    id: 1,
    nombre: 'Polipropileno P4',
    requiereManual: false
  },

  COUCHE: {
    id: 2,
    nombre: 'Papel couché',
    requiereManual: true
  },

  CARTULINA: {
    id: 3,
    nombre: 'Papel cartulina para carpetas',
    requiereManual: true
  },

  TRANSPARENTE: {
    id: 4,
    nombre: 'Adhesivo transparente',
    requiereManual: true
  },

  METALIZADO: {
    id: 5,
    nombre: 'Adhesivo metalizado',
    requiereManual: true
  },

  BOND: {
    id: 6,
    nombre: 'Papel Bond para libretines/talonarios',
    requiereManual: true
  }
};

// ======================================================
// CATÁLOGO PRODUCTOS PEGASO
// ======================================================

const PRODUCTOS = {
  ETIQUETA_GENERICA: 1,
  ETIQUETA_RECTANGULAR: 2,
  ETIQUETA_TROQUELADA: 3,
  ETIQUETA_REDONDEADA: 4,
  ADHESIVO_TRANSPARENTE: 5,
  ADHESIVO_METALIZADO: 6,
  ADHESIVO_ECOLOGICO: 7,
  PAPEL_COUCHE_ADHESIVO: 8,
  CARTULINA_CARPETAS: 9,
  BOND_LIBRETINES: 10,
  BOND_TALONARIOS: 11
};

// ======================================================
// NORMALIZADOR DE TEXTO
// ======================================================

function normalizar(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toUpperCase();
}

// ======================================================
// RESOLVER MATERIAL
// ======================================================

function resolverMaterial(data) {

  // El extractor todavía puede no enviar material.
  // En etiquetas normales, el material por defecto de Pegaso es P4.
  const textoMaterial = normalizar(
    data.material ??
    data.material_nombre ??
    ''
  );

  // Si no especifica material:
  // usamos P4 como producto estándar de Pegaso.
  if (!textoMaterial) {
    return MATERIALES.P4;
  }

  if (
    textoMaterial.includes('P4') ||
    textoMaterial.includes('POLIPROPILENO')
  ) {
    return MATERIALES.P4;
  }

  if (
    textoMaterial.includes('COUCHE') ||
    textoMaterial.includes('COUCHE')
  ) {
    return MATERIALES.COUCHE;
  }

  if (textoMaterial.includes('CARTULINA')) {
    return MATERIALES.CARTULINA;
  }

  if (textoMaterial.includes('TRANSPARENTE')) {
    return MATERIALES.TRANSPARENTE;
  }

  if (textoMaterial.includes('METALIZADO')) {
    return MATERIALES.METALIZADO;
  }

  if (textoMaterial.includes('BOND')) {
    return MATERIALES.BOND;
  }

  // Material mencionado pero no reconocido:
  // no inventamos un ID.
  return {
    id: null,
    nombre: data.material ?? data.material_nombre ?? null,
    requiereManual: true
  };
}

// ======================================================
// RESOLVER PRODUCTO PEGASO
// ======================================================

function resolverProducto(data, material) {

  const forma = normalizar(data.forma);

  // ----------------------------------------------------
  // Materiales especiales primero
  // ----------------------------------------------------

  if (material.id === 4) {
    return PRODUCTOS.ADHESIVO_TRANSPARENTE;
  }

  if (material.id === 5) {
    return PRODUCTOS.ADHESIVO_METALIZADO;
  }

  if (material.id === 2) {
    return PRODUCTOS.PAPEL_COUCHE_ADHESIVO;
  }

  if (material.id === 3) {
    return PRODUCTOS.CARTULINA_CARPETAS;
  }

  // ----------------------------------------------------
  // P4
  // ----------------------------------------------------

  if (material.id === 1) {

    if (
      forma === 'RECTANGULAR' ||
      forma === 'RECTANGULO' ||
      forma === 'RECTA'
    ) {
      return PRODUCTOS.ETIQUETA_RECTANGULAR;
    }

    if (
      forma === 'TROQUELADA' ||
      forma === 'TROQUELADO' ||
      forma === 'IRREGULAR'
    ) {
      return PRODUCTOS.ETIQUETA_TROQUELADA;
    }

    if (
      forma === 'REDONDEADA' ||
      forma === 'PUNTAS REDONDEADAS'
    ) {
      return PRODUCTOS.ETIQUETA_REDONDEADA;
    }

    // No inventamos una clasificación más específica.
    return PRODUCTOS.ETIQUETA_GENERICA;
  }

  // Material sin producto automático conocido.
  return null;
}

// ======================================================
// PROCESAR DETALLES
// ======================================================

return items.map((item) => {

  const data = item.json;

  const material = resolverMaterial(data);

  const productoId = resolverProducto(
    data,
    material
  );

  return {
    json: {
      ...data,

      // Catálogo Pegaso
      producto_id: productoId,
      material_id: material.id,

      // Ayuda para depuración / trazabilidad
      material_resuelto: material.nombre,

      // Solo P4 tiene cálculo automático actualmente.
      requiere_cotizacion_manual:
        material.requiereManual === true ||
        material.id === null ||
        productoId === null
    }
  };
});

// ======================================================
// RESOLVER DISEÑO
// ======================================================
// Toma:
// - los detalles ya resueltos por catálogo
// - los diseños existentes del cliente
//
// Devuelve:
// - un item por detalle
// - diseno_id si encuentra coincidencia exacta
// - diseno_id = null si no existe
// ======================================================

const detalles = $('Resolver catálogo Pegaso').all();
const disenos = $input.all();

function normalizarTexto(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase();
}

return detalles.map((item, index) => {
  const detalle = item.json;

  const clienteId = Number(detalle.cliente_id);
  const materialId = Number(detalle.material_id);
  const ancho = Number(detalle.ancho_cm);
  const alto = Number(detalle.alto_cm);
  const forma = normalizarTexto(detalle.forma);
  const nombre = normalizarTexto(detalle.nombre || detalle.producto);

  const encontrado = disenos.find((d) => {
    const diseno = d.json;

    if (!diseno || !diseno.id) {
      return false;
    }

    return (
      Number(diseno.cliente_id) === clienteId &&
      Number(diseno.material_id) === materialId &&
      Number(diseno.ancho_cm) === ancho &&
      Number(diseno.alto_cm) === alto &&
      normalizarTexto(diseno.forma) === forma &&
      normalizarTexto(diseno.nombre) === nombre &&
      diseno.activo === true
    );
  });

  return {
    json: {
      ...detalle,

      diseno_id: encontrado
        ? Number(encontrado.json.id)
        : null,

      diseno_existente: Boolean(encontrado),

      diseno_nombre_resuelto: encontrado
        ? encontrado.json.nombre
        : null,

      detalle_index: detalle.detalle_index ?? index
    }
  };
});

const creados = $input.all();
const originales = $('¿Diseño existe?').all();

return creados.map((item, index) => {
  const creado = item.json;

  // Como esta rama FALSE mantiene el orden de los items,
  // recuperamos el detalle original correspondiente.
  const original = originales.find(
    o =>
      o.json.diseno_existente === false &&
      Number(o.json.cliente_id) === Number(creado.cliente_id) &&
      Number(o.json.material_id) === Number(creado.material_id) &&
      Number(o.json.ancho_cm) === Number(creado.ancho_cm) &&
      Number(o.json.alto_cm) === Number(creado.alto_cm) &&
      String(o.json.forma || '').toUpperCase() ===
        String(creado.forma || '').toUpperCase() &&
      String(o.json.nombre || o.json.producto || '').trim().toLowerCase() ===
        String(creado.nombre || '').trim().toLowerCase()
  );

  if (!original) {
    throw new Error(
      `No pude relacionar el diseño creado ID ${creado.id} con su detalle original.`
    );
  }

  return {
    json: {
      ...original.json,

      diseno_id: Number(creado.id),
      diseno_existente: false,
      diseno_creado: true,
      diseno_nombre_resuelto: creado.nombre
    }
  };
});

// ======================================================
// NODO N8N: Normalizar mensaje
// ARCHIVO: code/01-entrada/normalizar-mensaje.js
// VERSION: 2.1
// ======================================================
//
// RESPONSABILIDAD:
//
// - Unificar entrada real de WhatsApp y entrada TEST.
// - Normalizar teléfono, nombre, mensaje, tipo y canal.
// - CONSERVAR metadatos multimedia provenientes de
//   "Preparar entrada WhatsApp".
// - Compatible con:
//      TEXTO
//      IMAGEN
//      AUDIO
//      VIDEO
//      DOCUMENTO
//      otros tipos ya existentes.
// - No decidir si una imagen se analiza.
// - No decidir si un audio se transcribe.
// - No descargar multimedia.
// - No llamar IA.
// - No consultar PostgreSQL.
//
// ======================================================

const items =
  $input.all();


// ======================================================
// 1. HELPERS
// ======================================================

function normalizarTelefono(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  let telefono =
    String(valor)
      .trim()
      .replace(/\s+/g, '')
      .replace(/-/g, '')
      .replace(/\(/g, '')
      .replace(/\)/g, '');


  // --------------------------------------------------
  // Ecuador:
  //
  // 0999999999
  // ->
  // 593999999999
  // --------------------------------------------------

  if (
    telefono.startsWith('0')
  ) {
    telefono =
      '593' +
      telefono.substring(1);
  }


  // --------------------------------------------------
  // +593...
  // ->
  // 593...
  // --------------------------------------------------

  if (
    telefono.startsWith('+')
  ) {
    telefono =
      telefono.substring(1);
  }


  return telefono || null;
}


function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function booleano(
  valor,
  defecto = false
) {

  if (
    typeof valor === 'boolean'
  ) {
    return valor;
  }

  if (
    valor === true ||
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === false ||
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return defecto;
}


// ======================================================
// 2. NORMALIZAR ITEMS
// ======================================================

return items.map((item) => {

  const data =
    item.json ?? {};


  // ==================================================
  // TELÉFONO
  // ==================================================

  const telefono =
    normalizarTelefono(
      data.telefono ??
      data.whatsapp ??
      null
    );


  // ==================================================
  // MENSAJE
  // ==================================================
  //
  // IMPORTANTE:
  //
  // Para multimedia este campo puede contener:
  //
  // [IMAGEN] ...
  // [MEDIA_PENDIENTE] {...}
  //
  // o:
  //
  // [AUDIO]
  // [MEDIA_PENDIENTE] {...}
  //
  // No debemos modificar internamente ese descriptor.
  //
  // ==================================================

  const mensaje =
    textoONull(
      data.mensaje ??
      data.contenido
    ) ?? '';


  // ==================================================
  // TIPO
  // ==================================================

  const tipo =
    String(
      data.tipo ??
      'TEXTO'
    )
      .trim()
      .toUpperCase();


  // ==================================================
  // CANAL
  // ==================================================

  const canal =
    String(
      data.canal ??
      'WHATSAPP'
    )
      .trim()
      .toUpperCase();


  // ==================================================
  // MULTIMEDIA
  // ==================================================

  const mediaSoportada =
    booleano(
      data.media_soportada,
      false
    );


  const requiereProcesamientoMedia =
    booleano(
      data.requiere_procesamiento_media,
      false
    );


  const aptoParaFlujoTexto =
    booleano(
      data.apto_para_flujo_texto,
      false
    );


  const aptoParaFlujoConversacional =
    booleano(
      data.apto_para_flujo_conversacional,
      false
    );


  // ==================================================
  // SALIDA
  // ==================================================

  return {
    json: {

      // -----------------------------------------------
      // CONSERVAMOS PRIMERO TODO EL CONTRATO PREVIO.
      //
      // Fundamental para multimedia:
      //
      // - meta_whatsapp
      // - media_soportada
      // - descriptor [MEDIA_PENDIENTE]
      // - flags de control
      // -----------------------------------------------

      ...data,


      // -----------------------------------------------
      // CAMPOS NORMALIZADOS
      // -----------------------------------------------

      telefono,

      nombre_whatsapp:
        data.nombre_whatsapp ??
        data.nombre ??
        null,

      mensaje,

      tipo,

      canal,

      mensaje_externo_id:
        data.mensaje_externo_id ??
        null,


      // -----------------------------------------------
      // MULTIMEDIA
      // -----------------------------------------------

      meta_whatsapp:
        data.meta_whatsapp ??
        null,

      media_soportada:
        mediaSoportada,

      requiere_procesamiento_media:
        requiereProcesamientoMedia,

      apto_para_flujo_texto:
        aptoParaFlujoTexto,

      apto_para_flujo_conversacional:
        aptoParaFlujoConversacional,


      // -----------------------------------------------
      // CONTROL
      // -----------------------------------------------

      mensaje_normalizado:
        true,

      recibido_at:
        data.recibido_at ??
        new Date().toISOString()
    }
  };
});

// ======================================================
// RESOLVER CONTACTO
// ======================================================

const entrada = $('Normalizar mensaje').first().json;

const resultadoBusqueda = $input.first()?.json ?? {};

const contactoExiste =
  resultadoBusqueda.id != null &&
  Number(resultadoBusqueda.id) > 0;

return [
  {
    json: {
      // Mensaje entrante
      telefono: entrada.telefono,
      nombre_whatsapp: entrada.nombre_whatsapp,
      mensaje: entrada.mensaje,
      tipo: entrada.tipo,
      canal: entrada.canal,
      mensaje_externo_id: entrada.mensaje_externo_id,
      recibido_at: entrada.recibido_at,

      // Resolución
      contacto_existe: contactoExiste,

      contacto_id:
        contactoExiste
          ? Number(resultadoBusqueda.id)
          : null,

      cliente_id:
        contactoExiste &&
        resultadoBusqueda.cliente_id != null
          ? Number(resultadoBusqueda.cliente_id)
          : null,

      contacto_nombre:
        contactoExiste
          ? resultadoBusqueda.nombre
          : null,

      es_cliente_registrado:
        contactoExiste &&
        resultadoBusqueda.cliente_id != null
    }
  }
];

// ======================================================
// PREPARAR CONVERSACIÓN
// ======================================================
// Entrada:
//   - conversación ya resuelta
//   - puede pertenecer a cliente, contacto o prospecto
//   - puede incluir contexto_comercial desde PostgreSQL
//
// Salida:
//   estructura uniforme para:
//   - guardar mensaje entrante
//   - recuperar historial
//   - preparar contexto IA
//   - conservar contexto comercial persistente
// ======================================================

const data = $input.first().json;


// ======================================================
// HELPERS
// ======================================================

function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleano(valor, defecto = false) {
  if (typeof valor === 'boolean') {
    return valor;
  }

  if (valor === 'true') {
    return true;
  }

  if (valor === 'false') {
    return false;
  }

  return defecto;
}


function objetoJSON(valor) {
  // Ya es objeto
  if (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return valor;
  }

  // PostgreSQL/n8n podría entregarlo como string
  if (typeof valor === 'string') {
    const limpio = valor.trim();

    if (!limpio) {
      return {};
    }

    try {
      const parsed = JSON.parse(limpio);

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }
    } catch (error) {
      // No detenemos el flujo por un JSON vacío o mal formado.
      return {};
    }
  }

  return {};
}


// ======================================================
// VALIDACIONES BÁSICAS
// ======================================================

if (!data.conversacion_id) {
  throw new Error(
    'Preparar conversación: no existe conversacion_id.'
  );
}

if (!data.telefono) {
  throw new Error(
    'Preparar conversación: no existe telefono.'
  );
}


// ======================================================
// NORMALIZACIÓN DE IDS
// ======================================================

const conversacionId =
  numeroONull(data.conversacion_id);

if (conversacionId === null) {
  throw new Error(
    'Preparar conversación: conversacion_id no es válido.'
  );
}


const clienteId =
  numeroONull(data.cliente_id) ??
  numeroONull(data.conversacion_cliente_id);


const contactoId =
  numeroONull(data.contacto_id) ??
  numeroONull(data.conversacion_contacto_id);


const prospectoId =
  numeroONull(data.prospecto_id) ??
  numeroONull(data.conversacion_prospecto_id);


// ======================================================
// DETERMINAR ACTOR
// ======================================================

let tipoActor = 'DESCONOCIDO';

if (clienteId !== null) {
  tipoActor = 'CLIENTE';
}
else if (contactoId !== null) {
  tipoActor = 'CONTACTO';
}
else if (prospectoId !== null) {
  tipoActor = 'PROSPECTO';
}


// ======================================================
// RECUPERAR CONTEXTO COMERCIAL
// ======================================================
//
// Soportamos varios nombres por seguridad porque el dato
// puede venir:
// - directamente desde Buscar conversación
// - renombrado por un resolver previo
//
// Orden de prioridad:
// 1. contexto_comercial
// 2. conversacion_contexto_comercial
//
// ======================================================

const contextoComercial =
  objetoJSON(
    data.contexto_comercial ??
    data.conversacion_contexto_comercial ??
    {}
  );


// ======================================================
// NORMALIZAR ESTADO DE CONVERSACIÓN
// ======================================================

const conversacionEstado =
  data.conversacion_estado ??
  data.estado ??
  'ACTIVA';


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      ...data,

      // ============================================
      // CONVERSACIÓN
      // ============================================

      conversacion_id:
        conversacionId,

      conversacion_existe:
        true,

      conversacion_nueva:
        booleano(
          data.conversacion_nueva,
          false
        ),

      conversacion_estado:
        conversacionEstado,

      conversacion_cliente_id:
        clienteId,

      conversacion_contacto_id:
        contactoId,

      conversacion_prospecto_id:
        prospectoId,

      // ============================================
      // CONTEXTO COMERCIAL PERSISTENTE
      // ============================================

      contexto_comercial:
        contextoComercial,

      // ============================================
      // ACTORES
      // ============================================

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      prospecto_id:
        prospectoId,

      tipo_actor:
        tipoActor,

      // ============================================
      // MENSAJE
      // ============================================

      mensaje:
        data.mensaje ?? '',

      tipo:
        data.tipo ?? 'TEXTO',

      canal:
        data.canal ?? 'WHATSAPP',

      mensaje_externo_id:
        data.mensaje_externo_id ?? null,

      recibido_at:
        data.recibido_at ??
        new Date().toISOString(),

      // ============================================
      // FLAGS
      // ============================================

      es_cliente_registrado:
        booleano(
          data.es_cliente_registrado,
          false
        ),

      prospecto_existe:
        booleano(
          data.prospecto_existe,
          false
        )
    }
  }
];

// ======================================================
// NODO N8N: Preparar contexto IA
// ARCHIVO: code/03-conversacion/preparar-contexto-ia.js
// VERSION: 4.4
// ======================================================
//
// RESPONSABILIDAD:
//
// - Construir el contexto final para el cerebro comercial.
// - Mantener "Preparar conversación" como fuente de verdad
//   para identidad y memoria comercial persistida.
// - Usar prioritariamente el turno ENRIQUECIDO recibido por
//   la entrada del nodo (audio transcrito, imágenes, etc.).
// - Usar "Resolver turno conversacional" como fallback.
// - Incorporar análisis de imagen válido desde Groq,
//   DeepSeek u OpenAI.
// - Propagar medidas escritas detectadas en imágenes de forma
//   estructurada (ancho/alto/diámetro) sin romper el contexto actual.
// - Incorporar transcripciones de audio ya aplicadas al turno.
// - NO entregar links de multimedia al cerebro.
// - Limitar el historial libre a una ventana reciente.
// - Limitar el número máximo de mensajes históricos.
// - Detectar si empieza una nueva sesión por inactividad.
// - Conservar contexto_comercial estructurado aunque el
//   historial libre haya expirado.
// - Excluir del historial los marcadores internos (respuesta omitida
//   y bot reactivado por administrador).
// - Exponer ultimo_saliente (origen BOT / AUTOMATICO / HUMANO,
//   acción equivalente, si llegó después del inicio del turno)
//   y medidas_ya_solicitadas para el anti-duplicado.
// - Reglas pre-IA solo para texto sin multimedia:
//   SALUDO_SIMPLE (respuesta corta fija), PRODUCTO_NO_P4
//   (DERIVAR_HUMANO + COTIZACION_ESPECIAL) y
//   DIVISION_MINIMO_DISENOS (INFORMAR_MINIMO: no se puede
//   repartir la cantidad con menos de 1000 por diseño; nunca
//   deriva). Cuando aplican se
//   emite decision con el contrato del cerebro y
//   requiere_cerebro_comercial = false para saltar la IA.
// - NO llamar a IA.
// - NO escribir PostgreSQL.
//
// ======================================================


// ======================================================
// 0. CONFIGURACIÓN
// ======================================================

const VENTANA_HISTORIAL_HORAS = 24;

const MAX_MENSAJES_HISTORIAL = 24;

const MAX_SALIENTES_RECIENTES = 6;

const LARGO_MAXIMO_CONTENIDO_HISTORIAL = 4000;

const PREFIJO_AUTOMATICO_WHATSAPP_BUSINESS = '[AUTOMATICO WHATSAPP BUSINESS';

const PREFIJO_RESPUESTA_OMITIDA = '[RESPUESTA AUTOMÁTICA OMITIDA';

const PREFIJO_BOT_REACTIVADO = '[BOT REACTIVADO POR ADMINISTRADOR';

// Marcadores internos: se guardan como SALIENTE, nunca se envían
// y no forman parte de la conversación con el cliente.
function esMarcadorInterno(contenido) {
  const t = String(contenido ?? '').trim();
  return t.startsWith(PREFIJO_RESPUESTA_OMITIDA) || t.startsWith(PREFIJO_BOT_REACTIVADO);
}

const OFFSET_HORA_ECUADOR = -5;


// ======================================================
// 1. HELPERS
// ======================================================

function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function booleano(valor, defecto = false) {
  if (typeof valor === 'boolean') {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return defecto;
}


function primeroDefinido(...valores) {
  for (const valor of valores) {
    if (
      valor !== undefined &&
      valor !== null &&
      valor !== ''
    ) {
      return valor;
    }
  }

  return null;
}


function objeto(valor) {
  return (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  )
    ? valor
    : {};
}


function fechaMs(valor) {
  if (!valor) {
    return null;
  }

  const ms =
    Date.parse(valor);

  return Number.isFinite(ms)
    ? ms
    : null;
}


function normalizarTexto(valor) {
  return String(valor ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


function clasificacionDesdeEstado(estado) {
  const valor =
    textoONull(estado)
      ?.toUpperCase() ??
    null;

  if (!valor) {
    return null;
  }

  if (
    [
      'INTERESADO',
      'ACEPTADO',
      'PAGO_PENDIENTE',
      'ABONO_REPORTADO',
      'EN_PROCESO'
    ].includes(valor)
  ) {
    return 'A';
  }

  if (
    [
      'COTIZADO',
      'CALIFICADO',
      'EN_SEGUIMIENTO',
      'CONTACTADO'
    ].includes(valor)
  ) {
    return 'B';
  }

  return 'C';
}


// ======================================================
// 2. CONTEXTO ACTUAL
// ======================================================

let actual = {};

try {
  actual =
    $('Preparar conversación')
      .first()
      .json ?? {};
} catch (error) {
  throw new Error(
    'Preparar contexto IA: no se pudo recuperar "Preparar conversación".'
  );
}


// ======================================================
// 3. RESOLVER TURNO
// ======================================================
//
// PRIORIDAD:
//
// 1. Entrada actual del nodo.
//
//    Esto permite recibir:
//      - Aplicar transcripciones al turno
//      - futuros enriquecedores multimedia
//
// 2. Resolver turno conversacional.
//
// Así NO perdemos las transcripciones que acabamos de
// aplicar al turno.
//
// ======================================================

const entradaNodo =
  $input.first()?.json ?? {};


let turnoOriginal = {};

try {
  turnoOriginal =
    $('Resolver turno conversacional')
      .first()
      .json ?? {};
} catch (error) {
  turnoOriginal = {};
}


const entradaTieneTurno =
  Array.isArray(
    entradaNodo.turno_mensajes
  ) &&
  entradaNodo.turno_mensajes.length > 0;


const turno =
  entradaTieneTurno
    ? {
        ...turnoOriginal,
        ...entradaNodo
      }
    : turnoOriginal;


// ======================================================
// 3.1 IDS DEL TURNO
// ======================================================

const turnoMensajeIds =
  turno.continuar_procesamiento === true &&
  Array.isArray(turno.turno_mensaje_ids)
    ? turno.turno_mensaje_ids
        .map(numeroONull)
        .filter(id => id !== null)
    : Array.isArray(turno.turno_mensajes)
      ? turno.turno_mensajes
          .map(m => numeroONull(m.id))
          .filter(id => id !== null)
      : [];


const hayTurno =
  turnoMensajeIds.length > 0 &&
  (
    textoONull(turno.turno_texto) !== null ||
    (
      Array.isArray(turno.turno_mensajes) &&
      turno.turno_mensajes.length > 0
    )
  );


// ======================================================
// 4. MEDIA DEL TURNO
// ======================================================

const PREFIJO_PENDIENTE =
  '[MEDIA_PENDIENTE]';


const LINEA_IMAGEN_NO_ANALIZADA =
  '[CONTEXTO DE IMAGEN · revision=SI · motivo=IMAGEN_NO_ANALIZADA] ' +
  'La imagen no pudo revisarse automáticamente.';


const LINEA_AUDIO_NO_TRANSCRITO =
  '[TRANSCRIPCION DE AUDIO · revision=SI · motivo=AUDIO_NO_TRANSCRITO] ' +
  'El audio no pudo transcribirse automáticamente.';


function quitarPendientes(
  contenido,
  tipo = null,
  reemplazar = true
) {
  const tipoNormalizado =
    String(tipo ?? '')
      .trim()
      .toUpperCase();

  return String(contenido ?? '')
    .split('\n')
    .flatMap(linea => {
      const limpia =
        linea.trim();

      if (
        !limpia.startsWith(
          PREFIJO_PENDIENTE
        )
      ) {
        return [linea];
      }

      if (!reemplazar) {
        return [];
      }

      if (tipoNormalizado === 'IMAGEN') {
        return [
          LINEA_IMAGEN_NO_ANALIZADA
        ];
      }

      if (tipoNormalizado === 'AUDIO') {
        return [
          LINEA_AUDIO_NO_TRANSCRITO
        ];
      }

      return [
        `[ARCHIVO NO PROCESABLE · tipo=${tipoNormalizado || 'DESCONOCIDO'}] ` +
        'El archivo no pudo procesarse automáticamente.'
      ];
    })
    .join('\n')
    .trim();
}


function atributosCabecera(linea) {
  const cabecera =
    linea.match(
      /^\[([^\]]*)\]/
    );

  if (!cabecera) {
    return {};
  }

  return Object.fromEntries(
    cabecera[1]
      .split('·')
      .map(parte =>
        parte
          .trim()
          .split('=')
      )
      .filter(par =>
        par.length === 2
      )
      .map(([clave, valor]) => [
        clave.trim(),
        valor.trim()
      ])
  );
}


// ======================================================
// 4.1 RECUPERAR ANÁLISIS DE IMÁGENES
// ======================================================
//
// Tomamos análisis válidos de cualquier proveedor.
//
// La prioridad natural es:
//
// Groq
//   ↓ fallback
// DeepSeek
//   ↓ fallback
// OpenAI
//
// Como cada mensaje_id debería terminar válido en un solo
// proveedor, almacenamos solo análisis_valido=true.
//
// ======================================================

function obtenerItemsNodo(nombre) {
  try {
    return $(nombre)
      .all()
      .map(item => item.json ?? {});
  } catch (_) {
    return [];
  }
}


const analisisImagenes = [
  ...obtenerItemsNodo(
    'Validar análisis imagen Groq'
  ),
  ...obtenerItemsNodo(
    'Validar análisis imagen DeepSeek'
  ),
  ...obtenerItemsNodo(
    'Analizar imagen OpenAI'
  ),
  ...obtenerItemsNodo(
    'Validar análisis imagen OpenAI'
  )
];


const contenidoAnalizado =
  new Map();

const medidasImagenPorMensaje =
  new Map();


for (const analisis of analisisImagenes) {
  const mensajeId =
    numeroONull(
      analisis.mensaje_id
    );

  const contenido =
    textoONull(
      analisis.contenido_actualizado
    );

  if (
    mensajeId === null ||
    contenido === null
  ) {
    continue;
  }

  if (
    analisis.analisis_valido === false
  ) {
    continue;
  }

  // Primero que llega válido gana.
  // Normalmente será Groq.
  if (
    !contenidoAnalizado.has(
      mensajeId
    )
  ) {
    contenidoAnalizado.set(
      mensajeId,
      contenido
    );
  }

  const analisisNormalizado =
    objeto(
      analisis.analisis
    );

  const medidasDetectadas =
    booleano(
      primeroDefinido(
        analisis.medidas_detectadas,
        analisisNormalizado.medidas_detectadas
      ),
      false
    );

  const anchoCm =
    numeroONull(
      primeroDefinido(
        analisis.ancho_cm,
        analisisNormalizado.ancho_cm
      )
    );

  const altoCm =
    numeroONull(
      primeroDefinido(
        analisis.alto_cm,
        analisisNormalizado.alto_cm
      )
    );

  const diametroCm =
    numeroONull(
      primeroDefinido(
        analisis.diametro_cm,
        analisisNormalizado.diametro_cm
      )
    );

  const medidasVisibles =
    textoONull(
      primeroDefinido(
        analisis.medidas_visibles,
        analisisNormalizado.medidas_visibles
      )
    );

  if (
    medidasDetectadas ||
    anchoCm !== null ||
    altoCm !== null ||
    diametroCm !== null ||
    medidasVisibles !== null
  ) {
    medidasImagenPorMensaje.set(
      mensajeId,
      {
        mensaje_id:
          mensajeId,

        proveedor:
          textoONull(
            analisis.proveedor_analisis
          ),

        contenido_detectado:
          textoONull(
            analisis.contenido_detectado ??
            analisisNormalizado.contenido_detectado
          ),

        confianza:
          textoONull(
            analisis.confianza ??
            analisisNormalizado.confianza
          ),

        ancho_cm:
          anchoCm,

        alto_cm:
          altoCm,

        diametro_cm:
          diametroCm,

        texto_original:
          medidasVisibles,

        fuente:
          'IMAGEN'
      }
    );
  }
}


// ======================================================
// 4.2 MENSAJES DEL TURNO
// ======================================================

const mensajesTurnoOrigen =
  hayTurno &&
  Array.isArray(
    turno.turno_mensajes
  )
    ? turno.turno_mensajes
    : [
        {
          id: null,
          tipo:
            actual.tipo,

          contenido:
            hayTurno
              ? turno.turno_texto
              : actual.mensaje
        }
      ];


const mensajesTurno =
  mensajesTurnoOrigen.map(m => {

    const id =
      numeroONull(
        m.id
      );

    const tipo =
      (
        textoONull(
          m.tipo
        ) ??
        'TEXTO'
      ).toUpperCase();


    let contenido =
      contenidoAnalizado.get(id) ??
      m.contenido ??
      '';


    // --------------------------------------------------
    // TEXTO
    // --------------------------------------------------

    if (tipo === 'TEXTO') {
      contenido =
        String(contenido)
          .trim();
    }

    // --------------------------------------------------
    // MEDIA
    // --------------------------------------------------

    else {
      contenido =
        quitarPendientes(
          contenido,
          tipo,
          true
        );
    }


    return {
      ...m,

      id,

      tipo,

      contenido
    };
  });


// ======================================================
// 4.3 TEXTO FINAL DEL TURNO
// ======================================================

const textoTurno =
  mensajesTurno
    .map(m =>
      textoONull(
        m.contenido
      )
    )
    .filter(Boolean)
    .join('\n');


const medidasImagenTurno =
  mensajesTurno
    .map(m =>
      medidasImagenPorMensaje.get(
        numeroONull(m.id)
      ) ?? null
    )
    .filter(Boolean);


// ======================================================
// 4.4 RESUMEN DE MEDIA
// ======================================================

let imagenesAnalizadas = 0;

let audiosTranscritos = 0;

let comprobanteDetectado = false;

let revisionImagen = false;

let revisionAudio = false;

let archivoNoProcesable = false;


for (const m of mensajesTurno) {

  if (m.tipo === 'TEXTO') {
    continue;
  }


  for (
    const linea of String(
      m.contenido ?? ''
    )
      .split('\n')
      .map(l => l.trim())
  ) {

    // --------------------------------------------------
    // ARCHIVO NO PROCESABLE
    // --------------------------------------------------

    if (
      linea.startsWith(
        '[ARCHIVO NO PROCESABLE'
      )
    ) {
      archivoNoProcesable =
        true;
    }


    // --------------------------------------------------
    // IMAGEN
    // --------------------------------------------------

    if (
      m.tipo === 'IMAGEN' &&
      linea.startsWith(
        '[CONTEXTO DE IMAGEN'
      )
    ) {

      const atributos =
        atributosCabecera(
          linea
        );

      if (atributos.contenido) {
        imagenesAnalizadas++;
      }

      if (
        atributos.revision === 'SI'
      ) {
        revisionImagen =
          true;
      }

      if (
        atributos.contenido ===
        'COMPROBANTE_PAGO'
      ) {
        comprobanteDetectado =
          true;
      }
    }


    // --------------------------------------------------
    // AUDIO
    // --------------------------------------------------

    if (
      m.tipo === 'AUDIO' &&
      linea.startsWith(
        '[TRANSCRIPCION DE AUDIO'
      )
    ) {

      const atributos =
        atributosCabecera(
          linea
        );

      if (
        atributos.revision === 'SI'
      ) {
        revisionAudio =
          true;
      } else {
        audiosTranscritos++;
      }
    }
  }
}


// Si "Aplicar transcripciones al turno" ya resolvió
// explícitamente el estado, lo respetamos.

if (
  turno.requiere_revision_audio === true
) {
  revisionAudio =
    true;
}


const mediaTurno = {

  cantidad_media:
    mensajesTurno.filter(
      m =>
        m.tipo !== 'TEXTO'
    ).length,

  imagenes_analizadas:
    imagenesAnalizadas,

  audios_transcritos:
    audiosTranscritos,

  comprobante_detectado:
    comprobanteDetectado,

  requiere_revision_imagen:
    revisionImagen,

  requiere_revision_audio:
    revisionAudio,

  archivo_no_procesable:
    archivoNoProcesable,

  medidas_detectadas_imagen:
    medidasImagenTurno.length > 0,

  cantidad_imagenes_con_medidas:
    medidasImagenTurno.length,

  medidas_imagen:
    medidasImagenTurno,

  requiere_revision_humana:
    (
      revisionImagen ||
      revisionAudio ||
      archivoNoProcesable
    ),

  motivo_derivacion:
    archivoNoProcesable
      ? 'ARCHIVO_NO_PROCESABLE'

      : revisionImagen
        ? 'IMAGEN_REQUIERE_REVISION'

        : revisionAudio
          ? 'AUDIO_REQUIERE_REVISION'

          : null
};


// ======================================================
// 5. RECUPERAR HISTORIAL COMPLETO
// ======================================================

let itemsHistorial = [];

try {
  itemsHistorial =
    $('Recuperar historial conversación')
      .all();
} catch (error) {
  itemsHistorial =
    [];
}


const idsTurno =
  new Set(
    turnoMensajeIds
  );


const externosTurno =
  new Set(
    itemsHistorial
      .map(item =>
        item.json ?? {}
      )
      .filter(row =>
        idsTurno.has(
          numeroONull(
            row.id
          )
        )
      )
      .map(row =>
        textoONull(
          row.mensaje_externo_id
        )
      )
      .filter(Boolean)
  );


const externosVistos =
  new Set();


// ======================================================
// 5.1 REFERENCIA TEMPORAL DEL TURNO
// ======================================================
//
// Preferimos la fecha del último mensaje del turno.
// Si no existe, usamos recibido_at.
// Último fallback: ahora.
//
// ======================================================

const fechasTurno =
  mensajesTurno
    .map(m =>
      fechaMs(
        m.enviado_at
      )
    )
    .filter(ms =>
      ms !== null
    );


const referenciaTurnoMs =
  fechasTurno.length > 0
    ? Math.max(
        ...fechasTurno
      )
    : (
        fechaMs(
          actual.recibido_at
        ) ??
        Date.now()
      );


const limiteHistorialMs =
  referenciaTurnoMs -
  (
    VENTANA_HISTORIAL_HORAS *
    60 *
    60 *
    1000
  );


// ======================================================
// 5.2 LIMPIAR Y FILTRAR HISTORIAL
// ======================================================

let historialCandidato =
  itemsHistorial
    .map(item =>
      item.json ?? null
    )
    .filter(row => {

      if (!row) {
        return false;
      }


      const id =
        numeroONull(
          row.id
        );


      const externo =
        textoONull(
          row.mensaje_externo_id
        );


      // -----------------------------------------------
      // NO incluir turno actual
      // -----------------------------------------------

      if (
        idsTurno.has(id)
      ) {
        return false;
      }


      // -----------------------------------------------
      // NO incluir duplicados externos
      // -----------------------------------------------

      if (
        externo !== null
      ) {

        if (
          externosTurno.has(
            externo
          ) ||
          externosVistos.has(
            externo
          )
        ) {
          return false;
        }

        externosVistos.add(
          externo
        );
      }


      // -----------------------------------------------
      // Debe tener contenido
      // -----------------------------------------------

      const tieneContenido =
        row.contenido !== undefined &&
        row.contenido !== null &&
        String(
          row.contenido
        ).trim() !== '';

      if (!tieneContenido) {
        return false;
      }

      if (esMarcadorInterno(row.contenido)) {
        return false;
      }


      // -----------------------------------------------
      // VENTANA TEMPORAL
      // -----------------------------------------------

      const fecha =
        fechaMs(
          row.enviado_at
        );

      if (
        fecha !== null &&
        fecha < limiteHistorialMs
      ) {
        return false;
      }


      return true;
    })
    .sort((a, b) => {

      const fechaA =
        fechaMs(
          a.enviado_at
        ) ?? 0;

      const fechaB =
        fechaMs(
          b.enviado_at
        ) ?? 0;

      if (fechaA !== fechaB) {
        return fechaA - fechaB;
      }

      return (
        numeroONull(a.id) ?? 0
      ) -
      (
        numeroONull(b.id) ?? 0
      );
    });


// ======================================================
// 5.3 LÍMITE DE MENSAJES
// ======================================================
//
// Conservamos los MÁS RECIENTES.
//
// ======================================================

if (
  historialCandidato.length >
  MAX_MENSAJES_HISTORIAL
) {
  historialCandidato =
    historialCandidato.slice(
      -MAX_MENSAJES_HISTORIAL
    );
}


// ======================================================
// 5.4 HISTORIAL FINAL PARA IA
// ======================================================

const historial =
  historialCandidato
    .map(row => {

      const tipo =
        (
          textoONull(
            row.tipo
          ) ??
          'TEXTO'
        ).toUpperCase();


      let contenido =
        row.contenido ?? '';


      if (
        tipo !== 'TEXTO'
      ) {
        contenido =
          quitarPendientes(
            contenido,
            tipo,
            false
          );
      }


      contenido =
        String(
          contenido ?? ''
        )
          .trim()
          .slice(
            0,
            LARGO_MAXIMO_CONTENIDO_HISTORIAL
          );


      return {

        direccion:
          textoONull(
            row.direccion
          ),

        contenido,

        tipo,

        enviado_at:
          row.enviado_at ??
          null
      };
    })
    .filter(row =>
      textoONull(
        row.contenido
      ) !== null
    );


// ======================================================
// 6. DETECTAR SESIÓN NUEVA POR INACTIVIDAD
// ======================================================
//
// Si NO hay historial dentro de las últimas 24 horas,
// consideramos que este es un nuevo episodio
// conversacional.
//
// NO borramos la memoria comercial.
