if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (error) {
    return [
      {
        json: {
          valid: false,
          validation_reason:
            'La IA devolvió texto pero no JSON válido.',
          raw:
            data
        }
      }
    ];
  }
}

if (
  data &&
  typeof data === 'object' &&
  data.output &&
  typeof data.output === 'object'
) {
  data = data.output;
}


// ======================================================
