  $input.all().map(item => item.json ?? {});

function configPorClave(clave) {
  const fila = filasConfig.find(f => f.clave === clave);

  return fila ? objetoJSON(fila.valor_json) : null;
}

const config =
  configPorClave('MODO_PRUEBA') ?? {
    activo: true,
    telefonos_permitidos: []
  };


// ======================================================
// 2.1. CONFIGURACIÓN DEL TURNO CONVERSACIONAL
// ======================================================

const configDebounce =
  configPorClave('DEBOUNCE_WHATSAPP') ?? {};

function enteroEnRango(valor, minimo, maximo, defecto) {
  const n = Number(valor);

  if (valor === null || valor === undefined || valor === '' || !Number.isFinite(n)) {
    return defecto;
  }

  return Math.min(maximo, Math.max(minimo, Math.round(n)));
}

const debounceMsNormal = enteroEnRango(
  configDebounce.debounce_ms,
  0,
  DEBOUNCE_WHATSAPP_MS_MAXIMO,
  DEBOUNCE_WHATSAPP_MS_DEFECTO
);

const debouncePrimerContactoMs = enteroEnRango(
  configDebounce.debounce_primer_contacto_ms,
  0,
  DEBOUNCE_WHATSAPP_MS_MAXIMO,
  Math.max(debounceMsNormal, DEBOUNCE_PRIMER_CONTACTO_MS_DEFECTO)
);

const turnoMaxAntiguedadSegundos = enteroEnRango(
  configDebounce.turno_max_antiguedad_segundos,
  60,
  86400,
  TURNO_MAX_ANTIGUEDAD_SEGUNDOS_DEFECTO
);


// ======================================================
// 3. NORMALIZAR TELÉFONO
// ======================================================

const telefono = String(
  mensaje.telefono ??
  mensaje.wa_id ??
  mensaje.from ??
  ''
)
  .replace(/\D/g, '')
  .trim();


// ======================================================
// 4. RESOLVER MODO PRUEBA
// ======================================================

const modoPrueba =
  config.activo === true;


// ======================================================
// 5. NORMALIZAR TELÉFONOS AUTORIZADOS
// ======================================================

const telefonosPermitidos =
  Array.isArray(config.telefonos_permitidos)
    ? config.telefonos_permitidos
        .map(t =>
          String(t ?? '')
            .replace(/\D/g, '')
            .trim()
        )
        .filter(Boolean)
    : [];


// ======================================================
// 6. COMPROBAR AUTORIZACIÓN
// ======================================================

const telefonoPermitido =
  telefono !== '' &&
  telefonosPermitidos.includes(telefono);


// ======================================================
// 7. DECISIÓN
// ======================================================
//
// Si modo prueba está apagado:
//   BOT habilitado.
//
// Si modo prueba está encendido:
//   BOT solamente para teléfonos autorizados.
// ======================================================

const puedeResponderBot =
  modoPrueba === false ||
  telefonoPermitido === true;


// ======================================================
// 8. MOTIVO
// ======================================================

let motivoBloqueo = null;

if (!puedeResponderBot) {

  if (!telefono) {
    motivoBloqueo =
      'MODO_PRUEBA_TELEFONO_NO_IDENTIFICADO';
  } else {
    motivoBloqueo =
      'MODO_PRUEBA_TELEFONO_NO_AUTORIZADO';
  }

}


// ======================================================
// 9. RECUPERAR INFORMACIÓN DE CONVERSACIÓN
// ======================================================
//
// Nos interesa conservar IDs para diagnóstico.
// ======================================================

let conversacion = {};

try {
  conversacion =
    $('Preparar conversación').first().json ?? {};
} catch (error) {
  conversacion = {};
}


// ======================================================
// 9.1. PRIMER CONTACTO (DEBOUNCE EXTENDIDO)
// ======================================================

let eventoWhatsApp = {};

try {
  eventoWhatsApp =
    $('Normalizar evento WhatsApp').first().json?.evento_whatsapp ?? {};
} catch (error) {
  eventoWhatsApp = {};
}

const sesionActualizadaMs = Date.parse(
  conversacion.contexto_comercial?.sesion?.actualizado_at ?? ''
);

const sinTurnoBotReciente =
  !Number.isFinite(sesionActualizadaMs) ||
  Date.now() - sesionActualizadaMs > SESION_PRIMER_CONTACTO_HORAS * 3600 * 1000;

let debounceMotivo = 'NORMAL';

if (eventoWhatsApp.es_lead_anuncio === true) {
  debounceMotivo = 'PRIMER_CONTACTO_ANUNCIO';
} else if (conversacion.conversacion_nueva === true) {
  debounceMotivo = 'PRIMER_CONTACTO_CONVERSACION_NUEVA';
} else if (sinTurnoBotReciente) {
  debounceMotivo = 'PRIMER_CONTACTO_SESION_NUEVA';
}

const debounceMs =
  debounceMotivo === 'NORMAL'
    ? debounceMsNormal
    : Math.max(debounceMsNormal, debouncePrimerContactoMs);


// ======================================================
// 10. SALIDA
// ======================================================

return [
  {
    json: {

      // ----------------------------------------------
      // Identidad del mensaje
      // ----------------------------------------------

      telefono,

      mensaje_actual:
        mensaje.mensaje_actual ??
        mensaje.contenido ??
        mensaje.texto ??
        null,

      tipo_mensaje:
        mensaje.tipo_mensaje ??
        mensaje.tipo ??
        null,


      // ----------------------------------------------
      // Conversación
      // ----------------------------------------------

      conversacion_id:
        conversacion.conversacion_id ??
        conversacion.id ??
        null,

      prospecto_id:
        conversacion.prospecto_id ??
        null,

      cliente_id:
        conversacion.cliente_id ??
        null,


      // ----------------------------------------------
      // Configuración BOT
      // ----------------------------------------------

      modo_prueba:
        modoPrueba,

      telefono_prueba_permitido:
        telefonoPermitido,

      puede_responder_bot:
        puedeResponderBot,

      motivo_bloqueo_bot:
        motivoBloqueo,


      // ----------------------------------------------
      // Turno conversacional (debounce)
      // ----------------------------------------------

      debounce_ms:
        debounceMs,

      debounce_segundos:
        debounceMs / 1000,

      debounce_motivo:
        debounceMotivo,

      turno_max_antiguedad_segundos:
        turnoMaxAntiguedadSegundos,

      debounce_configurado:
        Object.keys(configDebounce).length > 0,


      // ----------------------------------------------
      // Diagnóstico
      // ----------------------------------------------

      telefonos_permitidos_configurados:
        telefonosPermitidos.length,

      permiso_resuelto_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// FINALIZAR MENSAJE - MODO PRUEBA
// ======================================================
//
// El mensaje YA fue guardado.
//
// Este número no tiene autorización para ser atendido
// automáticamente mientras MODO_PRUEBA esté activo.
//
// No llamar IA.
// No cotizar.
// No responder WhatsApp.
// No modificar la conversación comercial.
// ======================================================

const input =
  $input.first()?.json ?? {};

return [
  {
    json: {

      success: true,

      flujo:
        'MODO_PRUEBA',

      mensaje_guardado:
        true,

      respuesta_automatica:
        false,

      automatizacion_ejecutada:
        false,

      modo_prueba:
        input.modo_prueba === true,

      telefono_prueba_permitido:
        input.telefono_prueba_permitido === true,

      puede_responder_bot:
        false,

      motivo:
        input.motivo_bloqueo_bot ??
        'MODO_PRUEBA_TELEFONO_NO_AUTORIZADO',

      telefono:
        input.telefono ?? null,

      conversacion_id:
        input.conversacion_id ?? null,

      prospecto_id:
        input.prospecto_id ?? null,

      finalizado_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// VALIDAR VERIFICACIÓN DE WEBHOOK DE META / WHATSAPP
// ======================================================

const input = $input.first().json;

// Query parameters enviados por Meta
const query = input.query ?? {};

// Datos de verificación
const mode = query['hub.mode'] ?? null;
const verifyToken = query['hub.verify_token'] ?? null;
const challenge = query['hub.challenge'] ?? null;

// IMPORTANTE:
// Debe ser exactamente el mismo token colocado en Meta.
const EXPECTED_VERIFY_TOKEN = 'pegaso_whatsapp_verify_2026';

// Validación
const tokenValido =
  mode === 'subscribe' &&
  verifyToken === EXPECTED_VERIFY_TOKEN &&
  challenge !== null &&
  challenge !== undefined &&
  String(challenge).trim() !== '';

// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      ...input,

      meta_verificacion: {
        valido: tokenValido,

        mode,
        challenge:
          challenge !== null && challenge !== undefined
            ? String(challenge)
            : null,

        token_recibido: verifyToken !== null,

        motivo: tokenValido
          ? 'VERIFICACION_META_OK'
          : 'VERIFICACION_META_RECHAZADA'
      }
    }
  }
];

// ======================================================
// NODO N8N: Normalizar evento WhatsApp
// ARCHIVO: code/01-entrada/normalizar-evento-whatsapp.js
// VERSION: 2.2
// RESPONSABILIDAD:
// - Detectar el origen del webhook:
//      1. YCloud inbound:
//         whatsapp.inbound_message.received
//
//      2. YCloud WhatsApp Business App / dispositivo:
//         whatsapp.smb.message.echoes
//
//      3. Meta Cloud API directo:
//         body.entry
//
// - Extraer cuenta Pegaso, cliente y mensaje a un objeto
//   evento_whatsapp uniforme.
//
// - Mantener compatibilidad con todo el flujo existente:
//      telefono_cliente
//      wa_id
//      user_id
//      nombre_cliente
//      mensaje_id
//      timestamp
//      tipo_mensaje
//      texto
//      caption
//      media_*
//
// - Extraer multimedia:
//      imagen
//      audio
//      documento
//      video
//
// - Identificar mensajes enviados manualmente desde
//   WhatsApp Business de Pegaso.
//
// - Clasificar cada evento en clasificacion_mensaje:
//      ENTRANTE_CLIENTE / SALIENTE_HUMANO / SALIENTE_AUTOMATICO.
//   Todo echo es direccion SALIENTE y va a la ruta de
//   salida; nunca entra como mensaje del cliente.
//   SALIENTE_AUTOMATICO = automatización de la app
//   WhatsApp Business (bienvenida / respuestas de las
//   preguntas rápidas del anuncio): se registra pero NO
//   marca atención humana.
//
// - Exponer el contexto de anuncio (referral CTWA) del
//   mensaje entrante: es_lead_anuncio y anuncio.
//
// - NO guardar mensajes.
// - NO modificar prospectos.
// - NO decidir si debe intervenir humano.
// - NO descargar multimedia.
// ======================================================

const input = $input.first().json;
const body = input.body ?? {};


// ======================================================
// 0. AUTOMATIZACIONES DE WHATSAPP BUSINESS
// ======================================================
//
// YCloud entrega los mensajes automáticos de la app
// WhatsApp Business (bienvenida, respuesta del anuncio)
// como whatsapp.smb.message.echoes, con exactamente los
// mismos campos que un mensaje escrito por una persona.
// No existe bandera que los distinga, por eso se
// reconocen por su texto configurado.
//
// Si se cambia una automatización en la app, actualizar
// aquí su texto normalizado (minúsculas, sin tildes,
// sin signos ni emojis).
//
// exacto = true: el mensaje debe ser solo esa frase.
// exacto = false: basta con que empiece por esa frase.
//
// accion_equivalente: lo que ese mensaje ya le pidió o
// dijo al cliente, para no repetirlo desde el BOT.
// ======================================================

const AUTOMATIZACIONES_WHATSAPP_BUSINESS = [
  {
    codigo: 'RESPUESTA_ANUNCIO_MEDIDAS',
    texto: 'claro con mucho gusto le podemos ayudar en que medidas requiere sus etiquetas',
    exacto: false,
    accion_equivalente: 'PEDIR_MEDIDAS'
  },
  {
    codigo: 'BIENVENIDA_PEGASO',
    texto: 'gracias por comunicarte con pegaso adhesivos le saluda borys espinoza',
    exacto: false,
    accion_equivalente: 'SALUDO'
  },
  {
    codigo: 'BIENVENIDA_ANUNCIO',
    texto: 'hola le saluda borys espinoza como puedo ayudarle',
    exacto: true,
    accion_equivalente: 'SALUDO'
  },
  {
    codigo: 'RESPUESTA_ANUNCIO_MATERIAL',
    texto: 'trabajamos con plastico polipropileno de alta adherencia',
    exacto: false,
    accion_equivalente: 'INFORMAR_MATERIAL'
  }
];


// ======================================================
// 1. HELPERS
// ======================================================

const limpiarTelefono = (valor) => {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const limpio = String(valor)
    .replace(/[^\d]/g, '')
    .trim();

  return limpio || null;
};


const textoONull = (valor) => {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
};


const isoAUnix = (valor) => {
  if (!valor) {
    return null;
  }

  const fecha =
    new Date(valor);

  if (
    Number.isNaN(
      fecha.getTime()
    )
  ) {
    return valor;
  }

  return String(
    Math.floor(
      fecha.getTime() / 1000
    )
  );
};


const normalizarHuella = (valor) =>
  String(valor ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();


const resolverAutomatizacion = (valor) => {
  const huella =
    normalizarHuella(valor);

  if (!huella) {
    return null;
  }

  return AUTOMATIZACIONES_WHATSAPP_BUSINESS.find(
    a =>
      a.exacto
        ? huella === a.texto
        : huella.startsWith(a.texto)
  ) ?? null;
};


const extraerAnuncio = (referral) => {
  if (
    !referral ||
    typeof referral !== 'object'
  ) {
    return null;
  }

  const sourceType =
    textoONull(referral.source_type)?.toLowerCase() ?? null;

  const ctwaClid =
    textoONull(referral.ctwa_clid);

  if (
    sourceType !== 'ad' &&
    !ctwaClid
  ) {
    return null;
  }

  return {
    source_type: sourceType,
    source_id: textoONull(referral.source_id),
    source_url: textoONull(referral.source_url),
    headline: textoONull(referral.headline),
    ctwa_clid: ctwaClid,
    welcome_message:
      textoONull(referral.welcome_message?.text)
  };
};


// ======================================================
// 2. DETECTAR TIPO DE EVENTO
// ======================================================

const tipoEvento =
  textoONull(
    body.type
  );


// ------------------------------------------------------
// YCLOUD - MENSAJE ENTRANTE DEL CLIENTE
// ------------------------------------------------------

const esYCloudInbound =
  tipoEvento ===
    'whatsapp.inbound_message.received' &&
  !!body.whatsappInboundMessage;


// ------------------------------------------------------
// YCLOUD - MENSAJE ENVIADO DESDE WHATSAPP BUSINESS
// ------------------------------------------------------
//
// Este evento aparece cuando alguien escribe desde:
//
// - WhatsApp Business App
// - WhatsApp Web vinculado
// - dispositivo vinculado
//
// No corresponde al webhook inbound del cliente.
//
// Ejemplo:
// from = número Pegaso
// to   = número cliente
//
// ------------------------------------------------------

const esYCloudEchoHumano =
  tipoEvento ===
    'whatsapp.smb.message.echoes' &&
  !!body.whatsappMessage;


// ------------------------------------------------------
// META CLOUD API DIRECTO
// ------------------------------------------------------

const esMeta =
  Array.isArray(
    body.entry
  );


// ======================================================
// 3. VALORES NORMALIZADOS
// ======================================================

let procesable = false;

let object = null;
let field = null;

let phoneNumberId = null;
let displayPhoneNumber = null;

let telefonoCliente = null;
let waId = null;
let userId = null;
let nombreCliente = null;

let mensajeId = null;
let timestamp = null;
let tipo = null;

let texto = null;
let caption = null;

let mediaId = null;
let mediaMimeType = null;
let mediaSha256 = null;
let mediaLink = null;

let origen = null;

let proveedorEventoId = null;
let wabaId = null;


// ======================================================
// 4. NUEVOS CAMPOS DE CONTROL
// ======================================================

let direccion = null;

let actor = null;

let esMensajeEntrante = false;

let esMensajeHumanoPegaso = false;

let esMensajeAutomaticoPegaso = false;

let clasificacionMensaje = null;

let automatizacion = null;

let anuncio = null;

let eventoConversacional = false;


// ======================================================
// 5. HELPER MULTIMEDIA YCLOUD
// ======================================================
//
// Tanto whatsappInboundMessage como whatsappMessage
// pueden contener estructuras multimedia similares.
//
// ======================================================

function extraerMediaYCloud(message, tipoMensaje) {

  if (
    !message ||
    !tipoMensaje
  ) {
    return {
      id: null,
      mimeType: null,
      sha256: null,
      caption: null,
      link: null
    };
  }


  if (
    ![
      'image',
      'audio',
      'document',
      'video',
      'sticker'
    ].includes(tipoMensaje)
  ) {
    return {
      id: null,
      mimeType: null,
      sha256: null,
      caption: null,
      link: null
    };
  }


  const media =
    message[tipoMensaje] ?? {};


  return {

    id:
      media.id ??
      media.mediaId ??
      null,

    mimeType:
      media.mimeType ??
      media.mime_type ??
      null,

    sha256:
      media.sha256 ??
      null,

    caption:
      media.caption ??
      null,

    link:
      media.link ??
      null
  };
}


// ======================================================
// 6. YCLOUD - MENSAJE ENTRANTE
// ======================================================

if (esYCloudInbound) {

  const message =
    body.whatsappInboundMessage ?? {};


  // ----------------------------------------------------
  // ORIGEN
  // ----------------------------------------------------

  origen =
    'YCLOUD';

  proveedorEventoId =
    body.id ?? null;


  // ----------------------------------------------------
  // COMPATIBILIDAD
  // ----------------------------------------------------

  object =
    'whatsapp_business_account';

  field =
    'messages';


  // ----------------------------------------------------
  // CLASIFICACIÓN
  // ----------------------------------------------------

  direccion =
    'ENTRANTE';

  actor =
    'PROSPECTO';

  esMensajeEntrante =
    true;

  esMensajeHumanoPegaso =
    false;

  clasificacionMensaje =
    'ENTRANTE_CLIENTE';

  eventoConversacional =
    true;


  // ----------------------------------------------------
  // ANUNCIO (Click to WhatsApp)
  // ----------------------------------------------------
  //
  // Meta adjunta referral al primer mensaje que llega
  // desde un anuncio. La app WhatsApp Business responde
  // sola a ese mensaje y su eco llega segundos después.
  //
  // ----------------------------------------------------

  anuncio =
    extraerAnuncio(
      message.referral
    );


  // ----------------------------------------------------
  // CUENTA PEGASO
  // ----------------------------------------------------

  wabaId =
    message.wabaId ??
    null;


  // YCloud no entrega aquí Meta phone_number_id.
  phoneNumberId =
    null;


  displayPhoneNumber =
    limpiarTelefono(
      message.to
    );


  // ----------------------------------------------------
  // CLIENTE
  // ----------------------------------------------------

  telefonoCliente =
    limpiarTelefono(
      message.from
    );


  waId =
    limpiarTelefono(
      message.from
    );


  userId =
    message.fromUserId ??
    null;


  nombreCliente =
    message.customerProfile?.name ??
    null;


  // ----------------------------------------------------
  // MENSAJE
  // ----------------------------------------------------

  mensajeId =
    message.wamid ??
    message.id ??
    null;


  timestamp =
    isoAUnix(
      message.sendTime ??
      message.createTime
    );


  tipo =
    textoONull(
      message.type
    )?.toLowerCase() ??
    null;


  // ----------------------------------------------------
  // TEXTO
  // ----------------------------------------------------

  if (
    tipo === 'text'
  ) {

    texto =
      message.text?.body ??
      null;
  }


  // ----------------------------------------------------
  // MULTIMEDIA
  // ----------------------------------------------------

  const media =
    extraerMediaYCloud(
      message,
      tipo
    );


  mediaId =
    media.id;

  mediaMimeType =
    media.mimeType;

  mediaSha256 =
    media.sha256;

  mediaLink =
    media.link;

  caption =
    media.caption;


  // ----------------------------------------------------
  // PROCESABLE
  // ----------------------------------------------------

  procesable =
    !!mensajeId &&
    !!telefonoCliente &&
    !!tipo;
}


// ======================================================
// 7. YCLOUD - MENSAJE HUMANO DE PEGASO
// ======================================================
//
// Ejemplo real:
//
// type:
// whatsapp.smb.message.echoes
//
// whatsappMessage:
// {
//   from: "+593962645735",
//   to: "+593996588558",
//   type: "text",
//   text: {
//     body: "hola otra vez"
//   }
// }
//
// IMPORTANTE:
//
// En este evento:
//
// from = PEGASO
// to   = CLIENTE
//
// Por eso telefono_cliente sale de message.to.
//
// ======================================================

else if (esYCloudEchoHumano) {

  const message =
    body.whatsappMessage ?? {};


  // ----------------------------------------------------
  // ORIGEN
  // ----------------------------------------------------

  origen =
    'YCLOUD';

  proveedorEventoId =
    body.id ?? null;


  // ----------------------------------------------------
  // COMPATIBILIDAD
  // ----------------------------------------------------
  //
  // Conservamos estos valores para no romper nodos que
  // esperan la estructura histórica.
  //
  // ----------------------------------------------------

  object =
    'whatsapp_business_account';

  field =
    'messages';


  // ----------------------------------------------------
  // CLASIFICACIÓN
  // ----------------------------------------------------

  direccion =
    'SALIENTE';

  automatizacion =
    textoONull(message.type)?.toLowerCase() === 'text'
      ? resolverAutomatizacion(
          message.text?.body
        )
      : null;

  esMensajeAutomaticoPegaso =
    automatizacion !== null;

  actor =
    esMensajeAutomaticoPegaso
      ? 'AUTOMATIZACION_WHATSAPP_BUSINESS'
      : 'HUMANO_PEGASO';

  esMensajeEntrante =
    false;

  esMensajeHumanoPegaso =
    !esMensajeAutomaticoPegaso;

  clasificacionMensaje =
    esMensajeAutomaticoPegaso
      ? 'SALIENTE_AUTOMATICO'
      : 'SALIENTE_HUMANO';

  eventoConversacional =
    true;


  // ----------------------------------------------------
  // CUENTA PEGASO
  // ----------------------------------------------------

  wabaId =
    message.wabaId ??
    null;


  phoneNumberId =
    null;


  // En echo:
  // FROM = PEGASO

  displayPhoneNumber =
    limpiarTelefono(
      message.from
    );


  // ----------------------------------------------------
  // CLIENTE
  // ----------------------------------------------------
  //
  // En echo:
  // TO = CLIENTE
  //
  // ----------------------------------------------------

  telefonoCliente =
    limpiarTelefono(
      message.to
    );


  waId =
    limpiarTelefono(
      message.to
    );


  userId =
    message.toUserId ??
    null;


  // El evento echo normalmente no trae
  // customerProfile del cliente.
  nombreCliente =
    message.customerProfile?.name ??
    null;


  // ----------------------------------------------------
  // MENSAJE
  // ----------------------------------------------------

  mensajeId =
    message.wamid ??
    message.id ??
    null;


  timestamp =
    isoAUnix(
      message.sendTime ??
      message.createTime
    );


  tipo =
    textoONull(
      message.type
    )?.toLowerCase() ??
    null;


  // ----------------------------------------------------
  // TEXTO
  // ----------------------------------------------------

  if (
    tipo === 'text'
  ) {

    texto =
      message.text?.body ??
      null;
  }


  // ----------------------------------------------------
  // MULTIMEDIA
  // ----------------------------------------------------
  //
  // Dejamos soporte también para que una persona de
  // Pegaso pueda enviar imagen/documento/video/etc.
  //
  // ----------------------------------------------------

  const media =
    extraerMediaYCloud(
      message,
      tipo
    );


  mediaId =
    media.id;

  mediaMimeType =
    media.mimeType;

  mediaSha256 =
    media.sha256;

  mediaLink =
    media.link;

  caption =
    media.caption;


  // ----------------------------------------------------
  // PROCESABLE
  // ----------------------------------------------------
  //
  // Sí es un evento conversacional válido.
  //
  // El IF "¿Mensaje humano de Pegaso?" debe interceptarlo
  // ANTES del flujo normal del prospecto.
  //
  // ----------------------------------------------------

  procesable =
    !!mensajeId &&
    !!telefonoCliente &&
    !!tipo;
}


// ======================================================
// 8. META CLOUD API DIRECTO
// ======================================================

else if (esMeta) {

  const entry =
    body.entry?.[0] ?? {};

  const change =
    entry.changes?.[0] ?? {};


  field =
    change.field ??
    null;


  const value =
    change.value ?? {};

  const metadata =
    value.metadata ?? {};

  const contacts =
    value.contacts ?? [];

  const messages =
    value.messages ?? [];


  const contact =
    contacts[0] ?? {};

  const message =
    messages[0] ?? {};


  tipo =
    textoONull(
      message.type
    )?.toLowerCase() ??
    null;


  origen =
    'META_CLOUD_API';


  object =
    body.object ??
    null;


  // ----------------------------------------------------
  // CLASIFICACIÓN
  // ----------------------------------------------------

  direccion =
    'ENTRANTE';

  actor =
    'PROSPECTO';

  esMensajeEntrante =
    messages.length > 0;

  esMensajeHumanoPegaso =
    false;

  clasificacionMensaje =
    messages.length > 0
      ? 'ENTRANTE_CLIENTE'
      : null;

  eventoConversacional =
    messages.length > 0;


  // ----------------------------------------------------
  // CUENTA PEGASO
  // ----------------------------------------------------

  phoneNumberId =
    metadata.phone_number_id ??
    null;


  displayPhoneNumber =
    limpiarTelefono(
      metadata.display_phone_number
    );


  wabaId =
    entry.id ??
    null;


  // ----------------------------------------------------
  // CLIENTE
  // ----------------------------------------------------

  telefonoCliente =
    limpiarTelefono(
      message.from ??
      contact.wa_id
    );


  waId =
    limpiarTelefono(
      contact.wa_id
    );


  userId =
    contact.user_id ??
    null;


  nombreCliente =
    contact.profile?.name ??
    null;


  // ----------------------------------------------------
  // MENSAJE
  // ----------------------------------------------------

  mensajeId =
    message.id ??
    null;


  timestamp =
    message.timestamp ??
    null;


  // ----------------------------------------------------
  // TEXTO
  // ----------------------------------------------------

  if (
    tipo === 'text'
  ) {

    texto =
      message.text?.body ??
      null;
  }


  // ----------------------------------------------------
  // IMAGEN
  // ----------------------------------------------------

  if (
    tipo === 'image'
  ) {

    mediaId =
      message.image?.id ??
      null;

    mediaMimeType =
      message.image?.mime_type ??
      null;

    mediaSha256 =
      message.image?.sha256 ??
      null;

    caption =
      message.image?.caption ??
      null;
  }


  // ----------------------------------------------------
  // AUDIO
  // ----------------------------------------------------

  if (
    tipo === 'audio'
  ) {

    mediaId =
      message.audio?.id ??
      null;

    mediaMimeType =
      message.audio?.mime_type ??
      null;

    mediaSha256 =
      message.audio?.sha256 ??
      null;
  }


  // ----------------------------------------------------
  // DOCUMENTO
  // ----------------------------------------------------

  if (
    tipo === 'document'
  ) {

    mediaId =
      message.document?.id ??
      null;

    mediaMimeType =
      message.document?.mime_type ??
      null;

    mediaSha256 =
      message.document?.sha256 ??
      null;

    caption =
      message.document?.caption ??
      null;
  }


  // ----------------------------------------------------
  // VIDEO
  // ----------------------------------------------------

  if (
    tipo === 'video'
  ) {

    mediaId =
      message.video?.id ??
      null;

    mediaMimeType =
      message.video?.mime_type ??
      null;

    mediaSha256 =
      message.video?.sha256 ??
      null;

    caption =
      message.video?.caption ??
      null;
  }


  // ----------------------------------------------------
  // PROCESABLE
  // ----------------------------------------------------

  const esEventoMessages =
    field === 'messages';


  const tieneMensaje =
    messages.length > 0;


  procesable =
    esEventoMessages &&
    tieneMensaje &&
    !!mensajeId &&
    !!telefonoCliente;
}


// ======================================================
// 9. EVENTOS NO CONVERSACIONALES / DESCONOCIDOS
// ======================================================
//
// Ejemplo:
//
// whatsapp.message.updated
//
// No debe confundirse con intervención humana.
//
// ======================================================

else {

  origen =
    tipoEvento?.startsWith('whatsapp.')
      ? 'YCLOUD'
      : null;


  proveedorEventoId =
    body.id ??
    null;


  procesable =
    false;


  eventoConversacional =
    false;


  esMensajeEntrante =
    false;


  esMensajeHumanoPegaso =
    false;
}


// ======================================================
// 10. SALIDA NORMALIZADA
// ======================================================

return [
  {
    json: {

      evento_whatsapp: {

        // ==============================================
        // PROCESABILIDAD
        // ==============================================

        procesable,


        // ==============================================
        // TIPO DE EVENTO
        // ==============================================

        evento_tipo:
          tipoEvento,

        evento_conversacional:
          eventoConversacional,


        // ==============================================
        // DIRECCIÓN / ACTOR
        // ==============================================

        direccion,

        actor,

        es_mensaje_entrante:
          esMensajeEntrante,

        es_mensaje_humano_pegaso:
          esMensajeHumanoPegaso,

        es_mensaje_automatico_pegaso:
          esMensajeAutomaticoPegaso,

        clasificacion_mensaje:
          clasificacionMensaje,

        automatizacion_codigo:
          automatizacion?.codigo ?? null,

        accion_equivalente:
          automatizacion?.accion_equivalente ?? null,


        // ==============================================
        // ANUNCIO
        // ==============================================

        es_lead_anuncio:
          anuncio !== null,

        anuncio,


        // ==============================================
        // COMPATIBILIDAD
        // ==============================================

        object,

        field,


        // ==============================================
        // CUENTA / PEGASO
        // ==============================================

        phone_number_id:
          phoneNumberId,

        display_phone_number:
          displayPhoneNumber,

        waba_id:
          wabaId,


        // ==============================================
        // CLIENTE
        // ==============================================

        telefono_cliente:
          telefonoCliente,

        wa_id:
          waId,

        user_id:
          userId,

        nombre_cliente:
          nombreCliente,


        // ==============================================
        // MENSAJE
        // ==============================================

        mensaje_id:
          mensajeId,

        timestamp,

        tipo_mensaje:
          tipo,

        texto,

        caption,


        // ==============================================
        // MULTIMEDIA
        // ==============================================

        media_id:
          mediaId,

        media_mime_type:
          mediaMimeType,

        media_sha256:
          mediaSha256,

        media_link:
          mediaLink,


        // ==============================================
        // CONTROL INTERNO
        // ==============================================

        canal:
          'WHATSAPP',

        origen,

        proveedor_evento_id:
          proveedorEventoId
      },


      // =================================================
      // CONSERVAR EXACTAMENTE EL WEBHOOK ORIGINAL
      // =================================================

      payload_original:
        input
    }
  }
];

// ======================================================
// NODO N8N: Preparar entrada WhatsApp
// ARCHIVO: code/01-entrada/preparar-entrada-whatsapp.js
// VERSION: 2.1
// RESPONSABILIDAD:
// - Validar que exista evento_whatsapp procesable con telefono_cliente y mensaje_id (lanza error si no)
// - Traducir tipo_mensaje de WhatsApp a enum interno
//   (TEXTO, IMAGEN, AUDIO, VIDEO, DOCUMENTO, STICKER,
//    UBICACION, CONTACTO, INTERACTIVO, DESCONOCIDO)
// - Texto: mensaje = body.
// - Imagen/audio soportados:
//   mensaje = descriptor controlado que se guarda en mensajes.contenido:
//     línea 1 "[IMAGEN] caption" o "[AUDIO]"
//     línea 2 "[MEDIA_PENDIENTE] {json}"
// - Imagen no descargable: genera contexto de revisión.
// - Audio no descargable: genera contexto de revisión.
// - Video/documento: por ahora continúan como ARCHIVO NO PROCESABLE.
// - Aceptar enlaces de descarga solo de
//   https://api.ycloud.com/v2/whatsapp/media/download/
//   (anti-SSRF: la credencial YCloud nunca sale a otro host)
// - Convertir timestamp Unix a fecha ISO.
// - Agrupar datos extra en meta_whatsapp.
// - Emitir contrato compatible con "Mensaje entrante TEST".
// - Calcular:
//      apto_para_flujo_texto
//      apto_para_flujo_conversacional
//      media_soportada
//      requiere_procesamiento_media
// - NO descargar ni analizar multimedia.
// - NO transcribir audio.
// - NO decidir acción comercial.
// ======================================================


// ======================================================
// 0. CONFIGURACIÓN
// ======================================================

const MIME_IMAGEN_SOPORTADOS = [
  'image/jpeg',
  'image/png',
  'image/webp'
];

const MIME_AUDIO_SOPORTADOS = [
  'audio/ogg',
  'audio/opus',
  'audio/mpeg',
  'audio/mp3',
  'audio/mp4',
  'audio/x-m4a',
  'audio/m4a',
  'audio/wav',
  'audio/x-wav',
  'audio/webm'
];

const LINK_YCLOUD_PERMITIDO =
  /^https:\/\/api\.ycloud\.com\/v2\/whatsapp\/media\/download\/[A-Za-z0-9_-]+(\?[A-Za-z0-9%._~&=+-]*)?$/;

const LARGO_MAXIMO_LINK = 2048;
const LARGO_MAXIMO_CAPTION = 1000;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function mimeBase(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .trim()
      .toLowerCase();

  if (!limpio) {
    return null;
  }

  return limpio
    .split(';')[0]
    .trim() || null;
}


function normalizarCaption(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return '';
  }

  return String(valor)
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, LARGO_MAXIMO_CAPTION);
}


// ======================================================
// 2. INPUT
// ======================================================

const input =
  $input.first().json;

const evento =
  input.evento_whatsapp ?? null;


// ======================================================
// 3. VALIDACIONES BÁSICAS
// ======================================================

if (!evento) {
  throw new Error(
    'PREPARAR ENTRADA WHATSAPP: no existe evento_whatsapp.'
  );
}

if (!evento.procesable) {
  throw new Error(
    'PREPARAR ENTRADA WHATSAPP: el evento no está marcado como procesable.'
  );
}

if (!evento.telefono_cliente) {
  throw new Error(
    'PREPARAR ENTRADA WHATSAPP: no existe telefono_cliente.'
  );
}

if (!evento.mensaje_id) {
  throw new Error(
    'PREPARAR ENTRADA WHATSAPP: no existe mensaje_id.'
  );
}


// ======================================================
// 4. NORMALIZAR TIPO
// ======================================================

const tipoOriginal =
  String(
    evento.tipo_mensaje ?? ''
  )
    .trim()
    .toLowerCase();

let tipoMensaje =
  'DESCONOCIDO';

switch (tipoOriginal) {

  case 'text':
    tipoMensaje = 'TEXTO';
    break;

  case 'image':
    tipoMensaje = 'IMAGEN';
    break;

  case 'audio':
    tipoMensaje = 'AUDIO';
    break;

  case 'video':
    tipoMensaje = 'VIDEO';
    break;

  case 'document':
    tipoMensaje = 'DOCUMENTO';
    break;

  case 'sticker':
    tipoMensaje = 'STICKER';
    break;

  case 'location':
    tipoMensaje = 'UBICACION';
    break;

  case 'contacts':
    tipoMensaje = 'CONTACTO';
    break;

  case 'interactive':
    tipoMensaje = 'INTERACTIVO';
    break;
}


// ======================================================
// 5. TEXTO UTILIZABLE
// ======================================================

let mensaje = null;

if (tipoOriginal === 'text') {
  mensaje =
    textoONull(
      evento.texto
    );
}


// ------------------------------------------------------
// Caption para medios que puedan traerlo.
// Audio normalmente no trae caption, pero no perjudica
// conservarlo si el proveedor alguna vez lo entrega.
// ------------------------------------------------------

if (
  !mensaje &&
  [
    'image',
    'audio',
    'video',
    'document'
  ].includes(tipoOriginal)
) {
  mensaje =
    textoONull(
      evento.caption
    );
}


// ======================================================
// 6. TIMESTAMP
// ======================================================

let fechaMensaje = null;

if (evento.timestamp) {

  const timestampNumero =
    Number(
      evento.timestamp
    );

  if (
    Number.isFinite(
      timestampNumero
    )
  ) {
    fechaMensaje =
      new Date(
        timestampNumero * 1000
      ).toISOString();
  }
}


// ======================================================
// 7. CONTROL GENERAL DE MULTIMEDIA
// ======================================================

const esMultimedia = [
  'image',
  'audio',
  'video',
  'document',
  'sticker'
].includes(
  tipoOriginal
);


const requiereProcesamientoMedia =
  esMultimedia &&
  !!evento.media_id;


const aptoParaFlujoTexto =
  tipoOriginal === 'text' &&
  mensaje !== null;


// ======================================================
// 8. DESCRIPTOR MULTIMEDIA
// ======================================================
//
// IMPORTANTE:
//
// El caption se aplana a una sola línea.
// Así el cliente no puede inyectar artificialmente:
//   [MEDIA_PENDIENTE]
//   [CONTEXTO DE IMAGEN]
//   [TRANSCRIPCION DE AUDIO]
// etc.
//
// Los stickers continúan fuera del flujo conversacional.
//
// ======================================================

const TIPOS_FLUJO_MEDIA = [
  'image',
  'audio',
  'video',
  'document'
];

const entraComoMedia =
  TIPOS_FLUJO_MEDIA.includes(
    tipoOriginal
  );


const mimeTypeOriginal =
  textoONull(
    evento.media_mime_type
  );


const mimeType =
  mimeBase(
    evento.media_mime_type
  );


const linkMedia =
  textoONull(
    evento.media_link
  );


const linkPermitido =
  !!linkMedia &&
  linkMedia.length <= LARGO_MAXIMO_LINK &&
  LINK_YCLOUD_PERMITIDO.test(
    linkMedia
  );


const imagenSoportada =
  tipoOriginal === 'image' &&
  MIME_IMAGEN_SOPORTADOS.includes(
    mimeType
  );


const audioSoportado =
  tipoOriginal === 'audio' &&
  MIME_AUDIO_SOPORTADOS.includes(
    mimeType
  );


let mediaSoportada =
  false;

let motivoMediaNoProcesable =
  null;

let lineaMedia =
  null;


// ======================================================
// 9. CONSTRUIR MENSAJE MULTIMEDIA
// ======================================================

if (entraComoMedia) {

  const caption =
    normalizarCaption(
      evento.caption
    );


  // ----------------------------------------------------
  // IMAGEN SOPORTADA + LINK VÁLIDO
  // ----------------------------------------------------

  if (
    imagenSoportada &&
    linkPermitido
  ) {

    mediaSoportada =
      true;

    lineaMedia =
      '[MEDIA_PENDIENTE] ' +
      JSON.stringify({
        tipo_media:
          'IMAGEN',

        mime_type:
          mimeType,

        mime_type_original:
          mimeTypeOriginal,

        media_id:
          evento.media_id ?? null,

        link:
          linkMedia
      });

  }


  // ----------------------------------------------------
  // AUDIO SOPORTADO + LINK VÁLIDO
  // ----------------------------------------------------

  else if (
    audioSoportado &&
    linkPermitido
  ) {

    mediaSoportada =
      true;

    lineaMedia =
      '[MEDIA_PENDIENTE] ' +
      JSON.stringify({
        tipo_media:
          'AUDIO',

        mime_type:
          mimeType,

        mime_type_original:
          mimeTypeOriginal,

        media_id:
          evento.media_id ?? null,

        link:
          linkMedia
      });

  }


  // ----------------------------------------------------
  // IMAGEN SOPORTADA PERO SIN LINK UTILIZABLE
  // ----------------------------------------------------

  else if (
    imagenSoportada
  ) {

    motivoMediaNoProcesable =
      'IMAGEN_NO_DESCARGABLE';

    lineaMedia =
      '[CONTEXTO DE IMAGEN · revision=SI · motivo=IMAGEN_NO_DESCARGABLE] ' +
      'No se pudo obtener la imagen para revisarla automáticamente.';

  }


  // ----------------------------------------------------
  // AUDIO SOPORTADO PERO SIN LINK UTILIZABLE
  // ----------------------------------------------------

  else if (
    audioSoportado
  ) {

    motivoMediaNoProcesable =
      'AUDIO_NO_DESCARGABLE';

    lineaMedia =
      '[CONTEXTO DE AUDIO · revision=SI · motivo=AUDIO_NO_DESCARGABLE] ' +
      'No se pudo obtener el audio para transcribirlo automáticamente.';

  }


  // ----------------------------------------------------
  // IMAGEN CON FORMATO NO SOPORTADO
  // ----------------------------------------------------

  else if (
    tipoOriginal === 'image'
  ) {

    motivoMediaNoProcesable =
      'FORMATO_IMAGEN_NO_SOPORTADO';

    lineaMedia =
      `[ARCHIVO NO PROCESABLE · tipo=${tipoMensaje} · mime=${mimeTypeOriginal ?? 'desconocido'}] ` +
      'El bot no puede revisar este archivo automáticamente.';

  }


  // ----------------------------------------------------
  // AUDIO CON FORMATO NO SOPORTADO
  // ----------------------------------------------------

  else if (
    tipoOriginal === 'audio'
  ) {

    motivoMediaNoProcesable =
      'FORMATO_AUDIO_NO_SOPORTADO';

    lineaMedia =
      `[ARCHIVO NO PROCESABLE · tipo=${tipoMensaje} · mime=${mimeTypeOriginal ?? 'desconocido'}] ` +
      'El bot no puede transcribir este audio automáticamente.';

  }


  // ----------------------------------------------------
  // VIDEO / DOCUMENTO
  // ----------------------------------------------------

  else {

    motivoMediaNoProcesable =
      'TIPO_ARCHIVO_NO_SOPORTADO';

    lineaMedia =
      `[ARCHIVO NO PROCESABLE · tipo=${tipoMensaje} · mime=${mimeTypeOriginal ?? 'desconocido'}] ` +
      'El bot no puede revisar este archivo automáticamente.';

  }


  // ----------------------------------------------------
  // CONTENIDO QUE SE PERSISTE EN mensajes.contenido
  // ----------------------------------------------------

  mensaje =
    `[${tipoMensaje}]` +
    (
      caption
        ? ` ${caption}`
        : ''
    ) +
    `\n${lineaMedia}`;
}


// ======================================================
// 10. APTO PARA FLUJO CONVERSACIONAL
// ======================================================
//
// Conservamos exactamente el comportamiento anterior:
//
// TEXTO:
//   sí
//
// IMAGEN/AUDIO/VIDEO/DOCUMENTO:
//   sí, incluso cuando no son procesables automáticamente,
//   porque la etapa posterior puede derivarlos a humano.
//
// STICKER:
//   no.
//
// ======================================================

const aptoParaFlujoConversacional =
  aptoParaFlujoTexto ||
  entraComoMedia;


// ======================================================
// 11. SALIDA
// ======================================================

return [
  {
    json: {

      // ===============================================
      // CONTRATO COMPATIBLE CON "Mensaje entrante TEST"
      // ===============================================

      telefono:
        String(
          evento.telefono_cliente
        ),

      nombre_whatsapp:
        evento.nombre_cliente ?? null,

      mensaje,

      tipo:
        tipoMensaje,

      canal:
        'WHATSAPP',

      mensaje_externo_id:
        evento.mensaje_id,


      // ===============================================
      // INFORMACIÓN EXTRA DE META
      // ===============================================

      meta_whatsapp: {

        wa_id:
          evento.wa_id ?? null,

        user_id:
          evento.user_id ?? null,

        phone_number_id:
          evento.phone_number_id ?? null,

        display_phone_number:
          evento.display_phone_number ?? null,

        timestamp:
          evento.timestamp ?? null,

        fecha_mensaje:
          fechaMensaje,

        tipo_original:
          tipoOriginal || null,


        // ---------------------------------------------
        // MULTIMEDIA
        // ---------------------------------------------

        media: {

          presente:
            esMultimedia,

          requiere_procesamiento:
            requiereProcesamientoMedia,

          id:
            evento.media_id ?? null,

          // Conservamos el MIME tal como llegó.
          mime_type:
            evento.media_mime_type ?? null,

          // Y añadimos el MIME base para lógica interna.
          mime_type_base:
            mimeType,

          sha256:
            evento.media_sha256 ?? null,

          caption:
            evento.caption ?? null,

          link:
            linkMedia,

          link_permitido:
            linkPermitido,

          soportada:
            mediaSoportada,

          tipo_media:
            mediaSoportada
              ? tipoMensaje
              : null,

          motivo_no_procesable:
            motivoMediaNoProcesable
        }
      },


      // ===============================================
      // CONTROL
      // ===============================================

      entrada_whatsapp_preparada:
        true,

      apto_para_flujo_texto:
        aptoParaFlujoTexto,

      apto_para_flujo_conversacional:
        aptoParaFlujoConversacional,

      media_soportada:
        mediaSoportada,

      requiere_procesamiento_media:
        requiereProcesamientoMedia
    }
  }
];

// ======================================================
// PREPARAR ENVÍO WHATSAPP - YCLOUD
// PEGASO ADHESIVOS
// VERSION: 3.0
// ======================================================
//
// V2.1: no envía si el texto persistido es el marcador
// [RESPUESTA AUTOMÁTICA OMITIDA ...] de "Preparar respuesta
// comercial" (motivo_no_envio = RESPUESTA_OMITIDA_DUPLICADA).
//
// V2.2: si la decisión comercial trae enviar_imagen_material,
// emite enviar_imagen y ycloud_request_imagen (foto del
// material) para "YCloud Enviar imagen material", que se
// envía después del texto.
//
// V3.0: lee enviar_imagen_informativa / imagen_informativa_url
// (material o metodología) y expone imagen_informativa. La
// imagen se envía ANTES del texto ("YCloud Enviar imagen" →
// "Esperar antes del texto" → "YCloud Enviar Wts").
//
// Puede recibir datos desde distintas rutas:
//
// - Guardar mensaje saliente
// - Guardar mensaje comercial
// - Guardar mensaje transición humano
//
// IMPORTANTE:
//
// Los nodos PostgreSQL pueden devolver únicamente la fila
// insertada y perder datos del contrato anterior, por ejemplo:
//
// - telefono
// - nombre_whatsapp
// - proveedor
// - mensaje de negocio
//
// Por eso este nodo recupera identidad y contexto desde
// nodos anteriores como fallback.
//
// Responsabilidades:
//
// 1. Resolver mensaje persistido.
// 2. Resolver teléfono destino.
// 3. Confirmar que la ejecución nació de WhatsApp real.
// 4. Resolver proveedor YCloud.
// 5. Resolver número emisor Pegaso.
// 6. Construir request compatible con YCloud.
// 7. Evitar envíos físicos durante TEST/manual.
// 8. Construir el request de la imagen informativa, si aplica.
//
// ======================================================

const input =
  $input.first().json ?? {};


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero =
    Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function limpiarTelefono(valor) {

  const texto =
    textoONull(valor);

  if (!texto) {
    return null;
  }

  const limpio =
    texto
      .replace(/[^\d]/g, '')
      .trim();

  return limpio || null;
}


function telefonoE164(valor) {

  const limpio =
    limpiarTelefono(valor);

  if (!limpio) {
    return null;
  }

  return `+${limpio}`;
}


// ------------------------------------------------------
// Recupera de forma segura otro nodo del workflow.
//
// Si el nodo no participó en esta ejecución:
// devuelve {}.
//
// Esto es importante porque este nodo sirve a varias rutas.
// ------------------------------------------------------

function obtenerNodo(nombre) {

  try {

    return (
      $(nombre)
        .first()
        .json ?? {}
    );

  } catch (_) {

    return {};

  }
}


// ======================================================
// 2. RECUPERAR CONTRATOS DE RUTAS ANTERIORES
// ======================================================

const decision =
  obtenerNodo(
    'Recuperar decisión comercial'
  );


const prepararRespuestaComercial =
  obtenerNodo(
    'Preparar respuesta comercial'
  );


const prepararMensajeCotizacion =
  obtenerNodo(
    'Preparar mensaje cotización'
  );


const prepararMensajeHumano =
  obtenerNodo(
    'Preparar mensaje transición humano'
  );


const prepararDerivacionHumana =
  obtenerNodo(
    'Preparar derivación humana'
  );


const guardarContextoHandoff =
  obtenerNodo(
    'Guardar contexto handoff'
  );


const prepararContextoHandoff =
  obtenerNodo(
    'Preparar contexto handoff'
  );


const entradaWhatsApp =
  obtenerNodo(
    'Preparar entrada WhatsApp'
  );


// ======================================================
// 3. RECUPERAR EVENTO NORMALIZADO
// ======================================================

const normalizado =
  obtenerNodo(
    'Normalizar evento WhatsApp'
  );


const eventoWhatsApp =
  (
    normalizado.evento_whatsapp &&
    typeof normalizado.evento_whatsapp === 'object'
  )
    ? normalizado.evento_whatsapp
    : {};


// ======================================================
// 4. MENSAJE DB / IDENTIDAD
// ======================================================

const mensajeDbId =
  numeroONull(
    input.id ??
    input.mensaje_db_id
  );


const conversacionId =
  numeroONull(
    input.conversacion_id ??
    prepararMensajeHumano.conversacion_id ??
    prepararDerivacionHumana.conversacion_id ??
    guardarContextoHandoff.conversacion_id ??
    decision.conversacion_id ??
    entradaWhatsApp.conversacion_id
  );


// ======================================================
// 5. RESOLVER TEXTO DE SALIDA
// ======================================================
//
// Primera opción:
// contenido ya persistido en mensajes.
//
// Los demás son únicamente fallbacks de seguridad.
//
// ======================================================

const textoSalida =
  textoONull(
    input.contenido
  ) ??

  textoONull(
    input.texto_salida
  ) ??

  // Handoff humano
  textoONull(
    prepararMensajeHumano.mensaje_salida
  ) ??

  textoONull(
    prepararMensajeHumano.mensaje_transicion
  ) ??

  textoONull(
    prepararMensajeHumano.handoff_mensaje_transicion
  ) ??

  // Respuesta comercial
  textoONull(
    prepararRespuestaComercial.mensaje_salida
  ) ??

  textoONull(
    prepararRespuestaComercial.mensaje_comercial
  ) ??

  // Cotización
  textoONull(
    prepararMensajeCotizacion.mensaje_salida
  ) ??

  textoONull(
    prepararMensajeCotizacion.mensaje_comercial
  ) ??

  null;


if (!textoSalida) {

  throw new Error(
    'PREPARAR ENVÍO WHATSAPP: el mensaje saliente no contiene texto.'
  );

}


// ======================================================
// 6. RESOLVER TELÉFONO DESTINO
// ======================================================
//
// El mensaje guardado puede NO conservar teléfono.
//
// Prioridad:
//
// 1. input actual
// 2. decisión comercial
// 3. mensaje humano
// 4. derivación humana
// 5. contexto handoff
// 6. entrada WhatsApp
// 7. evento normalizado
//
// ======================================================

let telefonoDestino =
  limpiarTelefono(
    input.telefono_destino
  ) ??

  limpiarTelefono(
    input.telefono
  ) ??

  limpiarTelefono(
    decision.telefono
  ) ??

  limpiarTelefono(
    prepararMensajeHumano.telefono
  ) ??

  limpiarTelefono(
    prepararDerivacionHumana.telefono
  ) ??

  limpiarTelefono(
    guardarContextoHandoff.telefono
  ) ??

  limpiarTelefono(
    prepararContextoHandoff.telefono
  ) ??

  limpiarTelefono(
    entradaWhatsApp.telefono
  ) ??

  limpiarTelefono(
    eventoWhatsApp.telefono_cliente
  ) ??

  limpiarTelefono(
    eventoWhatsApp.from
  ) ??

  limpiarTelefono(
    eventoWhatsApp.wa_id
  );


if (!telefonoDestino) {

  throw new Error(
    'PREPARAR ENVÍO WHATSAPP: no se pudo resolver el teléfono destino.'
  );

}


// ======================================================
// 7. DETERMINAR SI VIENE DE WHATSAPP REAL
// ======================================================
//
// Camino real:
//
// Webhook YCloud
//   → Normalizar evento WhatsApp
//   → Preparar entrada WhatsApp
//   → ...
//
// Camino TEST:
//
// Execute workflow
//   → Mensaje TEST
//
// Solo enviamos físicamente cuando la ejecución pertenece
// a un mensaje WhatsApp real.
//
// ======================================================

const canalEntrada =
  String(
    entradaWhatsApp.canal ??
    eventoWhatsApp.canal ??
    ''
  )
    .trim()
    .toUpperCase();


const entradaPreparada =
  entradaWhatsApp
    .entrada_whatsapp_preparada === true;


const eventoProcesable =
  eventoWhatsApp.procesable === true;


const vieneDeWhatsAppReal =
  (
    entradaPreparada &&
    canalEntrada === 'WHATSAPP'
  )
  ||
  (
    eventoProcesable &&
    String(
      eventoWhatsApp.canal ?? ''
    )
      .trim()
      .toUpperCase() === 'WHATSAPP'
  );


// ======================================================
// 8. RESOLVER PROVEEDOR
// ======================================================
//
// El proveedor puede venir explícitamente del evento.
//
// También aceptamos el hecho de que el evento normalizado
// venga del webhook YCloud.
//
// ======================================================

let proveedor =
  textoONull(
    eventoWhatsApp.origen
  ) ??

  textoONull(
    eventoWhatsApp.proveedor
  ) ??

  textoONull(
    entradaWhatsApp.origen
  ) ??

  textoONull(
    entradaWhatsApp.proveedor_whatsapp
  ) ??

  null;


if (proveedor) {
  proveedor =
    proveedor.toUpperCase();
}


// Si existe un evento real YCloud pero el normalizador
// todavía no expone origen explícitamente, podemos
// reconocerlo por la estructura del evento.
//
// NO se aplica en ejecuciones manuales.
if (
  !proveedor &&
  vieneDeWhatsAppReal &&
  (
    eventoWhatsApp.waba_id ||
    eventoWhatsApp.mensaje_id ||
    entradaWhatsApp.meta_whatsapp
  )
) {

  proveedor =
    'YCLOUD';

}


const vieneDeYCloud =
  proveedor === 'YCLOUD';


// ======================================================
// 9. RESOLVER NÚMERO EMISOR PEGASO
// ======================================================
//
// YCloud inbound:
//
// from = cliente
// to   = Pegaso
//
// En la normalización normalmente:
//
// display_phone_number = número Pegaso.
//
// ======================================================

const metaWhatsApp =
  (
    entradaWhatsApp.meta_whatsapp &&
    typeof entradaWhatsApp.meta_whatsapp === 'object'
  )
    ? entradaWhatsApp.meta_whatsapp
    : {};


let telefonoEmisor =
  limpiarTelefono(
    eventoWhatsApp.display_phone_number
  ) ??

  limpiarTelefono(
    eventoWhatsApp.telefono_emisor
  ) ??

  limpiarTelefono(
    entradaWhatsApp.display_phone_number
  ) ??

  limpiarTelefono(
    metaWhatsApp.display_phone_number
  ) ??

  null;


// ------------------------------------------------------
// Fallback operativo.
//
// Número oficial actualmente conectado a YCloud.
//
// Si Pegaso trabaja después con múltiples números,
// este fallback debe desaparecer y resolverse por WABA.
// ------------------------------------------------------

if (!telefonoEmisor) {

  telefonoEmisor =
    '593962645735';

}


// ======================================================
// 10. RESOLVER TIPO DE MENSAJE
// ======================================================
//
// `HANDOFF_HUMANO` describe el propósito comercial,
// pero físicamente sigue siendo un mensaje de texto.
//
// ======================================================

const tipoOriginal =
  String(
    input.tipo ??
    input.tipo_salida ??
    input.tipo_mensaje_salida ??
    prepararMensajeHumano.tipo_mensaje_salida ??
    'TEXTO'
  )
    .trim()
    .toUpperCase();


const tiposTransportablesComoTexto = [
  'TEXTO',
  'TEXT',
  'HANDOFF_HUMANO',
  'RESPUESTA_COMERCIAL',
  'COTIZACION'
];


const esTexto =
  tiposTransportablesComoTexto
    .includes(tipoOriginal);


// Para YCloud siempre será físicamente "text".
const tipoYCloud =
  'text';


// ======================================================
// 11. DECIDIR SI SE ENVÍA
// ======================================================

const respuestaOmitida =
  String(textoSalida ?? '')
    .trim()
    .startsWith('[RESPUESTA AUTOMÁTICA OMITIDA') ||
  (
    prepararRespuestaComercial.omitir_envio === true &&
    String(textoSalida ?? '').trim() ===
      String(prepararRespuestaComercial.respuesta_final ?? '').trim()
  );


const enviarWhatsApp =
  !respuestaOmitida &&
  vieneDeWhatsAppReal &&
  vieneDeYCloud &&
  esTexto &&
  Boolean(telefonoDestino) &&
  Boolean(telefonoEmisor) &&
  Boolean(textoSalida);


// ======================================================
// 12. MOTIVO DE NO ENVÍO
// ======================================================

let motivoNoEnvio =
  null;


if (!enviarWhatsApp) {

  if (respuestaOmitida) {

    motivoNoEnvio =
      'RESPUESTA_OMITIDA_DUPLICADA';

  }

  else if (!vieneDeWhatsAppReal) {

    motivoNoEnvio =
      'EJECUCION_NO_ORIGINADA_EN_WEBHOOK_WHATSAPP';

  }

  else if (!vieneDeYCloud) {

    motivoNoEnvio =
      'ORIGEN_NO_ES_YCLOUD';

  }

  else if (!esTexto) {

    motivoNoEnvio =
      'TIPO_MENSAJE_NO_SOPORTADO';

  }

  else if (!telefonoDestino) {

    motivoNoEnvio =
      'TELEFONO_DESTINO_FALTANTE';

  }

  else if (!telefonoEmisor) {

    motivoNoEnvio =
      'TELEFONO_EMISOR_FALTANTE';

  }

  else if (!textoSalida) {

    motivoNoEnvio =
      'TEXTO_SALIDA_FALTANTE';

  }

  else {

    motivoNoEnvio =
      'DATOS_ENVIO_INCOMPLETOS';

  }

}


// ======================================================
// 13. BODY YCLOUD
// ======================================================

const bodyYCloud = {

  from:
    telefonoE164(
      telefonoEmisor
    ),

  to:
    telefonoE164(
      telefonoDestino
    ),

  type:
    tipoYCloud,

  text: {
    body:
      textoSalida
  }

};


// ======================================================
// 13.1 IMAGEN INFORMATIVA (ANTES DEL TEXTO)
// ======================================================
//
// Solo cuando "Resolver contexto comercial" marcó
// enviar_imagen_informativa (material o metodología) y el
// texto sí se envía. "YCloud Enviar imagen" continúa ante
// error, así que el texto sale aunque la imagen falle.
//
// ======================================================

const urlImagenInformativa =
  decision.enviar_imagen_informativa === true
    ? textoONull(decision.imagen_informativa_url)
    : null;

const enviarImagen =
  enviarWhatsApp &&
  urlImagenInformativa !== null;

const bodyYCloudImagen =
  enviarImagen
    ? {
        from:
          telefonoE164(
            telefonoEmisor
          ),

        to:
          telefonoE164(
            telefonoDestino
          ),

        type:
          'image',

        image: {
          link:
            urlImagenInformativa
        }
      }
    : null;


// ======================================================
// 14. DIAGNÓSTICO DE ORIGEN
// ======================================================
//
// Muy útil mientras estabilizamos todas las rutas.
//
// Permite ver exactamente de dónde se recuperó teléfono.
//
// ======================================================

let telefonoDestinoOrigen =
  null;


if (
  limpiarTelefono(
    input.telefono_destino ??
    input.telefono
  )
) {

  telefonoDestinoOrigen =
    'INPUT_ACTUAL';

}

else if (
  limpiarTelefono(
    decision.telefono
  )
) {

  telefonoDestinoOrigen =
    'RECUPERAR_DECISION_COMERCIAL';

}

else if (
  limpiarTelefono(
    prepararMensajeHumano.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_MENSAJE_TRANSICION_HUMANO';

}

else if (
  limpiarTelefono(
    prepararDerivacionHumana.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_DERIVACION_HUMANA';

}

else if (
  limpiarTelefono(
    guardarContextoHandoff.telefono
  )
) {

  telefonoDestinoOrigen =
    'GUARDAR_CONTEXTO_HANDOFF';

}

else if (
  limpiarTelefono(
    prepararContextoHandoff.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_CONTEXTO_HANDOFF';

}

else if (
  limpiarTelefono(
    entradaWhatsApp.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_ENTRADA_WHATSAPP';

}

else {

  telefonoDestinoOrigen =
    'EVENTO_WHATSAPP';

}


// ======================================================
// 15. SALIDA
// ======================================================

return [
  {
    json: {

      // ----------------------------------------------
      // IDENTIFICACIÓN
      // ----------------------------------------------

      mensaje_db_id:
        mensajeDbId,

      conversacion_id:
        conversacionId,


      // ----------------------------------------------
      // DESTINO / EMISOR
      // ----------------------------------------------

      telefono_destino:
        telefonoDestino,

      telefono_destino_origen:
        telefonoDestinoOrigen,

      telefono_emisor:
        telefonoEmisor,

      telefono_destino_e164:
        telefonoE164(
          telefonoDestino
        ),

      telefono_emisor_e164:
        telefonoE164(
          telefonoEmisor
        ),


      // ----------------------------------------------
      // CONTENIDO
      // ----------------------------------------------

      texto_salida:
        textoSalida,

      tipo_salida:
        tipoOriginal,

      tipo_ycloud:
        tipoYCloud,


      // ----------------------------------------------
      // CONTROL
      // ----------------------------------------------

      proveedor_whatsapp:
        proveedor,

      viene_de_ycloud:
        vieneDeYCloud,

      viene_de_whatsapp_real:
        vieneDeWhatsAppReal,

      enviar_whatsapp:
        enviarWhatsApp,

      motivo_no_envio:
        motivoNoEnvio,


      // ----------------------------------------------
      // REQUEST YCLOUD
      // ----------------------------------------------

      ycloud_request: {
        body:
          bodyYCloud
      },

      enviar_imagen:
        enviarImagen,

      imagen_informativa:
        enviarImagen
          ? textoONull(decision.imagen_informativa)
          : null,

      ycloud_request_imagen: {
        body:
          bodyYCloudImagen
      },


      // ----------------------------------------------
      // DIAGNÓSTICO
      // ----------------------------------------------

      waba_id:
        eventoWhatsApp.waba_id ??
        metaWhatsApp.waba_id ??
        null,

      mensaje_entrante_id:
        eventoWhatsApp.mensaje_id ??
        entradaWhatsApp.mensaje_externo_id ??
        null,

      preparado_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// NODO N8N: Peparar notificacion humano
// ARCHIVO: code/06-derivacion-humana/preparar-notificacion-humano.js
// VERSION: 2.1
// RESPONSABILIDAD:
// - Construir una notificación INTERNA para Pegaso cuando una conversación requiere intervención humana
// - Clasificar la alerta en una categoría (INTERESADO_PAGO, PAGO_REPORTADO, SOLICITA_CONTACTO, ARCHIVO_REQUIERE_REVISION, NEGOCIACION, RECLAMO, REVISION_GENERAL)
// - Ajustar la prioridad de la alerta según la categoría
// - Generar asunto, texto plano y HTML del email con datos del prospecto y su último mensaje
// - Marcar canal_notificacion = EMAIL (destinos previstos: email Brevo/Resend; WhatsApp interno a futuro)
// - NO enviar el correo (lo hacen los nodos HTTP "Brevo - Enviar notificación humana" y, como respaldo, "Resend - Enviar notificación humana")
// - NO enviar nada al prospecto
// ======================================================

const input =
  $input.first().json;


// ======================================================
// 1. HELPERS
// ======================================================

function texto(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


// ======================================================
// 2. DATOS PRINCIPALES
// ======================================================

const conversacionId =
  numeroONull(
    input.conversacion_id
  );


const prospectoId =
  numeroONull(
    input.prospecto_id
  );


const nombre =
  texto(
    input.prospecto_nombre
  ) ??
  texto(
    input.nombre_whatsapp
  ) ??
  'Sin nombre';


const telefono =
  texto(
    input.telefono
  ) ??
  'No disponible';


const ciudad =
  texto(
    input.prospecto_ciudad
  ) ??
  texto(
    input.ciudad_detectada
  ) ??
  'No registrada';


const intencion =
  (
    texto(
      input.intencion
    ) ??
    'OTRO'
  ).toUpperCase();


const motivo =
  (
    texto(
      input.handoff_motivo
    ) ??
    texto(
      input.motivo_derivacion
    ) ??
    'OTRO'
  ).toUpperCase();


const prioridad =
  (
    texto(
      input.handoff_prioridad
    ) ??
    texto(
      input.prioridad_derivacion
    ) ??
    'NORMAL'
  ).toUpperCase();


const mensajeCliente =
  texto(
    input.handoff_mensaje_cliente
  ) ??
  texto(
    input.mensaje_actual
  ) ??
  'No disponible';


const clasificacionProspecto =
  texto(
    input.clasificacion_prospecto
  ) ??
  texto(
    input.prospecto_clasificacion
  ) ??
  null;


// ======================================================
// 3. CLASIFICAR TIPO DE ALERTA
// ======================================================

let categoriaNotificacion =
  'REVISION_GENERAL';


if (
  [
    'SOLICITA_CUENTA',
    'SOLICITA_DATOS_BANCARIOS',
    'PIDE_CUENTA',
    'PIDE_NUMERO_CUENTA',
    'INTERES_PAGO'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'INTERESADO_PAGO';

}


else if (
  [
    'REPORTA_PAGO',
    'ENVIA_COMPROBANTE',
    'COMPROBANTE_PAGO',
    'PAGO_REALIZADO'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'PAGO_REPORTADO';

}


else if (
  [
    'SOLICITA_LLAMADA',
    'QUIERE_LLAMAR',
    'QUIERE_QUE_LO_LLAMEN',
    'ATENCION_TELEFONICA'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'SOLICITA_CONTACTO';

}


else if (
  [
    'IMAGEN_REQUIERE_REVISION',
    'ARCHIVO_NO_PROCESABLE',
    'ARCHIVO_DISENO',
    'ARCHIVO_NO_ANALIZABLE',
    'IMAGEN_NO_ANALIZABLE',
    'ARCHIVO_REQUIERE_REVISION',
    'DISENO_REQUIERE_REVISION'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'ARCHIVO_REQUIERE_REVISION';

}


else if (
  [
    'NEGOCIACION',
    'NEGOCIAR_PRECIO',
    'PRECIO_ESPECIAL',
    'DESCUENTO'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'NEGOCIACION';

}


else if (
  [
    'RECLAMO',
    'INCONVENIENTE',
    'QUEJA'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'RECLAMO';

}


// ======================================================
// 4. RESOLVER PRIORIDAD REAL
// ======================================================

let prioridadFinal =
  prioridad;


if (
  categoriaNotificacion ===
  'PAGO_REPORTADO'
) {

  prioridadFinal =
    'ALTA';

}


else if (
  categoriaNotificacion ===
  'INTERESADO_PAGO'
) {

  prioridadFinal =
    'ALTA';

}


else if (
  categoriaNotificacion ===
  'RECLAMO'
) {

  prioridadFinal =
    'ALTA';

}


