function numero(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function medidaTexto(valor) {

  const n =
    numero(valor);

  if (n === null) {
    return '';
  }

  if (
    Number.isInteger(n)
  ) {
    return String(n);
  }

  return String(
    Number(
      n.toFixed(2)
    )
  );
}


// ======================================================
// 3. REGLAS DE PRODUCCIÓN
// ======================================================

const MEDIDA_MINIMA_CM = 2;


