// ======================================================
// 6. HELPERS GENERALES
// ======================================================

function numero(valor) {

  const n =
    Number(
      valor ?? 0
    );

  return Number.isFinite(n)
    ? n
    : 0;

}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;

}


function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;

}


// ------------------------------------------------------
// DINERO
// ------------------------------------------------------

function dinero(valor) {

  return `$${numero(valor).toFixed(2)}`;

}


// ------------------------------------------------------
// CANTIDAD
// ------------------------------------------------------

function cantidadTexto(valor) {

  return numero(valor)
    .toLocaleString(
      'es-EC'
    );

}


// ------------------------------------------------------
// MEDIDA
// ------------------------------------------------------

function medidaTexto(valor) {

  const n =
    numero(valor);

  if (
    Number.isInteger(n)
  ) {

    return String(n);

  }

  return String(
    Number(
      n.toFixed(2)
    )
  );

}


// ======================================================
// 7. DESCRIBIR MEDIDA + FORMA
// ======================================================

function describirForma(detalle) {

  const forma =
    String(
      detalle.forma ||
      'RECTANGULAR'
    )
      .trim()
      .toUpperCase();


  const ancho =
    medidaTexto(
      detalle.ancho_cm
    );


  const alto =
    medidaTexto(
      detalle.alto_cm
    );


  // ----------------------------------------------------
  // CIRCULAR
  // ----------------------------------------------------

  if (
    forma === 'CIRCULAR'
  ) {

    return `${ancho} cm circulares`;

  }


  // ----------------------------------------------------
  // REDONDEADAS
  // ----------------------------------------------------

  if (
    forma === 'REDONDEADA' ||
    forma === 'REDONDEADO' ||
    forma === 'PUNTAS_REDONDEADAS'
  ) {

    return (
      `${ancho}x${alto} cm ` +
      `con puntas redondeadas`
    );

  }


  // ----------------------------------------------------
  // TROQUELADAS / IRREGULARES
  // ----------------------------------------------------

  if (
    forma === 'TROQUELADA' ||
    forma === 'TROQUELADO' ||
    forma === 'IRREGULAR'
  ) {

    return (
      `${ancho}x${alto} cm ` +
      `troqueladas`
    );

  }


  // ----------------------------------------------------
  // RECTANGULAR / CUADRADA
  // ----------------------------------------------------

  return (
    `${ancho}x${alto} cm ` +
    `rectangulares`
  );

}


// ======================================================
// 8. DETECTAR COTIZACIONES RECIENTES
// ======================================================
//
