  );


const contactoId =
  numeroONull(
    guardado.contacto_id
  ) ??
  numeroONull(
    unificarConversacion.contacto_id
  ) ??
  numeroONull(
    prepararConversacion.contacto_id
  ) ??
  numeroONull(
    unificarProspecto.contacto_id
  ) ??
  numeroONull(
    resolverProspecto.contacto_id
  );


// ------------------------------------------------------
// Datos de contacto
// ------------------------------------------------------

const telefono =
  textoONull(
    guardado.telefono
  ) ??
  textoONull(
    unificarConversacion.telefono
  ) ??
  textoONull(
    prepararConversacion.telefono
  ) ??
  textoONull(
    unificarProspecto.telefono
  ) ??
  textoONull(
    resolverProspecto.telefono
  );


const nombreWhatsapp =
  textoONull(
    guardado.nombre_whatsapp
  ) ??
  textoONull(
    unificarConversacion.nombre_whatsapp
  ) ??
  textoONull(
    prepararConversacion.nombre_whatsapp
  ) ??
  textoONull(
    unificarProspecto.nombre_whatsapp
  ) ??
  textoONull(
    resolverProspecto.nombre_whatsapp
  );


// ======================================================
// 4. CONFIGURACIÓN
// ======================================================

let config = {};

try {
  config =
    $('Resolver permiso automatización').first().json ?? {};
} catch (error) {
  config = {};
}

const turnoMaxAntiguedadSegundos =
  numeroONull(
    config.turno_max_antiguedad_segundos
  ) ??
  TURNO_MAX_ANTIGUEDAD_SEGUNDOS_DEFECTO;


// ======================================================
// 5. MENSAJES DE LA CONVERSACIÓN
// ======================================================
//
// El input principal de este nodo son las filas devueltas por:
//
// Recuperar historial conversación
//
// ======================================================

const filas =
  $input.all()
    .map(
      item => item.json
    )
    .filter(
      fila =>
        fila &&
        numeroONull(
          fila.id
        ) !== null
    )
    .map(
      fila => ({
        ...fila,
        id:
          Number(
            fila.id
          )
      })
    )
    .sort(
      (a, b) =>
        a.id - b.id
    );


const miFila =
  filas.find(
    fila =>
      fila.id === miId
  );

if (!miFila) {
  throw new Error(
    `Resolver turno conversacional: el mensaje ${miId} no aparece en "Recuperar historial conversación".`
  );
}


const conversacionId =
  numeroONull(
    guardado.conversacion_id
  ) ??
  numeroONull(
    miFila.conversacion_id
  ) ??
  numeroONull(
    unificarConversacion.conversacion_id
  ) ??
  numeroONull(
    unificarConversacion.id
  ) ??
  numeroONull(
    prepararConversacion.conversacion_id
  );


// ======================================================
// 6. VALIDACIÓN MÍNIMA DE IDENTIDAD
// ======================================================
//
// conversacion_id es indispensable.
//
// prospecto_id se conserva siempre que exista.
//
// No lanzamos error aquí por prospecto_id porque:
// - el debounce puede ser reutilizable
// - la derivación humana sí puede exigirlo después
//
// ======================================================

if (
  conversacionId === null ||
  conversacionId <= 0
) {
  throw new Error(
    'Resolver turno conversacional: no se pudo resolver conversacion_id.'
  );
}


// ======================================================
// 7. ENTRANTES VÁLIDOS
// ======================================================
//
// Eliminamos duplicados por mensaje_externo_id.
//
// ======================================================

const externosVistos =
  new Set();

const entrantes =
  [];

let miEsDuplicado =
  false;


for (const fila of filas) {

  if (
    direccion(
      fila
    ) !== 'ENTRANTE'
  ) {
    continue;
  }

  const externo =
    textoONull(
      fila.mensaje_externo_id
    );

  const duplicado =
    externo !== null &&
    externosVistos.has(
      externo
    );

  if (
    externo !== null
  ) {
    externosVistos.add(
      externo
    );
  }

  if (duplicado) {

    if (
      fila.id === miId
    ) {
      miEsDuplicado =
        true;
    }

    continue;
  }

  entrantes.push(
    fila
  );
}


const ultimoEntranteId =
  entrantes.length > 0
    ? entrantes[
        entrantes.length - 1
      ].id
    : null;


// ======================================================
// 8. CONTRATO BASE DE IDENTIDAD
// ======================================================

const identidad = {

  conversacion_id:
    conversacionId,

  prospecto_id:
    prospectoId,

  cliente_id:
    clienteId,

  contacto_id:
    contactoId,

  telefono:
    telefono,

  nombre_whatsapp:
    nombreWhatsapp
};


// ======================================================
// 9. SALIDA SIN PROCESAR
// ======================================================

function noProcesar(
  resultado,
  motivo,
  extra = {}
) {

  return [
    {
      json: {

        success:
          true,

        flujo:
          'DEBOUNCE',

        ...identidad,

        mensaje_id:
          miId,

        continuar_procesamiento:
          false,

        resultado_turno:
          resultado,

        motivo_no_procesamiento:
          motivo,

        respuesta_automatica:
          false,

        mensaje_guardado:
          true,

        ultimo_entrante_id:
          ultimoEntranteId,

        ...extra,

        turno_resuelto_at:
          new Date().toISOString()

      }
    }
  ];
}


if (miEsDuplicado) {

  return noProcesar(
    'DUPLICADO',
    'MENSAJE_DUPLICADO',
    {
      mensaje_externo_id:
        textoONull(
          miFila.mensaje_externo_id
        )
    }
  );
}


if (
  ultimoEntranteId !== miId
) {

  return noProcesar(
    'DEBOUNCE_SUPERSEDED',
    'MENSAJE_POSTERIOR_RECIBIDO',
    {
      mensaje_posterior_id:
        ultimoEntranteId
    }
  );
}


// ======================================================
// 9.1 GUARDIA HUMANA POSTERIOR A LA ESPERA
// ======================================================

const salientesHumanos =
  filas.filter(
    fila =>
      direccion(fila) === 'SALIENTE' &&
      origenSaliente(fila) === 'HUMANO'
  );

const ultimoHumano =
  salientesHumanos.length > 0
    ? salientesHumanos[salientesHumanos.length - 1]
    : null;

const ultimaReactivacionId =
  filas
    .filter(
      fila =>
        direccion(fila) === 'SALIENTE' &&
        String(fila.contenido ?? '')
          .trim()
          .startsWith(PREFIJO_BOT_REACTIVADO)
    )
    .reduce(
      (max, fila) => Math.max(max, fila.id),
      0
    );

if (
  ultimoHumano &&
  ultimoHumano.id > ultimaReactivacionId
) {

  const fechaHumano =
    fechaMs(ultimoHumano.enviado_at);

  const humanoPosterior =
    ultimoHumano.id > miId;

  const humanoReciente =
    fechaHumano !== null &&
    Date.now() - fechaHumano <= HUMANO_ACTIVO_MINUTOS * 60 * 1000;

  if (humanoPosterior || humanoReciente) {

    return noProcesar(
      'ATENCION_HUMANA',
      humanoPosterior
        ? 'HUMANO_RESPONDIO_DURANTE_ESPERA'
        : 'INTERVENCION_HUMANA_RECIENTE',
      {
        ultimo_saliente_humano_id:
          ultimoHumano.id
      }
    );
  }
}


// ======================================================
// 10. ARMAR EL TURNO
// ======================================================
//
// Turno = ENTRANTE válidos que cumplen:
//
// - id <= este mensaje
// - id > último SALIENTE anterior a este mensaje
// - procesado = false
// - no más antiguos que turno_max_antiguedad_segundos
//
// ======================================================

const ultimoSalienteAnteriorId =
  filas
    .filter(
      fila =>
        direccion(
          fila
        ) === 'SALIENTE' &&
        origenSaliente(
          fila
        ) !== 'AUTOMATICO' &&
        fila.id < miId
    )
    .reduce(
      (max, fila) =>
        Math.max(
          max,
          fila.id
        ),
      0
    );


const miFecha =
  fechaMs(
    guardado.enviado_at
  ) ??
  fechaMs(
    miFila.enviado_at
  );


let descartadosPorAntiguedad =
  0;


const turno =
  entrantes.filter(
    fila => {

      if (
        fila.id > miId ||
        fila.id <= ultimoSalienteAnteriorId
      ) {
        return false;
      }

      if (
        verdadero(
          fila.procesado
        )
      ) {
        return false;
      }

      const fecha =
        fechaMs(
          fila.enviado_at
        );

      if (
        miFecha !== null &&
        fecha !== null &&
        miFecha - fecha >
          turnoMaxAntiguedadSegundos * 1000
      ) {

        descartadosPorAntiguedad++;

        return false;
      }

      return true;
    }
  );


if (
  !turno.some(
    fila =>
      fila.id === miId
  )
) {

  return noProcesar(
    'YA_PROCESADO',
    'TURNO_YA_PROCESADO'
  );
}


// ======================================================
// 11. NORMALIZAR MENSAJES DEL TURNO
// ======================================================

const turnoMensajes =
  turno.map(
    fila => ({

      id:
        fila.id,

      contenido:
        String(
          fila.contenido ?? ''
        ).trim(),

      tipo:
        textoONull(
          fila.tipo
        ) ??
        'TEXTO',

      enviado_at:
        fila.enviado_at ??
        null

    })
  );


const turnoTexto =
  turnoMensajes
    .map(
      m =>
        m.contenido
    )
    .filter(
      Boolean
    )
    .join(
      '\n'
    );


// ======================================================
// 12. SALIDA PARA PROCESAR
// ======================================================

return [
  {
    json: {

      success:
        true,

      flujo:
        'DEBOUNCE',

      // -----------------------------------------------
      // IDENTIDAD
      // -----------------------------------------------

      ...identidad,


      // -----------------------------------------------
      // MENSAJE ACTUAL
      // -----------------------------------------------

      mensaje_id:
        miId,


      // -----------------------------------------------
      // CONTROL DE DEBOUNCE
      // -----------------------------------------------

      continuar_procesamiento:
        true,

      resultado_turno:
        'PROCESAR',

      motivo_no_procesamiento:
        null,

      ultimo_entrante_id:
        ultimoEntranteId,

      ultimo_saliente_anterior_id:
        ultimoSalienteAnteriorId ||
        null,


      // -----------------------------------------------
      // TURNO
      // -----------------------------------------------

      turno_mensaje_ids:
        turnoMensajes.map(
          m => m.id
        ),

      turno_desde_id:
        turnoMensajes[0]?.id ??
        miId,

      turno_hasta_id:
        miId,

      cantidad_mensajes_turno:
        turnoMensajes.length,

      turno_mensajes:
        turnoMensajes,

      turno_texto:
        turnoTexto,

      mensajes_descartados_por_antiguedad:
        descartadosPorAntiguedad,


      // -----------------------------------------------
      // CONTROL
      // -----------------------------------------------

      turno_resuelto_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// NODO N8N: Preparar media del turno
// ARCHIVO: code/03-conversacion/preparar-media-turno.js
// VERSION: 1.0
// RESPONSABILIDAD:
// - Tras "IF: ¿Procesar turno?" (true), buscar en el turno las imágenes todavía sin analizar (tipo IMAGEN con línea "[MEDIA_PENDIENTE] {json}")
// - Revalidar cada una: MIME JPEG/PNG/WebP y enlace https://api.ycloud.com/v2/whatsapp/media/download/ (anti-SSRF); máximo MAX_IMAGENES_POR_TURNO
// - Emitir un item por imagen a analizar (analizar_imagen = true) con mensaje_id, enlace, MIME, caption y el contexto comercial breve para la IA visual
// - Si no hay ninguna: un solo item con analizar_imagen = false (el IF siguiente va directo a "Preparar contexto IA")
// - Las imágenes que no pasan la validación o exceden el máximo quedan pendientes: "Preparar contexto IA" las marca para revisión humana
// - NO descargar, NO llamar a la IA, NO escribir en PostgreSQL
// ======================================================

const MAX_IMAGENES_POR_TURNO = 3;

const MIME_IMAGEN_SOPORTADOS = ['image/jpeg', 'image/png', 'image/webp'];

const LINK_YCLOUD_PERMITIDO =
  /^https:\/\/api\.ycloud\.com\/v2\/whatsapp\/media\/download\/[A-Za-z0-9_-]+(\?[A-Za-z0-9%._~&=+-]*)?$/;

const PREFIJO_PENDIENTE = '[MEDIA_PENDIENTE] ';

const LARGO_MAXIMO_TEXTO_TURNO = 1500;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {
  if (valor === undefined || valor === null) {
    return null;
  }

  const limpio = String(valor).trim();

  return limpio !== '' ? limpio : null;
}

function lineas(contenido) {
  return String(contenido ?? '').split('\n');
}

function esLineaDeSistema(linea) {
  return /^\[(MEDIA_PENDIENTE|CONTEXTO DE IMAGEN|ARCHIVO NO PROCESABLE)[\]\s·]/.test(linea.trim());
}

function leerPendiente(contenido) {
  const linea = lineas(contenido)
    .map(l => l.trim())
    .find(l => l.startsWith(PREFIJO_PENDIENTE));

  if (!linea) {
    return null;
  }

  try {
    const datos = JSON.parse(linea.slice(PREFIJO_PENDIENTE.length));

    return datos && typeof datos === 'object' ? datos : null;
  } catch (error) {
    return null;
  }
}

function captionDe(contenido) {
  const primera = lineas(contenido)[0] ?? '';

  return primera.replace(/^\[IMAGEN\]\s*/, '').trim();
}


// ======================================================
// 2. TURNO
// ======================================================

let turno = {};

try {
  turno = $('Resolver turno conversacional').first().json ?? {};
} catch (error) {
  turno = $input.first().json ?? {};
}

const turnoMensajes = Array.isArray(turno.turno_mensajes)
  ? turno.turno_mensajes
  : [];


// ======================================================
// 3. CONTEXTO PARA LA IA VISUAL
// ======================================================
//
// Lo que el cliente escribió en el turno (texto y captions, sin
// líneas de sistema) y lo poco de la memoria comercial que ayuda a
// interpretar la imagen. Nunca el enlace.
// ======================================================

const textoTurnoCliente = turnoMensajes
  .map(m => lineas(m.contenido)
    .filter(l => !esLineaDeSistema(l))
    .map(l => l.replace(/^\[(IMAGEN|AUDIO|VIDEO|DOCUMENTO)\]\s*/, '').trim())
    .filter(Boolean)
    .join(' '))
  .filter(Boolean)
  .join('\n')
  .slice(0, LARGO_MAXIMO_TEXTO_TURNO);

let conversacion = {};

try {
  conversacion = $('Preparar conversación').first().json ?? {};
} catch (error) {
  conversacion = {};
}

const memoria =
  conversacion.contexto_comercial &&
  typeof conversacion.contexto_comercial === 'object'
    ? conversacion.contexto_comercial
    : {};

const cotizacionPrevia = memoria.cotizacion ?? {};

const contextoComercialBreve = [
  textoONull(conversacion.prospecto_producto_interes ?? memoria.prospecto?.producto_interes)
    ? `Producto de interés: ${textoONull(conversacion.prospecto_producto_interes ?? memoria.prospecto?.producto_interes)}.`
    : null,
  cotizacionPrevia.ancho_cm && cotizacionPrevia.alto_cm
    ? `Ya conversamos de etiquetas de ${cotizacionPrevia.ancho_cm}x${cotizacionPrevia.alto_cm} cm.`
    : null
]
  .filter(Boolean)
  .join(' ') || 'Sin datos comerciales previos.';


// ======================================================
// 4. IMÁGENES A ANALIZAR
// ======================================================

const candidatas = [];
let descartadas = 0;

for (const mensaje of turnoMensajes) {
  if (String(mensaje.tipo ?? '').toUpperCase() !== 'IMAGEN') {
    continue;
  }

  const pendiente = leerPendiente(mensaje.contenido);

  if (!pendiente) {
    continue;
  }

  const mime = textoONull(pendiente.mime_type)?.toLowerCase() ?? null;
  const link = textoONull(pendiente.link);

  const valida =
    MIME_IMAGEN_SOPORTADOS.includes(mime) &&
    link !== null &&
    link.length <= 2048 &&
    LINK_YCLOUD_PERMITIDO.test(link);

  if (!valida || candidatas.length >= MAX_IMAGENES_POR_TURNO) {
    descartadas++;
    continue;
  }

  candidatas.push({
    mensaje_id: Number(mensaje.id),
    mime_type: mime,
    media_link: link,
    caption: captionDe(mensaje.contenido),
    contenido_base: lineas(mensaje.contenido)[0].trim()
  });
}


// ======================================================
// 5. SALIDA
// ======================================================

if (candidatas.length === 0) {
  return [
    {
      json: {
        analizar_imagen: false,
        imagenes_por_analizar: 0,
        imagenes_descartadas: descartadas,
        conversacion_id: turno.conversacion_id ?? null
      }
    }
  ];
}

return candidatas.map((imagen, indice) => ({
  json: {
    analizar_imagen: true,
    imagenes_por_analizar: candidatas.length,
    imagenes_descartadas: descartadas,
    indice_imagen: indice,
    conversacion_id: turno.conversacion_id ?? null,
    ...imagen,
    texto_turno_cliente: textoTurnoCliente || '(el cliente no escribió texto)',
    contexto_comercial_breve: contextoComercialBreve
  }
}));

// ======================================================
// NODO N8N: VALIDAR ANÁLISIS IMAGEN GROQ
// PEGASO ADHESIVOS
// ARCHIVO: code/03-conversacion/validar-analisis-imagen.js
// VERSION: 2.1
// ======================================================
//
// RESPONSABILIDAD:
//
// - Recibir la salida de "Analizar imagen Groq Basic LLM".
// - Validar que el análisis visual cumpla el contrato.
// - Recuperar el mensaje original desde "Preparar media del turno".
// - NO necesita recibir nuevamente el binario.
// - NO analiza la imagen.
// - NO decide la acción comercial.
// - NO deriva directamente a humano.
// - Si Groq falla, devuelve analisis_valido = false para
//   permitir que el IF envíe el flujo a DeepSeek.
// - Extraer y normalizar medidas escritas explícitamente en la imagen
//   sin estimarlas ni alterar el resto del contrato visual.
//
// IMPORTANTE:
//
// Esta misma lógica puede reutilizarse después para:
//
//   Validar análisis imagen DeepSeek
//   Validar análisis imagen OpenAI
//
// cambiando únicamente PROVEEDOR_ANALISIS.
//
// ======================================================


const PROVEEDOR_ANALISIS = 'GROQ';


// ======================================================
// 1. CONSTANTES
// ======================================================

const CONTENIDOS_VALIDOS = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS',
  'COMPROBANTE_PAGO',
  'EVIDENCIA_RECLAMO',
  'CAPTURA_DE_PANTALLA',
  'NO_RELACIONADO',
  'NO_DETERMINABLE'
];


const MOTIVOS_REVISION_VALIDOS = [
  'NINGUNO',
  'IMAGEN_ILEGIBLE',
  'IMAGEN_AMBIGUA',
  'DISENO_COMPLEJO',
  'OTRO'
];


const CONFIANZAS_VALIDAS = [
  'ALTA',
  'MEDIA',
  'BAJA'
];


const CONTENIDOS_ETIQUETA = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS'
];


const LARGO_MAXIMO_RESUMEN = 500;
const LARGO_MAXIMO_CAMPO = 250;


// ======================================================
// 2. HELPERS
// ======================================================

function textoONull(
  valor,
  largo = LARGO_MAXIMO_CAMPO
) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  if (!limpio) {
    return null;
  }

  return limpio.slice(
    0,
    largo
  );
}


function numeroONull(
  valor
) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleanoONull(
  valor
) {

  if (
    valor === true ||
    valor === false
  ) {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return null;
}


function medidaONull(
  valor
) {

  const n =
    numeroONull(valor);

  if (
    n === null ||
    n <= 0
  ) {
    return null;
  }

  return n;
}


function quitarCorchetes(
  valor
) {

  const texto =
    textoONull(valor);

  if (!texto) {
    return null;
  }

  return texto
    .replace(/\[/g, '(')
    .replace(/\]/g, ')');
}


function obtenerNodo(
  nombre
) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


// ======================================================
// 3. LEER RESPUESTA DEL LLM
// ======================================================
//
// Dependiendo del nodo de n8n y del Output Parser,
// la respuesta puede llegar:
//
// {
//   output: {...}
// }
//
// {
//   output: "{...}"
// }
//
// {
//   text: "{...}"
// }
//
// o directamente como objeto.
//
// También puede llegar:
//
// {
//   error: ...
// }
//
// si el nodo está configurado con Continue On Fail.
//
// ======================================================

function leerSalidaIA(
  json
) {

  if (
    !json ||
    typeof json !== 'object'
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  // --------------------------------------------------
  // Error explícito del nodo
  // --------------------------------------------------

  if (json.error) {

    const detalle =
      textoONull(
        json.error?.message ??
        json.error
      );

    return {
      error:
        'IA_FALLIDA',

      detalle
    };

  }


  // --------------------------------------------------
  // Buscar salida probable
  // --------------------------------------------------

  let salida =
    json.output ??
    json.text ??
    json.response ??
    json.result ??
    json.data ??
    null;


  // Algunos nodos pueden devolver directamente
  // el contrato en el root.

  if (
    salida === null &&
    json.contenido_detectado !== undefined
  ) {

    salida =
      json;

  }


  // --------------------------------------------------
  // Parsear JSON string
  // --------------------------------------------------

  if (
    typeof salida === 'string'
  ) {

    let limpio =
      salida.trim();


    limpio =
      limpio.replace(
        /^```(?:json)?\s*/i,
        ''
      );


    limpio =
      limpio.replace(
        /\s*```$/,
        ''
      );


    try {

      salida =
        JSON.parse(
          limpio
        );

    } catch (_) {

      return {
        error:
          'JSON_INVALIDO',

        detalle:
          limpio.slice(
            0,
            300
          )
      };

    }

  }


  // --------------------------------------------------
  // Validar que sea objeto
  // --------------------------------------------------

  if (
    !salida ||
    typeof salida !== 'object' ||
    Array.isArray(salida)
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  return {
    datos:
      salida
  };
}


// ======================================================
// 4. VALIDAR CONTRATO
// ======================================================

function validarContrato(
  datos
) {

  if (
    !CONTENIDOS_VALIDOS.includes(
      datos.contenido_detectado
    )
  ) {

    return (
      'contenido_detectado inválido'
    );

  }


  if (
    !CONFIANZAS_VALIDAS.includes(
      datos.confianza
    )
  ) {

    return (
      'confianza inválida'
    );

  }


  if (
    !MOTIVOS_REVISION_VALIDOS.includes(
      datos.motivo_revision
    )
  ) {

    return (
      'motivo_revision inválido'
    );

  }


  const camposBooleanos = [
    'envase_detectado',
    'etiqueta_visible',
    'diseno_visible',
    'requiere_revision_humana'
  ];


  for (
    const campo
    of camposBooleanos
  ) {

    if (
      booleanoONull(
        datos[campo]
      ) === null
    ) {

      return (
        `${campo} debe ser boolean`
      );

    }

  }


  const medidasNumericas = [
    'ancho_cm',
    'alto_cm',
    'diametro_cm'
  ];

  for (const campo of medidasNumericas) {
    const valor = datos[campo];

    if (
      valor !== undefined &&
      valor !== null &&
      medidaONull(valor) === null
    ) {
      return `${campo} debe ser number positivo o null`;
    }
  }


  if (
    !textoONull(
      datos.resumen_para_cerebro,
      LARGO_MAXIMO_RESUMEN
    )
  ) {

    return (
      'resumen_para_cerebro vacío'
    );

  }


  return null;
}


// ======================================================
// 5. RECUPERAR CONTEXTO ORIGINAL
// ======================================================
//
// El nodo LLM puede devolver únicamente:
//
// {
//   output: {...}
// }
//
// Por eso NO dependemos de que preserve:
//
// - mensaje_id
// - conversacion_id
// - caption
// - contenido_base
//
// Estos datos se recuperan desde:
//
// "Preparar media del turno"
//
// ======================================================

const origenes = (() => {

  try {

    return (
      $('Preparar media del turno')
        .all()
    );

  } catch (_) {

    return [];

  }

})();


// ======================================================
// 6. PROCESAR ITEMS
// ======================================================

const entradas =
  $input.all();


const resultados =
  entradas.map(
    (
      item,
      indice
    ) => {

      const input =
        item.json ?? {};


      const origen =
        origenes[indice]?.json ??
        origenes[0]?.json ??
        {};


      // ==================================================
      // IDENTIDAD
      // ==================================================

      const mensajeId =
        numeroONull(
          input.mensaje_id ??
          origen.mensaje_id
        );


      const conversacionId =
        numeroONull(
          input.conversacion_id ??
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base ??
          input.contenido_base,
          1500
        ) ??
        '[IMAGEN]';


      // ==================================================
      // LEER IA
      // ==================================================

      const lectura =
        leerSalidaIA(
          input
        );


      const errorContrato =
        lectura.datos
          ? validarContrato(
              lectura.datos
            )
          : null;


      // ==================================================
      // 7. ANÁLISIS INVÁLIDO
      // ==================================================
      //
      // Aquí NO derivamos humano todavía.
      //
      // Groq inválido
      //    ↓
      // IF false
      //    ↓
      // DeepSeek
      //
      // ==================================================

      if (
        lectura.error ||
        errorContrato
      ) {

        const errorAnalisis =
          lectura.error ??
          'SCHEMA_INVALIDO';


        const detalleError =
          lectura.detalle ??
          errorContrato ??
          null;


        return {
          json: {

            mensaje_id:
              mensajeId,

            conversacion_id:
              conversacionId,

            proveedor_analisis:
              PROVEEDOR_ANALISIS,


            // ------------------------------------------
            // RESULTADO
            // ------------------------------------------

            analisis_valido:
              false,

            requiere_revision:
              true,

            motivo_revision:
              'ANALISIS_NO_DISPONIBLE',


            // ------------------------------------------
            // DETECCIÓN
            // ------------------------------------------

            comprobante_detectado:
              false,

            contenido_detectado:
              null,

            confianza:
              null,

            analisis:
              null,


            // ------------------------------------------
            // ERROR
            // ------------------------------------------

            error_analisis:
              errorAnalisis,

            detalle_error:
              detalleError,


            // ------------------------------------------
            // CONTEXTO PARA SIGUIENTE FALLBACK
            // ------------------------------------------

            contenido_base:
              contenidoBase,

            contenido_actualizado:
              (
                `${contenidoBase}\n` +
                `[CONTEXTO DE IMAGEN · proveedor=${PROVEEDOR_ANALISIS} · ` +
                'revision=SI · motivo=ANALISIS_NO_DISPONIBLE] ' +
                'El análisis automático de esta imagen no estuvo disponible.'
              )

          }
        };

      }


      // ==================================================
      // 8. ANÁLISIS VÁLIDO
      // ==================================================

      const datos =
        lectura.datos;


      const contenido =
        datos.contenido_detectado;


      const confianza =
        datos.confianza;


      // ==================================================
      // 8.1 MEDIDAS ESCRITAS
      // ==================================================
      //
      // Compatibilidad:
      // - Si el schema nuevo trae medidas_detectadas, se respeta.
      // - Si un fallback antiguo solo trae medidas_visibles, se infiere.
      // - Si existen ancho/alto/diámetro explícitos, también cuenta como
      //   medida detectada.
      //
      // Nunca se calculan medidas desde proporciones de la fotografía.
      // ==================================================

      const anchoCm =
        medidaONull(
          datos.ancho_cm
        );

      const altoCm =
        medidaONull(
          datos.alto_cm
        );

      const diametroCm =
        medidaONull(
          datos.diametro_cm
        );

      const medidasVisiblesOriginales =
        textoONull(
          datos.medidas_visibles,
          180
        );

      const medidaEstructuradaExiste =
        anchoCm !== null ||
        altoCm !== null ||
        diametroCm !== null;

      const medidasDetectadas =
        booleanoONull(
          datos.medidas_detectadas
        ) === true ||
        medidasVisiblesOriginales !== null ||
        medidaEstructuradaExiste;

      const medidasVisiblesDerivadas =
        [
          anchoCm !== null
            ? `ancho ${anchoCm} cm`
            : null,
          altoCm !== null
            ? `alto ${altoCm} cm`
            : null,
          diametroCm !== null
            ? `diámetro ${diametroCm} cm`
            : null
        ]
          .filter(Boolean)
          .join(' · ');

      const medidasVisibles =
        medidasDetectadas
          ? (
              medidasVisiblesOriginales ??
              textoONull(
                medidasVisiblesDerivadas,
                180
              )
            )
          : null;


      // ==================================================
      // 9. NORMALIZAR ANÁLISIS
      // ==================================================

      const analisis = {

        contenido_detectado:
          contenido,


        producto_probable:
          contenido === 'NO_RELACIONADO'
            ? null
            : textoONull(
                datos.producto_probable
              ),


        envase_detectado:
          booleanoONull(
            datos.envase_detectado
          ) === true,


        forma_envase:
          textoONull(
            datos.forma_envase
          ),


        etiqueta_visible:
          booleanoONull(
            datos.etiqueta_visible
          ) === true,


        diseno_visible:
          booleanoONull(
            datos.diseno_visible
          ) === true,


        texto_visible_relevante:
          contenido === 'COMPROBANTE_PAGO'
            ? null
            : textoONull(
                datos.texto_visible_relevante
              ),


        colores_relevantes:
          Array.isArray(
            datos.colores_relevantes
          )
            ? datos.colores_relevantes
                .map(
                  color =>
                    textoONull(
                      color,
                      40
                    )
                )
                .filter(
                  Boolean
                )
                .slice(
                  0,
                  6
                )
            : [],


        medidas_detectadas:
          medidasDetectadas,

        ancho_cm:
          medidasDetectadas
            ? anchoCm
            : null,

        alto_cm:
          medidasDetectadas
            ? altoCm
            : null,

        diametro_cm:
          medidasDetectadas
            ? diametroCm
            : null,

        medidas_visibles:
          medidasVisibles,


        requiere_revision_humana:
          booleanoONull(
            datos.requiere_revision_humana
          ) === true,


        motivo_revision:
          datos.motivo_revision,


        confianza,


        resumen_para_cerebro:
          textoONull(
            datos.resumen_para_cerebro,
            LARGO_MAXIMO_RESUMEN
          )

      };


      // ==================================================
      // 10. DETERMINAR REVISIÓN HUMANA
      // ======================================================

      let motivoRevision =
        null;


      if (
        analisis
          .requiere_revision_humana === true
      ) {

        motivoRevision =
          analisis.motivo_revision !==
          'NINGUNO'
            ? analisis.motivo_revision
            : 'OTRO';

      }


      else if (
        confianza ===
        'BAJA'
      ) {

        motivoRevision =
          'CONFIANZA_BAJA';

      }


      else if (
        contenido ===
        'NO_DETERMINABLE'
      ) {

        motivoRevision =
          'IMAGEN_AMBIGUA';

      }


      const requiereRevision =
        motivoRevision !==
        null;


      // ==================================================
      // 11. CONSTRUIR CONTEXTO LEGIBLE
      // ======================================================

      const cabecera = [

        'CONTEXTO DE IMAGEN',

        `proveedor=${PROVEEDOR_ANALISIS}`,

        `contenido=${contenido}`,

        `confianza=${confianza}`,

        `revision=${
          requiereRevision
            ? 'SI'
            : 'NO'
        }`,

        requiereRevision
          ? `motivo=${motivoRevision}`
          : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' · '
        );


      const detalle = [

        quitarCorchetes(
          analisis
            .resumen_para_cerebro
        ),


        analisis.producto_probable
          ? (
              'Producto probable: ' +
              `${quitarCorchetes(
                analisis.producto_probable
              )}.`
            )
          : null,


        analisis.forma_envase
          ? (
              'Envase: ' +
              `${quitarCorchetes(
                analisis.forma_envase
              )}.`
            )
          : null,


        analisis.texto_visible_relevante
          ? (
              'Texto visible: "' +
              `${quitarCorchetes(
                analisis.texto_visible_relevante
              )}".`
            )
          : null,


        analisis
          .colores_relevantes
          .length > 0
            ? (
                'Colores: ' +
                `${analisis
                  .colores_relevantes
                  .join(', ')}.`
              )
            : null,


        analisis.medidas_detectadas
          ? (
              'Medidas escritas en la imagen: ' +
              [
                analisis.ancho_cm !== null
                  ? `ancho=${analisis.ancho_cm} cm`
                  : null,
                analisis.alto_cm !== null
                  ? `alto=${analisis.alto_cm} cm`
                  : null,
                analisis.diametro_cm !== null
                  ? `diámetro=${analisis.diametro_cm} cm`
                  : null,
                analisis.medidas_visibles
                  ? `texto="${quitarCorchetes(
                      analisis.medidas_visibles
                    )}"`
                  : null
              ]
                .filter(Boolean)
                .join(' · ') +
              '.'
            )
          : CONTENIDOS_ETIQUETA.includes(
              contenido
            )
              ? 'Sin medidas visibles.'
              : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' '
        );


      // ==================================================
      // 12. SALIDA
      // ======================================================

      return {
        json: {

          mensaje_id:
            mensajeId,

          conversacion_id:
            conversacionId,

          proveedor_analisis:
            PROVEEDOR_ANALISIS,


          // ------------------------------------------
          // RESULTADO
          // ------------------------------------------

          analisis_valido:
            true,

          requiere_revision:
            requiereRevision,

          motivo_revision:
            motivoRevision,


          // ------------------------------------------
          // DETECCIÓN
          // ------------------------------------------

          comprobante_detectado:
            contenido ===
            'COMPROBANTE_PAGO',

          contenido_detectado:
            contenido,

          confianza,

          medidas_detectadas:
            analisis.medidas_detectadas,

          ancho_cm:
            analisis.ancho_cm,

          alto_cm:
            analisis.alto_cm,

          diametro_cm:
            analisis.diametro_cm,

          medidas_visibles:
            analisis.medidas_visibles,

          medidas_para_cerebro: {
            detectadas:
              analisis.medidas_detectadas,

            ancho_cm:
              analisis.ancho_cm,

            alto_cm:
              analisis.alto_cm,

            diametro_cm:
              analisis.diametro_cm,

            texto_original:
              analisis.medidas_visibles,

            fuente:
              'IMAGEN'
          },


          // ------------------------------------------
          // ERROR
          // ------------------------------------------

          error_analisis:
            null,

          detalle_error:
            null,


          // ------------------------------------------
          // ANÁLISIS NORMALIZADO
          // ------------------------------------------

          analisis,


          // ------------------------------------------
          // CONTEXTO
          // ------------------------------------------

          contenido_base:
            contenidoBase,

          contenido_actualizado:
            (
              `${contenidoBase}\n` +
              `[${cabecera}] ${detalle}`
            )

        }
      };

    }
  );


return resultados;

// ======================================================
// NODO N8N: VALIDAR ANÁLISIS IMAGEN GROQ
// PEGASO ADHESIVOS
// ARCHIVO: code/03-conversacion/validar-analisis-imagen.js
// VERSION: 2.1
// ======================================================
//
// RESPONSABILIDAD:
//
// - Recibir la salida de "Analizar imagen Groq Basic LLM".
// - Validar que el análisis visual cumpla el contrato.
// - Recuperar el mensaje original desde "Preparar media del turno".
// - NO necesita recibir nuevamente el binario.
// - NO analiza la imagen.
// - NO decide la acción comercial.
// - NO deriva directamente a humano.
// - Si Groq falla, devuelve analisis_valido = false para
//   permitir que el IF envíe el flujo a DeepSeek.
// - Extraer y normalizar medidas escritas explícitamente en la imagen
//   sin estimarlas ni alterar el resto del contrato visual.
//
// IMPORTANTE:
//
// Esta misma lógica puede reutilizarse después para:
//
//   Validar análisis imagen DeepSeek
//   Validar análisis imagen OpenAI
//
// cambiando únicamente PROVEEDOR_ANALISIS.
//
// ======================================================


const PROVEEDOR_ANALISIS = 'GROQ';


// ======================================================
// 1. CONSTANTES
// ======================================================

const CONTENIDOS_VALIDOS = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS',
  'COMPROBANTE_PAGO',
  'EVIDENCIA_RECLAMO',
  'CAPTURA_DE_PANTALLA',
  'NO_RELACIONADO',
  'NO_DETERMINABLE'
];


const MOTIVOS_REVISION_VALIDOS = [
  'NINGUNO',
  'IMAGEN_ILEGIBLE',
  'IMAGEN_AMBIGUA',
  'DISENO_COMPLEJO',
  'OTRO'
];


const CONFIANZAS_VALIDAS = [
  'ALTA',
  'MEDIA',
  'BAJA'
];


const CONTENIDOS_ETIQUETA = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS'
];


const LARGO_MAXIMO_RESUMEN = 500;
const LARGO_MAXIMO_CAMPO = 250;


// ======================================================
// 2. HELPERS
// ======================================================

function textoONull(
  valor,
  largo = LARGO_MAXIMO_CAMPO
) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  if (!limpio) {
    return null;
  }

  return limpio.slice(
    0,
    largo
  );
}


function numeroONull(
  valor
) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleanoONull(
  valor
) {

  if (
    valor === true ||
    valor === false
  ) {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return null;
}


function medidaONull(
  valor
) {

  const n =
    numeroONull(valor);

  if (
    n === null ||
    n <= 0
  ) {
    return null;
  }

  return n;
}


function quitarCorchetes(
  valor
) {

  const texto =
    textoONull(valor);

  if (!texto) {
    return null;
  }

  return texto
    .replace(/\[/g, '(')
    .replace(/\]/g, ')');
}


function obtenerNodo(
  nombre
) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


// ======================================================
// 3. LEER RESPUESTA DEL LLM
// ======================================================
//
// Dependiendo del nodo de n8n y del Output Parser,
// la respuesta puede llegar:
//
// {
//   output: {...}
// }
//
// {
//   output: "{...}"
// }
//
// {
//   text: "{...}"
// }
//
// o directamente como objeto.
//
// También puede llegar:
//
// {
//   error: ...
// }
//
// si el nodo está configurado con Continue On Fail.
//
// ======================================================

function leerSalidaIA(
  json
) {

  if (
    !json ||
    typeof json !== 'object'
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  // --------------------------------------------------
  // Error explícito del nodo
  // --------------------------------------------------

  if (json.error) {

    const detalle =
      textoONull(
        json.error?.message ??
        json.error
      );

    return {
      error:
        'IA_FALLIDA',

      detalle
    };

  }


  // --------------------------------------------------
  // Buscar salida probable
  // --------------------------------------------------

  let salida =
    json.output ??
    json.text ??
    json.response ??
    json.result ??
    json.data ??
    null;


  // Algunos nodos pueden devolver directamente
  // el contrato en el root.

  if (
    salida === null &&
    json.contenido_detectado !== undefined
  ) {

    salida =
      json;

  }


  // --------------------------------------------------
  // Parsear JSON string
  // --------------------------------------------------

  if (
    typeof salida === 'string'
  ) {

    let limpio =
      salida.trim();


    limpio =
      limpio.replace(
        /^```(?:json)?\s*/i,
        ''
      );


    limpio =
      limpio.replace(
        /\s*```$/,
        ''
      );


    try {

      salida =
        JSON.parse(
          limpio
        );

    } catch (_) {

      return {
        error:
          'JSON_INVALIDO',

        detalle:
          limpio.slice(
            0,
            300
          )
      };

    }

  }


  // --------------------------------------------------
  // Validar que sea objeto
  // --------------------------------------------------

  if (
    !salida ||
    typeof salida !== 'object' ||
    Array.isArray(salida)
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  return {
    datos:
      salida
  };
}


// ======================================================
// 4. VALIDAR CONTRATO
// ======================================================

function validarContrato(
  datos
) {

  if (
    !CONTENIDOS_VALIDOS.includes(
      datos.contenido_detectado
    )
  ) {

    return (
      'contenido_detectado inválido'
    );

  }


  if (
    !CONFIANZAS_VALIDAS.includes(
      datos.confianza
    )
  ) {

    return (
      'confianza inválida'
    );

  }


  if (
    !MOTIVOS_REVISION_VALIDOS.includes(
      datos.motivo_revision
    )
  ) {

    return (
      'motivo_revision inválido'
    );

  }


  const camposBooleanos = [
    'envase_detectado',
    'etiqueta_visible',
    'diseno_visible',
    'requiere_revision_humana'
  ];


  for (
    const campo
    of camposBooleanos
  ) {

    if (
      booleanoONull(
        datos[campo]
      ) === null
    ) {

      return (
        `${campo} debe ser boolean`
      );

    }

  }


  const medidasNumericas = [
    'ancho_cm',
    'alto_cm',
    'diametro_cm'
  ];

  for (const campo of medidasNumericas) {
    const valor = datos[campo];

    if (
      valor !== undefined &&
      valor !== null &&
      medidaONull(valor) === null
    ) {
      return `${campo} debe ser number positivo o null`;
    }
  }


  if (
    !textoONull(
      datos.resumen_para_cerebro,
      LARGO_MAXIMO_RESUMEN
    )
  ) {

    return (
      'resumen_para_cerebro vacío'
    );

  }


  return null;
}


// ======================================================
// 5. RECUPERAR CONTEXTO ORIGINAL
// ======================================================
//
// El nodo LLM puede devolver únicamente:
//
// {
//   output: {...}
// }
//
// Por eso NO dependemos de que preserve:
//
// - mensaje_id
// - conversacion_id
// - caption
// - contenido_base
//
// Estos datos se recuperan desde:
//
// "Preparar media del turno"
//
// ======================================================

const origenes = (() => {

  try {

    return (
      $('Preparar media del turno')
        .all()
    );

  } catch (_) {

    return [];

  }

})();


// ======================================================
// 6. PROCESAR ITEMS
// ======================================================

const entradas =
  $input.all();


const resultados =
  entradas.map(
    (
      item,
      indice
    ) => {

      const input =
        item.json ?? {};


      const origen =
        origenes[indice]?.json ??
        origenes[0]?.json ??
        {};


      // ==================================================
      // IDENTIDAD
      // ==================================================

      const mensajeId =
        numeroONull(
          input.mensaje_id ??
          origen.mensaje_id
        );


      const conversacionId =
        numeroONull(
          input.conversacion_id ??
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base ??
          input.contenido_base,
          1500
        ) ??
        '[IMAGEN]';


      // ==================================================
      // LEER IA
      // ==================================================

      const lectura =
        leerSalidaIA(
          input
        );


      const errorContrato =
        lectura.datos
          ? validarContrato(
              lectura.datos
            )
          : null;


      // ==================================================
      // 7. ANÁLISIS INVÁLIDO
      // ==================================================
      //
      // Aquí NO derivamos humano todavía.
      //
      // Groq inválido
      //    ↓
      // IF false
      //    ↓
      // DeepSeek
      //
      // ==================================================

      if (
        lectura.error ||
        errorContrato
      ) {

        const errorAnalisis =
          lectura.error ??
          'SCHEMA_INVALIDO';


        const detalleError =
          lectura.detalle ??
          errorContrato ??
          null;


        return {
          json: {

            mensaje_id:
              mensajeId,

            conversacion_id:
              conversacionId,

            proveedor_analisis:
              PROVEEDOR_ANALISIS,


            // ------------------------------------------
            // RESULTADO
            // ------------------------------------------

            analisis_valido:
              false,

            requiere_revision:
              true,

            motivo_revision:
              'ANALISIS_NO_DISPONIBLE',


            // ------------------------------------------
            // DETECCIÓN
            // ------------------------------------------

            comprobante_detectado:
              false,

            contenido_detectado:
              null,

            confianza:
              null,

            analisis:
              null,


            // ------------------------------------------
            // ERROR
            // ------------------------------------------

            error_analisis:
              errorAnalisis,

            detalle_error:
              detalleError,


            // ------------------------------------------
            // CONTEXTO PARA SIGUIENTE FALLBACK
            // ------------------------------------------

            contenido_base:
              contenidoBase,

            contenido_actualizado:
              (
                `${contenidoBase}\n` +
                `[CONTEXTO DE IMAGEN · proveedor=${PROVEEDOR_ANALISIS} · ` +
                'revision=SI · motivo=ANALISIS_NO_DISPONIBLE] ' +
                'El análisis automático de esta imagen no estuvo disponible.'
              )

          }
        };

      }


      // ==================================================
      // 8. ANÁLISIS VÁLIDO
      // ==================================================

      const datos =
        lectura.datos;


      const contenido =
        datos.contenido_detectado;


      const confianza =
        datos.confianza;


      // ==================================================
      // 8.1 MEDIDAS ESCRITAS
      // ==================================================
      //
      // Compatibilidad:
      // - Si el schema nuevo trae medidas_detectadas, se respeta.
      // - Si un fallback antiguo solo trae medidas_visibles, se infiere.
      // - Si existen ancho/alto/diámetro explícitos, también cuenta como
      //   medida detectada.
      //
      // Nunca se calculan medidas desde proporciones de la fotografía.
      // ==================================================

      const anchoCm =
        medidaONull(
          datos.ancho_cm
        );

      const altoCm =
        medidaONull(
          datos.alto_cm
        );

      const diametroCm =
        medidaONull(
          datos.diametro_cm
        );

      const medidasVisiblesOriginales =
        textoONull(
          datos.medidas_visibles,
          180
        );

      const medidaEstructuradaExiste =
        anchoCm !== null ||
        altoCm !== null ||
        diametroCm !== null;

      const medidasDetectadas =
        booleanoONull(
          datos.medidas_detectadas
        ) === true ||
        medidasVisiblesOriginales !== null ||
        medidaEstructuradaExiste;

      const medidasVisiblesDerivadas =
        [
          anchoCm !== null
            ? `ancho ${anchoCm} cm`
            : null,
          altoCm !== null
            ? `alto ${altoCm} cm`
            : null,
          diametroCm !== null
            ? `diámetro ${diametroCm} cm`
            : null
        ]
          .filter(Boolean)
          .join(' · ');

      const medidasVisibles =
        medidasDetectadas
          ? (
              medidasVisiblesOriginales ??
              textoONull(
                medidasVisiblesDerivadas,
                180
              )
            )
          : null;


      // ==================================================
      // 9. NORMALIZAR ANÁLISIS
      // ==================================================

      const analisis = {

        contenido_detectado:
          contenido,


        producto_probable:
          contenido === 'NO_RELACIONADO'
            ? null
            : textoONull(
                datos.producto_probable
              ),


        envase_detectado:
          booleanoONull(
            datos.envase_detectado
          ) === true,


        forma_envase:
          textoONull(
            datos.forma_envase
          ),


        etiqueta_visible:
          booleanoONull(
            datos.etiqueta_visible
          ) === true,


        diseno_visible:
          booleanoONull(
            datos.diseno_visible
          ) === true,


        texto_visible_relevante:
          contenido === 'COMPROBANTE_PAGO'
            ? null
            : textoONull(
                datos.texto_visible_relevante
              ),


        colores_relevantes:
          Array.isArray(
            datos.colores_relevantes
          )
            ? datos.colores_relevantes
                .map(
                  color =>
                    textoONull(
                      color,
                      40
                    )
                )
                .filter(
                  Boolean
                )
                .slice(
                  0,
                  6
                )
            : [],


        medidas_detectadas:
          medidasDetectadas,

        ancho_cm:
          medidasDetectadas
            ? anchoCm
            : null,

        alto_cm:
          medidasDetectadas
            ? altoCm
            : null,

        diametro_cm:
          medidasDetectadas
            ? diametroCm
            : null,

        medidas_visibles:
          medidasVisibles,


        requiere_revision_humana:
          booleanoONull(
            datos.requiere_revision_humana
          ) === true,


        motivo_revision:
          datos.motivo_revision,


        confianza,


        resumen_para_cerebro:
          textoONull(
            datos.resumen_para_cerebro,
            LARGO_MAXIMO_RESUMEN
          )

      };


      // ==================================================
      // 10. DETERMINAR REVISIÓN HUMANA
      // ======================================================

      let motivoRevision =
        null;


      if (
        analisis
          .requiere_revision_humana === true
      ) {

        motivoRevision =
          analisis.motivo_revision !==
          'NINGUNO'
            ? analisis.motivo_revision
            : 'OTRO';

      }


      else if (
        confianza ===
        'BAJA'
      ) {

        motivoRevision =
          'CONFIANZA_BAJA';

      }


      else if (
        contenido ===
        'NO_DETERMINABLE'
      ) {

        motivoRevision =
          'IMAGEN_AMBIGUA';

      }


      const requiereRevision =
        motivoRevision !==
        null;


      // ==================================================
      // 11. CONSTRUIR CONTEXTO LEGIBLE
      // ======================================================

      const cabecera = [

        'CONTEXTO DE IMAGEN',

        `proveedor=${PROVEEDOR_ANALISIS}`,

        `contenido=${contenido}`,

        `confianza=${confianza}`,

        `revision=${
          requiereRevision
            ? 'SI'
            : 'NO'
        }`,

        requiereRevision
          ? `motivo=${motivoRevision}`
          : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' · '
        );


      const detalle = [

        quitarCorchetes(
          analisis
            .resumen_para_cerebro
        ),


        analisis.producto_probable
          ? (
              'Producto probable: ' +
              `${quitarCorchetes(
                analisis.producto_probable
              )}.`
            )
          : null,


        analisis.forma_envase
          ? (
              'Envase: ' +
              `${quitarCorchetes(
                analisis.forma_envase
              )}.`
            )
          : null,


        analisis.texto_visible_relevante
          ? (
              'Texto visible: "' +
              `${quitarCorchetes(
                analisis.texto_visible_relevante
              )}".`
            )
          : null,


        analisis
          .colores_relevantes
          .length > 0
            ? (
                'Colores: ' +
                `${analisis
                  .colores_relevantes
                  .join(', ')}.`
              )
            : null,


        analisis.medidas_detectadas
          ? (
              'Medidas escritas en la imagen: ' +
              [
                analisis.ancho_cm !== null
                  ? `ancho=${analisis.ancho_cm} cm`
                  : null,
                analisis.alto_cm !== null
                  ? `alto=${analisis.alto_cm} cm`
                  : null,
                analisis.diametro_cm !== null
                  ? `diámetro=${analisis.diametro_cm} cm`
                  : null,
                analisis.medidas_visibles
                  ? `texto="${quitarCorchetes(
                      analisis.medidas_visibles
                    )}"`
                  : null
              ]
                .filter(Boolean)
                .join(' · ') +
              '.'
            )
          : CONTENIDOS_ETIQUETA.includes(
              contenido
            )
              ? 'Sin medidas visibles.'
              : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' '
        );


      // ==================================================
      // 12. SALIDA
      // ======================================================

      return {
        json: {

          mensaje_id:
            mensajeId,

          conversacion_id:
            conversacionId,

          proveedor_analisis:
            PROVEEDOR_ANALISIS,


          // ------------------------------------------
          // RESULTADO
          // ------------------------------------------

          analisis_valido:
            true,

          requiere_revision:
            requiereRevision,

          motivo_revision:
            motivoRevision,


          // ------------------------------------------
          // DETECCIÓN
          // ------------------------------------------

          comprobante_detectado:
            contenido ===
            'COMPROBANTE_PAGO',

          contenido_detectado:
            contenido,

          confianza,

          medidas_detectadas:
            analisis.medidas_detectadas,

          ancho_cm:
            analisis.ancho_cm,

          alto_cm:
            analisis.alto_cm,

          diametro_cm:
            analisis.diametro_cm,

          medidas_visibles:
            analisis.medidas_visibles,

          medidas_para_cerebro: {
            detectadas:
              analisis.medidas_detectadas,

            ancho_cm:
              analisis.ancho_cm,

            alto_cm:
              analisis.alto_cm,

            diametro_cm:
              analisis.diametro_cm,

            texto_original:
              analisis.medidas_visibles,

            fuente:
              'IMAGEN'
          },


          // ------------------------------------------
          // ERROR
          // ------------------------------------------

          error_analisis:
            null,

          detalle_error:
            null,


          // ------------------------------------------
          // ANÁLISIS NORMALIZADO
          // ------------------------------------------

          analisis,


          // ------------------------------------------
          // CONTEXTO
          // ------------------------------------------

          contenido_base:
            contenidoBase,

          contenido_actualizado:
            (
              `${contenidoBase}\n` +
              `[${cabecera}] ${detalle}`
            )

        }
      };

    }
  );


return resultados;

// ======================================================
// NODO N8N: VALIDAR ANÁLISIS IMAGEN GROQ
// PEGASO ADHESIVOS
// ARCHIVO: code/03-conversacion/validar-analisis-imagen.js
// VERSION: 2.1
// ======================================================
//
// RESPONSABILIDAD:
//
// - Recibir la salida de "Analizar imagen Groq Basic LLM".
// - Validar que el análisis visual cumpla el contrato.
// - Recuperar el mensaje original desde "Preparar media del turno".
// - NO necesita recibir nuevamente el binario.
// - NO analiza la imagen.
// - NO decide la acción comercial.
// - NO deriva directamente a humano.
// - Si Groq falla, devuelve analisis_valido = false para
//   permitir que el IF envíe el flujo a DeepSeek.
// - Extraer y normalizar medidas escritas explícitamente en la imagen
//   sin estimarlas ni alterar el resto del contrato visual.
//
// IMPORTANTE:
//
// Esta misma lógica puede reutilizarse después para:
//
//   Validar análisis imagen DeepSeek
//   Validar análisis imagen OpenAI
//
// cambiando únicamente PROVEEDOR_ANALISIS.
//
// ======================================================


const PROVEEDOR_ANALISIS = 'GROQ';


// ======================================================
// 1. CONSTANTES
// ======================================================

const CONTENIDOS_VALIDOS = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS',
  'COMPROBANTE_PAGO',
  'EVIDENCIA_RECLAMO',
  'CAPTURA_DE_PANTALLA',
  'NO_RELACIONADO',
  'NO_DETERMINABLE'
];


const MOTIVOS_REVISION_VALIDOS = [
  'NINGUNO',
  'IMAGEN_ILEGIBLE',
  'IMAGEN_AMBIGUA',
  'DISENO_COMPLEJO',
  'OTRO'
];


const CONFIANZAS_VALIDAS = [
  'ALTA',
  'MEDIA',
  'BAJA'
];


const CONTENIDOS_ETIQUETA = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS'
];


const LARGO_MAXIMO_RESUMEN = 500;
const LARGO_MAXIMO_CAMPO = 250;


// ======================================================
// 2. HELPERS
// ======================================================

function textoONull(
  valor,
  largo = LARGO_MAXIMO_CAMPO
) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  if (!limpio) {
    return null;
  }

  return limpio.slice(
    0,
    largo
  );
}


function numeroONull(
  valor
) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleanoONull(
  valor
) {

  if (
    valor === true ||
    valor === false
  ) {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return null;
}


function medidaONull(
  valor
) {

  const n =
    numeroONull(valor);

  if (
    n === null ||
    n <= 0
  ) {
    return null;
  }

  return n;
}


function quitarCorchetes(
  valor
) {

  const texto =
    textoONull(valor);

  if (!texto) {
    return null;
  }

  return texto
    .replace(/\[/g, '(')
    .replace(/\]/g, ')');
}


function obtenerNodo(
  nombre
) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


// ======================================================
// 3. LEER RESPUESTA DEL LLM
// ======================================================
//
// Dependiendo del nodo de n8n y del Output Parser,
// la respuesta puede llegar:
//
// {
//   output: {...}
// }
//
// {
//   output: "{...}"
// }
//
// {
//   text: "{...}"
// }
//
// o directamente como objeto.
//
// También puede llegar:
//
// {
//   error: ...
// }
//
// si el nodo está configurado con Continue On Fail.
//
// ======================================================

function leerSalidaIA(
  json
) {

  if (
    !json ||
    typeof json !== 'object'
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  // --------------------------------------------------
  // Error explícito del nodo
  // --------------------------------------------------

  if (json.error) {

    const detalle =
      textoONull(
        json.error?.message ??
        json.error
      );

    return {
      error:
        'IA_FALLIDA',

      detalle
    };

  }


  // --------------------------------------------------
  // Buscar salida probable
  // --------------------------------------------------

  let salida =
    json.output ??
    json.text ??
    json.response ??
    json.result ??
    json.data ??
    null;


  // Algunos nodos pueden devolver directamente
  // el contrato en el root.

  if (
    salida === null &&
    json.contenido_detectado !== undefined
  ) {

    salida =
      json;

  }


  // --------------------------------------------------
  // Parsear JSON string
  // --------------------------------------------------

  if (
    typeof salida === 'string'
  ) {

    let limpio =
      salida.trim();


    limpio =
      limpio.replace(
        /^```(?:json)?\s*/i,
        ''
      );


    limpio =
      limpio.replace(
        /\s*```$/,
        ''
      );


    try {

      salida =
        JSON.parse(
          limpio
        );

    } catch (_) {

      return {
        error:
          'JSON_INVALIDO',

        detalle:
          limpio.slice(
            0,
            300
          )
      };

    }

  }


  // --------------------------------------------------
  // Validar que sea objeto
  // --------------------------------------------------

  if (
    !salida ||
    typeof salida !== 'object' ||
    Array.isArray(salida)
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  return {
    datos:
      salida
  };
}


// ======================================================
// 4. VALIDAR CONTRATO
// ======================================================

function validarContrato(
  datos
) {

  if (
    !CONTENIDOS_VALIDOS.includes(
      datos.contenido_detectado
    )
  ) {

    return (
      'contenido_detectado inválido'
    );

  }


  if (
    !CONFIANZAS_VALIDAS.includes(
      datos.confianza
    )
  ) {

    return (
      'confianza inválida'
    );

  }


  if (
    !MOTIVOS_REVISION_VALIDOS.includes(
      datos.motivo_revision
    )
  ) {

    return (
      'motivo_revision inválido'
    );

  }


  const camposBooleanos = [
    'envase_detectado',
    'etiqueta_visible',
    'diseno_visible',
    'requiere_revision_humana'
  ];


  for (
    const campo
    of camposBooleanos
  ) {

    if (
      booleanoONull(
        datos[campo]
      ) === null
    ) {

      return (
        `${campo} debe ser boolean`
      );

    }

  }


  const medidasNumericas = [
    'ancho_cm',
    'alto_cm',
    'diametro_cm'
  ];

  for (const campo of medidasNumericas) {
    const valor = datos[campo];

    if (
      valor !== undefined &&
      valor !== null &&
      medidaONull(valor) === null
    ) {
      return `${campo} debe ser number positivo o null`;
    }
  }


  if (
    !textoONull(
      datos.resumen_para_cerebro,
      LARGO_MAXIMO_RESUMEN
    )
  ) {

    return (
      'resumen_para_cerebro vacío'
    );

  }


  return null;
}


// ======================================================
// 5. RECUPERAR CONTEXTO ORIGINAL
// ======================================================
//
// El nodo LLM puede devolver únicamente:
//
// {
//   output: {...}
// }
//
// Por eso NO dependemos de que preserve:
//
// - mensaje_id
// - conversacion_id
// - caption
// - contenido_base
//
// Estos datos se recuperan desde:
//
// "Preparar media del turno"
//
// ======================================================

const origenes = (() => {

  try {

    return (
      $('Preparar media del turno')
        .all()
    );

  } catch (_) {

    return [];

  }

})();


// ======================================================
// 6. PROCESAR ITEMS
// ======================================================

const entradas =
  $input.all();


const resultados =
  entradas.map(
    (
      item,
      indice
    ) => {

      const input =
        item.json ?? {};


      const origen =
        origenes[indice]?.json ??
        origenes[0]?.json ??
        {};


      // ==================================================
      // IDENTIDAD
      // ==================================================

      const mensajeId =
        numeroONull(
          input.mensaje_id ??
          origen.mensaje_id
        );


      const conversacionId =
        numeroONull(
          input.conversacion_id ??
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base ??
          input.contenido_base,
          1500
        ) ??
        '[IMAGEN]';


      // ==================================================
      // LEER IA
      // ==================================================

      const lectura =
        leerSalidaIA(
          input
        );


      const errorContrato =
        lectura.datos
          ? validarContrato(
              lectura.datos
            )
          : null;


      // ==================================================
      // 7. ANÁLISIS INVÁLIDO
      // ==================================================
      //
      // Aquí NO derivamos humano todavía.
      //
      // Groq inválido
      //    ↓
      // IF false
      //    ↓
      // DeepSeek
      //
      // ==================================================

      if (
        lectura.error ||
        errorContrato
      ) {

        const errorAnalisis =
          lectura.error ??
          'SCHEMA_INVALIDO';


        const detalleError =
          lectura.detalle ??
          errorContrato ??
          null;


        return {
          json: {

            mensaje_id:
              mensajeId,

            conversacion_id:
              conversacionId,

            proveedor_analisis:
              PROVEEDOR_ANALISIS,


            // ------------------------------------------
            // RESULTADO
            // ------------------------------------------

            analisis_valido:
              false,

            requiere_revision:
              true,

            motivo_revision:
              'ANALISIS_NO_DISPONIBLE',


            // ------------------------------------------
            // DETECCIÓN
            // ------------------------------------------

            comprobante_detectado:
              false,

            contenido_detectado:
              null,

            confianza:
              null,

            analisis:
              null,


            // ------------------------------------------
            // ERROR
            // ------------------------------------------

            error_analisis:
              errorAnalisis,

            detalle_error:
              detalleError,


            // ------------------------------------------
            // CONTEXTO PARA SIGUIENTE FALLBACK
            // ------------------------------------------

            contenido_base:
              contenidoBase,

            contenido_actualizado:
              (
                `${contenidoBase}\n` +
                `[CONTEXTO DE IMAGEN · proveedor=${PROVEEDOR_ANALISIS} · ` +
                'revision=SI · motivo=ANALISIS_NO_DISPONIBLE] ' +
                'El análisis automático de esta imagen no estuvo disponible.'
              )

          }
        };

      }


      // ==================================================
      // 8. ANÁLISIS VÁLIDO
      // ==================================================

      const datos =
        lectura.datos;


      const contenido =
        datos.contenido_detectado;


      const confianza =
        datos.confianza;


      // ==================================================
      // 8.1 MEDIDAS ESCRITAS
      // ==================================================
      //
      // Compatibilidad:
      // - Si el schema nuevo trae medidas_detectadas, se respeta.
      // - Si un fallback antiguo solo trae medidas_visibles, se infiere.
      // - Si existen ancho/alto/diámetro explícitos, también cuenta como
      //   medida detectada.
      //
      // Nunca se calculan medidas desde proporciones de la fotografía.
      // ==================================================

      const anchoCm =
        medidaONull(
          datos.ancho_cm
        );

      const altoCm =
        medidaONull(
          datos.alto_cm
        );

      const diametroCm =
        medidaONull(
          datos.diametro_cm
        );

      const medidasVisiblesOriginales =
        textoONull(
          datos.medidas_visibles,
          180
        );

      const medidaEstructuradaExiste =
        anchoCm !== null ||
        altoCm !== null ||
        diametroCm !== null;

      const medidasDetectadas =
        booleanoONull(
          datos.medidas_detectadas
        ) === true ||
        medidasVisiblesOriginales !== null ||
        medidaEstructuradaExiste;

      const medidasVisiblesDerivadas =
        [
          anchoCm !== null
            ? `ancho ${anchoCm} cm`
            : null,
          altoCm !== null
            ? `alto ${altoCm} cm`
            : null,
          diametroCm !== null
            ? `diámetro ${diametroCm} cm`
            : null
        ]
          .filter(Boolean)
          .join(' · ');

      const medidasVisibles =
        medidasDetectadas
          ? (
              medidasVisiblesOriginales ??
              textoONull(
                medidasVisiblesDerivadas,
                180
              )
            )
          : null;


      // ==================================================
      // 9. NORMALIZAR ANÁLISIS
      // ==================================================

      const analisis = {

        contenido_detectado:
          contenido,


        producto_probable:
          contenido === 'NO_RELACIONADO'
            ? null
            : textoONull(
                datos.producto_probable
              ),


        envase_detectado:
          booleanoONull(
            datos.envase_detectado
          ) === true,


        forma_envase:
          textoONull(
            datos.forma_envase
          ),


        etiqueta_visible:
          booleanoONull(
            datos.etiqueta_visible
          ) === true,


        diseno_visible:
          booleanoONull(
            datos.diseno_visible
          ) === true,


        texto_visible_relevante:
          contenido === 'COMPROBANTE_PAGO'
            ? null
            : textoONull(
                datos.texto_visible_relevante
              ),


        colores_relevantes:
          Array.isArray(
            datos.colores_relevantes
          )
            ? datos.colores_relevantes
                .map(
                  color =>
                    textoONull(
                      color,
                      40
                    )
                )
                .filter(
                  Boolean
                )
                .slice(
                  0,
                  6
                )
            : [],


        medidas_detectadas:
          medidasDetectadas,

        ancho_cm:
          medidasDetectadas
            ? anchoCm
            : null,

        alto_cm:
          medidasDetectadas
            ? altoCm
            : null,

        diametro_cm:
          medidasDetectadas
            ? diametroCm
            : null,

        medidas_visibles:
          medidasVisibles,


        requiere_revision_humana:
          booleanoONull(
            datos.requiere_revision_humana
          ) === true,


        motivo_revision:
          datos.motivo_revision,


        confianza,


        resumen_para_cerebro:
          textoONull(
            datos.resumen_para_cerebro,
            LARGO_MAXIMO_RESUMEN
          )

      };


      // ==================================================
      // 10. DETERMINAR REVISIÓN HUMANA
      // ======================================================

      let motivoRevision =
        null;


      if (
        analisis
          .requiere_revision_humana === true
      ) {

        motivoRevision =
          analisis.motivo_revision !==
          'NINGUNO'
            ? analisis.motivo_revision
            : 'OTRO';

      }


      else if (
        confianza ===
        'BAJA'
      ) {

        motivoRevision =
          'CONFIANZA_BAJA';

      }


      else if (
        contenido ===
        'NO_DETERMINABLE'
      ) {

        motivoRevision =
          'IMAGEN_AMBIGUA';

      }


      const requiereRevision =
        motivoRevision !==
        null;


      // ==================================================
      // 11. CONSTRUIR CONTEXTO LEGIBLE
      // ======================================================

      const cabecera = [

        'CONTEXTO DE IMAGEN',

        `proveedor=${PROVEEDOR_ANALISIS}`,

        `contenido=${contenido}`,

        `confianza=${confianza}`,

        `revision=${
          requiereRevision
            ? 'SI'
            : 'NO'
        }`,

        requiereRevision
          ? `motivo=${motivoRevision}`
          : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' · '
        );


      const detalle = [

        quitarCorchetes(
          analisis
            .resumen_para_cerebro
        ),


        analisis.producto_probable
          ? (
              'Producto probable: ' +
              `${quitarCorchetes(
                analisis.producto_probable
              )}.`
            )
          : null,


        analisis.forma_envase
          ? (
              'Envase: ' +
              `${quitarCorchetes(
                analisis.forma_envase
              )}.`
            )
          : null,


        analisis.texto_visible_relevante
          ? (
              'Texto visible: "' +
              `${quitarCorchetes(
                analisis.texto_visible_relevante
              )}".`
            )
          : null,


        analisis
          .colores_relevantes
          .length > 0
            ? (
                'Colores: ' +
                `${analisis
                  .colores_relevantes
                  .join(', ')}.`
              )
            : null,


        analisis.medidas_detectadas
          ? (
              'Medidas escritas en la imagen: ' +
              [
                analisis.ancho_cm !== null
                  ? `ancho=${analisis.ancho_cm} cm`
                  : null,
                analisis.alto_cm !== null
                  ? `alto=${analisis.alto_cm} cm`
                  : null,
                analisis.diametro_cm !== null
                  ? `diámetro=${analisis.diametro_cm} cm`
                  : null,
                analisis.medidas_visibles
                  ? `texto="${quitarCorchetes(
                      analisis.medidas_visibles
                    )}"`
                  : null
              ]
                .filter(Boolean)
                .join(' · ') +
              '.'
            )
          : CONTENIDOS_ETIQUETA.includes(
              contenido
            )
              ? 'Sin medidas visibles.'
              : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' '
        );


      // ==================================================
      // 12. SALIDA
      // ======================================================

      return {
        json: {

          mensaje_id:
            mensajeId,

          conversacion_id:
            conversacionId,

          proveedor_analisis:
            PROVEEDOR_ANALISIS,


          // ------------------------------------------
          // RESULTADO
          // ------------------------------------------

          analisis_valido:
            true,

          requiere_revision:
            requiereRevision,

          motivo_revision:
            motivoRevision,


          // ------------------------------------------
          // DETECCIÓN
          // ------------------------------------------

          comprobante_detectado:
            contenido ===
            'COMPROBANTE_PAGO',

          contenido_detectado:
            contenido,

          confianza,

          medidas_detectadas:
            analisis.medidas_detectadas,

          ancho_cm:
            analisis.ancho_cm,

          alto_cm:
            analisis.alto_cm,

          diametro_cm:
            analisis.diametro_cm,

          medidas_visibles:
            analisis.medidas_visibles,

          medidas_para_cerebro: {
            detectadas:
              analisis.medidas_detectadas,

            ancho_cm:
              analisis.ancho_cm,

            alto_cm:
              analisis.alto_cm,

            diametro_cm:
              analisis.diametro_cm,

            texto_original:
              analisis.medidas_visibles,

            fuente:
              'IMAGEN'
          },


          // ------------------------------------------
          // ERROR
          // ------------------------------------------

          error_analisis:
            null,

          detalle_error:
            null,


          // ------------------------------------------
          // ANÁLISIS NORMALIZADO
          // ------------------------------------------

          analisis,


          // ------------------------------------------
          // CONTEXTO
          // ------------------------------------------

          contenido_base:
            contenidoBase,

          contenido_actualizado:
            (
              `${contenidoBase}\n` +
              `[${cabecera}] ${detalle}`
            )

        }
      };

    }
  );


return resultados;

// ======================================================
// NODO N8N: PREPARAR DERIVACIÓN IMAGEN FALLIDA
// PEGASO ADHESIVOS
// VERSION: 2.0
// ======================================================
//
// Se ejecuta únicamente cuando:
//
// Groq       -> análisis inválido
// DeepSeek   -> análisis inválido
// OpenAI     -> análisis inválido
//
// Objetivo:
//
// Transformar el fallo total del análisis visual en un
// contrato compatible con la ruta estándar de handoff.
//
// IMPORTANTE:
//
// - NO vuelve a analizar la imagen.
// - NO pasa otra vez por el cerebro comercial.
// - NO inventa qué contiene la imagen.
// - NO confirma pagos.
// - NO crea pedidos.
// - SÍ recupera correctamente prospecto/conversación.
// - SÍ conserva el mensaje/caption real del cliente.
// - SÍ deriva a humano con notificación.
//
// Ruta esperada:
//
// IF: ¿Análisis OpenAI válido?
// FALSE
//   ↓
// Preparar derivación imagen fallida
//   ↓
// Preparar derivación humana
//
// ======================================================


const input =
  $input.first().json ?? {};


// ======================================================
// 1. HELPERS
// ======================================================

function texto(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function obtenerNodo(nombre) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


function primerNumero(...valores) {

  for (const valor of valores) {

    const n =
      numeroONull(valor);

    if (
      n !== null &&
      n > 0
    ) {
      return n;
    }

  }

  return null;
}


function primerTexto(...valores) {

  for (const valor of valores) {

    const t =
      texto(valor);

    if (t !== null) {
      return t;
    }

  }

  return null;
}


// ======================================================
// 2. RECUPERAR CONTEXTO DE NODOS ANTERIORES
// ======================================================
//
// No dependemos de que el validador de imagen preserve
// todos los datos de negocio.
//
// ======================================================

const turno =
  obtenerNodo(
    'Resolver turno conversacional'
  );

const media =
  obtenerNodo(
    'Preparar media del turno'
  );

const entrada =
  obtenerNodo(
    'Preparar entrada WhatsApp'
  );

const resolverProspecto =
  obtenerNodo(
    'Resolver prospecto'
  );

const unificarProspecto =
  obtenerNodo(
    'Unificar prospecto'
  );

const prospectoCreado =
  obtenerNodo(
    'Preparar prospecto creado'
  );

const resolverConversacion =
  obtenerNodo(
    'Resolver conversación prospecto'
  );

const unificarConversacion =
  obtenerNodo(
    'Unificar conversación'
  );

const prepararConversacion =
  obtenerNodo(
    'Preparar conversación'
  );


// ======================================================
// 3. RESOLVER CONVERSACIÓN
// ======================================================

const conversacionId =
  primerNumero(

    input.conversacion_id,

    media.conversacion_id,

    turno.conversacion_id,

    resolverConversacion.conversacion_id,
    resolverConversacion.id,

    unificarConversacion.conversacion_id,
    unificarConversacion.id,

    prepararConversacion.conversacion_id,
    prepararConversacion.id
  );


if (conversacionId === null) {

  throw new Error(
    'DERIVACIÓN IMAGEN FALLIDA: no fue posible resolver conversacion_id.'
  );

}


// ======================================================
// 4. RESOLVER PROSPECTO
// ======================================================

const prospectoId =
  primerNumero(

    input.prospecto_id,

    resolverProspecto.prospecto_id,
    resolverProspecto.id,

    unificarProspecto.prospecto_id,
    unificarProspecto.id,

    prospectoCreado.prospecto_id,
    prospectoCreado.id,

    resolverConversacion.prospecto_id,

    unificarConversacion.prospecto_id,

    media.prospecto_id,

    turno.prospecto_id
  );


if (prospectoId === null) {

  throw new Error(
    'DERIVACIÓN IMAGEN FALLIDA: no fue posible resolver prospecto_id.'
  );

}


// ======================================================
// 5. CLIENTE / CONTACTO
// ======================================================

const clienteId =
  primerNumero(

    input.cliente_id,

    resolverProspecto.cliente_id,

    unificarProspecto.cliente_id,

    prospectoCreado.cliente_id,

    resolverConversacion.cliente_id,

    unificarConversacion.cliente_id
  );


const contactoId =
  primerNumero(

    input.contacto_id,

    resolverProspecto.contacto_id,

    unificarProspecto.contacto_id,

    prospectoCreado.contacto_id,

    resolverConversacion.contacto_id,

    unificarConversacion.contacto_id
  );


// ======================================================
// 6. TELÉFONO Y NOMBRE
// ======================================================

const telefono =
  primerTexto(

    input.telefono,

    resolverProspecto.telefono,

    unificarProspecto.telefono,

    prospectoCreado.telefono,

    entrada.telefono
  );


const nombre =
  primerTexto(

    input.prospecto_nombre,
    input.nombre_whatsapp,

    resolverProspecto.nombre_whatsapp,
    resolverProspecto.nombre,

    unificarProspecto.nombre_whatsapp,
    unificarProspecto.nombre,

    prospectoCreado.nombre_whatsapp,
    prospectoCreado.nombre,

    entrada.nombre_whatsapp
  );


// ======================================================
// 7. MENSAJE REAL DEL CLIENTE
// ======================================================
//
// Preferimos caption/texto original.
//
// NO usamos contenido_actualizado del validador como
// mensaje principal porque contiene metadata técnica.
//
// ======================================================

const mensajeCliente =
  primerTexto(

    input.mensaje_cliente_original,

    media.texto_turno_cliente,

    media.caption,

    entrada.mensaje,

    media.contenido_base,

    turno.turno_texto
  ) ??
  '[Imagen enviada por el prospecto]';


// ======================================================
// 8. INFORMACIÓN DEL FALLO VISUAL
// ======================================================

const motivoAnalisis =
  primerTexto(

    input.motivo_revision,

    input.error_analisis,

    input.detalle_error
  ) ??
  'ANALISIS_NO_DISPONIBLE';


const detalleError =
  primerTexto(

    input.detalle_error,

    input.error_analisis
  );


// ======================================================
// 9. MENSAJE DE TRANSICIÓN AL CLIENTE
// ======================================================
//
// Debe sonar natural.
// No decimos:
// "te paso con un asesor".
//
// ======================================================

const mensajeTransicion =
  'Permítame un momento por favor, vamos a revisar la imagen que nos envió.';


// ======================================================
// 10. SALIDA
// ======================================================

return [
  {
    json: {

      ...input,


      // ==================================================
      // IDENTIDAD
      // ==================================================

      conversacion_id:
        conversacionId,

      prospecto_id:
        prospectoId,

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      telefono,

      nombre_whatsapp:
        nombre,

      prospecto_nombre:
        nombre,


      // ==================================================
      // DECISIÓN COMERCIAL
      // ==================================================

      intencion:
        'OTRO',

      accion:
        'DERIVAR_HUMANO',

      requiere_humano:
        true,


      // ==================================================
      // HANDOFF
      // ==================================================

      handoff_motivo:
        'IMAGEN_REQUIERE_REVISION',

      motivo_derivacion:
        'IMAGEN_REQUIERE_REVISION',

      motivo:
        'IMAGEN_REQUIERE_REVISION',

      handoff_clasificacion:
        'REVISION_IMAGEN',

      clasificacion_handoff:
        'REVISION_IMAGEN',

      handoff_prioridad:
        'MEDIA',

      prioridad_derivacion:
        'MEDIA',

      prioridad:
        'MEDIA',


      // ==================================================
      // NOTIFICACIÓN INTERNA
      // ==================================================

      requiere_notificacion:
        true,

      handoff_requiere_notificacion:
        true,


      // ==================================================
      // MENSAJE ORIGINAL DEL PROSPECTO
      // ==================================================

      mensaje_actual:
        mensajeCliente,

      mensaje_cliente_original:
        mensajeCliente,

      ultimo_mensaje_cliente:
        mensajeCliente,


      // ==================================================
      // MENSAJE DE TRANSICIÓN
      // ==================================================

      respuesta_sugerida:
        mensajeTransicion,

      mensaje_transicion:
        mensajeTransicion,

      handoff_mensaje_cliente:
        mensajeCliente,


      // ==================================================
      // INFORMACIÓN DEL FALLO DE IMAGEN
      // ==================================================

      origen_derivacion:
        'ANALISIS_IMAGEN',

      analisis_imagen_fallido:
        true,

      analisis_imagen_motivo:
        motivoAnalisis,

      analisis_imagen_error:
        detalleError,

      contenido_imagen_detectado:
        input.contenido_detectado ??
        null,

      confianza_imagen:
        input.confianza ??
        null,


      // ==================================================
      // CONTROL
      // ==================================================

      derivacion_directa:
        true,

      derivacion_directa_motivo:
        'FALLO_TOTAL_ANALISIS_IMAGEN',

      handoff_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// PREPARAR ENTRADA NO SOPORTADA
// PEGASO ADHESIVOS
// ======================================================
//
// Objetivo:
// Convertir una entrada de WhatsApp que todavía no puede
// procesar automáticamente el bot en un mensaje válido
// para continuar por:
// contacto → prospecto → conversación → handoff.
//
// NO deriva todavía.
// Solo marca que esta entrada deberá terminar en humano.
// ======================================================

const input = $input.first().json;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio = String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


// ======================================================
// 2. TIPO RECIBIDO
// ======================================================

const tipo =
  String(
    input.tipo ??
    'DESCONOCIDO'
  )
    .trim()
    .toUpperCase();


// ======================================================
// 3. MENSAJE ORIGINAL / DESCRIPTOR
// ======================================================

const mensajeOriginal =
  textoONull(input.mensaje);


// ======================================================
// 4. MOTIVO DE DERIVACIÓN
// ======================================================

let motivo =
  'FORMATO_NO_SOPORTADO';

let descripcion =
  'El cliente envió un formato que todavía no puede procesarse automáticamente.';


switch (tipo) {

  case 'STICKER':
    motivo =
      'STICKER_NO_PROCESABLE';

    descripcion =
      'El cliente envió un sticker que requiere revisión manual.';
    break;


  case 'UBICACION':
    motivo =
      'UBICACION_NO_PROCESABLE';

    descripcion =
      'El cliente compartió una ubicación que todavía no procesa automáticamente el flujo.';
    break;


  case 'CONTACTO':
    motivo =
      'CONTACTO_NO_PROCESABLE';

    descripcion =
      'El cliente compartió un contacto que todavía no procesa automáticamente el flujo.';
    break;


  case 'INTERACTIVO':
    motivo =
      'MENSAJE_INTERACTIVO_NO_PROCESABLE';

    descripcion =
      'El cliente envió una interacción de WhatsApp que requiere revisión.';
    break;


  case 'DESCONOCIDO':
    motivo =
      'FORMATO_DESCONOCIDO';

    descripcion =
      'WhatsApp recibió un tipo de mensaje desconocido para el flujo.';
    break;
}


// ======================================================
// 5. MENSAJE QUE PERSISTIREMOS
// ======================================================

const mensaje =
  mensajeOriginal ??
  `[${tipo}] ${descripcion}`;


// ======================================================
// 6. SALIDA
// ======================================================

return [
  {
    json: {

      ...input,

      mensaje,

      // ----------------------------------------------
      // CONTROL DE ENTRADA
      // ----------------------------------------------

      entrada_no_soportada:
        true,

      requiere_humano_entrada:
        true,

      motivo_derivacion_entrada:
        motivo,

      prioridad_derivacion_entrada:
        'NORMAL',

      requiere_notificacion_entrada:
        true,

      descripcion_entrada_no_soportada:
        descripcion,

      entrada_no_soportada_preparada:
        true
    }
  }
];

// ======================================================
// PREPARAR HANDOFF ENTRADA NO SOPORTADA
// PEGASO ADHESIVOS
// VERSION: 1.1
// ======================================================
//
// OBJETIVO:
//
// Preparar una derivación humana directa cuando:
//
// 1. Llega un tipo de entrada que el flujo automático
//    todavía no puede procesar.
//
// 2. Un audio sí era soportado, pero fallaron todos los
//    mecanismos automáticos de transcripción:
//
//      Groq -> falla / transcripción inválida
//      Deepgram -> falla / transcripción inválida
//
// Ejemplos:
// - audio no interpretable
// - video
// - documento
// - sticker
// - ubicación
// - contacto
// - tipo desconocido
//
// IMPORTANTE:
//
// Este nodo NO:
// - transcribe audio
// - analiza imágenes
// - consulta al cerebro comercial
// - decide una cotización
//
// Este nodo únicamente normaliza el evento y construye
// el contrato necesario para la ruta estándar de
// derivación humana.
//
// Puede recibir datos desde distintos puntos del flujo,
// por lo que recupera contexto de nodos anteriores cuando
// el item actual perdió algunos campos.
//
// ======================================================

const input = $input.first().json ?? {};


// ======================================================
// 1. HELPERS
// ======================================================

function texto(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function objetoSeguro(valor) {

  return (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  )
    ? valor
    : {};
}


// ======================================================
// 2. RECUPERAR CONTEXTO DE NODOS ANTERIORES
// ======================================================
//
// Los nodos HTTP de error pueden perder parte del
// contrato previo.
//
// Recuperamos datos desde nodos estables del flujo.
// ======================================================

let turno = {};

try {

  turno =
    $('Resolver turno conversacional')
      .first()
      .json ?? {};

} catch (_) {

  turno = {};

}


let mediaAudio = {};

try {

  mediaAudio =
    $('Preparar audio del turno')
      .first()
      .json ?? {};

} catch (_) {

  mediaAudio = {};

}


let entradaWhatsApp = {};

try {

  entradaWhatsApp =
    $('Preparar entrada WhatsApp')
      .first()
      .json ?? {};

} catch (_) {

  entradaWhatsApp = {};

}


let normalizado = {};

try {

  normalizado =
    $('Normalizar mensaje')
      .first()
      .json ?? {};

} catch (_) {

  normalizado = {};

}


let conversacion = {};

try {

  conversacion =
    $('Preparar conversación')
      .first()
      .json ?? {};

} catch (_) {

  conversacion = {};

}


// ======================================================
// 3. IDENTIFICACIÓN
// ======================================================

const conversacionId =
  numeroONull(
    input.conversacion_id ??
    input.id_conversacion ??
    turno.conversacion_id ??
    mediaAudio.conversacion_id ??
    conversacion.conversacion_id ??
    conversacion.id
  );


const prospectoId =
  numeroONull(
    input.prospecto_id ??
    turno.prospecto_id ??
    mediaAudio.prospecto_id ??
    conversacion.prospecto_id
  );


const clienteId =
  numeroONull(
    input.cliente_id ??
    turno.cliente_id ??
    mediaAudio.cliente_id ??
    conversacion.cliente_id
  );


const contactoId =
  numeroONull(
    input.contacto_id ??
    turno.contacto_id ??
    mediaAudio.contacto_id ??
    conversacion.contacto_id
  );


// ======================================================
// 4. TELÉFONO / NOMBRE
// ======================================================

const telefono =
  texto(
    input.telefono ??
    turno.telefono ??
    mediaAudio.telefono ??
    normalizado.telefono ??
    entradaWhatsApp.telefono ??
    conversacion.telefono
  );


const nombreWhatsApp =
  texto(
    input.nombre_whatsapp ??
    input.prospecto_nombre ??
    turno.nombre_whatsapp ??
    mediaAudio.nombre_whatsapp ??
    normalizado.nombre_whatsapp ??
    entradaWhatsApp.nombre_whatsapp ??
    conversacion.nombre_whatsapp ??
    conversacion.prospecto_nombre
  );


// ======================================================
// 5. TIPO DE ENTRADA
// ======================================================

const tipoEntrada =
  (
    texto(
      input.tipo ??
      input.tipo_mensaje ??
      input.tipo_original ??
      input.meta_whatsapp?.tipo_original ??
      mediaAudio.tipo ??
      mediaAudio.tipo_media ??
      normalizado.tipo ??
      entradaWhatsApp.tipo ??
      entradaWhatsApp.meta_whatsapp?.tipo_original
    ) ??
    'DESCONOCIDO'
  ).toUpperCase();


// ======================================================
// 6. MENSAJE ORIGINAL DEL CLIENTE
// ======================================================

let mensajeActual =
  texto(
    input.mensaje_actual
  ) ??
  texto(
    input.mensaje_cliente_original
  ) ??
  texto(
    input.mensaje
  ) ??
  texto(
    input.contenido
  ) ??
  texto(
    input.texto_asociado
  ) ??
  texto(
    input.caption
  ) ??
  texto(
    input.meta_whatsapp?.media?.caption
  ) ??
  texto(
    mediaAudio.texto_asociado
  ) ??
  texto(
    mediaAudio.contenido_base
  ) ??
  texto(
    normalizado.mensaje
  ) ??
  texto(
    entradaWhatsApp.mensaje
  ) ??
  '';


// Si el mensaje quedó únicamente como descriptor de sistema,
// construimos una representación más humana.

if (
  mensajeActual === '[AUDIO]' ||
  mensajeActual === '[VIDEO]' ||
  mensajeActual === '[DOCUMENTO]'
) {

  const descripcionTipo =
    tipoEntrada === 'AUDIO'
      ? 'Audio enviado por el prospecto'
      : tipoEntrada === 'VIDEO'
        ? 'Video enviado por el prospecto'
        : tipoEntrada === 'DOCUMENTO'
          ? 'Documento enviado por el prospecto'
          : 'Archivo enviado por el prospecto';

  mensajeActual =
    `[${descripcionTipo}]`;
}


// ======================================================
// 7. DETECTAR FALLO DE TRANSCRIPCIÓN DE AUDIO
// ======================================================
//
// Esta detección permite que este mismo nodo reciba:
//
// - false de "IF: ¿Transcripción válida Deepgram?"
// - error de "Transcribir audio Deepgram"
// - error de descarga del audio fallback
//
// sin confundirlo con una entrada simplemente no soportada.
// ======================================================

const errorActual =
  texto(
    input.error_transcripcion ??
    input.detalle_error ??
    input.details?.message ??
    input.error?.message ??
    input.error
  );


const proveedorTranscripcion =
  texto(
    input.proveedor_transcripcion ??
    input.proveedor_fallback
  );


const pareceAudio =
  tipoEntrada === 'AUDIO' ||
  tipoEntrada === 'VOICE' ||
  input.audio_preparado === true ||
  input.fallback_audio === true ||
  input.media_id !== undefined ||
  mediaAudio.audio_preparado === true ||
  mediaAudio.media_id !== undefined;


const transcripcionMarcadaInvalida =
  input.transcripcion_valida === false;


const falloDeepgram =
  proveedorTranscripcion === 'DEEPGRAM' ||
  input.proveedor_fallback === 'DEEPGRAM';


const falloTranscripcionAudio =
  pareceAudio &&
  (
    transcripcionMarcadaInvalida ||
    falloDeepgram ||
    errorActual !== null
  );


// ======================================================
// 8. MOTIVO DE HANDOFF
// ======================================================

let motivo =
  'ENTRADA_NO_SOPORTADA';


let prioridad =
  'NORMAL';


let mensajeTransicion =
  'Permítame un momento por favor, ya revisamos lo que nos envió.';


// ------------------------------------------------------
// FALLO TOTAL DE TRANSCRIPCIÓN
// ------------------------------------------------------

if (falloTranscripcionAudio) {

  motivo =
    'AUDIO_REQUIERE_REVISION';

  prioridad =
    'MEDIA';

  mensajeTransicion =
    'Permítame un momento por favor, no pudimos interpretar correctamente el audio que nos envió y vamos a revisarlo manualmente.';

}


// ------------------------------------------------------
// ENTRADA NO SOPORTADA NORMAL
// ------------------------------------------------------

else {

  switch (tipoEntrada) {

    case 'AUDIO':
    case 'VOICE':

      motivo =
        'AUDIO_REQUIERE_REVISION';

      prioridad =
        'MEDIA';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos el audio que nos envió.';

      break;


    case 'VIDEO':

      motivo =
        'VIDEO_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos el video que nos envió.';

      break;


    case 'DOCUMENTO':
    case 'DOCUMENT':

      motivo =
        'DOCUMENTO_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos el archivo que nos envió.';

      break;


    case 'STICKER':

      motivo =
        'STICKER_NO_PROCESABLE';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos su mensaje.';

      break;


    case 'LOCATION':
    case 'UBICACION':

      motivo =
        'UBICACION_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos la ubicación que nos envió.';

      break;


    case 'CONTACT':
    case 'CONTACTO':
    case 'CONTACTS':

      motivo =
        'CONTACTO_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos la información que nos envió.';

      break;


    default:

      motivo =
        'ENTRADA_NO_SOPORTADA';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos lo que nos envió.';
  }
}


// ======================================================
// 9. DATOS TÉCNICOS DE AUDIO
// ======================================================

const mediaId =
  texto(
    input.media_id ??
    mediaAudio.media_id ??
    entradaWhatsApp.meta_whatsapp?.media?.id
  );


const mimeType =
  texto(
    input.mime_type ??
    mediaAudio.mime_type ??
    entradaWhatsApp.meta_whatsapp?.media?.mime_type
  );


const indiceAudio =
  numeroONull(
    input.indice_audio ??
    mediaAudio.indice_audio
  );


// ======================================================
// 10. CLASIFICACIÓN DEL ORIGEN DEL HANDOFF
// ======================================================

let origenHandoff =
  'ENTRADA_NO_SOPORTADA';


if (falloTranscripcionAudio) {

  origenHandoff =
    'FALLO_TRANSCRIPCION_AUDIO';

}


// ======================================================
// 11. VALIDACIONES MÍNIMAS
// ======================================================
//
// No obligamos prospecto_id aquí porque existen rutas
// donde podría tratarse de un cliente registrado.
//
// La ruta estándar de derivación decidirá después qué
// identidad debe persistir.
//
// Sí necesitamos conversación para no crear un handoff
// huérfano.
// ======================================================

if (
  conversacionId === null ||
  conversacionId <= 0
) {

  throw new Error(
    'PREPARAR HANDOFF ENTRADA NO SOPORTADA: no se pudo resolver conversacion_id.'
  );

}


// ======================================================
// 12. SALIDA
// ======================================================

return [
  {
    json: {

      // ------------------------------------------------
      // CONSERVAR CONTRATO ORIGINAL
      // ------------------------------------------------

      ...input,


      // ------------------------------------------------
      // IDENTIDAD
      // ------------------------------------------------

      conversacion_id:
        conversacionId,

      prospecto_id:
        prospectoId,

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      telefono,

      nombre_whatsapp:
        nombreWhatsApp,

      prospecto_nombre:
        nombreWhatsApp,


      // ------------------------------------------------
      // DECISIÓN
      // ------------------------------------------------

      intencion:
        'SOLICITAR_HUMANO',

      accion:
        'DERIVAR_HUMANO',

      requiere_humano:
        true,

      requiere_notificacion:
        true,

      handoff_requiere_notificacion:
        true,


      // ------------------------------------------------
      // HANDOFF
      // ------------------------------------------------

      handoff_motivo:
        motivo,

      motivo_derivacion:
        motivo,

      handoff_prioridad:
        prioridad,

      prioridad_derivacion:
        prioridad,

      origen_handoff:
        origenHandoff,

      clasificacion_handoff:
        falloTranscripcionAudio
          ? 'REVISION_AUDIO'
          : 'REVISION_ENTRADA',


      // ------------------------------------------------
      // MENSAJE DEL CLIENTE
      // ------------------------------------------------

      mensaje_actual:
        mensajeActual,

      mensaje_cliente_original:
        mensajeActual,

      handoff_mensaje_cliente:
        mensajeActual,


      // ------------------------------------------------
      // RESPUESTA DE TRANSICIÓN
      // ------------------------------------------------

      respuesta_sugerida:
        mensajeTransicion,

      mensaje_transicion:
        mensajeTransicion,


      // ------------------------------------------------
      // TIPO DE ENTRADA
      // ------------------------------------------------

      tipo_entrada_no_soportada:
        tipoEntrada,


      // ------------------------------------------------
      // AUDIO / TRANSCRIPCIÓN
      // ------------------------------------------------

      fallo_transcripcion_audio:
        falloTranscripcionAudio,

      proveedor_transcripcion:
        proveedorTranscripcion,

      media_id:
        mediaId,

      mime_type:
        mimeType,

      indice_audio:
        indiceAudio,

      error_transcripcion_handoff:
        errorActual,


      // ------------------------------------------------
      // CONTROL
      // ------------------------------------------------

      derivacion_directa_entrada:
        true,

      derivacion_directa:
        true,

      derivacion_directa_motivo:
        falloTranscripcionAudio
          ? 'FALLO_TOTAL_TRANSCRIPCION_AUDIO'
          : 'ENTRADA_NO_SOPORTADA',

      handoff_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// NODO N8N: Preparar audio del turno
// ARCHIVO: code/03-conversacion/preparar-audio-turno.js
// VERSION: 1.0
// RESPONSABILIDAD:
// - Tras resolver el turno conversacional, buscar audios
//   pendientes de transcripción.
// - Leer el descriptor [MEDIA_PENDIENTE] persistido en
//   mensajes.contenido.
// - Revalidar MIME y enlace YCloud.
// - Emitir un item por audio válido.
// - Limitar la cantidad de audios procesados por turno.
// - Conservar identidad y contexto del turno.
// - NO descargar audio.
// - NO transcribir.
// - NO llamar al cerebro comercial.
// - NO escribir PostgreSQL.
// ======================================================


// ======================================================
// 0. CONFIGURACIÓN
// ======================================================

const MAX_AUDIOS_POR_TURNO = 3;

const MAX_LINK_LENGTH = 2048;

const PREFIJO_PENDIENTE =
  '[MEDIA_PENDIENTE] ';


// MIME admitidos para STT.
//
// WhatsApp/YCloud normalmente entrega notas de voz como:
// audio/ogg; codecs=opus
//
// En Preparar entrada WhatsApp el MIME debería llegar
// normalizado sin parámetros:
// audio/ogg
// ======================================================

const MIME_AUDIO_SOPORTADOS = [
  'audio/ogg',
  'audio/opus',
  'audio/mpeg',
  'audio/mp3',
  'audio/mp4',
  'audio/x-m4a',
  'audio/m4a',
  'audio/wav',
  'audio/x-wav',
  'audio/webm'
];


// ======================================================
// ANTI-SSRF
// ======================================================

const LINK_YCLOUD_PERMITIDO =
  /^https:\/\/api\.ycloud\.com\/v2\/whatsapp\/media\/download\/[A-Za-z0-9_-]+(\?[A-Za-z0-9%._~&=+-]*)?$/;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero =
    Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function normalizarMime(valor) {

  const mime =
    textoONull(valor);

  if (!mime) {
    return null;
  }

  return mime
    .toLowerCase()
    .split(';')[0]
    .trim();
}


function lineas(contenido) {

  return String(
    contenido ?? ''
  ).split('\n');
}


// ======================================================
// 2. LEER [MEDIA_PENDIENTE]
// ======================================================

function leerPendiente(contenido) {

  const linea =
    lineas(contenido)
      .map(
        valor =>
          valor.trim()
      )
      .find(
        valor =>
          valor.startsWith(
            PREFIJO_PENDIENTE
          )
      );

  if (!linea) {
    return null;
  }

  const jsonTexto =
    linea.slice(
      PREFIJO_PENDIENTE.length
    );

  try {

    const datos =
      JSON.parse(
        jsonTexto
      );

    if (
      !datos ||
      typeof datos !== 'object' ||
      Array.isArray(datos)
    ) {
      return null;
    }

    return datos;

  } catch (error) {

    return null;
  }
}


// ======================================================
// 3. TEXTO/CAPTION DEL AUDIO
// ======================================================

function textoAudioDe(contenido) {

  const primeraLinea =
    lineas(contenido)[0] ?? '';

  return String(
    primeraLinea
  )
    .replace(
      /^\[AUDIO\]\s*/i,
      ''
    )
    .trim();
}


// ======================================================
// 4. RECUPERAR TURNO GANADOR
// ======================================================
//
// IMPORTANTE:
//
// No dependemos del item que llega inmediatamente
// desde la rama de imágenes.
//
// Leemos directamente el contrato original de:
//
// Resolver turno conversacional
//
// De esta forma audio funciona:
// - haya imágenes o no
// - haya pasado por Groq visual
// - haya pasado por DeepSeek visual
// - haya pasado por OpenAI visual
//
// ======================================================

let turno = {};

try {

  turno =
    $('Resolver turno conversacional')
      .first()
      .json ?? {};

} catch (error) {

  turno =
    $input.first().json ?? {};
}


const turnoMensajes =
  Array.isArray(
    turno.turno_mensajes
  )
    ? turno.turno_mensajes
    : [];


// ======================================================
// 5. IDENTIDAD
// ======================================================

const conversacionId =
  numeroONull(
    turno.conversacion_id
  );


const prospectoId =
  numeroONull(
    turno.prospecto_id
  );


const clienteId =
  numeroONull(
    turno.cliente_id
  );


const contactoId =
  numeroONull(
    turno.contacto_id
  );


const telefono =
  textoONull(
    turno.telefono
  );


const nombreWhatsapp =
  textoONull(
    turno.nombre_whatsapp
  );


// ======================================================
// 6. BUSCAR AUDIOS PENDIENTES
// ======================================================

const candidatos = [];

let descartados = 0;


for (
  const mensaje of turnoMensajes
) {

  const tipo =
    String(
      mensaje.tipo ?? ''
    )
      .trim()
      .toUpperCase();


  // --------------------------------------------------
  // Solo AUDIO
  // --------------------------------------------------

  if (
    tipo !== 'AUDIO'
  ) {
    continue;
  }


  // --------------------------------------------------
  // Descriptor multimedia
  // --------------------------------------------------

  const pendiente =
    leerPendiente(
      mensaje.contenido
    );


  if (!pendiente) {

    descartados++;

    continue;
  }


  const mime =
    normalizarMime(
      pendiente.mime_type
    );


  const link =
    textoONull(
      pendiente.link
    );


  const mediaId =
    textoONull(
      pendiente.media_id
    );


  // --------------------------------------------------
  // Validar formato
  // --------------------------------------------------

  const mimeValido =
    mime !== null &&
    MIME_AUDIO_SOPORTADOS.includes(
      mime
    );


  const linkValido =
    link !== null &&
    link.length <=
      MAX_LINK_LENGTH &&
    LINK_YCLOUD_PERMITIDO.test(
      link
    );


  if (
    !mimeValido ||
    !linkValido
  ) {

    descartados++;

    continue;
  }


  // --------------------------------------------------
  // Límite por turno
  // --------------------------------------------------

  if (
    candidatos.length >=
    MAX_AUDIOS_POR_TURNO
  ) {

    descartados++;

    continue;
  }


  const mensajeId =
    numeroONull(
      mensaje.id
    );


  candidatos.push({

    mensaje_id:
      mensajeId,

    media_id:
      mediaId,

    mime_type:
      mime,

    media_link:
      link,

    texto_asociado:
      textoAudioDe(
        mensaje.contenido
      ),

    contenido_base:
      lineas(
        mensaje.contenido
      )[0]?.trim() ??
      '[AUDIO]',

    enviado_at:
      mensaje.enviado_at ??
      null
  });
}


// ======================================================
// 7. NO HAY AUDIOS
// ======================================================
//
// Emitimos SIEMPRE un item.
//
// Así el IF:
//
// ¿Hay audios por transcribir?
//
// puede evaluar:
//
// {{$json.transcribir_audio}}
//
// ======================================================

if (
  candidatos.length === 0
) {

  return [
    {
      json: {

        transcribir_audio:
          false,

        audios_por_transcribir:
          0,

        audios_descartados:
          descartados,


        // ----------------------------------------------
        // IDENTIDAD
        // ----------------------------------------------

        conversacion_id:
          conversacionId,

        prospecto_id:
          prospectoId,

        cliente_id:
          clienteId,

        contacto_id:
          contactoId,

        telefono,

        nombre_whatsapp:
          nombreWhatsapp,


        // ----------------------------------------------
        // TURNO
        // ----------------------------------------------

        turno_mensaje_ids:
          Array.isArray(
            turno.turno_mensaje_ids
          )
            ? turno.turno_mensaje_ids
            : [],

        turno_desde_id:
          numeroONull(
            turno.turno_desde_id
          ),

        turno_hasta_id:
          numeroONull(
            turno.turno_hasta_id
          ),

        turno_texto:
          textoONull(
            turno.turno_texto
          ),


        // ----------------------------------------------
