// ======================================================
// NODO N8N: Validar transcripción audio
// ARCHIVO: code/03-conversacion/validar-transcripcion-audio.js
// VERSION: 2.0
// ======================================================
//
// RESPONSABILIDAD:
//
// - Validar transcripciones provenientes de:
//
//   1. Groq Whisper
//   2. Deepgram Nova
//
// - Detectar automáticamente qué proveedor respondió.
// - Recuperar identidad del audio desde
//   "Preparar audio del turno".
// - Emparejar por posición:
//      indice_audio
//      mensaje_id
//      media_id
//      conversacion_id
// - Entregar un contrato uniforme para:
//
//      IF: ¿Transcripción válida?
//      Aplicar transcripciones al turno
//
// - NO interpretar comercialmente.
// - NO llamar al cerebro comercial.
// - NO escribir PostgreSQL.
// - NO lanzar error por fallo de STT.
//
// ======================================================


const LARGO_MAXIMO_TRANSCRIPCION = 12000;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor, limite = null) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  let limpio = String(valor)
    .replace(/\u0000/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s*\n\s*/g, ' ')
    .trim();

  if (!limpio) {
    return null;
  }

  if (
    limite !== null &&
    Number.isFinite(limite) &&
    limite > 0
  ) {
    limpio = limpio.slice(0, limite);
  }

  return limpio;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero = Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function normalizarError(valor) {

  if (!valor) {
    return null;
  }

  if (typeof valor === 'string') {
    return textoONull(valor, 1500);
  }

  if (typeof valor === 'object') {

    try {
      return textoONull(
        JSON.stringify(valor),
        1500
      );
    } catch (_) {
      return 'ERROR_NO_SERIALIZABLE';
    }

  }

  return textoONull(
    valor,
    1500
  );
}


// ======================================================
// 2. DETECTAR ERROR HTTP / N8N
// ======================================================

function detectarErrorRespuesta(json) {

  if (
    !json ||
    typeof json !== 'object'
  ) {
    return {
      existe: true,
      motivo: 'RESPUESTA_VACIA',
      error: 'La respuesta del proveedor STT está vacía.'
    };
  }


  // --------------------------------------------------
// Errores n8n HTTP Request
// --------------------------------------------------

  if (json.error) {

    return {
      existe: true,
      motivo: 'ERROR_TRANSCRIPCION',
      error:
        normalizarError(
          json.error
        ) ??
        'El proveedor de transcripción devolvió un error.'
    };

  }


  if (
    numeroONull(
      json.statusCode
    ) !== null &&
    Number(
      json.statusCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.message ??
          json.body ??
          json
        )
    };

  }


  if (
    numeroONull(
      json.details?.httpCode
    ) !== null &&
    Number(
      json.details.httpCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.details
        )
    };

  }


  return {
    existe: false,
    motivo: null,
    error: null
  };
}


// ======================================================
// 3. LEER RESPUESTA GROQ
// ======================================================
//
// Groq:
//
// {
//   "text": "..."
// }
//
// ======================================================

function leerGroq(json) {

  const texto =
    textoONull(
      json.text ??
      json.body?.text ??
      json.data?.text ??
      json.response?.text,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  if (!texto) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'GROQ',

    modelo:
      'whisper-large-v3-turbo',

    texto,

    confianza:
      null,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 4. LEER RESPUESTA DEEPGRAM
// ======================================================
//
// Deepgram:
//
// {
//   results: {
//     channels: [
//       {
//         alternatives: [
//           {
//             transcript: "...",
//             confidence: 0.99
//           }
//         ]
//       }
//     ]
//   }
// }
//
// ======================================================

function leerDeepgram(json) {

  const alternativa =
    json.results
      ?.channels
      ?.[0]
      ?.alternatives
      ?.[0] ??
    null;


  const texto =
    textoONull(
      alternativa?.transcript ??
      json.results
        ?.utterances
        ?.[0]
        ?.transcript ??
      json.results
        ?.channels
        ?.[0]
        ?.alternatives
        ?.[0]
        ?.paragraphs
        ?.transcript,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  const confianza =
    numeroONull(
      alternativa?.confidence
    );


  const pareceDeepgram =
    !!json.metadata ||
    !!json.results?.channels ||
    !!json.results?.utterances;


  if (!pareceDeepgram) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  if (!texto) {

    return {
      reconocido: true,
      valido: false,

      proveedor:
        'DEEPGRAM',

      modelo:
        json.metadata?.model_info
          ? Object.values(
              json.metadata.model_info
            )[0]?.name ?? 'nova-3'
          : 'nova-3',

      texto:
        null,

      confianza,

      motivo:
        'TRANSCRIPCION_VACIA',

      error:
        'Deepgram respondió correctamente pero no devolvió texto utilizable.'
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'DEEPGRAM',

    modelo:
      json.metadata?.model_info
        ? Object.values(
            json.metadata.model_info
          )[0]?.name ?? 'nova-3'
        : 'nova-3',

    texto,

    confianza,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 5. LEER RESPUESTA STT
// ======================================================

function leerRespuestaSTT(json) {

  const error =
    detectarErrorRespuesta(
      json
    );


  if (
    error.existe
  ) {

    return {
      valido:
        false,

      proveedor:
        null,

      modelo:
        null,

      texto:
        null,

      confianza:
        null,

      motivo:
        error.motivo,

      error:
        error.error
    };

  }


  // --------------------------------------------------
// 5.1 DEEPGRAM
// --------------------------------------------------

  const deepgram =
    leerDeepgram(
      json
    );


  if (
    deepgram.reconocido
  ) {
    return deepgram;
  }


  // --------------------------------------------------
// 5.2 GROQ
// --------------------------------------------------

  const groq =
    leerGroq(
      json
    );


  if (
    groq.reconocido
  ) {
    return groq;
  }


  // --------------------------------------------------
// 5.3 DESCONOCIDO
// --------------------------------------------------

  return {
    valido:
      false,

    proveedor:
      null,

    modelo:
      null,

    texto:
      null,

    confianza:
      null,

    motivo:
      'FORMATO_RESPUESTA_DESCONOCIDO',

    error:
      'El proveedor STT respondió, pero el formato de respuesta no coincide con Groq ni Deepgram.'
  };
}


