// NODO N8N: Aplicar transcripciones al turno
// ARCHIVO: code/03-conversacion/aplicar-transcripciones-turno.js
// VERSION: 1.0
// ======================================================
//
// RESPONSABILIDAD:
//
// - Recibir todas las transcripciones validadas del turno.
// - Recuperar el turno original desde
//   "Resolver turno conversacional".
// - Asociar cada transcripción por mensaje_id.
// - Sustituir el marcador [MEDIA_PENDIENTE] del AUDIO
//   por su transcripción.
// - Eliminar URLs / metadatos técnicos antes de enviar
//   contenido al cerebro comercial.
// - Mantener el orden cronológico de los mensajes.
// - Generar UN SOLO ITEM para "Preparar contexto IA".
// - Informar si algún audio falló.
//
// IMPORTANTE:
//
// Este nodo NO:
// - interpreta comercialmente los audios
// - llama IA
// - responde al cliente
// - escribe PostgreSQL
//
// ======================================================


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor, limite = null) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  let limpio =
    String(valor).trim();

  if (!limpio) {
    return null;
  }

  if (
    limite !== null &&
    Number.isFinite(limite) &&
    limite > 0
  ) {
    limpio =
      limpio.slice(0, limite);
  }

  return limpio;
}


function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero =
    Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function normalizarTipo(valor) {
  return String(
    valor ?? ''
  )
    .trim()
    .toUpperCase();
}


function primeraLinea(contenido) {
  const linea =
    String(contenido ?? '')
      .split('\n')[0]
      ?.trim();

  return linea || null;
}


function contenidoBaseAudio(contenido) {
  const primera =
    primeraLinea(contenido);

  if (
    primera &&
    primera.startsWith('[AUDIO]')
  ) {
    return primera;
  }

  return '[AUDIO]';
}


// ======================================================
// 2. RECUPERAR TURNO ORIGINAL
// ======================================================

let turno = {};

try {
  turno =
    $('Resolver turno conversacional')
      .first()
      .json ?? {};
} catch (_) {
  turno = {};
}


const conversacionId =
  numeroONull(
    turno.conversacion_id
  );


if (!conversacionId) {
  throw new Error(
    'APLICAR TRANSCRIPCIONES: no existe conversacion_id en "Resolver turno conversacional".'
  );
}


const turnoMensajes =
  Array.isArray(turno.turno_mensajes)
    ? turno.turno_mensajes
    : [];


if (turnoMensajes.length === 0) {
  throw new Error(
    'APLICAR TRANSCRIPCIONES: el turno no contiene mensajes.'
  );
}


// ======================================================
// 3. RECIBIR TRANSCRIPCIONES
// ======================================================

const entradas =
  $input.all()
    .map(item => item.json ?? {});


// ======================================================
// 4. INDEXAR POR mensaje_id
// ======================================================

const porMensajeId =
  new Map();

const mensajesDuplicados =
  new Set();


for (const item of entradas) {

  const mensajeId =
    numeroONull(
      item.mensaje_id
    );

  if (mensajeId === null) {
    continue;
  }

  if (porMensajeId.has(mensajeId)) {
    mensajesDuplicados.add(
      mensajeId
    );

    continue;
  }

  porMensajeId.set(
    mensajeId,
    item
  );
}


// ======================================================
// 5. APLICAR TRANSCRIPCIONES
// ======================================================

let audiosEnTurno = 0;
let transcripcionesValidas = 0;
let transcripcionesFallidas = 0;
let audiosSinResultado = 0;

const motivosRevision =
  new Set();

const transcripciones =
  [];


const mensajesActualizados =
  turnoMensajes.map(mensaje => {

    const mensajeId =
      numeroONull(
        mensaje.id
      );

    const tipo =
      normalizarTipo(
        mensaje.tipo
      );


    // ==================================================
    // MENSAJE NO AUDIO
    // ==================================================

    if (tipo !== 'AUDIO') {
      return {
        ...mensaje
      };
    }


    audiosEnTurno++;


    // ==================================================
    // AUDIO
    // ==================================================

    const base =
      contenidoBaseAudio(
        mensaje.contenido
      );

    const resultado =
      mensajeId !== null
        ? porMensajeId.get(mensajeId)
        : null;


    // ==================================================
    // 5.1 NO EXISTE RESULTADO PARA ESTE AUDIO
    // ==================================================

    if (!resultado) {

      audiosSinResultado++;

      motivosRevision.add(
        'AUDIO_SIN_RESULTADO'
      );

      return {
        ...mensaje,

        contenido:
          `${base}\n` +
          '[TRANSCRIPCION DE AUDIO · revision=SI · motivo=AUDIO_SIN_RESULTADO] ' +
          'Este audio no pudo procesarse automáticamente.',

        audio_transcrito:
          false,

        audio_requiere_revision:
          true,

        transcripcion:
          null
      };
    }


    // ==================================================
    // 5.2 RESULTADO DUPLICADO
    // ==================================================

    if (
      mensajeId !== null &&
      mensajesDuplicados.has(mensajeId)
    ) {

      transcripcionesFallidas++;

      motivosRevision.add(
        'TRANSCRIPCION_DUPLICADA'
      );

      return {
        ...mensaje,

        contenido:
          `${base}\n` +
          '[TRANSCRIPCION DE AUDIO · revision=SI · motivo=TRANSCRIPCION_DUPLICADA] ' +
          'Se recibieron varias transcripciones para el mismo audio.',

        audio_transcrito:
          false,

        audio_requiere_revision:
          true,

        transcripcion:
          null
      };
    }


    const transcripcionValida =
      resultado.transcripcion_valida === true;

    const textoTranscrito =
      textoONull(
        resultado.texto_transcrito,
        12000
      );


    // ==================================================
    // 5.3 TRANSCRIPCIÓN FALLIDA
    // ==================================================

    if (
      !transcripcionValida ||
      !textoTranscrito
    ) {

      transcripcionesFallidas++;

      const motivo =
        textoONull(
          resultado.motivo_revision
        ) ??
        'TRANSCRIPCION_NO_DISPONIBLE';

      motivosRevision.add(
        motivo
      );

      transcripciones.push({
        mensaje_id:
          mensajeId,

        indice_audio:
          numeroONull(
            resultado.indice_audio
          ),

        media_id:
          textoONull(
            resultado.media_id
          ),

        valida:
          false,

        texto:
          null,

        motivo_revision:
          motivo,

        proveedor:
          textoONull(
            resultado.proveedor_transcripcion
          ),

        modelo:
          textoONull(
            resultado.modelo_transcripcion
          )
      });


      return {
        ...mensaje,

        contenido:
          `${base}\n` +
          `[TRANSCRIPCION DE AUDIO · revision=SI · motivo=${motivo}] ` +
          'No fue posible transcribir automáticamente este audio.',

        audio_transcrito:
          false,

        audio_requiere_revision:
          true,

        transcripcion:
          null,

        motivo_revision_audio:
          motivo
      };
    }


    // ==================================================
    // 5.4 TRANSCRIPCIÓN CORRECTA
    // ==================================================

    transcripcionesValidas++;


    transcripciones.push({
      mensaje_id:
        mensajeId,

      indice_audio:
        numeroONull(
          resultado.indice_audio
        ),

      media_id:
        textoONull(
          resultado.media_id
        ),

      valida:
        true,

      texto:
        textoTranscrito,

      motivo_revision:
        null,

      proveedor:
        textoONull(
          resultado.proveedor_transcripcion
        ) ??
        'GROQ',

      modelo:
        textoONull(
          resultado.modelo_transcripcion
        ) ??
        'whisper-large-v3-turbo'
    });


    return {
      ...mensaje,

      contenido:
        `${base}\n` +
        `[TRANSCRIPCION DE AUDIO · proveedor=${textoONull(resultado.proveedor_transcripcion) ?? 'GROQ'}] ` +
        textoTranscrito,

      audio_transcrito:
        true,

      audio_requiere_revision:
        false,

      transcripcion:
        textoTranscrito,

      proveedor_transcripcion:
        textoONull(
          resultado.proveedor_transcripcion
        ) ??
        'GROQ'
    };
  });


// ======================================================
// 6. RECONSTRUIR TURNO TEXTO
// ======================================================
//
// Este es el contenido que posteriormente debe poder
// consumir "Preparar contexto IA".
//
// Ejemplo:
//
// [AUDIO]
// [TRANSCRIPCION DE AUDIO · proveedor=GROQ] Hola...
//
// quiero 1000 etiquetas
//
// [AUDIO]
// [TRANSCRIPCION DE AUDIO · proveedor=GROQ] de 10x5...
//
// ======================================================

const turnoTextoActualizado =
  mensajesActualizados
    .map(mensaje =>
      textoONull(
        mensaje.contenido,
        15000
      )
    )
    .filter(Boolean)
    .join('\n');


// ======================================================
// 7. ESTADO GLOBAL DEL AUDIO
// ======================================================

const totalFallos =
  transcripcionesFallidas +
  audiosSinResultado;


const requiereRevisionAudio =
  totalFallos > 0;


const audioListoParaCerebro =
  !requiereRevisionAudio;


// ======================================================
// 8. IDENTIDAD ADICIONAL
// ======================================================

let audioOrigen = {};

try {
  audioOrigen =
    $('Preparar audio del turno')
      .first()
      .json ?? {};
} catch (_) {
  audioOrigen = {};
}


// ======================================================
// 9. SALIDA ÚNICA
// ======================================================
//
// SIEMPRE devolvemos UN SOLO ITEM.
//
// Esto es deliberado.
//
// Tres audios:
//   ↓
// tres transcripciones
//   ↓
// UN turno enriquecido
//   ↓
// UNA decisión comercial
//
// ======================================================

return [
  {
    json: {

      // ==================================================
      // CONTRATO ORIGINAL DEL TURNO
      // ==================================================

      ...turno,


      // ==================================================
      // IDENTIDAD
      // ==================================================

      conversacion_id:
        conversacionId,

      prospecto_id:
        numeroONull(
          audioOrigen.prospecto_id ??
          turno.prospecto_id
        ),

      cliente_id:
        numeroONull(
          audioOrigen.cliente_id ??
          turno.cliente_id
        ),

      contacto_id:
        numeroONull(
          audioOrigen.contacto_id ??
          turno.contacto_id
        ),

      telefono:
        textoONull(
          audioOrigen.telefono ??
          turno.telefono
        ),

      nombre_whatsapp:
        textoONull(
          audioOrigen.nombre_whatsapp ??
          turno.nombre_whatsapp
        ),


      // ==================================================
      // TURNO ENRIQUECIDO
      // ==================================================

      turno_mensajes:
        mensajesActualizados,

      turno_texto:
        turnoTextoActualizado,

      turno_mensaje_ids:
        mensajesActualizados
          .map(m => numeroONull(m.id))
          .filter(id => id !== null),

      cantidad_mensajes_turno:
        mensajesActualizados.length,


      // ==================================================
      // TRANSCRIPCIONES
      // ==================================================

      transcripciones_audio:
        transcripciones,

      audios_en_turno:
        audiosEnTurno,

      transcripciones_validas:
        transcripcionesValidas,

      transcripciones_fallidas:
        transcripcionesFallidas,

      audios_sin_resultado:
        audiosSinResultado,


      // ==================================================
      // CONTROL GLOBAL
      // ==================================================

      audio_procesado:
        true,

      audio_listo_para_cerebro:
        audioListoParaCerebro,

      requiere_revision_audio:
        requiereRevisionAudio,

      motivos_revision_audio:
        Array.from(
          motivosRevision
        ),

      transcripciones_aplicadas:
        transcripcionesValidas > 0,

      procesado_audio_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// NODO N8N: Preparar fallback Deepgram
// PEGASO ADHESIVOS
// VERSION: 1.0
// ======================================================
//
// Se ejecuta cuando la transcripción primaria con Groq
// no fue válida.
//
// RESPONSABILIDAD:
//
// - Recibir uno o varios audios fallidos.
// - Recuperar su metadata original desde
//   "Preparar audio del turno".
// - Emparejar por mensaje_id / media_id.
// - Preparar nuevamente media_link para volver a
//   descargar el archivo desde YCloud.
// - NO transcribir.
// - NO decidir handoff.
// ======================================================

const fallidos = $input.all();


// ======================================================
// 1. HELPERS
// ======================================================

function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const t = String(valor).trim();

  return t !== ''
    ? t
    : null;
}


// ======================================================
// 2. RECUPERAR AUDIOS ORIGINALES
// ======================================================

let originales = [];

try {
  originales =
    $('Preparar audio del turno')
      .all()
      .map(item => item.json ?? {});
} catch (_) {
  originales = [];
}


// ======================================================
// 3. EMPAREJAR FALLIDOS CON AUDIO ORIGINAL
// ======================================================

const resultados = fallidos.map((item, indice) => {

  const fallido =
    item.json ?? {};

  const mensajeId =
    numeroONull(fallido.mensaje_id);

  const mediaId =
    textoONull(fallido.media_id);


  // --------------------------------------------------
  // Buscar preferentemente por mensaje_id.
  // Si no existe, por media_id.
  // Último fallback: posición.
  // --------------------------------------------------

  let original =
    originales.find(o =>
      mensajeId !== null &&
      numeroONull(o.mensaje_id) === mensajeId
    );

  if (!original && mediaId) {
    original =
      originales.find(o =>
        textoONull(o.media_id) === mediaId
      );
  }

  if (!original) {
    original =
      originales[indice] ?? {};
  }


  // ==================================================
  // 4. DATOS DEL AUDIO
  // ==================================================

  const mediaLink =
    textoONull(
      original.media_link ??
      fallido.media_link
    );

  const mimeType =
    textoONull(
      original.mime_type ??
      fallido.mime_type
    ) ??
    'audio/ogg';

  const mediaIdFinal =
    textoONull(
      original.media_id ??
      fallido.media_id
    );

  const mensajeIdFinal =
    numeroONull(
      original.mensaje_id ??
      fallido.mensaje_id
    );


  if (!mediaLink) {
    throw new Error(
      `PREPARAR FALLBACK DEEPGRAM: no se pudo recuperar media_link para mensaje_id=${mensajeIdFinal ?? 'null'}.`
    );
  }


  // ==================================================
  // 5. SALIDA
  // ==================================================

  return {
    json: {

      ...fallido,

      mensaje_id:
        mensajeIdFinal,

      media_id:
        mediaIdFinal,

      media_link:
        mediaLink,

      mime_type:
        mimeType,

      indice_audio:
        numeroONull(
          original.indice_audio ??
          fallido.indice_audio
        ) ?? indice,

      conversacion_id:
        numeroONull(
          original.conversacion_id ??
          fallido.conversacion_id
        ),

      prospecto_id:
        numeroONull(
          original.prospecto_id ??
          fallido.prospecto_id
        ),

      telefono:
        textoONull(
          original.telefono ??
          fallido.telefono
        ),

      nombre_whatsapp:
        textoONull(
          original.nombre_whatsapp ??
          fallido.nombre_whatsapp
        ),

      proveedor_fallback:
        'DEEPGRAM',

      fallback_audio:
        true,

      fallback_preparado_at:
        new Date().toISOString()
    }
  };
});

return resultados;

// ======================================================
// NODO N8N: Validar transcripción audio
// ARCHIVO: code/03-conversacion/validar-transcripcion-audio.js
// VERSION: 2.0
// ======================================================
//
// RESPONSABILIDAD:
//
// - Validar transcripciones provenientes de:
//
//   1. Groq Whisper
//   2. Deepgram Nova
//
// - Detectar automáticamente qué proveedor respondió.
// - Recuperar identidad del audio desde
//   "Preparar audio del turno".
// - Emparejar por posición:
//      indice_audio
//      mensaje_id
//      media_id
//      conversacion_id
// - Entregar un contrato uniforme para:
//
//      IF: ¿Transcripción válida?
//      Aplicar transcripciones al turno
//
// - NO interpretar comercialmente.
// - NO llamar al cerebro comercial.
// - NO escribir PostgreSQL.
// - NO lanzar error por fallo de STT.
//
// ======================================================


const LARGO_MAXIMO_TRANSCRIPCION = 12000;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor, limite = null) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  let limpio = String(valor)
    .replace(/\u0000/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s*\n\s*/g, ' ')
    .trim();

  if (!limpio) {
    return null;
  }

  if (
    limite !== null &&
    Number.isFinite(limite) &&
    limite > 0
  ) {
    limpio = limpio.slice(0, limite);
  }

  return limpio;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero = Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function normalizarError(valor) {

  if (!valor) {
    return null;
  }

  if (typeof valor === 'string') {
    return textoONull(valor, 1500);
  }

  if (typeof valor === 'object') {

    try {
      return textoONull(
        JSON.stringify(valor),
        1500
      );
    } catch (_) {
      return 'ERROR_NO_SERIALIZABLE';
    }

  }

  return textoONull(
    valor,
    1500
  );
}


// ======================================================
// 2. DETECTAR ERROR HTTP / N8N
// ======================================================

function detectarErrorRespuesta(json) {

  if (
    !json ||
    typeof json !== 'object'
  ) {
    return {
      existe: true,
      motivo: 'RESPUESTA_VACIA',
      error: 'La respuesta del proveedor STT está vacía.'
    };
  }


  // --------------------------------------------------
// Errores n8n HTTP Request
// --------------------------------------------------

  if (json.error) {

    return {
      existe: true,
      motivo: 'ERROR_TRANSCRIPCION',
      error:
        normalizarError(
          json.error
        ) ??
        'El proveedor de transcripción devolvió un error.'
    };

  }


  if (
    numeroONull(
      json.statusCode
    ) !== null &&
    Number(
      json.statusCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.message ??
          json.body ??
          json
        )
    };

  }


  if (
    numeroONull(
      json.details?.httpCode
    ) !== null &&
    Number(
      json.details.httpCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.details
        )
    };

  }


  return {
    existe: false,
    motivo: null,
    error: null
  };
}


// ======================================================
// 3. LEER RESPUESTA GROQ
// ======================================================
//
// Groq:
//
// {
//   "text": "..."
// }
//
// ======================================================

function leerGroq(json) {

  const texto =
    textoONull(
      json.text ??
      json.body?.text ??
      json.data?.text ??
      json.response?.text,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  if (!texto) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'GROQ',

    modelo:
      'whisper-large-v3-turbo',

    texto,

    confianza:
      null,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 4. LEER RESPUESTA DEEPGRAM
// ======================================================
//
// Deepgram:
//
// {
//   results: {
//     channels: [
//       {
//         alternatives: [
//           {
//             transcript: "...",
//             confidence: 0.99
//           }
//         ]
//       }
//     ]
//   }
// }
//
// ======================================================

function leerDeepgram(json) {

  const alternativa =
    json.results
      ?.channels
      ?.[0]
      ?.alternatives
      ?.[0] ??
    null;


  const texto =
    textoONull(
      alternativa?.transcript ??
      json.results
        ?.utterances
        ?.[0]
        ?.transcript ??
      json.results
        ?.channels
        ?.[0]
        ?.alternatives
        ?.[0]
        ?.paragraphs
        ?.transcript,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  const confianza =
    numeroONull(
      alternativa?.confidence
    );


  const pareceDeepgram =
    !!json.metadata ||
    !!json.results?.channels ||
    !!json.results?.utterances;


  if (!pareceDeepgram) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  if (!texto) {

    return {
      reconocido: true,
      valido: false,

      proveedor:
        'DEEPGRAM',

      modelo:
        json.metadata?.model_info
          ? Object.values(
              json.metadata.model_info
            )[0]?.name ?? 'nova-3'
          : 'nova-3',

      texto:
        null,

      confianza,

      motivo:
        'TRANSCRIPCION_VACIA',

      error:
        'Deepgram respondió correctamente pero no devolvió texto utilizable.'
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'DEEPGRAM',

    modelo:
      json.metadata?.model_info
        ? Object.values(
            json.metadata.model_info
          )[0]?.name ?? 'nova-3'
        : 'nova-3',

    texto,

    confianza,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 5. LEER RESPUESTA STT
// ======================================================

function leerRespuestaSTT(json) {

  const error =
    detectarErrorRespuesta(
      json
    );


  if (
    error.existe
  ) {

    return {
      valido:
        false,

      proveedor:
        null,

      modelo:
        null,

      texto:
        null,

      confianza:
        null,

      motivo:
        error.motivo,

      error:
        error.error
    };

  }


  // --------------------------------------------------
// 5.1 DEEPGRAM
// --------------------------------------------------

  const deepgram =
    leerDeepgram(
      json
    );


  if (
    deepgram.reconocido
  ) {
    return deepgram;
  }


  // --------------------------------------------------
// 5.2 GROQ
// --------------------------------------------------

  const groq =
    leerGroq(
      json
    );


  if (
    groq.reconocido
  ) {
    return groq;
  }


  // --------------------------------------------------
// 5.3 DESCONOCIDO
// --------------------------------------------------

  return {
    valido:
      false,

    proveedor:
      null,

    modelo:
      null,

    texto:
      null,

    confianza:
      null,

    motivo:
      'FORMATO_RESPUESTA_DESCONOCIDO',

    error:
      'El proveedor STT respondió, pero el formato de respuesta no coincide con Groq ni Deepgram.'
  };
}


// ======================================================
// 6. RECUPERAR AUDIOS ORIGINALES
// ======================================================
//
// "Preparar audio del turno" sigue siendo la fuente
// principal de identidad.
//
// ======================================================

let origenes = [];

try {

  origenes =
    $('Preparar audio del turno')
      .all()
      .map(
        item =>
          item.json ?? {}
      )
      .filter(
        item =>
          item.transcribir_audio === true
      );

} catch (_) {

  origenes = [];

}


const entradas =
  $input.all();


// ======================================================
// 7. CONSISTENCIA DEL LOTE
// ======================================================

const loteConsistente =
  origenes.length ===
  entradas.length;


// ======================================================
// 8. PROCESAR RESPUESTAS
// ======================================================

const resultados =
  entradas.map(
    (item, indice) => {

      const respuesta =
        item.json ?? {};


      const origen =
        origenes[indice] ?? {};


      const lectura =
        leerRespuestaSTT(
          respuesta
        );


      const mensajeId =
        numeroONull(
          origen.mensaje_id
        );


      const indiceAudio =
        numeroONull(
          origen.indice_audio
        ) ??
        indice;


      const mediaId =
        textoONull(
          origen.media_id
        );


      const conversacionId =
        numeroONull(
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base,
          1500
        ) ??
        '[AUDIO]';


      const prospectoId =
        numeroONull(
          origen.prospecto_id
        );


      const clienteId =
        numeroONull(
          origen.cliente_id
        );


      const contactoId =
        numeroONull(
          origen.contacto_id
        );


      const telefono =
        textoONull(
          origen.telefono
        );


      const nombreWhatsApp =
        textoONull(
          origen.nombre_whatsapp
        );


      const mimeType =
        textoONull(
          origen.mime_type
        );


      const textoAsociado =
        textoONull(
          origen.texto_asociado
        );


      // ==================================================
      // 8.1 ERROR DE CORRELACIÓN
      // ==================================================

      if (
        !loteConsistente
      ) {

        return {
          json: {

            mensaje_id:
              mensajeId,

            indice_audio:
              indiceAudio,

            media_id:
              mediaId,

            conversacion_id:
              conversacionId,

            prospecto_id:
              prospectoId,

            cliente_id:
              clienteId,

            contacto_id:
              contactoId,

            telefono,

            nombre_whatsapp:
              nombreWhatsApp,

            proveedor_transcripcion:
              lectura.proveedor,

            modelo_transcripcion:
              lectura.modelo,

            transcripcion_valida:
              false,

            requiere_revision:
              true,

            motivo_revision:
