            null,

          texto_transcrito:
            textoTranscrito,

          confianza_transcripcion:
            lectura.confianza,

          error_transcripcion:
            null,


          // ----------------------------------------------
          // CONTEXTO ORIGINAL
          // ----------------------------------------------

          mime_type:
            mimeType,

          texto_asociado:
            textoAsociado,

          contenido_base:
            contenidoBase,


          // ----------------------------------------------
          // CONTENIDO SEGURO PARA IA
          // ----------------------------------------------

          contenido_actualizado:
            `${contenidoBase}\n` +
            `[TRANSCRIPCION DE AUDIO · proveedor=${lectura.proveedor}] ${textoTranscrito}`,


          // ----------------------------------------------
          // CONTROL
          // ----------------------------------------------

          transcripcion_validada_at:
            new Date().toISOString()

        }
      };

    }
  );


// ======================================================
// 9. SALIDA
// ======================================================

return resultados;

