// ======================================================
// NODO N8N: PROCESAR COMANDO BOT
// PEGASO ADHESIVOS
// VERSION: 2.0
// ======================================================
//
// Objetivo:
//
// Interpretar comandos administrativos enviados por
// teléfonos autorizados:
//
// STOP  -> activa MODO_PRUEBA
// START -> desactiva MODO_PRUEBA
// ACTIVEBOT 0999999999 -> el bot vuelve a atender a ese
//   prospecto (requiere_humano = false), lo ejecuta
//   "Reactivar bot prospecto"
//
// Este nodo:
// - NO procesa conversaciones comerciales
// - NO busca prospectos
// - NO responde al cerebro comercial
// - NO modifica PostgreSQL
// - Entrega telefono_objetivo solo con dígitos y prefijo
//   593 (0999999999 -> 593999999999)
//
// ======================================================

const input = $input.first().json ?? {};


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}

function limpiarTelefono(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\D/g, '')
      .trim();

  return limpio || null;
}


// ======================================================
// 2. RECUPERAR EVENTO
// ======================================================

const evento =
  input.evento_whatsapp ??
  input;


// ======================================================
// 3. ADMINISTRADORES AUTORIZADOS
// ======================================================

const ADMINISTRADORES = [
  '593996588558',
  '593999217750'
];


// ======================================================
// 4. RESOLVER DATOS
// ======================================================

const telefonoAdmin =
  limpiarTelefono(
    evento.telefono_cliente ??
    evento.from
  );

const textoRecibido =
  textoONull(
    evento.texto ??
    evento.text?.body
  );

const textoComando =
  textoRecibido
    ? textoRecibido.toUpperCase().replace(/\s+/g, ' ')
    : null;

const coincidenciaActivebot =
  textoComando
    ? textoComando.match(/^ACTIVEBOT ([+\d][\d\s\-().]*)$/)
    : null;

const comando =
  coincidenciaActivebot
    ? 'ACTIVEBOT'
    : textoComando;


// Ecuador: 0999999999 / 999999999 / +593 99 999 9999 -> 593999999999
function telefonoEcuador(valor) {
  const digitos =
    limpiarTelefono(valor);

  if (!digitos) {
    return null;
  }

  if (digitos.startsWith('593')) {
    return digitos;
  }

  if (digitos.startsWith('0')) {
    return '593' + digitos.substring(1);
  }

  if (digitos.length === 9) {
    return '593' + digitos;
  }

  return digitos;
}


// ======================================================
// 5. VALIDAR ADMINISTRADOR
// ======================================================

if (
  !telefonoAdmin ||
  !ADMINISTRADORES.includes(telefonoAdmin)
) {
  throw new Error(
    'PROCESAR COMANDO BOT: teléfono no autorizado.'
  );
}


// ======================================================
// 6. VALIDAR COMANDO
// ======================================================

if (
  comando !== 'STOP' &&
  comando !== 'START' &&
  comando !== 'ACTIVEBOT'
) {
  throw new Error(
    `PROCESAR COMANDO BOT: comando no soportado: ${comando ?? 'NULL'}.`
  );
}

const telefonoObjetivo =
  coincidenciaActivebot
    ? telefonoEcuador(coincidenciaActivebot[1])
    : null;

if (
  comando === 'ACTIVEBOT' &&
  !/^\d{11,15}$/.test(telefonoObjetivo ?? '')
) {
  throw new Error(
    `PROCESAR COMANDO BOT: teléfono inválido en ACTIVEBOT: ${coincidenciaActivebot?.[1] ?? 'NULL'}.`
  );
}


// ======================================================
// 7. RESOLVER NUEVO ESTADO
// ======================================================

const modoPruebaNuevo =
  comando === 'STOP';

const botHabilitado =
  comando === 'START';

const MOTIVOS = {
  STOP: 'COMANDO_ADMIN_STOP',
  START: 'COMANDO_ADMIN_START',
  ACTIVEBOT: 'COMANDO_ADMIN_ACTIVEBOT'
};


// ======================================================
// 8. SALIDA
// ======================================================

return [
  {
    json: {
      comando_bot:
        comando,

      telefono_admin:
        telefonoAdmin,

      modo_prueba_nuevo:
        modoPruebaNuevo,

      bot_habilitado:
        botHabilitado,

      telefono_objetivo:
        telefonoObjetivo,

      motivo_cambio:
        MOTIVOS[comando],

      mensaje_externo_id:
        evento.mensaje_id ??
        evento.wamid ??
        null,

      proveedor_evento_id:
        evento.proveedor_evento_id ??
        null,

      comando_valido:
        true,

      procesado_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// NORMALIZAR INTERVENCIÓN HUMANA
// PEGASO ADHESIVOS
// VERSION 1.1
// RESPONSABILIDAD:
// - Normalizar todo mensaje SALIENTE enviado desde la app
//   WhatsApp Business (echo YCloud) para registrarlo.
// - intervencion_humana = false cuando el echo es una
//   automatización de la app (clasificacion_mensaje =
//   SALIENTE_AUTOMATICO): se registra pero no marca
//   atención humana.
// - El contenido de un automático se guarda con el prefijo
//   [AUTOMATICO WHATSAPP BUSINESS · accion=...] para que
//   el historial lo distinga de un mensaje humano.
// ======================================================

const PREFIJO_AUTOMATICO =
  '[AUTOMATICO WHATSAPP BUSINESS';

const input = $input.first()?.json ?? {};

function textoONull(valor) {
  if (valor === undefined || valor === null) {
    return null;
  }

  const t = String(valor).trim();
  return t !== '' ? t : null;
}

function telefono(valor) {
  if (valor === undefined || valor === null) {
    return null;
  }

  const t = String(valor)
    .replace(/\D/g, '')
    .trim();

  return t || null;
}


// ======================================================
// EVENTO NORMALIZADO
// ======================================================

const evento =
  input.evento_whatsapp ??
  input;


// ======================================================
// TELÉFONO CLIENTE
// ======================================================
//
// Para mensajes enviados por Pegaso:
//
// Pegaso = FROM
// Cliente = TO
//
// Si el normalizador ya resolvió telefono_cliente,
// lo usamos primero.
// ======================================================

const telefonoCliente =
  telefono(
    evento.telefono_cliente ??
    evento.to ??
    evento.destino ??
    null
  );

if (!telefonoCliente) {
  throw new Error(
    'INTERVENCION HUMANA: no se pudo resolver telefono_cliente.'
  );
}


// ======================================================
// TELÉFONO PEGASO
// ======================================================

const telefonoPegaso =
  telefono(
    evento.display_phone_number ??
    evento.from ??
    null
  );


// ======================================================
// TIPO
// ======================================================

const tipoOriginal =
  String(
    evento.tipo_mensaje ??
    evento.tipo ??
    'text'
  )
    .trim()
    .toLowerCase();

let tipo = 'DESCONOCIDO';

switch (tipoOriginal) {
  case 'text':
    tipo = 'TEXTO';
    break;

  case 'image':
    tipo = 'IMAGEN';
    break;

  case 'audio':
    tipo = 'AUDIO';
    break;

  case 'video':
    tipo = 'VIDEO';
    break;

  case 'document':
    tipo = 'DOCUMENTO';
    break;

  case 'sticker':
    tipo = 'STICKER';
    break;

  case 'location':
    tipo = 'UBICACION';
    break;
}


// ======================================================
// CONTENIDO
// ======================================================

let contenido = null;

if (tipo === 'TEXTO') {
  contenido =
    textoONull(
      evento.texto ??
      evento.text?.body ??
      evento.mensaje
    );
}

else if (tipo === 'IMAGEN') {
  const caption =
    textoONull(
      evento.caption
    );

  contenido =
    caption
      ? `[IMAGEN] ${caption}`
      : '[IMAGEN]';
}

else if (tipo === 'AUDIO') {
  contenido = '[AUDIO]';
}

else if (tipo === 'VIDEO') {
  const caption =
    textoONull(
      evento.caption
    );

  contenido =
    caption
      ? `[VIDEO] ${caption}`
      : '[VIDEO]';
}

else if (tipo === 'DOCUMENTO') {
  const caption =
    textoONull(
      evento.caption
    );

  contenido =
    caption
      ? `[DOCUMENTO] ${caption}`
      : '[DOCUMENTO]';
}

else {
  contenido =
    `[MENSAJE MANUAL ${tipo}]`;
}


// ======================================================
// AUTOMATIZACIÓN WHATSAPP BUSINESS
// ======================================================

const esAutomatico =
  evento.es_mensaje_automatico_pegaso === true;

const accionEquivalente =
  textoONull(
    evento.accion_equivalente
  );

if (esAutomatico) {
  contenido =
    `${PREFIJO_AUTOMATICO} · accion=${accionEquivalente ?? 'NINGUNA'}] ${contenido ?? ''}`.trim();
}


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      intervencion_humana:
        !esAutomatico,

      origen_mensaje:
        esAutomatico
          ? 'AUTOMATICO_WHATSAPP_BUSINESS'
          : 'HUMANO',

      clasificacion_mensaje:
        esAutomatico
          ? 'SALIENTE_AUTOMATICO'
          : 'SALIENTE_HUMANO',

      automatizacion_codigo:
        textoONull(
          evento.automatizacion_codigo
        ),

      accion_equivalente:
        accionEquivalente,

      enviado_por_bot: false,

      canal: 'WHATSAPP',

      proveedor: 'YCLOUD',

      telefono_cliente:
        telefonoCliente,

      telefono_pegaso:
        telefonoPegaso,

      tipo,

      tipo_original:
        tipoOriginal,

      contenido,

      mensaje_externo_id:
        evento.mensaje_id ??
        evento.wamid ??
        null,

      proveedor_evento_id:
        evento.proveedor_evento_id ??
        null,

      enviado_at:
        evento.fecha_mensaje ??
        (
          evento.timestamp
            ? new Date(
                Number(evento.timestamp) * 1000
              ).toISOString()
            : new Date().toISOString()
        ),

      normalizado_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// PREPARAR MENSAJE HUMANO SALIENTE
// PEGASO ADHESIVOS
// VERSION 1.2
// RESPONSABILIDAD:
// - Armar la fila SALIENTE del echo de WhatsApp Business
//   (humano o automatización) para "Guardar mensaje humano
//   saliente", conservando mensaje_externo_id.
// - origen_mensaje / intervencion_humana vienen de
//   "Normalizar intervención humana", salvo que "Buscar
//   prospecto intervención humana" marque
//   respuesta_rapida_apertura: el eco es la respuesta
//   automática de una pregunta rápida del anuncio y se
//   guarda como AUTOMATICO (no humano).
// ======================================================

const PREFIJO_AUTOMATICO =
  '[AUTOMATICO WHATSAPP BUSINESS';

const conversacion =
  $input.first()?.json ?? {};

const evento =
  $('Normalizar intervención humana')
    .first()
    .json ?? {};

let respuestaRapidaApertura = false;

try {
  respuestaRapidaApertura =
    $('Buscar prospecto intervención humana')
      .first()
      .json
      ?.respuesta_rapida_apertura === true;
} catch (_) {
  respuestaRapidaApertura = false;
}

const automaticoPorApertura =
  evento.intervencion_humana !== false &&
  respuestaRapidaApertura;

const contenidoBase =
  evento.contenido ??
  '[MENSAJE ENVIADO MANUALMENTE]';


const conversacionId =
  Number(
    conversacion.conversacion_id
  );

if (
  !Number.isFinite(conversacionId) ||
  conversacionId <= 0
) {
  throw new Error(
    'MENSAJE HUMANO: conversacion_id inválido.'
  );
}


return [
  {
    json: {

      conversacion_id:
        conversacionId,

      cliente_id:
        conversacion.cliente_id ?? null,

      prospecto_id:
        conversacion.prospecto_id ?? null,

      telefono:
        conversacion.telefono ??
        evento.telefono_cliente ??
        null,

      direccion:
        'SALIENTE',

      tipo:
        evento.tipo ??
        'TEXTO',

      contenido:
        automaticoPorApertura
          ? `${PREFIJO_AUTOMATICO} · accion=NINGUNA · motivo=RESPUESTA_RAPIDA_APERTURA] ${contenidoBase}`
          : contenidoBase,

      mensaje_externo_id:
        evento.mensaje_externo_id ??
        null,

      enviado_at:
        evento.enviado_at ??
        new Date().toISOString(),

      procesado:
        true,

      origen_mensaje:
        automaticoPorApertura
          ? 'AUTOMATICO_WHATSAPP_BUSINESS'
          : evento.origen_mensaje ?? 'HUMANO',

      intervencion_humana:
        evento.intervencion_humana !== false &&
        !automaticoPorApertura,

      respuesta_rapida_apertura:
        automaticoPorApertura

    }
  }
];

// ======================================================
// CALCULAR PRECIO DETALLE
// PEGASO ADHESIVOS - V2.6
// ======================================================
//
// FUENTE ÚNICA DE VERDAD PARA REGLAS DE PRECIO.
//
// Mantiene compatibilidad con:
// - cotizacion_detalles
// - Calcular resumen cotización
// - Recuperar detalles calculados
// - Construir mensaje comercial
//
// ======================================================
//
// ORDEN REAL DEL CALCULO (V2.6):
//
//   1. Validar medida minima (ningun lado < 2 cm).
//   2. Precio fijo (banda pequena $18 / 4x4 $20).
//      Si aplica, se saltan los pasos 3 a 5.
//   3. Dimensiones de calculo: +1/+1 si es 5x5 exacto.
//   4. Dimensiones de calculo: +1/+1 por forma especial.
//   5. Factor:
//      5a. factor del rango de cantidad (1000-2000 / 3000-5000);
//      5b. tamano grande: si ancho_calc x alto_calc x factor
//          del rango > $130 por 1000 -> factor 0.67
//          (solo si es menor que el del rango).
//   6. precio_1000 = ancho_calc x alto_calc x factor
//      (o precio fijo).
//   7. total = precio_1000 x cantidad / 1000 - descuento.
//   8. Redondeo comercial: Math.ceil(total).
//   9. Precio minimo absoluto por detalle: max(total, $18).
//  10. Unitario, subtotal e IVA se derivan del total final.
//
// ======================================================
//
// REGLAS V2.6:
//
// 1. MEDIDA MÍNIMA
//    Ninguna dimensión puede ser < 2 cm.
//    Es decir, 1 cm o menos no se produce.
//
// 2. BANDA FIJA PEQUEÑA $18 / 1000
//    Cualquier medida donde:
//      ancho >= 2 y ancho < 4
//      alto  >= 2 y alto  < 4
//
//    Ejemplos:
//      2x2
//      2x3
//      3x2
//      3x3
//      3x2.5
//      3.2x2
//      3.4x3.2
//      2.2x2.5
//
//    Todas cuestan $18 / 1000.
//
//    La forma NO modifica este precio.
//
// 3. PRECIO FIJO 4x4
//    4x4 cm -> $20 / 1000.
//
// 4. 5x5 cm
//    Para cálculo se aumenta:
//    +1 cm ancho
//    +1 cm alto
//
// 5. RANGOS DE CANTIDAD (reemplazan al factor general 0.72)
//    1000 - 2000 -> factor 0.75
//    3000 - 5000 -> factor 0.67
//    6000 o mas  -> NO se cotiza automaticamente.
//                   "Resolver contexto comercial" deriva
//                   a humano antes de llegar aqui; si
//                   aun asi llega, este nodo lanza error.
//
//    1000 y 2000 comparten precio por 1000: la mejora
//    empieza en 3000 (mejora_precio_desde_cantidad).
//
//    IMPORTANTE:
//    No modifica precios fijos.
//
// 6. TAMANO GRANDE
//    Es grande la etiqueta cuyo precio por 1000 calculado
//    con el factor del rango supera $130.
//    (10x10 = $75 -> mediana).
//    factor = 0.67 si es menor que el del rango.
//
// 7. VOLUMEN >= 10.000 (factor 0.50)
//    Retirado: desde 6000 la cantidad va a humano.
//
// 8. FORMAS ESPECIALES
//    circular / redondeada / troquelada
//    +1 cm ancho
//    +1 cm alto
//
//    EXCEPTO:
//    cuando aplica una banda/precio fijo.
//
// 9. REDONDEO
//    Precio comercial final:
//    Math.ceil(...)
//
// 10. PRECIO MINIMO ABSOLUTO POR DETALLE
//    Despues del redondeo:
//    total = max(total, $18)
//    No altera medidas, cantidad, factor ni precio_1000.
//
// ======================================================


const items =
  $input.all();


const detallesOriginales =
  $('EXPANDIR DETALLES')
    .all();


// ======================================================
// 1. POLÍTICA CENTRAL DE PRECIOS PEGASO
// ======================================================
//
// ESTA ES LA SECCIÓN QUE DEBEMOS EDITAR EN EL FUTURO
// CUANDO CAMBIEN PRECIOS O REGLAS.
//
// ======================================================

const REGLAS_PRECIO = {


  // --------------------------------------------------
  // Restricción mínima
  // --------------------------------------------------

  MEDIDA_MINIMA_PERMITIDA_CM:
    2,


  // --------------------------------------------------
  // Banda fija pequeña
  // --------------------------------------------------
  //
  // Desde 2 cm inclusive
  // hasta 4 cm exclusivo.
  //
  // Ambos lados deben estar dentro de esta banda.
  //
  // --------------------------------------------------

  BANDA_PEQUENA_MIN_CM:
    2,

  BANDA_PEQUENA_MAX_EXCLUSIVO_CM:
    4,

  PRECIO_BANDA_PEQUENA_1000:
    18,


  // --------------------------------------------------
  // Precio fijo 4x4
  // --------------------------------------------------

  PRECIO_FIJO_4X4_1000:
    20,


  // --------------------------------------------------
  // Regla 5x5
  // --------------------------------------------------

  MEDIDA_ESPECIAL_5X5_CM:
    5,

  INCREMENTO_5X5_ANCHO_CM:
    1,

  INCREMENTO_5X5_ALTO_CM:
    1,


  // --------------------------------------------------
  // Rangos de cantidad
  // --------------------------------------------------
  //
  // Ordenados de menor a mayor. Las cantidades ya
  // llegan en multiplos de 1000 (minimo 1000).
  // Por encima del ultimo "hasta" no hay precio
  // automatico: corresponde DERIVAR_HUMANO.
  //
  // --------------------------------------------------

  RANGOS_CANTIDAD: [
    {
      codigo: 'RANGO_1000_2000',
      desde: 1000,
      hasta: 2000,
      factor: 0.75
    },
    {
      codigo: 'RANGO_3000_5000',
      desde: 3000,
      hasta: 5000,
      factor: 0.67
    }
  ],


  // --------------------------------------------------
  // Tamano grande
  // --------------------------------------------------
  //
  // Grande = precio por 1000 calculado con el factor
  // del rango mayor a este limite.
  //
  // --------------------------------------------------

  LIMITE_PRECIO_1000_TAMANO_GRANDE:
    130,

  FACTOR_TAMANO_GRANDE:
    0.67,


  // --------------------------------------------------
  // Precio minimo absoluto por detalle
  // --------------------------------------------------

  PRECIO_MINIMO_DETALLE:
    18,


  // --------------------------------------------------
  // Incremento por forma
  // --------------------------------------------------

  INCREMENTO_FORMA_ANCHO_CM:
    1,

  INCREMENTO_FORMA_ALTO_CM:
    1,


  // --------------------------------------------------
  // IVA interno
  // --------------------------------------------------
  //
  // Se mantiene para DB / contabilidad.
  // No debe mostrarse como "IVA incluido"
  // en el mensaje comercial.
  //
  // --------------------------------------------------

  IVA:
    0.15,


  // --------------------------------------------------
  // Material P4
  // --------------------------------------------------

  MATERIAL_P4_ID:
    1
};


// ======================================================
// 2. HELPERS GENERALES
// ======================================================

function limpiarTexto(
  valor
) {

  return String(
    valor ?? ''
  )
    .trim()
    .toUpperCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}


// ======================================================
// 3. NORMALIZAR FORMA
// ======================================================

function normalizarForma(
  valor
) {

  const forma =
    limpiarTexto(
      valor
    );


  if (!forma) {

    return 'RECTANGULAR';

  }


  // --------------------------------------------------
  // Rectangular / cuadrada
  // --------------------------------------------------

  if (
    forma === 'RECTANGULAR' ||
    forma === 'CUADRADA' ||
    forma === 'CUADRADO'
  ) {

    return 'RECTANGULAR';

  }


  // --------------------------------------------------
  // Redondeada / ovalada
  // --------------------------------------------------

  if (
    forma.includes('PUNTA REDONDEADA') ||
    forma.includes('PUNTAS REDONDEADAS') ||
    forma.includes('ESQUINA REDONDEADA') ||
    forma.includes('ESQUINAS REDONDEADAS') ||
    forma.includes('BORDE REDONDEADO') ||
    forma.includes('BORDES REDONDEADOS') ||
    forma === 'REDONDEADA' ||
    forma === 'REDONDEADO' ||
    forma === 'OVALADA' ||
    forma === 'OVALADO' ||
    forma === 'OVAL'
  ) {

    return 'REDONDEADA';

  }


  // --------------------------------------------------
  // Circular
  // --------------------------------------------------

  if (
    forma === 'CIRCULAR' ||
    forma === 'CIRCULO' ||
    forma === 'REDONDA' ||
    forma === 'REDONDO'
  ) {

    return 'CIRCULAR';

  }


  // --------------------------------------------------
  // Troquelada / irregular
  // --------------------------------------------------

  if (
    forma.includes('TROQUEL') ||
    forma.includes('IRREGULAR') ||
    forma.includes('FORMA ESPECIAL') ||
    forma.includes('FORMA PERSONALIZADA') ||
    forma.includes('CONTORNO') ||
    forma.includes('SILUETA') ||
    forma.includes('ARBOL') ||
    forma.includes('ESTRELLA') ||
    forma.includes('CORAZON') ||
    forma.includes('FLOR') ||
    forma.includes('NUBE') ||
    forma.includes('FIGURA')
  ) {

    return 'TROQUELADA';

  }


  // --------------------------------------------------
  // Conservamos comportamiento existente:
  // forma desconocida = troquelada.
  // --------------------------------------------------

  return 'TROQUELADA';

}


// ======================================================
// 4. INCREMENTO POR FORMA
// ======================================================

function aplicaIncrementoForma(
  formaNormalizada
) {

  return (
    formaNormalizada === 'CIRCULAR' ||
    formaNormalizada === 'TROQUELADA' ||
    formaNormalizada === 'REDONDEADA'
  );

}


// ======================================================
// 5. COMPARAR MEDIDAS
// ======================================================

function iguales(
  a,
  b,
  tolerancia = 0.000001
) {

  return (
    Math.abs(
      Number(a) -
      Number(b)
    ) <=
    tolerancia
  );

}


// ======================================================
// 6. MEDIDA CUADRADA EXACTA
// ======================================================

function esMedidaCuadradaExacta(
  ancho,
  alto,
  medida
) {

  return (
    iguales(
      ancho,
      medida
    ) &&
    iguales(
      alto,
      medida
    )
  );

}


// ======================================================
// 7. VALIDAR MEDIDA MÍNIMA
// ======================================================
//
// Pegaso NO produce etiquetas:
//
// 1x1
// 1x5
// 10x1
// 0.5x8
//
// En general:
// cualquier lado menor de 2 cm.
//
// ======================================================

function validarMedidaMinima(
  ancho,
  alto
) {

  return (
    ancho >=
      REGLAS_PRECIO
        .MEDIDA_MINIMA_PERMITIDA_CM &&
    alto >=
      REGLAS_PRECIO
        .MEDIDA_MINIMA_PERMITIDA_CM
  );

}


// ======================================================
// 8. BANDA FIJA PEQUEÑA
// ======================================================
//
// Regla comercial:
//
// Ambos lados:
//   >= 2 cm
//   < 4 cm
//
// Precio:
//   $18 / 1000
//
// Ejemplos válidos:
//   2x2
//   2x3
//   3x2
//   3x3
//   3x2.5
//   3.2x2
//   3.4x3.2
//   2.2x2.5
//
// ======================================================

function esBandaPequena18(
  ancho,
  alto
) {

  const min =
    REGLAS_PRECIO
      .BANDA_PEQUENA_MIN_CM;

  const max =
    REGLAS_PRECIO
      .BANDA_PEQUENA_MAX_EXCLUSIVO_CM;


  return (
    ancho >= min &&
    ancho < max &&
    alto >= min &&
    alto < max
  );

}


// ======================================================
// 9. RESOLVER PRECIO FIJO
// ======================================================

function resolverPrecioFijo(
  ancho,
  alto
) {


  // --------------------------------------------------
  // Banda pequeña 2 <= lado < 4
  // --------------------------------------------------

  if (
    esBandaPequena18(
      ancho,
      alto
    )
  ) {

    return {

      aplica:
        true,

      precio1000:
        REGLAS_PRECIO
          .PRECIO_BANDA_PEQUENA_1000,

      regla:
        'BANDA_PEQUENA_2_A_MENOR_4'

    };

  }


  // --------------------------------------------------
  // 4x4 exacto
  // --------------------------------------------------

  if (
    esMedidaCuadradaExacta(
      ancho,
      alto,
      4
    )
  ) {

    return {

      aplica:
        true,

      precio1000:
        REGLAS_PRECIO
          .PRECIO_FIJO_4X4_1000,

      regla:
        'PRECIO_FIJO_4X4'

    };

  }


  return {

    aplica:
      false,

    precio1000:
      null,

    regla:
      null

  };

}


// ======================================================
// 10. REGLA ESPECIAL 5X5
// ======================================================

function esEtiqueta5x5(
  ancho,
  alto
) {

  return esMedidaCuadradaExacta(
    ancho,
    alto,
    REGLAS_PRECIO
      .MEDIDA_ESPECIAL_5X5_CM
  );

}


// ======================================================
// 11. RANGO DE CANTIDAD
// ======================================================
//
// Devuelve null si la cantidad supera el ultimo rango
// (6000 o mas): no existe precio automatico.
//
// ======================================================

function resolverRangoCantidad(
  cantidad
) {

  return (
    REGLAS_PRECIO
      .RANGOS_CANTIDAD
      .find(
        rango =>
          cantidad <=
          rango.hasta
      ) ??
    null
  );

}


// ======================================================
// 12. RESOLVER FACTOR
// ======================================================
//
// Solo para precios NO fijos:
//
// 1. Factor del rango de cantidad.
// 2. Tamano grande (precio por 1000 con el factor del
//    rango > $130): factor 0.67 si es menor.
//
// Usa las dimensiones de calculo (ya incluyen +1 cm
// por 5x5 o forma especial).
//
// ======================================================

function resolverFactor(
  cantidad,
  anchoCalculado,
  altoCalculado
) {

  const rango =
    resolverRangoCantidad(
      cantidad
    );


  if (!rango) {

    const rangos =
      REGLAS_PRECIO
        .RANGOS_CANTIDAD;

    throw new Error(
      `Cantidad ${cantidad}: supera ${rangos[rangos.length - 1].hasta} ` +
      `etiquetas y no tiene precio automatico. ` +
      `Debe resolverse con DERIVAR_HUMANO antes de cotizar.`
    );

  }


  const precio1000Rango =
    anchoCalculado *
    altoCalculado *
    rango.factor;


  const tamanoGrande =
    precio1000Rango >
    REGLAS_PRECIO
      .LIMITE_PRECIO_1000_TAMANO_GRANDE;


  if (
    tamanoGrande &&
    REGLAS_PRECIO.FACTOR_TAMANO_GRANDE <
    rango.factor
  ) {

    return {

      factor:
        REGLAS_PRECIO
          .FACTOR_TAMANO_GRANDE,

      regla:
        'TAMANO_GRANDE_MAYOR_130',

      rango,

      precio1000Rango,

      tamanoGrande

    };

  }


  return {

    factor:
      rango.factor,

    regla:
      rango.codigo,

    rango,

    precio1000Rango,

    tamanoGrande

  };

}


// ======================================================
// 12.1 MEJORA EN EL SIGUIENTE RANGO
// ======================================================
//
// Devuelve la cantidad desde la que el precio por 1000
// realmente baja para estas dimensiones, o null.
//
// ======================================================

function resolverMejoraSiguienteRango(
  rangoActual,
  factorActual,
  anchoCalculado,
  altoCalculado
) {

  const rangos =
    REGLAS_PRECIO
      .RANGOS_CANTIDAD;

  const indice =
    rangos.indexOf(
      rangoActual
    );

  const siguiente =
    rangos[indice + 1];


  if (!siguiente) {
    return null;
  }


  const factorSiguiente =
    resolverFactor(
      siguiente.desde,
      anchoCalculado,
      altoCalculado
    ).factor;


  return factorSiguiente <
    factorActual
    ? siguiente.desde
    : null;

}


// ======================================================
// 13. PROCESAR DETALLES
// ======================================================

return items.map(
  (
    item,
    index
  ) => {


    // ==================================================
    // DATOS DB
    // ==================================================

    const db =
      item.json;


    const original =
      detallesOriginales[index]
        ?.json ||
      {};


    // ==================================================
    // IDENTIFICADORES
    // ==================================================

    const id =
      Number(
        db.id
      );


    const cotizacionId =
      Number(
        db.cotizacion_id ??
        original.cotizacion_id
      );


    const clienteId =
      original.cliente_id != null
        ? Number(
            original.cliente_id
          )
        : null;


    // ==================================================
    // VALIDACIONES DE IDENTIDAD
    // ==================================================

    if (
      !id ||
      id <= 0
    ) {

      throw new Error(
        `Detalle ${index}: el INSERT no devolvió un id válido de cotizacion_detalles.`
      );

    }


    if (
      !cotizacionId ||
      cotizacionId <= 0
    ) {

      throw new Error(
        `Detalle ${index}: cotizacion_id no es válido.`
      );

    }


    // ==================================================
    // DATOS BASE
    // ==================================================

    const cantidad =
      Number(
        db.cantidad ??
        original.cantidad
      );


    const ancho =
      Number(
        db.ancho_cm ??
        original.ancho_cm
      );


    const alto =
      Number(
        db.alto_cm ??
        original.alto_cm
      );


    const formaOriginal =
      String(
        db.forma ??
        original.forma ??
        'RECTANGULAR'
      );


    const forma =
      normalizarForma(
        formaOriginal
      );


    // ==================================================
    // VALIDACIONES COMERCIALES BASE
    // ==================================================

    if (
      !Number.isFinite(
        cantidad
      ) ||
      cantidad <= 0
    ) {

      throw new Error(
        `Detalle ${id}: cantidad inválida.`
      );

    }


    if (
      !Number.isFinite(
        ancho
      ) ||
      ancho <= 0
    ) {

      throw new Error(
        `Detalle ${id}: ancho_cm inválido.`
      );

    }


    if (
      !Number.isFinite(
        alto
      ) ||
      alto <= 0
    ) {

      throw new Error(
        `Detalle ${id}: alto_cm inválido.`
      );

    }


    // ==================================================
    // RESTRICCIÓN TÉCNICA
    // ==================================================

    const medidaPermitida =
      validarMedidaMinima(
        ancho,
        alto
      );


    if (
      !medidaPermitida
    ) {

      throw new Error(
        `Detalle ${id}: no es posible producir etiquetas de ${ancho}x${alto} cm. ` +
        `Pegaso no produce etiquetas que tengan 1 cm o menos en cualquiera de sus lados.`
      );

    }


    // ==================================================
    // LIMITE DE COTIZACION AUTOMATICA
    // ==================================================
    //
    // Aplica tambien a precios fijos.
    //
    // ==================================================

    if (
      !resolverRangoCantidad(
        cantidad
      )
    ) {

      throw new Error(
        `Detalle ${id}: ${cantidad} etiquetas no tienen precio automatico ` +
        `(6000 o mas). Debe resolverse con DERIVAR_HUMANO antes de cotizar.`
      );

    }


    // ==================================================
    // IDS CATÁLOGO
    // ==================================================

    const productoId =
      db.producto_id != null
        ? Number(
            db.producto_id
          )
        : original.producto_id != null
          ? Number(
              original.producto_id
            )
          : null;


    const materialId =
      db.material_id != null
        ? Number(
            db.material_id
          )
        : original.material_id != null
          ? Number(
              original.material_id
            )
          : null;


    const disenoId =
      db.diseno_id != null
        ? Number(
            db.diseno_id
          )
        : original.diseno_id != null
          ? Number(
              original.diseno_id
            )
          : null;


    // ==================================================
    // INFORMACIÓN COMERCIAL
    // ==================================================

    const producto =
      original.producto ??
      '';


    const nombre =
      original.nombre ??
      '';


    const sabor =
      original.sabor ??
      null;


    const cantidadOriginal =
      original.cantidad_original !== null &&
      original.cantidad_original !== undefined &&
      Number.isFinite(
        Number(
          original.cantidad_original
        )
      )
        ? Number(
            original.cantidad_original
          )
        : cantidad;


    const cantidadAsumida =
      Boolean(
        original.cantidad_asumida
      );


    const minimoAplicado =
      Boolean(
        original.minimo_aplicado
      );


    // ==================================================
    // PRECIO FIJO
    // ==================================================

    const precioFijo =
      resolverPrecioFijo(
        ancho,
        alto
      );


    const precioFijoAplicado =
      precioFijo.aplica === true;


    // ==================================================
    // DIMENSIONES DE CÁLCULO
    // ==================================================

    let anchoCalculado =
      ancho;

    let altoCalculado =
      alto;


    // --------------------------------------------------
    // Regla exacta 5x5
    // --------------------------------------------------

    const incremento5x5Aplicado =
      !precioFijoAplicado &&
      esEtiqueta5x5(
        ancho,
        alto
      );


    if (
      incremento5x5Aplicado
    ) {

      anchoCalculado +=
        REGLAS_PRECIO
          .INCREMENTO_5X5_ANCHO_CM;

      altoCalculado +=
        REGLAS_PRECIO
          .INCREMENTO_5X5_ALTO_CM;

    }


    // --------------------------------------------------
    // Incremento por forma
    //
    // IMPORTANTE:
    // Si existe precio fijo, la forma NO altera el precio.
    //
    // Ejemplo:
    // 3 x 2.5 ovalada = $18 / 1000.
    // --------------------------------------------------

    const incrementoFormaAplicado =
      !precioFijoAplicado &&
      aplicaIncrementoForma(
        forma
      );


    if (
      incrementoFormaAplicado
    ) {

      anchoCalculado +=
        REGLAS_PRECIO
          .INCREMENTO_FORMA_ANCHO_CM;

      altoCalculado +=
        REGLAS_PRECIO
          .INCREMENTO_FORMA_ALTO_CM;

    }


    // ==================================================
    // FACTOR
    // ==================================================

    let factor =
      null;

    let reglaPrecio =
      null;

    let factorResuelto =
      null;

    let mejoraPrecioDesdeCantidad =
      null;


    if (
      precioFijoAplicado
    ) {

      reglaPrecio =
        precioFijo.regla;

    } else {

      factorResuelto =
        resolverFactor(
          cantidad,
          anchoCalculado,
          altoCalculado
        );

      factor =
        factorResuelto.factor;

      reglaPrecio =
        factorResuelto.regla;

      mejoraPrecioDesdeCantidad =
        resolverMejoraSiguienteRango(
          factorResuelto.rango,
          factor,
          anchoCalculado,
          altoCalculado
        );

    }


    // ==================================================
    // PRECIO POR 1000 SIN REDONDEAR
    // ==================================================

    let precio1000Calculado;


    if (
      precioFijoAplicado
    ) {

      precio1000Calculado =
        Number(
          precioFijo
            .precio1000
        );

    } else {

      precio1000Calculado =
        anchoCalculado *
        altoCalculado *
        factor;

    }


    // ==================================================
    // PRECIO TOTAL ANTES DE DESCUENTO
    // ==================================================

    const precioTotalCalculado =
      precio1000Calculado *
      (
        cantidad /
        1000
      );


    // ==================================================
    // DESCUENTO
    // ==================================================

    const descuento =
      Number(
        db.descuento ??
        original.descuento ??
        0
      );


    const descuentoValido =
      Number.isFinite(
        descuento
      )
        ? descuento
        : 0;


    const precioDespuesDescuento =
      Math.max(
        0,
        precioTotalCalculado -
        descuentoValido
      );


    // ==================================================
    // REDONDEO COMERCIAL
    // ==================================================

    const totalRedondeado =
      Math.ceil(
        precioDespuesDescuento
      );


    // ==================================================
    // PRECIO MINIMO ABSOLUTO DEL DETALLE
    // ==================================================
    //
    // Ultimo paso economico: no altera factores,
    // medidas, cantidad ni precio_1000.
    //
    // ==================================================

    const precioMinimoAplicado =
      totalRedondeado <
      REGLAS_PRECIO
        .PRECIO_MINIMO_DETALLE;

    const total =
      Math.max(
        totalRedondeado,
        REGLAS_PRECIO
          .PRECIO_MINIMO_DETALLE
      );


    const precioUnitario =
      total /
      cantidad;


    // ==================================================
    // IVA INTERNO
    // ==================================================

    const subtotal =
      total /
      (
        1 +
        REGLAS_PRECIO.IVA
      );


    const iva =
      total -
      subtotal;


    // ==================================================
    // PRECIO 1000 COMERCIAL
    // ==================================================

    const precio1000Comercial =
      Math.ceil(
        precio1000Calculado
      );


    // ==================================================
    // COTIZACIÓN MANUAL
    // ==================================================

    const requiereCotizacionManual =
      materialId !== null &&
      materialId !==
        REGLAS_PRECIO
          .MATERIAL_P4_ID;


    // ==================================================
    // SALIDA
    // ==================================================

    return {

      json: {

        // ----------------------------------------------
        // PK REAL
        // ----------------------------------------------

        id,

        cotizacion_id:
          cotizacionId,

        cliente_id:
          clienteId,

        detalle_index:
          original.detalle_index ??
          index,


        // ----------------------------------------------
        // Catálogo
        // ----------------------------------------------

        producto_id:
          productoId,

        material_id:
          materialId,

        diseno_id:
          disenoId,


        // ----------------------------------------------
        // Producto
        // ----------------------------------------------

        producto,

        nombre,

        sabor,


        // ----------------------------------------------
        // Cantidades
        // ----------------------------------------------

        cantidad,

        cantidad_original:
          cantidadOriginal,

        cantidad_asumida:
          cantidadAsumida,

        minimo_aplicado:
          minimoAplicado,


        // ----------------------------------------------
        // Dimensiones reales
        // ----------------------------------------------

        ancho_cm:
          ancho,

        alto_cm:
          alto,


        // ----------------------------------------------
        // Restricción técnica
        // ----------------------------------------------

        medida_permitida:
          medidaPermitida,

        medida_minima_permitida_cm:
          REGLAS_PRECIO
            .MEDIDA_MINIMA_PERMITIDA_CM,


        // ----------------------------------------------
        // Forma
        // ----------------------------------------------

        forma_original:
          formaOriginal,

        forma,


        // ----------------------------------------------
        // Dimensiones usadas para cálculo
        // ----------------------------------------------

        ancho_calculado_cm:
          anchoCalculado,

        alto_calculado_cm:
          altoCalculado,


        // ----------------------------------------------
        // Reglas especiales
        // ----------------------------------------------

        precio_fijo_aplicado:
          precioFijoAplicado,

        precio_fijo_1000:
          precioFijoAplicado
            ? Number(
                precioFijo
                  .precio1000
                  .toFixed(2)
              )
            : null,


        banda_pequena_18_aplicada:
          reglaPrecio ===
          'BANDA_PEQUENA_2_A_MENOR_4',


        incremento_5x5_aplicado:
          incremento5x5Aplicado,


        // ----------------------------------------------
        // Compatibilidad con V2.3 / V2.4
        // ----------------------------------------------

        incremento_pequena_aplicado:
          incremento5x5Aplicado,

        incremento_forma_aplicado:
          incrementoFormaAplicado,


        // ----------------------------------------------
        // Regla precio
        // ----------------------------------------------

        regla_precio:
          reglaPrecio,

        factor_aplicado:
          factor,


        // ----------------------------------------------
        // Rango de cantidad / tamano grande
        // ----------------------------------------------

        rango_cantidad:
          factorResuelto?.rango.codigo ??
          null,

        rango_cantidad_desde:
          factorResuelto?.rango.desde ??
          null,

        rango_cantidad_hasta:
          factorResuelto?.rango.hasta ??
          null,

        factor_rango:
          factorResuelto?.rango.factor ??
          null,

        precio_1000_rango:
          factorResuelto
            ? Number(
                factorResuelto
                  .precio1000Rango
                  .toFixed(6)
              )
            : null,

        tamano_grande:
          factorResuelto?.tamanoGrande ??
          false,

        mejora_precio_desde_cantidad:
          mejoraPrecioDesdeCantidad,


        // ----------------------------------------------
        // Auditoría antes de redondeo
        // ----------------------------------------------

        precio_1000_calculado:
          Number(
            precio1000Calculado
              .toFixed(6)
          ),

        precio_total_calculado:
          Number(
            precioTotalCalculado
              .toFixed(6)
          ),

        precio_despues_descuento:
          Number(
            precioDespuesDescuento
              .toFixed(6)
          ),

        precio_total_antes_minimo:
          Number(
            totalRedondeado
              .toFixed(2)
          ),

        precio_minimo_detalle:
          REGLAS_PRECIO
            .PRECIO_MINIMO_DETALLE,

        precio_minimo_aplicado:
          precioMinimoAplicado,


        // ----------------------------------------------
        // Valores comerciales compatibles
        // ----------------------------------------------

        precio_1000:
          Number(
            precio1000Comercial
              .toFixed(2)
          ),

        precio_unitario:
          Number(
            precioUnitario
              .toFixed(6)
          ),

        precio_total:
          Number(
            total
              .toFixed(2)
          ),

        subtotal:
          Number(
            subtotal
              .toFixed(2)
          ),

        iva:
          Number(
            iva
              .toFixed(2)
          ),

        descuento:
          Number(
            descuentoValido
              .toFixed(2)
          ),

        total:
          Number(
            total
              .toFixed(2)
          ),


        // ----------------------------------------------
        // Control
        // ----------------------------------------------

        precio_redondeado:
          true,

        requiere_cotizacion_manual:
          requiereCotizacionManual,

        observaciones:
          original.observaciones ??
          db.observaciones ??
          ''

      }

    };

  }
);

// ======================================================
// CALCULAR RESUMEN COTIZACIÓN
// PEGASO ADHESIVOS - V2.3
// ======================================================
//
// Entrada:
//   varios registros de cotizacion_detalles
//   YA calculados / actualizados.
//
// Salida:
//   1 item con subtotal, IVA y total
//   de toda la cotización.
//
// IMPORTANTE:
//
// - Cada detalle ya viene con su redondeo comercial.
// - El resumen suma el campo "total" de cada detalle.
// - Si por compatibilidad no existe "total",
//   utiliza "precio_total".
// - IVA se mantiene internamente.
// - Ya NO depende de que el mensaje comercial
//   muestre "IVA incluido".
//
// ======================================================

const items = $input.all();


// ======================================================
// 1. VALIDACIÓN
// ======================================================

if (!items.length) {

  throw new Error(
    'No existen detalles para calcular el resumen.'
  );

}


// ======================================================
// 2. HELPERS
// ======================================================

function numero(valor) {

  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return 0;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : 0;
}


// ======================================================
// 3. COTIZACIÓN ID
// ======================================================

const cotizacionId =
  Number(
    items[0].json.cotizacion_id
  );


if (
  !cotizacionId ||
  cotizacionId <= 0
) {

  throw new Error(
    'cotizacion_id no válido para calcular el resumen.'
  );

}


// ======================================================
// 4. VALIDAR QUE TODOS PERTENEZCAN A LA MISMA COTIZACIÓN
// ======================================================

for (const item of items) {

  const detalleCotizacionId =
    Number(
      item.json.cotizacion_id
    );

  if (
    detalleCotizacionId !== cotizacionId
  ) {

    throw new Error(
      `Se encontraron detalles de distintas cotizaciones. ` +
      `Esperado: ${cotizacionId}, recibido: ${detalleCotizacionId}.`
    );

  }

}


// ======================================================
// 5. SUMAR TOTALES COMERCIALES
// ======================================================
//
// Preferencia:
//
// total
//   ↓
// precio_total
//
// "total" ya contempla:
// - regla de precio
// - descuento
// - redondeo comercial
//
// ======================================================

const totalCotizacion =
  items.reduce(
    (sum, item) => {

      const detalle =
        item.json;

      const totalDetalle =
        detalle.total !== null &&
        detalle.total !== undefined
          ? numero(detalle.total)
          : numero(detalle.precio_total);

      return sum + totalDetalle;

    },
    0
  );


// ======================================================
// 6. SUMAR DESCUENTOS
// ======================================================

const descuentoTotal =
  items.reduce(
    (sum, item) => {

      return (
        sum +
        numero(
          item.json.descuento
        )
      );

    },
    0
  );


// ======================================================
// 7. TOTAL ANTES DE REDONDEO / AUDITORÍA
// ======================================================
//
// Solo informativo.
//
// Permite comparar:
//
// cálculo matemático previo
// vs.
// precio comercial redondeado.
//
// ======================================================

const totalCalculadoSinRedondeo =
  items.reduce(
    (sum, item) => {

      const detalle =
        item.json;

      if (
        detalle.precio_despues_descuento !== null &&
        detalle.precio_despues_descuento !== undefined
      ) {

        return (
          sum +
          numero(
            detalle.precio_despues_descuento
          )
        );

      }

      if (
        detalle.precio_total_calculado !== null &&
        detalle.precio_total_calculado !== undefined
      ) {

        return (
          sum +
          numero(
            detalle.precio_total_calculado
          ) -
          numero(
            detalle.descuento
          )
        );

      }

      return sum;

    },
    0
  );


// ======================================================
// 8. IVA INTERNO
// ======================================================
//
// Se mantiene porque la estructura existente
// de cotizaciones ya trabaja con:
// subtotal / iva / total.
//
// Comercialmente no es necesario mostrar:
// "IVA incluido".
//
// ======================================================

const IVA =
  0.15;


const subtotal =
  totalCotizacion /
  (
    1 +
    IVA
  );


const iva =
  totalCotizacion -
  subtotal;


// ======================================================
// 9. INFORMACIÓN DE REGLAS APLICADAS
// ======================================================

const reglasAplicadas =
  [
    ...new Set(
      items
        .map(
          item =>
            item.json.regla_precio
        )
        .filter(Boolean)
    )
  ];


const huboRedondeo =
  items.some(
    item =>
      item.json.precio_redondeado === true
  );


const huboIncrementoPequena =
  items.some(
    item =>
      item.json.incremento_pequena_aplicado === true
  );


const huboIncrementoForma =
  items.some(
    item =>
      item.json.incremento_forma_aplicado === true
  );


// ======================================================
// 10. SALIDA
// ======================================================

return [
  {
    json: {

      cotizacion_id:
        cotizacionId,

      subtotal:
        Number(
          subtotal.toFixed(2)
        ),

      iva:
        Number(
          iva.toFixed(2)
        ),

      total:
        Number(
          totalCotizacion.toFixed(2)
        ),

      descuento_total:
        Number(
          descuentoTotal.toFixed(2)
        ),

      total_calculado_sin_redondeo:
        Number(
          totalCalculadoSinRedondeo.toFixed(6)
        ),

      cantidad_detalles:
        items.length,

      reglas_precio_aplicadas:
        reglasAplicadas,

      hubo_redondeo:
        huboRedondeo,

      hubo_incremento_pequena:
        huboIncrementoPequena,

      hubo_incremento_forma:
        huboIncrementoForma

    }
  }
];

// ======================================================
// NODO N8N: Validar extracción Groq
// PEGASO ADHESIVOS
// VERSION: 2.0
// ======================================================
//
// RESPONSABILIDAD:
//
// - Validar la salida estructurada del extractor de cotización.
// - Detectar errores de contrato.
// - Detectar cantidades comerciales imposibles (< 1000).
// - Detectar dimensiones inválidas.
// - Detectar contradicciones básicas entre forma y dimensiones.
// - Comparar de forma prudente contra el mensaje actual.
// - Detectar cuando el cliente expresó múltiples medidas y la IA
//   devolvió menos detalles de los necesarios.
// - Evitar aceptar alucinaciones evidentes.
//
// IMPORTANTE:
//
// Este nodo NO:
// - calcula precios;
// - corrige detalles;
// - inventa datos;
// - decide producibilidad;
// - consulta PostgreSQL;
// - responde al cliente.
//
// Solo declara:
//   valid = true / false
//
// ======================================================


// ======================================================
// 1. INPUT
// ======================================================

const item = $input.first().json ?? {};

const output =
  item.output &&
  typeof item.output === 'object' &&
  !Array.isArray(item.output)
    ? item.output
    : null;

const detalles =
  Array.isArray(output?.detalles)
    ? output.detalles
    : null;


// ======================================================
// 2. HELPERS
// ======================================================

function texto(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numero(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function normalizarTexto(valor) {
  const t =
    texto(valor);

  if (!t) {
    return '';
  }

  return t
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}


function casiIgual(a, b, tolerancia = 0.01) {
  const na = numero(a);
  const nb = numero(b);

  if (
    na === null ||
    nb === null
  ) {
    return false;
  }

  return Math.abs(na - nb) <= tolerancia;
}


function claveMedida(ancho, alto) {
  const a = numero(ancho);
  const h = numero(alto);

  if (
    a === null ||
    h === null
  ) {
    return null;
  }

  return `${a}x${h}`;
}


// ======================================================
// 3. OBTENER MENSAJE ACTUAL
// ======================================================
//
// Priorizamos Resolver contexto comercial porque es
// precisamente la entrada utilizada por el extractor.
//
// ======================================================

let contexto = {};

try {
  contexto =
    $('Resolver contexto comercial')
      .first()
      .json ?? {};
} catch (_) {
  contexto = {};
}


const mensajeActual =
  texto(
    contexto.mensaje_actual ??
    contexto.turno_texto ??
    null
  ) ?? '';

const mensajeNormalizado =
  normalizarTexto(mensajeActual);


// ======================================================
// 4. EXTRAER MEDIDAS EXPLÍCITAS DEL MENSAJE
// ======================================================
//
// Soporta:
// 8x11
// 8 x 11
// 8 por 11
// 8,5 x 10
// 8 de ancho por 11 de alto
//
// Esto NO pretende entender toda la conversación.
// Solo detectar medidas explícitas para evitar que la IA
// devuelva datos completamente diferentes.
//
// ======================================================

function extraerMedidasExplicitas(textoEntrada) {
  const resultado = [];

  if (!textoEntrada) {
    return resultado;
  }

  const limpio =
    textoEntrada
      .replace(/,/g, '.')
      .toLowerCase();

  // --------------------------------------------------
  // Caso explícito:
  // "11 de alto por 8 de ancho"
  // "8 de ancho por 11 de alto"
  // --------------------------------------------------

  const regexEtiquetado =
    /(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?\s*de\s*(ancho|alto)\s*(?:por|x)\s*(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?\s*de\s*(ancho|alto)/gi;

  let match;

  while (
    (match = regexEtiquetado.exec(limpio)) !== null
  ) {
    const valor1 = Number(match[1]);
    const tipo1 = match[2];
    const valor2 = Number(match[3]);
    const tipo2 = match[4];

    let ancho = null;
    let alto = null;

    if (tipo1 === 'ancho') {
      ancho = valor1;
    }

    if (tipo1 === 'alto') {
      alto = valor1;
    }

    if (tipo2 === 'ancho') {
      ancho = valor2;
    }

    if (tipo2 === 'alto') {
      alto = valor2;
    }

    if (
      Number.isFinite(ancho) &&
      Number.isFinite(alto)
    ) {
      resultado.push({
        ancho_cm: ancho,
        alto_cm: alto
      });
    }
  }

  // --------------------------------------------------
  // Caso común:
  // 8x11
  // 8 x 11
  // 8 por 11
  // --------------------------------------------------

  const regexComun =
    /(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?\s*(?:x|por)\s*(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?/gi;

  while (
    (match = regexComun.exec(limpio)) !== null
  ) {
    const ancho = Number(match[1]);
    const alto = Number(match[2]);

    if (
      !Number.isFinite(ancho) ||
      !Number.isFinite(alto)
    ) {
      continue;
    }

    const yaExiste =
      resultado.some(m =>
        casiIgual(m.ancho_cm, ancho) &&
        casiIgual(m.alto_cm, alto)
      );

    if (!yaExiste) {
      resultado.push({
        ancho_cm: ancho,
        alto_cm: alto
      });
    }
  }

  return resultado;
}


const medidasExplicitas =
  extraerMedidasExplicitas(
    mensajeActual
  );


// ======================================================
// 5. FORMAS PERMITIDAS
// ======================================================

const formasPermitidas = [
  'RECTANGULAR',
  'CUADRADA',
  'CIRCULAR',
  'IRREGULAR',
  'NO_ESPECIFICADA',
  null
];


// ======================================================
// 6. VALIDACIÓN
// ======================================================

let valid = true;
let reason = null;


// ------------------------------------------------------
// 6.1 Debe existir output
// ------------------------------------------------------

if (!output) {
  valid = false;

  reason =
    'La IA no devolvió un objeto output válido.';
}


// ------------------------------------------------------
// 6.2 Debe existir detalles[]
// ------------------------------------------------------

else if (!Array.isArray(detalles)) {
  valid = false;

  reason =
    'El campo detalles no existe o no es un array.';
}


// ------------------------------------------------------
// 6.3 No debe estar vacío
// ------------------------------------------------------

else if (detalles.length === 0) {
  valid = false;

  reason =
    'La IA devolvió detalles vacío.';
}


// ------------------------------------------------------
// 6.4 Límite de seguridad
// ------------------------------------------------------

else if (detalles.length > 10) {
  valid = false;

  reason =
    'La IA devolvió demasiados detalles de cotización.';
}


// ------------------------------------------------------
// 6.5 Validar cada detalle
// ------------------------------------------------------

else {

  for (
    let i = 0;
    i < detalles.length;
    i++
  ) {

    const d =
      detalles[i];

    const numeroDetalle =
      i + 1;


    // ----------------------------------------------
    // Debe ser objeto
    // ----------------------------------------------

    if (
      !d ||
      typeof d !== 'object' ||
      Array.isArray(d)
    ) {
      valid = false;

      reason =
        `El detalle ${numeroDetalle} no es un objeto válido.`;

      break;
    }


    // ----------------------------------------------
    // CAMPOS OBLIGATORIOS
    // ----------------------------------------------

    const camposObligatorios = [
      'cantidad',
      'producto',
      'nombre',
      'sabor',
      'ancho_cm',
      'alto_cm',
      'forma'
    ];

    for (const campo of camposObligatorios) {
      if (!(campo in d)) {
        valid = false;

        reason =
          `Falta el campo obligatorio "${campo}" en el detalle ${numeroDetalle}.`;

        break;
      }
    }

    if (!valid) {
      break;
    }


    // ----------------------------------------------
    // CANTIDAD
    // ----------------------------------------------

    if (
      d.cantidad !== null &&
      typeof d.cantidad !== 'number'
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} no es numérica.`;

      break;
    }


    if (
      typeof d.cantidad === 'number' &&
      (
        !Number.isFinite(d.cantidad) ||
        !Number.isInteger(d.cantidad)
      )
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} debe ser un número entero.`;

      break;
    }


    if (
      typeof d.cantidad === 'number' &&
      d.cantidad < 1000
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} es menor al mínimo comercial de 1000.`;

      break;
    }


    // ----------------------------------------------
    // PRODUCTO
    // ----------------------------------------------

    if (
      d.producto !== null &&
      typeof d.producto !== 'string'
    ) {
      valid = false;

      reason =
        `El producto del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // NOMBRE
    // ----------------------------------------------

    if (
      d.nombre !== null &&
      typeof d.nombre !== 'string'
    ) {
      valid = false;

      reason =
        `El nombre del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // SABOR
    // ----------------------------------------------

    if (
      d.sabor !== null &&
      typeof d.sabor !== 'string'
    ) {
      valid = false;

      reason =
        `El sabor del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // ANCHO
    // ----------------------------------------------

    if (
      d.ancho_cm !== null &&
      typeof d.ancho_cm !== 'number'
    ) {
      valid = false;

      reason =
        `El ancho_cm del detalle ${numeroDetalle} no es numérico.`;

      break;
    }


    if (
      typeof d.ancho_cm === 'number' &&
      (
        !Number.isFinite(d.ancho_cm) ||
        d.ancho_cm <= 0
      )
    ) {
      valid = false;

      reason =
        `El ancho_cm del detalle ${numeroDetalle} debe ser mayor a 0.`;

      break;
    }


    // ----------------------------------------------
    // ALTO
    // ----------------------------------------------

    if (
      d.alto_cm !== null &&
      typeof d.alto_cm !== 'number'
    ) {
      valid = false;

      reason =
        `El alto_cm del detalle ${numeroDetalle} no es numérico.`;

      break;
    }


    if (
      typeof d.alto_cm === 'number' &&
      (
        !Number.isFinite(d.alto_cm) ||
        d.alto_cm <= 0
      )
    ) {
      valid = false;

      reason =
        `El alto_cm del detalle ${numeroDetalle} debe ser mayor a 0.`;

      break;
    }


    // ----------------------------------------------
    // FORMA
    // ----------------------------------------------

    if (
      !formasPermitidas.includes(d.forma)
    ) {
      valid = false;

      reason =
        `La forma del detalle ${numeroDetalle} no es válida.`;

      break;
    }


    // ----------------------------------------------
    // CONSISTENCIA RECTANGULAR / CUADRADA
    // ----------------------------------------------
    //
    // No hacemos esto para CIRCULAR porque 8x8 circular
    // es perfectamente válido.
    //
    // ----------------------------------------------

    if (
      typeof d.ancho_cm === 'number' &&
      typeof d.alto_cm === 'number'
    ) {

      if (
        d.forma === 'CUADRADA' &&
        !casiIgual(
          d.ancho_cm,
          d.alto_cm
        )
      ) {
        valid = false;

        reason =
          `El detalle ${numeroDetalle} está marcado como CUADRADA pero ancho_cm y alto_cm son diferentes.`;

        break;
      }

      if (
        d.forma === 'RECTANGULAR' &&
        casiIgual(
          d.ancho_cm,
          d.alto_cm
        )
      ) {

        // Permitimos rectangular cuadrada físicamente,
        // porque comercialmente podría existir un troquel
        // rectangular de lados iguales.
        //
        // Por tanto NO invalidamos.
      }
    }


    // ----------------------------------------------
    // ALUCINACIÓN BÁSICA EN NOMBRE / SABOR
    // ----------------------------------------------
    //
    // Si nombre o sabor vienen informados pero NO aparecen
    // en el mensaje actual ni existe contexto que los respalde,
    // es sospechoso.
    //
    // No invalidamos producto aquí porque puede venir de la
    // memoria comercial previa.
    //
    // ----------------------------------------------

    for (const campo of ['nombre', 'sabor']) {

      const valor =
        texto(d[campo]);

      if (!valor) {
        continue;
      }

      const valorNormalizado =
        normalizarTexto(valor);

      const apareceEnMensaje =
        valorNormalizado !== '' &&
        mensajeNormalizado.includes(
          valorNormalizado
        );

      // Recuperamos contexto comercial completo para ver
      // si realmente estaba previamente guardado.

      const contextoTexto =
        normalizarTexto(
          JSON.stringify(
            contexto.contexto_comercial ?? {}
          )
        );

      const apareceEnContexto =
        valorNormalizado !== '' &&
        contextoTexto.includes(
          valorNormalizado
        );

      if (
        !apareceEnMensaje &&
        !apareceEnContexto
      ) {
        valid = false;

        reason =
          `El campo ${campo} del detalle ${numeroDetalle} contiene información no respaldada por el mensaje ni por el contexto.`;

        break;
      }
    }

    if (!valid) {
      break;
    }
  }
}


// ======================================================
