    let alto = null;

    if (tipo1 === 'ancho') {
      ancho = valor1;
    }

    if (tipo1 === 'alto') {
      alto = valor1;
    }

    if (tipo2 === 'ancho') {
      ancho = valor2;
    }

    if (tipo2 === 'alto') {
      alto = valor2;
    }

    if (
      Number.isFinite(ancho) &&
      Number.isFinite(alto)
    ) {
      resultado.push({
        ancho_cm: ancho,
        alto_cm: alto
      });
    }
  }

  // --------------------------------------------------
  // Caso común:
  // 8x11
  // 8 x 11
  // 8 por 11
  // --------------------------------------------------

  const regexComun =
    /(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?\s*(?:x|por)\s*(\d+(?:\.\d+)?)\s*(?:cm|centimetros?|centímetros?)?/gi;

  while (
    (match = regexComun.exec(limpio)) !== null
  ) {
    const ancho = Number(match[1]);
    const alto = Number(match[2]);

    if (
      !Number.isFinite(ancho) ||
      !Number.isFinite(alto)
    ) {
      continue;
    }

    const yaExiste =
      resultado.some(m =>
        casiIgual(m.ancho_cm, ancho) &&
        casiIgual(m.alto_cm, alto)
      );

    if (!yaExiste) {
      resultado.push({
        ancho_cm: ancho,
        alto_cm: alto
      });
    }
  }

  return resultado;
}


const medidasExplicitas =
  extraerMedidasExplicitas(
    mensajeActual
  );


// ======================================================
// 5. FORMAS PERMITIDAS
// ======================================================

const formasPermitidas = [
  'RECTANGULAR',
  'CUADRADA',
  'CIRCULAR',
  'IRREGULAR',
  'NO_ESPECIFICADA',
  null
];


// ======================================================
// 6. VALIDACIÓN
// ======================================================

let valid = true;
let reason = null;


// ------------------------------------------------------
// 6.1 Debe existir output
// ------------------------------------------------------

if (!output) {
  valid = false;

  reason =
    'La IA no devolvió un objeto output válido.';
}


// ------------------------------------------------------
// 6.2 Debe existir detalles[]
// ------------------------------------------------------

else if (!Array.isArray(detalles)) {
  valid = false;

  reason =
    'El campo detalles no existe o no es un array.';
}


// ------------------------------------------------------
// 6.3 No debe estar vacío
// ------------------------------------------------------

else if (detalles.length === 0) {
  valid = false;

  reason =
    'La IA devolvió detalles vacío.';
}


// ------------------------------------------------------
// 6.4 Límite de seguridad
// ------------------------------------------------------

else if (detalles.length > 10) {
  valid = false;

  reason =
    'La IA devolvió demasiados detalles de cotización.';
}


// ------------------------------------------------------
// 6.5 Validar cada detalle
// ------------------------------------------------------

else {

  for (
    let i = 0;
    i < detalles.length;
    i++
  ) {

    const d =
      detalles[i];

    const numeroDetalle =
      i + 1;


    // ----------------------------------------------
    // Debe ser objeto
    // ----------------------------------------------

    if (
      !d ||
      typeof d !== 'object' ||
      Array.isArray(d)
    ) {
      valid = false;

      reason =
        `El detalle ${numeroDetalle} no es un objeto válido.`;

      break;
    }


    // ----------------------------------------------
    // CAMPOS OBLIGATORIOS
    // ----------------------------------------------

    const camposObligatorios = [
      'cantidad',
      'producto',
      'nombre',
      'sabor',
      'ancho_cm',
      'alto_cm',
      'forma'
    ];

    for (const campo of camposObligatorios) {
      if (!(campo in d)) {
        valid = false;

        reason =
          `Falta el campo obligatorio "${campo}" en el detalle ${numeroDetalle}.`;

        break;
      }
    }

    if (!valid) {
      break;
    }


    // ----------------------------------------------
    // CANTIDAD
    // ----------------------------------------------

    if (
      d.cantidad !== null &&
      typeof d.cantidad !== 'number'
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} no es numérica.`;

      break;
    }


    if (
      typeof d.cantidad === 'number' &&
      (
        !Number.isFinite(d.cantidad) ||
        !Number.isInteger(d.cantidad)
      )
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} debe ser un número entero.`;

      break;
    }


    if (
      typeof d.cantidad === 'number' &&
      d.cantidad < 1000
    ) {
      valid = false;

      reason =
        `La cantidad del detalle ${numeroDetalle} es menor al mínimo comercial de 1000.`;

      break;
    }


    // ----------------------------------------------
    // PRODUCTO
    // ----------------------------------------------

    if (
      d.producto !== null &&
      typeof d.producto !== 'string'
    ) {
      valid = false;

      reason =
        `El producto del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // NOMBRE
    // ----------------------------------------------

    if (
      d.nombre !== null &&
      typeof d.nombre !== 'string'
    ) {
      valid = false;

      reason =
        `El nombre del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // SABOR
    // ----------------------------------------------

    if (
      d.sabor !== null &&
      typeof d.sabor !== 'string'
    ) {
      valid = false;

      reason =
        `El sabor del detalle ${numeroDetalle} no es texto.`;

      break;
    }


    // ----------------------------------------------
    // ANCHO
    // ----------------------------------------------

    if (
      d.ancho_cm !== null &&
      typeof d.ancho_cm !== 'number'
    ) {
      valid = false;

      reason =
        `El ancho_cm del detalle ${numeroDetalle} no es numérico.`;

      break;
    }


    if (
      typeof d.ancho_cm === 'number' &&
      (
        !Number.isFinite(d.ancho_cm) ||
        d.ancho_cm <= 0
      )
    ) {
      valid = false;

      reason =
        `El ancho_cm del detalle ${numeroDetalle} debe ser mayor a 0.`;

      break;
    }


    // ----------------------------------------------
    // ALTO
    // ----------------------------------------------

    if (
      d.alto_cm !== null &&
      typeof d.alto_cm !== 'number'
    ) {
      valid = false;

      reason =
        `El alto_cm del detalle ${numeroDetalle} no es numérico.`;

      break;
    }


    if (
      typeof d.alto_cm === 'number' &&
      (
        !Number.isFinite(d.alto_cm) ||
        d.alto_cm <= 0
      )
    ) {
      valid = false;

      reason =
        `El alto_cm del detalle ${numeroDetalle} debe ser mayor a 0.`;

      break;
    }


    // ----------------------------------------------
    // FORMA
    // ----------------------------------------------

    if (
      !formasPermitidas.includes(d.forma)
    ) {
      valid = false;

      reason =
        `La forma del detalle ${numeroDetalle} no es válida.`;

      break;
    }


    // ----------------------------------------------
    // CONSISTENCIA RECTANGULAR / CUADRADA
    // ----------------------------------------------
    //
    // No hacemos esto para CIRCULAR porque 8x8 circular
    // es perfectamente válido.
    //
    // ----------------------------------------------

    if (
      typeof d.ancho_cm === 'number' &&
      typeof d.alto_cm === 'number'
    ) {

      if (
        d.forma === 'CUADRADA' &&
        !casiIgual(
          d.ancho_cm,
          d.alto_cm
        )
      ) {
        valid = false;

        reason =
          `El detalle ${numeroDetalle} está marcado como CUADRADA pero ancho_cm y alto_cm son diferentes.`;

        break;
      }

      if (
        d.forma === 'RECTANGULAR' &&
        casiIgual(
          d.ancho_cm,
          d.alto_cm
        )
      ) {

        // Permitimos rectangular cuadrada físicamente,
        // porque comercialmente podría existir un troquel
        // rectangular de lados iguales.
        //
        // Por tanto NO invalidamos.
      }
    }


    // ----------------------------------------------
    // ALUCINACIÓN BÁSICA EN NOMBRE / SABOR
    // ----------------------------------------------
    //
    // Si nombre o sabor vienen informados pero NO aparecen
    // en el mensaje actual ni existe contexto que los respalde,
    // es sospechoso.
    //
    // No invalidamos producto aquí porque puede venir de la
    // memoria comercial previa.
    //
    // ----------------------------------------------

    for (const campo of ['nombre', 'sabor']) {

      const valor =
        texto(d[campo]);

      if (!valor) {
        continue;
      }

      const valorNormalizado =
        normalizarTexto(valor);

      const apareceEnMensaje =
        valorNormalizado !== '' &&
        mensajeNormalizado.includes(
          valorNormalizado
        );

      // Recuperamos contexto comercial completo para ver
      // si realmente estaba previamente guardado.

      const contextoTexto =
        normalizarTexto(
          JSON.stringify(
            contexto.contexto_comercial ?? {}
          )
        );

      const apareceEnContexto =
        valorNormalizado !== '' &&
        contextoTexto.includes(
          valorNormalizado
        );

      if (
        !apareceEnMensaje &&
        !apareceEnContexto
      ) {
        valid = false;

        reason =
          `El campo ${campo} del detalle ${numeroDetalle} contiene información no respaldada por el mensaje ni por el contexto.`;

        break;
      }
    }

    if (!valid) {
      break;
    }
  }
}


// ======================================================
// 7. VALIDAR COBERTURA DE MEDIDAS EXPLÍCITAS
// ======================================================
//
// Si el cliente escribió explícitamente:
// 8x11 y 8x8
//
// el extractor no puede devolver solo una.
//
// Solo aplicamos esta regla cuando encontramos
// dos o más pares explícitos en el mensaje.
//
// ======================================================

if (
  valid &&
  medidasExplicitas.length >= 2
) {

  const medidasExtraidas =
    detalles
      .map(d => ({
        ancho_cm:
          numero(d.ancho_cm),

        alto_cm:
          numero(d.alto_cm)
      }))
      .filter(m =>
        m.ancho_cm !== null &&
        m.alto_cm !== null
      );


  for (const medidaEsperada of medidasExplicitas) {

    const encontrada =
      medidasExtraidas.some(m =>
        casiIgual(
          m.ancho_cm,
          medidaEsperada.ancho_cm
        ) &&
        casiIgual(
          m.alto_cm,
          medidaEsperada.alto_cm
        )
      );

    if (!encontrada) {
      valid = false;

      reason =
        `El cliente indicó explícitamente la medida ${claveMedida(
          medidaEsperada.ancho_cm,
          medidaEsperada.alto_cm
        )}, pero el extractor no la incluyó en detalles.`;

      break;
    }
  }
}


// ======================================================
// 8. DETECTAR POSIBLE REDUCCIÓN DE PEDIDO MÚLTIPLE
// ======================================================
//
// Cuando existen dos o más medidas explícitas,
// esperamos al menos tantos detalles como medidas
// distintas.
//
// ======================================================

if (
  valid &&
  medidasExplicitas.length >= 2 &&
  detalles.length < medidasExplicitas.length
) {
  valid = false;

  reason =
    `El mensaje contiene ${medidasExplicitas.length} medidas explícitas, pero el extractor devolvió solo ${detalles.length} detalle(s).`;
}


// ======================================================
// 9. SALIDA
// ======================================================

return [
  {
    json: {

      valid,

      reason,

      detalles:
        valid
          ? detalles
          : [],

      cantidad_detalles:
        Array.isArray(detalles)
          ? detalles.length
          : 0,

      medidas_explicitas_mensaje:
        medidasExplicitas,

      cantidad_medidas_explicitas:
        medidasExplicitas.length,

      validado_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// APLICAR MÍNIMO DE IMPRESIÓN
// PEGASO ADHESIVOS - V2.4
// ======================================================
//
// V2.4: corta la cotizacion automatica (antes de insertar
// nada) si algun detalle normalizado llega a 6000 o mas.
// La derivacion normal ocurre en "Resolver contexto
// comercial"; esto solo cubre extracciones divergentes.
//
// ======================================================

const MINIMO_IMPRESION = 1000;
const MULTIPLO_IMPRESION = 1000;
const CANTIDAD_DERIVACION_HUMANA = 6000;

const input = $input.first().json;

const detalles = input.detalles;


// ======================================================
// VALIDACIÓN
// ======================================================

if (!Array.isArray(detalles)) {

  return [
    {
      json: {
        valid: false,
        error:
          'No se encontraron detalles válidos para cotización.',
        detalles: []
      }
    }
  ];

}


// ======================================================
// NORMALIZAR
// ======================================================

const detallesNormalizados =
  detalles.map((detalle) => {

    const cantidadRecibida =
      detalle.cantidad;

    const cantidadNumerica =
      Number(cantidadRecibida);


    // --------------------------------------------------
    // SIN CANTIDAD
    // --------------------------------------------------
    //
    // Pegaso no pregunta cantidad para iniciar cotización.
    // Se utiliza el mínimo determinístico de 1000.
    //
    // --------------------------------------------------

    if (
      cantidadRecibida === null ||
      cantidadRecibida === undefined ||
      cantidadRecibida === '' ||
      !Number.isFinite(cantidadNumerica) ||
      cantidadNumerica <= 0
    ) {

      return {

        ...detalle,

        cantidad_original:
          cantidadRecibida ?? null,

        cantidad:
          MINIMO_IMPRESION,

        cantidad_asumida:
          true,

        minimo_aplicado:
          true

      };

    }


    // --------------------------------------------------
    // MÍNIMO + MÚLTIPLOS DE 1000
    // --------------------------------------------------

    const cantidadFinal =
      Math.max(
        MINIMO_IMPRESION,
        Math.ceil(
          cantidadNumerica /
          MULTIPLO_IMPRESION
        ) *
        MULTIPLO_IMPRESION
      );


    const cantidadFueAjustada =
      cantidadFinal !== cantidadNumerica;


    return {

      ...detalle,

      cantidad_original:
        cantidadNumerica,

      cantidad:
        cantidadFinal,

      cantidad_asumida:
        false,

      minimo_aplicado:
        cantidadFueAjustada

    };

  });


const detallesMayoristas =
  detallesNormalizados.filter(
    d => d.cantidad >= CANTIDAD_DERIVACION_HUMANA
  );

if (detallesMayoristas.length > 0) {

  throw new Error(
    `Cotizacion automatica bloqueada: ${detallesMayoristas
      .map(d => d.cantidad)
      .join(', ')} etiquetas (${CANTIDAD_DERIVACION_HUMANA} o mas) ` +
    'requieren DERIVAR_HUMANO.'
  );

}


const minimoAplicado =
  detallesNormalizados.some(
    d => d.minimo_aplicado === true
  );


const algunaCantidadAsumida =
  detallesNormalizados.some(
    d => d.cantidad_asumida === true
  );


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      valid:
        true,

      detalles:
        detallesNormalizados,

      cantidad_detalles:
        detallesNormalizados.length,

      minimo_impresion:
        MINIMO_IMPRESION,

      multiplo_impresion:
        MULTIPLO_IMPRESION,

      minimo_aplicado:
        minimoAplicado,

      cantidad_asumida:
        algunaCantidadAsumida,

      nota_minimo:
        'La cantidad mínima de impresión es de 1000 etiquetas por diseño o tamaño y trabajamos en múltiplos de 1000. Si cambia una letra o palabra ya se considera otro diseño.'

    }
  }
];

return [
  {
    json: {
      valid: false,
      success: false,
      can_quote: false,
      status: 'AI_EXTRACTION_FAILED',
      error_code: 'ALL_AI_FAILED',
      message: 'No se pudo interpretar el pedido. Los modelos de IA no pudieron extraer datos válidos.',
      details: [],
      cantidad_detalles: 0,
      source: 'NONE'
    }
  }
];

// ============================================================
// PREPARAR DATOS PARA COTIZACIÓN
// PEGASO ADHESIVOS - V2.3
// ============================================================
//
// Entrada:
// input.detalles[]
//
// Para P4:
// - producto NO es obligatorio
// - material NO es obligatorio
// - necesitamos cantidad + ancho + alto
//
// ============================================================

const input = $input.first().json;

const detalles = input.detalles;


// ============================================================
// VALIDACIÓN
// ============================================================

if (
  !Array.isArray(detalles) ||
  detalles.length === 0
) {

  return [
    {
      json: {

        success: false,
        can_quote: false,

        status:
          'NO_DETAILS',

        message:
          'No existen detalles válidos para generar la cotización.',

        detalles: [],

        cantidad_detalles: 0,

        debug: {

          tipo_detalles:
            typeof detalles,

          es_array:
            Array.isArray(detalles),

          cantidad:
            Array.isArray(detalles)
              ? detalles.length
              : null,

          keys:
            Object.keys(input)
        }

      }
    }
  ];

}


// ============================================================
// NORMALIZAR
// ============================================================

const detallesValidos =
  detalles

    .filter(
      d =>
        d &&
        typeof d === 'object'
    )

    .map(d => {

      const cantidad =
        Number(
          d.cantidad ?? 0
        );

      const anchoCm =
        Number(
          d.ancho_cm ?? 0
        );

      const altoCm =
        Number(
          d.alto_cm ?? 0
        );


      return {

        cantidad,

        producto:
          d.producto != null &&
          String(d.producto).trim() !== ''
            ? String(d.producto).trim()
            : null,

        nombre:
          d.nombre != null &&
          String(d.nombre).trim() !== ''
            ? String(d.nombre).trim()
            : null,

        sabor:
          d.sabor ?? null,

        ancho_cm:
          anchoCm,

        alto_cm:
          altoCm,

        forma:
          String(
            d.forma ??
            'RECTANGULAR'
          ).toUpperCase(),

        cantidad_original:
          d.cantidad_original !== null &&
          d.cantidad_original !== undefined &&
          Number.isFinite(
            Number(d.cantidad_original)
          )
            ? Number(d.cantidad_original)
            : null,

        cantidad_asumida:
          d.cantidad_asumida === true,

        minimo_aplicado:
          d.minimo_aplicado === true

      };

    })


    // ========================================================
    // VALIDACIÓN COMERCIAL
    // ========================================================

    .filter(
      d =>
        Number.isFinite(d.cantidad) &&
        d.cantidad > 0 &&

        Number.isFinite(d.ancho_cm) &&
        d.ancho_cm > 0 &&

        Number.isFinite(d.alto_cm) &&
        d.alto_cm > 0
    );


// ============================================================
// VALIDACIÓN FINAL
// ============================================================

if (detallesValidos.length === 0) {

  return [
    {
      json: {

        success: false,
        can_quote: false,

        status:
          'NO_VALID_DETAILS',

        message:
          'Los detalles recibidos no contienen datos válidos para cotizar.',

        detalles: [],

        cantidad_detalles: 0,

        debug: {

          detalles_recibidos:
            detalles.length,

          detalles_validos:
            0,

          detalles_entrada:
            detalles
        }

      }
    }
  ];

}


// ============================================================
// SALIDA
// ============================================================

return [
  {
    json: {

      success:
        true,

      can_quote:
        true,

      status:
        'READY_FOR_QUOTATION',

      detalles:
        detallesValidos,

      cantidad_detalles:
        detallesValidos.length,

      minimo_impresion:
        input.minimo_impresion !== undefined
          ? Number(input.minimo_impresion)
          : 1000,

      multiplo_impresion:
        input.multiplo_impresion !== undefined
          ? Number(input.multiplo_impresion)
          : 1000,

      minimo_aplicado:
        input.minimo_aplicado === true,

      cantidad_asumida:
        input.cantidad_asumida === true,

      nota_minimo:
        input.nota_minimo ??
        null

    }
  }
];

// ======================================================
// EXPANDIR DETALLES
// ======================================================
//
// Entrada directa:
//   "EDT Datos del detalle"
//   - cotizacion_id
//   - cliente_id
//
// Detalles comerciales:
//   "Preparar datos cotización"
//   - detalles[]
//
// Salida:
//   1 item por cada detalle de la cotización
//
// IMPORTANTE:
//   producto NO es obligatorio.
//   Si nombre y producto vienen vacíos, se genera un
//   nombre técnico usando medidas + forma.
//
// Ejemplo:
//   5x5 + CIRCULAR
//   -> "Etiqueta 5x5 cm circular"
// ======================================================


// ======================================================
// 1. DATOS DE LA COTIZACIÓN
// ======================================================

const input = $input.first().json;

const cotizacionId =
  input.cotizacion_id != null
    ? Number(input.cotizacion_id)
    : null;

const clienteId =
  input.cliente_id != null
    ? Number(input.cliente_id)
    : null;


// ======================================================
// 2. RECUPERAR DETALLES PREPARADOS
// ======================================================

let datosPreparados = {};

try {
  datosPreparados =
    $('Preparar datos cotización').first().json ?? {};
} catch (error) {
  datosPreparados = {};
}

const detalles =
  Array.isArray(datosPreparados.detalles)
    ? datosPreparados.detalles
    : [];


// ======================================================
// 3. VALIDACIONES
// ======================================================

if (
  cotizacionId === null ||
  !Number.isFinite(cotizacionId) ||
  cotizacionId <= 0
) {
  throw new Error(
    'EXPANDIR DETALLES: cotizacion_id es obligatorio.'
  );
}

if (
  !Array.isArray(detalles) ||
  detalles.length === 0
) {
  throw new Error(
    'EXPANDIR DETALLES: no existen detalles preparados para calcular.'
  );
}


// ======================================================
// 4. HELPERS
// ======================================================

function limpiarTexto(valor) {
  if (valor === null || valor === undefined) {
    return null;
  }

  const texto = String(valor).trim();

  return texto !== ''
    ? texto
    : null;
}


function numeroTexto(valor) {
  const numero = Number(valor);

  if (!Number.isFinite(numero)) {
    return '';
  }

  return Number.isInteger(numero)
    ? String(numero)
    : String(numero);
}


function formaParaNombre(forma) {

  switch (forma) {

    case 'CIRCULAR':
      return 'circular';

    case 'RECTANGULAR':
      return 'rectangular';

    case 'CUADRADA':
      return 'cuadrada';

    case 'REDONDEADA':
      return 'con puntas redondeadas';

    case 'TROQUELADA':
      return 'troquelada';

    case 'IRREGULAR':
      return 'irregular';

    case 'NO_ESPECIFICADA':
      return '';

    default:
      return String(forma)
        .trim()
        .toLowerCase();
  }
}


function generarNombreTecnico(
  anchoCm,
  altoCm,
  forma
) {

  const ancho =
    numeroTexto(anchoCm);

  const alto =
    numeroTexto(altoCm);

  const formaTexto =
    formaParaNombre(forma);

  const medida =
    `${ancho}x${alto} cm`;

  if (formaTexto) {
    return `Etiqueta ${medida} ${formaTexto}`;
  }

  return `Etiqueta ${medida}`;
}


// ======================================================
// 5. EXPANDIR
// ======================================================

return detalles.map((detalle, index) => {

  const cantidad =
    Number(detalle.cantidad ?? 0);

  const anchoCm =
    Number(detalle.ancho_cm ?? 0);

  const altoCm =
    Number(detalle.alto_cm ?? 0);

  const cantidadOriginal =
    Number(
      detalle.cantidad_original ??
      detalle.cantidad ??
      0
    );

  const forma =
    String(
      detalle.forma ??
      'RECTANGULAR'
    )
      .trim()
      .toUpperCase();


  // ====================================================
  // VALIDACIÓN DEL DETALLE
  // ====================================================

  if (
    !Number.isFinite(cantidad) ||
    cantidad <= 0
  ) {
    throw new Error(
      `EXPANDIR DETALLES: cantidad inválida en detalle ${index}.`
    );
  }

  if (
    !Number.isFinite(anchoCm) ||
    anchoCm <= 0
  ) {
    throw new Error(
      `EXPANDIR DETALLES: ancho_cm inválido en detalle ${index}.`
    );
  }

  if (
    !Number.isFinite(altoCm) ||
    altoCm <= 0
  ) {
    throw new Error(
      `EXPANDIR DETALLES: alto_cm inválido en detalle ${index}.`
    );
  }


  // ====================================================
  // PRODUCTO Y NOMBRE
  // ====================================================

  const producto =
    limpiarTexto(detalle.producto);

  const nombreOriginal =
    limpiarTexto(detalle.nombre);

  // Prioridad:
  //
  // 1. nombre explícito
  // 2. producto
  // 3. nombre técnico generado
  //
  // producto puede permanecer null.

  const nombre =
    nombreOriginal ??
    producto ??
    generarNombreTecnico(
      anchoCm,
      altoCm,
      forma
    );


  // ====================================================
  // SALIDA DEL DETALLE
  // ====================================================

  return {
    json: {

      cotizacion_id:
        cotizacionId,

      cliente_id:
        clienteId,

      detalle_index:
        index,

      cantidad,

      // Producto no es obligatorio.
      producto,

      // Nombre sí queda resuelto para diseño.
      nombre,

      sabor:
        detalle.sabor ?? null,

      ancho_cm:
        anchoCm,

      alto_cm:
        altoCm,

      forma,

      cantidad_original:
        Number.isFinite(cantidadOriginal)
          ? cantidadOriginal
          : cantidad,

      minimo_aplicado:
        detalle.minimo_aplicado === true

    }
  };

});

// ======================================================
// RECUPERAR DETALLES CALCULADOS
