];

// ======================================================
// PREPARAR CONVERSACIÓN
// ======================================================
// Entrada:
//   - conversación ya resuelta
//   - puede pertenecer a cliente, contacto o prospecto
//   - puede incluir contexto_comercial desde PostgreSQL
//
// Salida:
//   estructura uniforme para:
//   - guardar mensaje entrante
//   - recuperar historial
//   - preparar contexto IA
//   - conservar contexto comercial persistente
// ======================================================

const data = $input.first().json;


// ======================================================
// HELPERS
// ======================================================

function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleano(valor, defecto = false) {
  if (typeof valor === 'boolean') {
    return valor;
  }

  if (valor === 'true') {
    return true;
  }

  if (valor === 'false') {
    return false;
  }

  return defecto;
}


function objetoJSON(valor) {
  // Ya es objeto
  if (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return valor;
  }

  // PostgreSQL/n8n podría entregarlo como string
  if (typeof valor === 'string') {
    const limpio = valor.trim();

    if (!limpio) {
      return {};
    }

    try {
      const parsed = JSON.parse(limpio);

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }
    } catch (error) {
      // No detenemos el flujo por un JSON vacío o mal formado.
      return {};
    }
  }

  return {};
}


// ======================================================
// VALIDACIONES BÁSICAS
// ======================================================

if (!data.conversacion_id) {
  throw new Error(
    'Preparar conversación: no existe conversacion_id.'
  );
}

if (!data.telefono) {
  throw new Error(
    'Preparar conversación: no existe telefono.'
  );
}


// ======================================================
// NORMALIZACIÓN DE IDS
// ======================================================

const conversacionId =
  numeroONull(data.conversacion_id);

if (conversacionId === null) {
  throw new Error(
    'Preparar conversación: conversacion_id no es válido.'
  );
}


const clienteId =
  numeroONull(data.cliente_id) ??
  numeroONull(data.conversacion_cliente_id);


const contactoId =
  numeroONull(data.contacto_id) ??
  numeroONull(data.conversacion_contacto_id);


const prospectoId =
  numeroONull(data.prospecto_id) ??
  numeroONull(data.conversacion_prospecto_id);


// ======================================================
// DETERMINAR ACTOR
// ======================================================

let tipoActor = 'DESCONOCIDO';

if (clienteId !== null) {
  tipoActor = 'CLIENTE';
}
else if (contactoId !== null) {
  tipoActor = 'CONTACTO';
}
else if (prospectoId !== null) {
  tipoActor = 'PROSPECTO';
}


// ======================================================
// RECUPERAR CONTEXTO COMERCIAL
// ======================================================
//
// Soportamos varios nombres por seguridad porque el dato
// puede venir:
// - directamente desde Buscar conversación
// - renombrado por un resolver previo
//
// Orden de prioridad:
// 1. contexto_comercial
// 2. conversacion_contexto_comercial
//
// ======================================================

const contextoComercial =
  objetoJSON(
    data.contexto_comercial ??
    data.conversacion_contexto_comercial ??
    {}
  );


// ======================================================
// NORMALIZAR ESTADO DE CONVERSACIÓN
// ======================================================

const conversacionEstado =
  data.conversacion_estado ??
  data.estado ??
  'ACTIVA';


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      ...data,

      // ============================================
      // CONVERSACIÓN
      // ============================================

      conversacion_id:
        conversacionId,

      conversacion_existe:
        true,

      conversacion_nueva:
        booleano(
          data.conversacion_nueva,
          false
        ),

      conversacion_estado:
        conversacionEstado,

      conversacion_cliente_id:
        clienteId,

      conversacion_contacto_id:
        contactoId,

      conversacion_prospecto_id:
        prospectoId,

      // ============================================
      // CONTEXTO COMERCIAL PERSISTENTE
      // ============================================

      contexto_comercial:
        contextoComercial,

      // ============================================
      // ACTORES
      // ============================================

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      prospecto_id:
        prospectoId,

      tipo_actor:
        tipoActor,

      // ============================================
      // MENSAJE
      // ============================================

      mensaje:
        data.mensaje ?? '',

      tipo:
        data.tipo ?? 'TEXTO',

      canal:
        data.canal ?? 'WHATSAPP',

      mensaje_externo_id:
        data.mensaje_externo_id ?? null,

      recibido_at:
        data.recibido_at ??
        new Date().toISOString(),

      // ============================================
      // FLAGS
      // ============================================

      es_cliente_registrado:
        booleano(
          data.es_cliente_registrado,
          false
        ),

      prospecto_existe:
        booleano(
          data.prospecto_existe,
          false
        )
    }
  }
];

// ======================================================
// NODO N8N: Preparar contexto IA
// ARCHIVO: code/03-conversacion/preparar-contexto-ia.js
// VERSION: 4.4
// ======================================================
//
// RESPONSABILIDAD:
//
// - Construir el contexto final para el cerebro comercial.
// - Mantener "Preparar conversación" como fuente de verdad
//   para identidad y memoria comercial persistida.
// - Usar prioritariamente el turno ENRIQUECIDO recibido por
//   la entrada del nodo (audio transcrito, imágenes, etc.).
// - Usar "Resolver turno conversacional" como fallback.
// - Incorporar análisis de imagen válido desde Groq,
//   DeepSeek u OpenAI.
// - Propagar medidas escritas detectadas en imágenes de forma
//   estructurada (ancho/alto/diámetro) sin romper el contexto actual.
// - Incorporar transcripciones de audio ya aplicadas al turno.
// - NO entregar links de multimedia al cerebro.
// - Limitar el historial libre a una ventana reciente.
// - Limitar el número máximo de mensajes históricos.
// - Detectar si empieza una nueva sesión por inactividad.
// - Conservar contexto_comercial estructurado aunque el
//   historial libre haya expirado.
// - Excluir del historial los marcadores internos (respuesta omitida
//   y bot reactivado por administrador).
// - Exponer ultimo_saliente (origen BOT / AUTOMATICO / HUMANO,
//   acción equivalente, si llegó después del inicio del turno)
//   y medidas_ya_solicitadas para el anti-duplicado.
// - Reglas pre-IA solo para texto sin multimedia:
//   SALUDO_SIMPLE (respuesta corta fija), PRODUCTO_NO_P4
//   (DERIVAR_HUMANO + COTIZACION_ESPECIAL) y
//   DIVISION_MINIMO_DISENOS (INFORMAR_MINIMO: no se puede
//   repartir la cantidad con menos de 1000 por diseño; nunca
//   deriva). Cuando aplican se
//   emite decision con el contrato del cerebro y
//   requiere_cerebro_comercial = false para saltar la IA.
// - NO llamar a IA.
// - NO escribir PostgreSQL.
//
// ======================================================


// ======================================================
// 0. CONFIGURACIÓN
// ======================================================

const VENTANA_HISTORIAL_HORAS = 24;

const MAX_MENSAJES_HISTORIAL = 24;

const MAX_SALIENTES_RECIENTES = 6;

const LARGO_MAXIMO_CONTENIDO_HISTORIAL = 4000;

const PREFIJO_AUTOMATICO_WHATSAPP_BUSINESS = '[AUTOMATICO WHATSAPP BUSINESS';

const PREFIJO_RESPUESTA_OMITIDA = '[RESPUESTA AUTOMÁTICA OMITIDA';

const PREFIJO_BOT_REACTIVADO = '[BOT REACTIVADO POR ADMINISTRADOR';

// Marcadores internos: se guardan como SALIENTE, nunca se envían
// y no forman parte de la conversación con el cliente.
function esMarcadorInterno(contenido) {
  const t = String(contenido ?? '').trim();
  return t.startsWith(PREFIJO_RESPUESTA_OMITIDA) || t.startsWith(PREFIJO_BOT_REACTIVADO);
}

const OFFSET_HORA_ECUADOR = -5;


// ======================================================
// 1. HELPERS
// ======================================================

function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function booleano(valor, defecto = false) {
  if (typeof valor === 'boolean') {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return defecto;
}


function primeroDefinido(...valores) {
  for (const valor of valores) {
    if (
      valor !== undefined &&
      valor !== null &&
      valor !== ''
    ) {
      return valor;
    }
  }

  return null;
}


function objeto(valor) {
  return (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  )
    ? valor
    : {};
}


function fechaMs(valor) {
  if (!valor) {
    return null;
  }

  const ms =
    Date.parse(valor);

  return Number.isFinite(ms)
    ? ms
    : null;
}


function normalizarTexto(valor) {
  return String(valor ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


function clasificacionDesdeEstado(estado) {
  const valor =
    textoONull(estado)
      ?.toUpperCase() ??
    null;

  if (!valor) {
    return null;
  }

  if (
    [
      'INTERESADO',
      'ACEPTADO',
      'PAGO_PENDIENTE',
      'ABONO_REPORTADO',
      'EN_PROCESO'
    ].includes(valor)
  ) {
    return 'A';
  }

  if (
    [
      'COTIZADO',
      'CALIFICADO',
      'EN_SEGUIMIENTO',
      'CONTACTADO'
    ].includes(valor)
  ) {
    return 'B';
  }

  return 'C';
}


// ======================================================
// 2. CONTEXTO ACTUAL
// ======================================================

let actual = {};

try {
  actual =
    $('Preparar conversación')
      .first()
      .json ?? {};
} catch (error) {
  throw new Error(
    'Preparar contexto IA: no se pudo recuperar "Preparar conversación".'
  );
}


// ======================================================
// 3. RESOLVER TURNO
// ======================================================
//
// PRIORIDAD:
//
// 1. Entrada actual del nodo.
//
//    Esto permite recibir:
//      - Aplicar transcripciones al turno
//      - futuros enriquecedores multimedia
//
// 2. Resolver turno conversacional.
//
// Así NO perdemos las transcripciones que acabamos de
// aplicar al turno.
//
// ======================================================

const entradaNodo =
  $input.first()?.json ?? {};


let turnoOriginal = {};

try {
  turnoOriginal =
    $('Resolver turno conversacional')
      .first()
      .json ?? {};
} catch (error) {
  turnoOriginal = {};
}


const entradaTieneTurno =
  Array.isArray(
    entradaNodo.turno_mensajes
  ) &&
  entradaNodo.turno_mensajes.length > 0;


const turno =
  entradaTieneTurno
    ? {
        ...turnoOriginal,
        ...entradaNodo
      }
    : turnoOriginal;


// ======================================================
// 3.1 IDS DEL TURNO
// ======================================================

const turnoMensajeIds =
  turno.continuar_procesamiento === true &&
  Array.isArray(turno.turno_mensaje_ids)
    ? turno.turno_mensaje_ids
        .map(numeroONull)
        .filter(id => id !== null)
    : Array.isArray(turno.turno_mensajes)
      ? turno.turno_mensajes
          .map(m => numeroONull(m.id))
          .filter(id => id !== null)
      : [];


const hayTurno =
  turnoMensajeIds.length > 0 &&
  (
    textoONull(turno.turno_texto) !== null ||
    (
      Array.isArray(turno.turno_mensajes) &&
      turno.turno_mensajes.length > 0
    )
  );


// ======================================================
// 4. MEDIA DEL TURNO
// ======================================================

const PREFIJO_PENDIENTE =
  '[MEDIA_PENDIENTE]';


const LINEA_IMAGEN_NO_ANALIZADA =
  '[CONTEXTO DE IMAGEN · revision=SI · motivo=IMAGEN_NO_ANALIZADA] ' +
  'La imagen no pudo revisarse automáticamente.';


const LINEA_AUDIO_NO_TRANSCRITO =
  '[TRANSCRIPCION DE AUDIO · revision=SI · motivo=AUDIO_NO_TRANSCRITO] ' +
  'El audio no pudo transcribirse automáticamente.';


function quitarPendientes(
  contenido,
  tipo = null,
  reemplazar = true
) {
  const tipoNormalizado =
    String(tipo ?? '')
      .trim()
      .toUpperCase();

  return String(contenido ?? '')
    .split('\n')
    .flatMap(linea => {
      const limpia =
        linea.trim();

      if (
        !limpia.startsWith(
          PREFIJO_PENDIENTE
        )
      ) {
        return [linea];
      }

      if (!reemplazar) {
        return [];
      }

      if (tipoNormalizado === 'IMAGEN') {
        return [
          LINEA_IMAGEN_NO_ANALIZADA
        ];
      }

      if (tipoNormalizado === 'AUDIO') {
        return [
          LINEA_AUDIO_NO_TRANSCRITO
        ];
      }

      return [
        `[ARCHIVO NO PROCESABLE · tipo=${tipoNormalizado || 'DESCONOCIDO'}] ` +
        'El archivo no pudo procesarse automáticamente.'
      ];
    })
    .join('\n')
    .trim();
}


function atributosCabecera(linea) {
  const cabecera =
    linea.match(
      /^\[([^\]]*)\]/
    );

  if (!cabecera) {
    return {};
  }

  return Object.fromEntries(
    cabecera[1]
      .split('·')
      .map(parte =>
        parte
          .trim()
          .split('=')
      )
      .filter(par =>
        par.length === 2
      )
      .map(([clave, valor]) => [
        clave.trim(),
        valor.trim()
      ])
  );
}


// ======================================================
// 4.1 RECUPERAR ANÁLISIS DE IMÁGENES
// ======================================================
//
// Tomamos análisis válidos de cualquier proveedor.
//
// La prioridad natural es:
//
// Groq
//   ↓ fallback
// DeepSeek
//   ↓ fallback
// OpenAI
//
// Como cada mensaje_id debería terminar válido en un solo
// proveedor, almacenamos solo análisis_valido=true.
//
// ======================================================

function obtenerItemsNodo(nombre) {
  try {
    return $(nombre)
      .all()
      .map(item => item.json ?? {});
  } catch (_) {
    return [];
  }
}


const analisisImagenes = [
  ...obtenerItemsNodo(
    'Validar análisis imagen Groq'
  ),
  ...obtenerItemsNodo(
    'Validar análisis imagen DeepSeek'
  ),
  ...obtenerItemsNodo(
    'Analizar imagen OpenAI'
  ),
  ...obtenerItemsNodo(
    'Validar análisis imagen OpenAI'
  )
];


const contenidoAnalizado =
  new Map();

const medidasImagenPorMensaje =
  new Map();


for (const analisis of analisisImagenes) {
  const mensajeId =
    numeroONull(
      analisis.mensaje_id
    );

  const contenido =
    textoONull(
      analisis.contenido_actualizado
    );

  if (
    mensajeId === null ||
    contenido === null
  ) {
    continue;
  }

  if (
    analisis.analisis_valido === false
  ) {
    continue;
  }

  // Primero que llega válido gana.
  // Normalmente será Groq.
  if (
    !contenidoAnalizado.has(
      mensajeId
    )
  ) {
    contenidoAnalizado.set(
      mensajeId,
      contenido
    );
  }

  const analisisNormalizado =
    objeto(
      analisis.analisis
    );

  const medidasDetectadas =
    booleano(
      primeroDefinido(
        analisis.medidas_detectadas,
        analisisNormalizado.medidas_detectadas
      ),
      false
    );

  const anchoCm =
    numeroONull(
      primeroDefinido(
        analisis.ancho_cm,
        analisisNormalizado.ancho_cm
      )
    );

  const altoCm =
    numeroONull(
      primeroDefinido(
        analisis.alto_cm,
        analisisNormalizado.alto_cm
      )
    );

  const diametroCm =
    numeroONull(
      primeroDefinido(
        analisis.diametro_cm,
        analisisNormalizado.diametro_cm
      )
    );

  const medidasVisibles =
    textoONull(
      primeroDefinido(
        analisis.medidas_visibles,
        analisisNormalizado.medidas_visibles
      )
    );

  if (
    medidasDetectadas ||
    anchoCm !== null ||
    altoCm !== null ||
    diametroCm !== null ||
    medidasVisibles !== null
  ) {
    medidasImagenPorMensaje.set(
      mensajeId,
      {
        mensaje_id:
          mensajeId,

        proveedor:
          textoONull(
            analisis.proveedor_analisis
          ),

        contenido_detectado:
          textoONull(
            analisis.contenido_detectado ??
            analisisNormalizado.contenido_detectado
          ),

        confianza:
          textoONull(
            analisis.confianza ??
            analisisNormalizado.confianza
          ),

        ancho_cm:
          anchoCm,

        alto_cm:
          altoCm,

        diametro_cm:
          diametroCm,

        texto_original:
          medidasVisibles,

        fuente:
          'IMAGEN'
      }
    );
  }
}


// ======================================================
// 4.2 MENSAJES DEL TURNO
// ======================================================

const mensajesTurnoOrigen =
  hayTurno &&
  Array.isArray(
    turno.turno_mensajes
  )
    ? turno.turno_mensajes
    : [
        {
          id: null,
          tipo:
            actual.tipo,

          contenido:
            hayTurno
              ? turno.turno_texto
              : actual.mensaje
        }
      ];


const mensajesTurno =
  mensajesTurnoOrigen.map(m => {

    const id =
      numeroONull(
        m.id
      );

    const tipo =
      (
        textoONull(
          m.tipo
        ) ??
        'TEXTO'
      ).toUpperCase();


    let contenido =
      contenidoAnalizado.get(id) ??
      m.contenido ??
      '';


    // --------------------------------------------------
    // TEXTO
    // --------------------------------------------------

    if (tipo === 'TEXTO') {
      contenido =
        String(contenido)
          .trim();
    }

    // --------------------------------------------------
    // MEDIA
    // --------------------------------------------------

    else {
      contenido =
        quitarPendientes(
          contenido,
          tipo,
          true
        );
    }


    return {
      ...m,

      id,

      tipo,

      contenido
    };
  });


// ======================================================
// 4.3 TEXTO FINAL DEL TURNO
// ======================================================

const textoTurno =
  mensajesTurno
    .map(m =>
      textoONull(
        m.contenido
      )
    )
    .filter(Boolean)
    .join('\n');


const medidasImagenTurno =
  mensajesTurno
    .map(m =>
      medidasImagenPorMensaje.get(
        numeroONull(m.id)
      ) ?? null
    )
    .filter(Boolean);


// ======================================================
// 4.4 RESUMEN DE MEDIA
// ======================================================

let imagenesAnalizadas = 0;

let audiosTranscritos = 0;

let comprobanteDetectado = false;

let revisionImagen = false;

let revisionAudio = false;

let archivoNoProcesable = false;


for (const m of mensajesTurno) {

  if (m.tipo === 'TEXTO') {
    continue;
  }


  for (
    const linea of String(
      m.contenido ?? ''
    )
      .split('\n')
      .map(l => l.trim())
  ) {

    // --------------------------------------------------
    // ARCHIVO NO PROCESABLE
    // --------------------------------------------------

    if (
      linea.startsWith(
        '[ARCHIVO NO PROCESABLE'
      )
    ) {
      archivoNoProcesable =
        true;
    }


    // --------------------------------------------------
    // IMAGEN
    // --------------------------------------------------

    if (
      m.tipo === 'IMAGEN' &&
      linea.startsWith(
        '[CONTEXTO DE IMAGEN'
      )
    ) {

      const atributos =
        atributosCabecera(
          linea
        );

      if (atributos.contenido) {
        imagenesAnalizadas++;
      }

      if (
        atributos.revision === 'SI'
      ) {
        revisionImagen =
          true;
      }

      if (
        atributos.contenido ===
        'COMPROBANTE_PAGO'
      ) {
        comprobanteDetectado =
          true;
      }
    }


    // --------------------------------------------------
    // AUDIO
    // --------------------------------------------------

    if (
      m.tipo === 'AUDIO' &&
      linea.startsWith(
        '[TRANSCRIPCION DE AUDIO'
      )
    ) {

      const atributos =
        atributosCabecera(
          linea
        );

      if (
        atributos.revision === 'SI'
      ) {
        revisionAudio =
          true;
      } else {
        audiosTranscritos++;
      }
    }
  }
}


// Si "Aplicar transcripciones al turno" ya resolvió
// explícitamente el estado, lo respetamos.

if (
  turno.requiere_revision_audio === true
) {
  revisionAudio =
    true;
}


const mediaTurno = {

  cantidad_media:
    mensajesTurno.filter(
      m =>
        m.tipo !== 'TEXTO'
    ).length,

  imagenes_analizadas:
    imagenesAnalizadas,

  audios_transcritos:
    audiosTranscritos,

  comprobante_detectado:
    comprobanteDetectado,

  requiere_revision_imagen:
    revisionImagen,

  requiere_revision_audio:
    revisionAudio,

  archivo_no_procesable:
    archivoNoProcesable,

  medidas_detectadas_imagen:
    medidasImagenTurno.length > 0,

  cantidad_imagenes_con_medidas:
    medidasImagenTurno.length,

  medidas_imagen:
    medidasImagenTurno,

  requiere_revision_humana:
    (
      revisionImagen ||
      revisionAudio ||
      archivoNoProcesable
    ),

  motivo_derivacion:
    archivoNoProcesable
      ? 'ARCHIVO_NO_PROCESABLE'

      : revisionImagen
        ? 'IMAGEN_REQUIERE_REVISION'

        : revisionAudio
          ? 'AUDIO_REQUIERE_REVISION'

          : null
};


// ======================================================
// 5. RECUPERAR HISTORIAL COMPLETO
// ======================================================

let itemsHistorial = [];

try {
  itemsHistorial =
    $('Recuperar historial conversación')
      .all();
} catch (error) {
  itemsHistorial =
    [];
}


const idsTurno =
  new Set(
    turnoMensajeIds
  );


const externosTurno =
  new Set(
    itemsHistorial
      .map(item =>
        item.json ?? {}
      )
      .filter(row =>
        idsTurno.has(
          numeroONull(
            row.id
          )
        )
      )
      .map(row =>
        textoONull(
          row.mensaje_externo_id
        )
      )
      .filter(Boolean)
  );


const externosVistos =
  new Set();


// ======================================================
// 5.1 REFERENCIA TEMPORAL DEL TURNO
// ======================================================
//
// Preferimos la fecha del último mensaje del turno.
// Si no existe, usamos recibido_at.
// Último fallback: ahora.
//
// ======================================================

const fechasTurno =
  mensajesTurno
    .map(m =>
      fechaMs(
        m.enviado_at
      )
    )
    .filter(ms =>
      ms !== null
    );


const referenciaTurnoMs =
  fechasTurno.length > 0
    ? Math.max(
        ...fechasTurno
      )
    : (
        fechaMs(
          actual.recibido_at
        ) ??
        Date.now()
      );


const limiteHistorialMs =
  referenciaTurnoMs -
  (
    VENTANA_HISTORIAL_HORAS *
    60 *
    60 *
    1000
  );


// ======================================================
// 5.2 LIMPIAR Y FILTRAR HISTORIAL
// ======================================================

let historialCandidato =
  itemsHistorial
    .map(item =>
      item.json ?? null
    )
    .filter(row => {

      if (!row) {
        return false;
      }


      const id =
        numeroONull(
          row.id
        );


      const externo =
        textoONull(
          row.mensaje_externo_id
        );


      // -----------------------------------------------
      // NO incluir turno actual
      // -----------------------------------------------

      if (
        idsTurno.has(id)
      ) {
        return false;
      }


      // -----------------------------------------------
      // NO incluir duplicados externos
      // -----------------------------------------------

      if (
        externo !== null
      ) {

        if (
          externosTurno.has(
            externo
          ) ||
          externosVistos.has(
            externo
          )
        ) {
          return false;
        }

        externosVistos.add(
          externo
        );
      }


      // -----------------------------------------------
      // Debe tener contenido
      // -----------------------------------------------

      const tieneContenido =
        row.contenido !== undefined &&
        row.contenido !== null &&
        String(
          row.contenido
        ).trim() !== '';

      if (!tieneContenido) {
        return false;
      }

      if (esMarcadorInterno(row.contenido)) {
        return false;
      }


      // -----------------------------------------------
      // VENTANA TEMPORAL
      // -----------------------------------------------

      const fecha =
        fechaMs(
          row.enviado_at
        );

      if (
        fecha !== null &&
        fecha < limiteHistorialMs
      ) {
        return false;
      }


      return true;
    })
    .sort((a, b) => {

      const fechaA =
        fechaMs(
          a.enviado_at
        ) ?? 0;

      const fechaB =
        fechaMs(
          b.enviado_at
        ) ?? 0;

      if (fechaA !== fechaB) {
        return fechaA - fechaB;
      }

      return (
        numeroONull(a.id) ?? 0
      ) -
      (
        numeroONull(b.id) ?? 0
      );
    });


// ======================================================
// 5.3 LÍMITE DE MENSAJES
// ======================================================
//
// Conservamos los MÁS RECIENTES.
//
// ======================================================

if (
  historialCandidato.length >
  MAX_MENSAJES_HISTORIAL
) {
  historialCandidato =
    historialCandidato.slice(
      -MAX_MENSAJES_HISTORIAL
    );
}


// ======================================================
// 5.4 HISTORIAL FINAL PARA IA
// ======================================================

const historial =
  historialCandidato
    .map(row => {

      const tipo =
        (
          textoONull(
            row.tipo
          ) ??
          'TEXTO'
        ).toUpperCase();


      let contenido =
        row.contenido ?? '';


      if (
        tipo !== 'TEXTO'
      ) {
        contenido =
          quitarPendientes(
            contenido,
            tipo,
            false
          );
      }


      contenido =
        String(
          contenido ?? ''
        )
          .trim()
          .slice(
            0,
            LARGO_MAXIMO_CONTENIDO_HISTORIAL
          );


      return {

        direccion:
          textoONull(
            row.direccion
          ),

        contenido,

        tipo,

        enviado_at:
          row.enviado_at ??
          null
      };
    })
    .filter(row =>
      textoONull(
