// ======================================================
// 10.1 REGLAS PRE-IA
// ======================================================
//
// Solo texto sin multimedia. Ante cualquier duda decide el
// cerebro: una regla solo aplica si el texto es inequívoco.
//
// SALUDO_SIMPLE: todas las palabras pertenecen al vocabulario
// de saludo y al menos una es un saludo núcleo.
// "Hola, necesito etiquetas de 5x5" NO es saludo simple.
//
// PRODUCTO_NO_P4: el texto nombra un impreso que no es
// etiqueta adhesiva y NO menciona etiquetas/stickers/adhesivos.
//
// DIVISION_MINIMO_DISENOS: el cliente quiere repartir una
// cantidad entre varios diseños (sabores, nombres, modelos)
// y la división es imposible: menos de 1000 por diseño o
// cantidades por diseño que no son múltiplo de 1000. Se
// explica el mínimo sin derivar. "3000 para 3 diseños" es
// posible y lo decide el cerebro.
//
// ======================================================

const VOCABULARIO_SALUDO = new Set([
  'hola', 'holi', 'ola', 'alo', 'hey', 'hi', 'hello',
  'buenas', 'buenos', 'buena', 'buen', 'dia', 'dias',
  'tarde', 'tardes', 'noche', 'noches', 'saludos', 'saludo',
  'que', 'tal', 'como', 'esta', 'estan', 'estas', 'muy', 'y',
  'senor', 'senora', 'senorita', 'sr', 'sra', 'srta',
  'estimado', 'estimada', 'estimados', 'amigo', 'amiga',
  'a', 'todos', 'usted', 'ustedes'
]);

const NUCLEO_SALUDO = new Set([
  'hola', 'holi', 'ola', 'alo', 'hey', 'hi', 'hello',
  'buenas', 'buenos', 'buena', 'buen', 'saludos', 'saludo'
]);

const PRODUCTOS_NO_P4 = [
  { patron: /\btarjetas? (de )?(presentacion|personales?|visita|de visita|corporativas?)\b/, producto: 'tarjetas de presentación' },
  { patron: /\b(flyers?|flayers?|volantes?)\b/, producto: 'flyers / volantes' },
  { patron: /\bcarpetas?\b/, producto: 'carpetas' },
  { patron: /\btalonarios?\b/, producto: 'talonarios' },
  { patron: /\bboletos?\b/, producto: 'boletos' },
  { patron: /\bentradas? (para|de)\b/, producto: 'entradas' },
  { patron: /\bformularios?\b/, producto: 'formularios' },
  { patron: /\bhojas? membretadas?\b|\bmembretes?\b/, producto: 'hojas membretadas' },
  { patron: /\b(tripticos?|dipticos?)\b/, producto: 'trípticos / dípticos' },
  { patron: /\bafiches?\b/, producto: 'afiches' },
  { patron: /\bbrochures?\b/, producto: 'brochures' }
];

const MENCIONA_ETIQUETA =
  /\b(etiquetas?|stickers?|adhesiv[oa]s?|calcomanias?|pegatinas?|rotulos?|vinil|viniles)\b/;

const RESPUESTA_TRANSICION_NO_P4 =
  'Permítame un momento por favor, verificamos su requerimiento.';


const MINIMO_POR_DISENO = 1000;

const PALABRA_DISENO =
  '(?:disenos?|modelos?|sabor(?:es)?|nombres?|variedad(?:es)?|version(?:es)?|textos?|tipos?|referencias?|artes?|marcas?|color(?:es)?|productos?|presentacion(?:es)?)';

const CANTIDAD_DISENOS =
  '(\\d{1,2}|un|uno|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|varios|varias|diferentes|distintos|distintas)';

const NUMEROS_PALABRA = {
  un: 1, uno: 1, una: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5,
  seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10
};

// Como normalizarTexto, pero conserva cantidades:
// "1.500" -> 1500, "dos mil" -> 2000, "mil" -> 1000.
function textoCantidades(valor) {
  return String(valor ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/(\d)[.,](?=\d{3}\b)/g, '$1')
    .replace(
      /\b(\d{1,3}|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez) mil\b/g,
      (_, n) => String((NUMEROS_PALABRA[n] ?? Number(n)) * 1000)
    )
    .replace(/\bmil\b/g, '1000')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// null = "varios / diferentes": al menos 2, número desconocido.
function numeroDisenos(token) {
  if (/^\d+$/.test(token)) {
    return Number(token);
  }

  return NUMEROS_PALABRA[token] ?? null;
}

function cantidadValidaPorDiseno(q) {
  return q >= MINIMO_POR_DISENO && q % MINIMO_POR_DISENO === 0;
}

function ajustarCantidadPorDiseno(q) {
  return Math.max(
    MINIMO_POR_DISENO,
    Math.ceil(q / MINIMO_POR_DISENO) * MINIMO_POR_DISENO
  );
}

function detectarDivisionDisenos(textoOriginal) {
  const t = textoCantidades(textoOriginal);

  const nombraDisenos =
    new RegExp(`\\b${PALABRA_DISENO}\\b`).test(t);

  if (!nombraDisenos && !/\b(otro|otra)\b/.test(t)) {
    return null;
  }

  // "1500 de un diseño y 1000 de otro y 500 de otro"
  const porDiseno =
    [...t.matchAll(
      /\b(\d{3,})\b (?:(?:etiquetas|unidades|stickers) )?(?:de|del|para|con|en) (?:un|una|uno|otro|otra|el otro|la otra|el primero?|el segundo|el tercero?)\b/g
    )].map(m => Number(m[1]));

  if (porDiseno.length >= 2) {
    return porDiseno.every(cantidadValidaPorDiseno)
      ? null
      : { tipo: 'CANTIDADES_POR_DISENO', cantidades: porDiseno };
  }

  // "500 de cada diseño" / "5 diseños de 500"
  const deCada = t.match(
    new RegExp(`\\b(\\d{3,})\\b (?:(?:etiquetas|unidades|stickers) )?(?:de|para|por|en) cada (?:uno|una|${PALABRA_DISENO})\\b`)
  );

  const nDisenosDe = t.match(
    new RegExp(`\\b${CANTIDAD_DISENOS} ${PALABRA_DISENO} (?:\\w+ )?de (\\d{3,})\\b`)
  );

  if (deCada || nDisenosDe) {
    const q = Number(deCada ? deCada[1] : nDisenosDe[2]);

    return cantidadValidaPorDiseno(q)
      ? null
      : {
          tipo: 'CANTIDAD_POR_CADA_DISENO',
          cantidad_por_diseno: q,
          disenos: nDisenosDe ? numeroDisenos(nDisenosDe[1]) : null
        };
  }

  // "las 3000 para 5 diseños" / "5 diseños pero solo 3000 etiquetas"
  // "1000 etiquetas, mitad de un diseño y mitad de otro"
  let total = null;
  let disenos = null;

  const totalAntes = t.match(
    new RegExp(`\\b(\\d{3,})\\b (?:\\w+ ){0,3}?(?:para|en|de|con|entre) (?:los |las )?${CANTIDAD_DISENOS} (?:\\w+ )?${PALABRA_DISENO}\\b`)
  );

  const totalDespues = t.match(
    new RegExp(`\\b${CANTIDAD_DISENOS} ${PALABRA_DISENO}\\b (?:\\w+ ){0,4}?(\\d{3,}) (?:etiquetas|unidades|stickers|en total)\\b`)
  );

  if (nombraDisenos && /\bmitad\b/.test(t)) {
    const primera = t.match(/\b(\d{3,})\b/);
    total = primera ? Number(primera[1]) : null;
    disenos = 2;
  } else if (totalAntes) {
    total = Number(totalAntes[1]);
    disenos = numeroDisenos(totalAntes[2]);
  } else if (totalDespues) {
    total = Number(totalDespues[2]);
    disenos = numeroDisenos(totalDespues[1]);
  }

  if (total === null || disenos === 1) {
    return null;
  }

  const minimoNecesario =
    (disenos ?? 2) * MINIMO_POR_DISENO;

  return total < minimoNecesario
    ? { tipo: 'TOTAL_ENTRE_DISENOS', total, disenos }
    : null;
}

function formatoMiles(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

function respuestaDivisionDisenos(division) {
  const base =
    'No es posible dividir la cantidad entre varios diseños: ' +
    'cada diseño requiere mínimo 1.000 etiquetas y trabajamos en múltiplos de 1.000. ' +
    'Si cambia una letra o palabra ya se considera otro diseño.';

  let detalle = '';

  if (division.tipo === 'CANTIDADES_POR_DISENO') {
    const partes = division.cantidades.map(q => {
      const ajustada = ajustarCantidadPorDiseno(q);
      return ajustada === q
        ? formatoMiles(q)
        : `${formatoMiles(q)} → ${formatoMiles(ajustada)}`;
    });

    const lista =
      partes.slice(0, -1).join(', ') + ' y ' + partes[partes.length - 1];

    const totalAjustado = division.cantidades
      .map(ajustarCantidadPorDiseno)
      .reduce((s, q) => s + q, 0);

    detalle =
      `Para sus ${division.cantidades.length} diseños las cantidades podrían ser: ` +
      `${lista} (${formatoMiles(totalAjustado)} en total).`;
  } else if (division.tipo === 'CANTIDAD_POR_CADA_DISENO') {
    detalle = division.disenos
      ? `Para ${division.disenos} diseños necesitaría 1.000 de cada uno: ` +
        `${formatoMiles(division.disenos * MINIMO_POR_DISENO)} etiquetas en total.`
      : `Cada diseño necesita 1.000 etiquetas, no ${formatoMiles(division.cantidad_por_diseno)}.`;
  } else {
    const posibles = Math.floor(division.total / MINIMO_POR_DISENO);

    const necesita = division.disenos
      ? `Para ${division.disenos} diseños necesitaría mínimo ` +
        `${formatoMiles(division.disenos * MINIMO_POR_DISENO)} etiquetas (1.000 por diseño).`
      : '';

    const alcance =
      posibles >= 2
        ? `Con ${formatoMiles(division.total)} etiquetas podemos hacerle hasta ${posibles} diseños de 1.000.`
        : posibles === 1
          ? `Con ${formatoMiles(division.total)} etiquetas podemos hacerle 1 diseño.`
          : '';

    detalle = [necesita, alcance].filter(Boolean).join(' ');
  }

  return `${base} ${detalle} ¿Con cuántos diseños desea que le coticemos?`
    .replace(/\s+/g, ' ')
    .trim();
}


function saludoHorario(textoPlano) {
  if (/\bnoches?\b/.test(textoPlano)) {
    return 'Buenas noches';
  }

  if (/\btardes?\b/.test(textoPlano)) {
    return 'Buenas tardes';
  }

  if (/\bdias?\b/.test(textoPlano)) {
    return 'Buenos días';
  }

  const horaEcuador =
    new Date(
      Date.now() + OFFSET_HORA_ECUADOR * 3600 * 1000
    ).getUTCHours();

  if (horaEcuador >= 5 && horaEcuador < 12) {
    return 'Buenos días';
  }

  if (horaEcuador >= 12 && horaEcuador < 19) {
    return 'Buenas tardes';
  }

  return 'Buenas noches';
}


function decisionBase() {
  return {
    intencion: 'OTRO',
    accion: 'RESPONDER_GENERAL',
    producto: null,
    material: null,
    cantidad: null,
    ancho_cm: null,
    alto_cm: null,
    forma: 'NO_ESPECIFICADA',
    ciudad_detectada: null,
    provincia_detectada: null,
    datos_suficientes_para_cotizar: false,
    requiere_humano: false,
    motivo_derivacion: 'NINGUNO',
    respuesta_sugerida: ''
  };
}


let reglaPreIA = null;

let decisionPreIA = null;

let productoNoP4Detectado = null;

let divisionDisenosDetectada = null;

const textoTurnoPlano =
  normalizarTexto(textoTurno);

if (
  mediaTurno.cantidad_media === 0 &&
  textoTurnoPlano !== ''
) {

  const tokens =
    textoTurnoPlano
      .split(' ')
      .map(t => t.replace(/(.)\1+/g, '$1'));

  const esSaludoSimple =
    tokens.length > 0 &&
    tokens.length <= 6 &&
    tokens.every(t => VOCABULARIO_SALUDO.has(t)) &&
    tokens.some(t => NUCLEO_SALUDO.has(t));

  const productoNoP4 =
    MENCIONA_ETIQUETA.test(textoTurnoPlano)
      ? null
      : PRODUCTOS_NO_P4.find(p => p.patron.test(textoTurnoPlano)) ?? null;

  if (esSaludoSimple) {
    reglaPreIA = 'SALUDO_SIMPLE';

    decisionPreIA = {
      ...decisionBase(),
      respuesta_sugerida:
        `${saludoHorario(textoTurnoPlano)} 🤗 ¿En qué podemos ayudarle?`
    };
  } else if (productoNoP4) {
    reglaPreIA = 'PRODUCTO_NO_P4';

    productoNoP4Detectado = productoNoP4.producto;

    decisionPreIA = {
      ...decisionBase(),
      intencion: 'SOLICITAR_COTIZACION',
      accion: 'DERIVAR_HUMANO',
      requiere_humano: true,
      motivo_derivacion: 'COTIZACION_ESPECIAL',
      respuesta_sugerida: RESPUESTA_TRANSICION_NO_P4
    };
  } else {
    divisionDisenosDetectada =
      detectarDivisionDisenos(textoTurno);

    if (divisionDisenosDetectada) {
      reglaPreIA = 'DIVISION_MINIMO_DISENOS';

      decisionPreIA = {
        ...decisionBase(),
        intencion: 'CONSULTAR_MINIMO',
        accion: 'INFORMAR_MINIMO',
        respuesta_sugerida:
          respuestaDivisionDisenos(divisionDisenosDetectada)
      };
    }
  }
}


// ======================================================
// 11. SALIDA
// ======================================================

return [
  {
    json: {

      // ==================================================
      // CONVERSACIÓN
      // ==================================================

      conversacion_id:
        numeroONull(
          actual.conversacion_id ??
          turno.conversacion_id
        ),

      conversacion_estado:
        textoONull(
          actual.conversacion_estado
        ),

      conversacion_nueva:
        booleano(
          actual.conversacion_nueva,
          false
        ),

      sesion_conversacional_nueva:
        sesionConversacionalNueva,

      ventana_historial_horas:
        VENTANA_HISTORIAL_HORAS,


      conversacion_cliente_id:
        numeroONull(
          actual.conversacion_cliente_id
        ),

      conversacion_contacto_id:
        numeroONull(
          actual.conversacion_contacto_id
        ),

      conversacion_prospecto_id:
        numeroONull(
          actual.conversacion_prospecto_id
        ),


      // ==================================================
      // CLIENTE / CONTACTO
      // ==================================================

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      contacto_nombre:
        textoONull(
          actual.contacto_nombre
        ),

      es_cliente_registrado:
        booleano(
          actual.es_cliente_registrado,
          false
        ),


      // ==================================================
      // PROSPECTO
      // ==================================================

      prospecto_existe:
        (
          prospectoId !== null ||
          booleano(
            actual.prospecto_existe,
            false
          )
        ),

      prospecto_id:
        prospectoId,

      prospecto_estado:
        prospectoEstado,

      prospecto_clasificacion:
        prospectoClasificacion,

      prospecto_nombre:
        textoONull(
          actual.prospecto_nombre
        ),

      prospecto_producto_interes:
        prospectoProductoInteres,

      prospecto_ciudad:
        prospectoCiudad,

      prospecto_provincia:
        prospectoProvincia,

      prospecto_diseno_estado:
        prospectoDisenoEstado,

      prospecto_ultima_intencion:
        prospectoUltimaIntencion,

      prospecto_ultima_accion:
        prospectoUltimaAccion,

      prospecto_requiere_humano:
        booleano(
          actual.prospecto_requiere_humano,
          false
        ),


      // ==================================================
      // ACTOR
      // ==================================================

      tipo_actor:
        tipoActor,


      // ==================================================
      // MENSAJE ACTUAL
      // ==================================================

      telefono:
        textoONull(
          actual.telefono ??
          turno.telefono
        ),

      nombre_whatsapp:
        textoONull(
          actual.nombre_whatsapp ??
          turno.nombre_whatsapp
        ),

      mensaje_actual:
        textoTurno,

      mensaje_disparador:
        (
          textoONull(
            actual.tipo
          ) ??
          'TEXTO'
        ).toUpperCase() ===
        'TEXTO'
          ? actual.mensaje ?? ''
          : quitarPendientes(
              actual.mensaje,
              actual.tipo,
              false
            ),

      turno_mensaje_ids:
        turnoMensajeIds,

      turno_desde_id:
        hayTurno
          ? numeroONull(
              turno.turno_desde_id
            )
          : null,

      turno_hasta_id:
        hayTurno
          ? numeroONull(
              turno.turno_hasta_id
            )
          : null,

      cantidad_mensajes_turno:
        hayTurno
          ? mensajesTurno.length
          : 1,

      turno_mensajes:
        mensajesTurno,

      tipo_mensaje:
        textoONull(
          actual.tipo
        ) ??
        (
          mensajesTurno.length === 1
            ? mensajesTurno[0].tipo
            : 'MULTIPLE'
        ),

      canal:
        textoONull(
          actual.canal
        ) ??
        'WHATSAPP',

      mensaje_externo_id:
        textoONull(
          actual.mensaje_externo_id
        ),

      recibido_at:
        actual.recibido_at ??
        null,


      // ==================================================
      // MEDIA DEL TURNO
      // ==================================================

      media_turno:
        mediaTurno,

      medidas_imagen_turno:
        medidasImagenTurno,

      medidas_detectadas_en_imagen:
        medidasImagenTurno.length > 0,


      // ==================================================
      // AUDIO
      // ==================================================

      transcripciones_audio:
        Array.isArray(
          turno.transcripciones_audio
        )
          ? turno.transcripciones_audio
          : [],

      audio_procesado:
        turno.audio_procesado === true,

      audio_listo_para_cerebro:
        turno.audio_listo_para_cerebro !== false,

      transcripciones_aplicadas:
        turno.transcripciones_aplicadas === true,


      // ==================================================
      // CONTEXTO COMERCIAL
      // ==================================================

      contexto_comercial:
        contextoComercial,


      // ==================================================
      // HISTORIAL RECIENTE
      // ==================================================

      historial,

      cantidad_mensajes_historial:
        historial.length,

      limite_mensajes_historial:
        MAX_MENSAJES_HISTORIAL,


      // ==================================================
      // CONTROL ANTI-REPETICIÓN
      // ==================================================

      ultimo_mensaje_saliente:
        ultimoMensajeSaliente,

      mensajes_salientes_recientes:
        mensajesSalientesRecientes,

      ultimo_saliente:
        ultimoSaliente,

      medidas_ya_solicitadas:
        medidasYaSolicitadas,


      // ==================================================
      // REGLAS PRE-IA
      // ==================================================

      regla_pre_ia:
        reglaPreIA,

      producto_no_p4:
        productoNoP4Detectado,

      division_disenos:
        divisionDisenosDetectada,

      requiere_cerebro_comercial:
        decisionPreIA === null,

      ...(
        decisionPreIA
          ? { decision: decisionPreIA }
          : {}
      )
    }
  }
];

// ======================================================
// VALIDAR EXTRACCIÓN CEREBRO COMERCIAL - V2.3
// ======================================================
// Valida:
// - contrato del Cerebro Comercial;
// - enums;
// - cotización P4;
// - continuidad conversacional;
// - medidas no producibles;
// - derivación humana;
// - clasificación A/B/C;
// - motivo de derivación;
// - notificación.
// ======================================================


// ======================================================
// 1. RECUPERAR Y NORMALIZAR RESPUESTA
// ======================================================

const item = $input.first().json;

let data =
  item.output ??
  item;

if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (error) {
    return [
      {
        json: {
          valid: false,
          validation_reason:
            'La IA devolvió texto pero no JSON válido.',
          raw:
            data
        }
      }
    ];
  }
}

if (
  data &&
  typeof data === 'object' &&
  data.output &&
  typeof data.output === 'object'
) {
  data = data.output;
}


// ======================================================
// 2. CATÁLOGOS
// ======================================================

const INTENCIONES = [
  'SOLICITAR_COTIZACION',
  'APORTAR_DATOS',
  'CONSULTAR_PRECIO',
  'CONSULTAR_MATERIAL',
  'CONSULTAR_MINIMO',
  'CONSULTAR_UBICACION',
  'CONSULTAR_METODOLOGIA',
  'CONSULTAR_ENTREGA',
  'CONSULTAR_DISENO',
  'ACEPTAR_COTIZACION',
  'CONSULTAR_PAGO',
  'REPORTAR_PAGO',
  'CONFIRMAR_PEDIDO',
  'SOLICITAR_LLAMADA',
  'SOLICITAR_HUMANO',
  'POSPONER_DECISION',
  'NEGOCIAR',
  'RECLAMO',
  'OTRO'
];

const ACCIONES = [
  'PEDIR_MEDIDAS',
  'PEDIR_PRODUCTO',
  'PEDIR_FORMA',
  'INFORMAR_MATERIAL',
  'INFORMAR_MINIMO',
  'INFORMAR_UBICACION',
  'INFORMAR_METODOLOGIA',
  'INFORMAR_METODOLOGIA_PAGO',
  'INFORMAR_ENTREGA',
  'INFORMAR_DISENO',
  'COTIZAR_P4',

  // ----------------------------------------------
  // NUEVO:
  // medida conocida pero técnicamente no producible
  // ----------------------------------------------
  'MEDIDA_NO_PRODUCIBLE',

  'REGISTRAR_ACEPTACION',
  'DERIVAR_HUMANO',
  'RESPONDER_GENERAL'
];

const FORMAS = [
  'RECTANGULAR',
  'CIRCULAR',
  'REDONDEADA',
  'TROQUELADA',
  'NO_ESPECIFICADA'
];

const MOTIVOS_DERIVACION = [
  'NINGUNO',
  'CONFIRMAR_PEDIDO',
  'SOLICITA_DATOS_PAGO',
  'REPORTA_PAGO',
  'ENVIA_COMPROBANTE',
  'SOLICITA_LLAMADA',
  'SOLICITA_HABLAR_CON_PERSONA',
  'ARCHIVO_DISENO',
  'IMAGEN_REQUIERE_REVISION',
  'ARCHIVO_NO_PROCESABLE',
  'DISENO_ESPECIAL',
  'NEGOCIACION',
  'RECLAMO',
  'PROBLEMA_PEDIDO',
  'PROBLEMA_PAGO',
  'PROBLEMA_ENTREGA',
  'OTRO'
];

const CLASIFICACIONES = [
  'A',
  'B',
  'C'
];

const CAMPOS_REQUERIDOS = [
  'intencion',
  'accion',
  'producto',
  'material',
  'cantidad',
  'ancho_cm',
  'alto_cm',
  'forma',
  'ciudad_detectada',
  'provincia_detectada',
  'datos_suficientes_para_cotizar',
  'requiere_humano',
  'motivo_derivacion',
  'requiere_notificacion',
  'clasificacion_prospecto',
  'respuesta_sugerida'
];


// ======================================================
// 3. HELPERS
// ======================================================

function numeroONull(valor) {
  return (
    valor === null ||
    (
      typeof valor === 'number' &&
      Number.isFinite(valor)
    )
  );
}

function textoONull(valor) {
  return (
    valor === null ||
    typeof valor === 'string'
  );
}

function invalido(reason) {
  return [
    {
      json: {
        ...(data && typeof data === 'object' ? data : {}),
        valid: false,
        validation_reason:
          reason
      }
    }
  ];
}


// ======================================================
// 4. ESTRUCTURA GENERAL
// ======================================================

if (
  !data ||
  typeof data !== 'object' ||
  Array.isArray(data)
) {
  return invalido(
    'La IA no devolvió un objeto válido.'
  );
}

for (const campo of CAMPOS_REQUERIDOS) {
  if (!(campo in data)) {
    return invalido(
      `Falta el campo obligatorio: ${campo}`
    );
  }
}


// ======================================================
// 5. ENUMS
// ======================================================

if (!INTENCIONES.includes(data.intencion)) {
  return invalido(
    `Intención inválida: ${data.intencion}`
  );
}

if (!ACCIONES.includes(data.accion)) {
  return invalido(
    `Acción inválida: ${data.accion}`
  );
}

if (!FORMAS.includes(data.forma)) {
  return invalido(
    `Forma inválida: ${data.forma}`
  );
}

if (
  !MOTIVOS_DERIVACION.includes(
    data.motivo_derivacion
  )
) {
  return invalido(
    `motivo_derivacion inválido: ${data.motivo_derivacion}`
  );
}

if (
  !CLASIFICACIONES.includes(
    data.clasificacion_prospecto
  )
) {
  return invalido(
    `clasificacion_prospecto inválida: ${data.clasificacion_prospecto}`
  );
}


// ======================================================
// 6. TIPOS
// ======================================================

if (
  typeof data.datos_suficientes_para_cotizar !== 'boolean'
) {
  return invalido(
    'datos_suficientes_para_cotizar debe ser boolean.'
  );
}

if (
  typeof data.requiere_humano !== 'boolean'
) {
  return invalido(
    'requiere_humano debe ser boolean.'
  );
}

if (
  typeof data.requiere_notificacion !== 'boolean'
) {
  return invalido(
    'requiere_notificacion debe ser boolean.'
  );
}

if (
  typeof data.respuesta_sugerida !== 'string'
) {
  return invalido(
    'respuesta_sugerida debe ser string.'
  );
}

for (
  const campo of [
    'producto',
    'material',
    'ciudad_detectada',
    'provincia_detectada'
  ]
) {
  if (!textoONull(data[campo])) {
    return invalido(
      `${campo} debe ser string o null.`
    );
  }
}

for (
  const campo of [
    'cantidad',
    'ancho_cm',
    'alto_cm'
  ]
) {
  if (!numeroONull(data[campo])) {
    return invalido(
      `${campo} debe ser número o null.`
    );
  }

  if (
    data[campo] !== null &&
    data[campo] <= 0
  ) {
    return invalido(
      `${campo} debe ser mayor que cero.`
    );
  }
}


// ======================================================
// 7. RESPUESTA SUGERIDA
// ======================================================
//
// COTIZAR_P4 es la única acción que puede llegar con
// respuesta vacía porque el nodo de cotización construye
// el mensaje final con el precio.
//
// TODAS las demás acciones deben mantener continuidad.
// ======================================================

if (
  data.accion !== 'COTIZAR_P4' &&
  data.respuesta_sugerida.trim() === ''
) {
  return invalido(
    `${data.accion} requiere respuesta_sugerida no vacía.`
  );
}


// ======================================================
// 7.1. CONTROL DE TONO
// ======================================================

if (
  data.respuesta_sugerida.includes('😊')
) {
  return invalido(
    'respuesta_sugerida no debe utilizar el emoji 😊.'
  );
}

if (
  /^(¡?Perfecto!?|Entendemos|Con gusto le explico)\b/i.test(
    data.respuesta_sugerida.trim()
  )
) {
  return invalido(
    'respuesta_sugerida inicia con una muletilla comercial no permitida.'
  );
}


// ======================================================
// 7.2. CONTROL ANTI-REPETICIÓN
// ======================================================

function normalizarParaComparar(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s¡!¿?.,;:*-]+|[\s¡!¿?.,;:*-]+$/g, '');
}

let ultimoMensajeSaliente = '';

try {
  ultimoMensajeSaliente =
    $('Preparar contexto IA')
      .first()
      .json
      .ultimo_mensaje_saliente ?? '';
} catch (_) {
  ultimoMensajeSaliente = '';
}

if (
  data.accion !== 'COTIZAR_P4' &&
  data.respuesta_sugerida.trim() !== '' &&
  ultimoMensajeSaliente
) {
  const actualNormalizado =
    normalizarParaComparar(
      data.respuesta_sugerida
    );

  const anteriorNormalizado =
    normalizarParaComparar(
      ultimoMensajeSaliente
    );

  if (
    actualNormalizado !== '' &&
    actualNormalizado === anteriorNormalizado
  ) {
    return invalido(
      'respuesta_sugerida repite exactamente el último mensaje saliente.'
    );
  }
}


// ======================================================
// 8. COTIZACIÓN P4
// ======================================================

if (
  data.accion === 'COTIZAR_P4'
) {

  if (
    data.cantidad === null
  ) {
    return invalido(
      'COTIZAR_P4 requiere cantidad. Si el cliente no indicó cantidad, debe usarse 1000.'
    );
  }

  if (
    data.ancho_cm === null ||
    data.alto_cm === null
  ) {
    return invalido(
      'COTIZAR_P4 requiere ancho_cm y alto_cm.'
    );
  }

  // ------------------------------------------------------
  // REGLA TÉCNICA DE PRODUCIBILIDAD
  // ------------------------------------------------------

  if (
    Number(data.ancho_cm) <= 1 ||
    Number(data.alto_cm) <= 1
  ) {
    return invalido(
      'COTIZAR_P4 no corresponde porque la medida contiene un lado de 1 cm o menos. Debe utilizar MEDIDA_NO_PRODUCIBLE.'
    );
  }

  if (
    data.datos_suficientes_para_cotizar !== true
  ) {
    return invalido(
      'COTIZAR_P4 requiere datos_suficientes_para_cotizar=true.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'COTIZAR_P4 no puede tener requiere_humano=true.'
    );
  }

  if (
    data.clasificacion_prospecto === 'C'
  ) {
    return invalido(
      'Un prospecto con datos suficientes para cotizar no debe clasificarse C.'
    );
  }
}


// ======================================================
// 9. PEDIR MEDIDAS
// ======================================================

if (
  data.accion === 'PEDIR_MEDIDAS'
) {

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_MEDIDAS no corresponde porque ya existen ancho_cm y alto_cm.'
    );
  }

  if (
    data.datos_suficientes_para_cotizar === true
  ) {
    return invalido(
      'PEDIR_MEDIDAS no puede tener datos_suficientes_para_cotizar=true.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'PEDIR_MEDIDAS no debe requerir atención humana.'
    );
  }
}


// ======================================================
// 9.1. MEDIDA NO PRODUCIBLE
// ======================================================
//
// Pegaso no produce etiquetas con un lado de
// 1 cm o menos.
//
// En este caso:
//
// - las medidas YA existen;
// - no corresponde PEDIR_MEDIDAS;
// - no corresponde COTIZAR_P4;
// - no corresponde DERIVAR_HUMANO;
// - el BOT debe explicar la restricción y solicitar
//   otra medida.
//
// ======================================================

if (
  data.accion === 'MEDIDA_NO_PRODUCIBLE'
) {

  // ------------------------------------------------------
  // DEBE CONOCERSE ANCHO Y ALTO
  // ------------------------------------------------------

  if (
    data.ancho_cm === null ||
    data.alto_cm === null
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere ancho_cm y alto_cm.'
    );
  }


  // ------------------------------------------------------
  // LA MEDIDA DEBE SER REALMENTE NO PRODUCIBLE
  // ------------------------------------------------------

  const medidaNoProducible =
    Number(data.ancho_cm) <= 1 ||
    Number(data.alto_cm) <= 1;

  if (
    !medidaNoProducible
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE solamente corresponde cuando ancho_cm o alto_cm es 1 cm o menos.'
    );
  }


  // ------------------------------------------------------
  // NO PUEDE PASAR A COTIZACIÓN
  // ------------------------------------------------------

  if (
    data.datos_suficientes_para_cotizar !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere datos_suficientes_para_cotizar=false.'
    );
  }


  // ------------------------------------------------------
  // NO NECESITA HUMANO
  // ------------------------------------------------------

  if (
    data.requiere_humano !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE no debe requerir atención humana.'
    );
  }


  // ------------------------------------------------------
  // SIN MOTIVO DE DERIVACIÓN
  // ------------------------------------------------------

  if (
    data.motivo_derivacion !== 'NINGUNO'
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE debe usar motivo_derivacion=NINGUNO.'
    );
  }


  // ------------------------------------------------------
  // SIN NOTIFICACIÓN INTERNA
  // ------------------------------------------------------

  if (
    data.requiere_notificacion !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE debe usar requiere_notificacion=false.'
    );
  }


  // ------------------------------------------------------
  // RESPUESTA OBLIGATORIA
  // ------------------------------------------------------

  if (
    typeof data.respuesta_sugerida !== 'string' ||
    data.respuesta_sugerida.trim() === ''
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere respuesta_sugerida no vacía.'
    );
  }


  // ------------------------------------------------------
  // INTENCIÓN PERMITIDA
  //
  // Normalmente será APORTAR_DATOS porque el cliente
  // acaba de proporcionar una nueva medida.
  //
  // También permitimos SOLICITAR_COTIZACION y
  // CONSULTAR_PRECIO porque puede llegar directamente
  // con la medida en el primer mensaje.
  // ------------------------------------------------------

  if (
    ![
      'APORTAR_DATOS',
      'SOLICITAR_COTIZACION',
      'CONSULTAR_PRECIO'
    ].includes(
      data.intencion
    )
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE solamente admite APORTAR_DATOS, SOLICITAR_COTIZACION o CONSULTAR_PRECIO.'
    );
  }
}


// ======================================================
// 10. CANTIDAD COMERCIAL POR DEFECTO
// ======================================================
//
// Si ya existen ancho_cm y alto_cm y el cliente no indicó
// cantidad, usamos 1000 como mínimo comercial.
//
// Esto también aplica a MEDIDA_NO_PRODUCIBLE porque
// conservamos el contexto comercial completo, aunque
// obviamente no se vaya a calcular precio.
//
// ======================================================

if (
  data.ancho_cm !== null &&
  data.alto_cm !== null &&
  data.cantidad === null
) {
  data.cantidad = 1000;
}

if (
  data.ancho_cm !== null &&
  data.alto_cm !== null &&
  data.accion === 'PEDIR_MEDIDAS'
) {
  return invalido(
    'PEDIR_MEDIDAS no corresponde porque ya existen ancho_cm y alto_cm.'
  );
}


// ======================================================
// 11. PEDIR PRODUCTO / FORMA
// ======================================================

if (
  data.accion === 'PEDIR_PRODUCTO'
) {

  if (
    data.producto !== null &&
    String(
      data.producto
    ).trim() !== ''
  ) {
    return invalido(
      'PEDIR_PRODUCTO no corresponde porque producto ya existe.'
    );
  }

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_PRODUCTO no corresponde para cotización P4 cuando ya existen medidas.'
    );
  }
}

if (
  data.accion === 'PEDIR_FORMA'
) {

  if (
    data.forma !== 'NO_ESPECIFICADA'
  ) {
    return invalido(
      'PEDIR_FORMA solamente corresponde cuando forma=NO_ESPECIFICADA.'
    );
  }

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_FORMA no corresponde cuando ya existen medidas suficientes.'
    );
  }
}


// ======================================================
// 12. ACCIONES INFORMATIVAS
// ======================================================

const REGLAS_INFORMATIVAS = {

  INFORMAR_MATERIAL:
    'CONSULTAR_MATERIAL',

  INFORMAR_MINIMO:
    'CONSULTAR_MINIMO',

  INFORMAR_UBICACION:
    'CONSULTAR_UBICACION',

  INFORMAR_METODOLOGIA:
    'CONSULTAR_METODOLOGIA',

  INFORMAR_METODOLOGIA_PAGO:
    'CONSULTAR_PAGO',

  INFORMAR_ENTREGA:
    'CONSULTAR_ENTREGA',

  INFORMAR_DISENO:
    'CONSULTAR_DISENO'
};

for (
  const [accion, intencion]
  of Object.entries(
    REGLAS_INFORMATIVAS
  )
) {

  if (
    data.accion === accion &&
    data.intencion !== intencion
  ) {
    return invalido(
      `${accion} requiere intencion=${intencion}.`
    );
  }

  if (
    data.accion === accion &&
    data.requiere_humano === true
  ) {
    return invalido(
      `${accion} no debe requerir atención humana.`
    );
  }
}


// ======================================================
// 13. ACEPTACIÓN SIMPLE
// ======================================================

if (
  data.accion === 'REGISTRAR_ACEPTACION'
) {

  if (
    data.intencion !== 'ACEPTAR_COTIZACION'
  ) {
    return invalido(
      'REGISTRAR_ACEPTACION requiere intencion=ACEPTAR_COTIZACION.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'REGISTRAR_ACEPTACION no debe requerir humano.'
    );
  }

  if (
    data.clasificacion_prospecto !== 'A'
  ) {
    return invalido(
      'ACEPTAR_COTIZACION debe clasificar al prospecto como A.'
    );
  }
}


// ======================================================
// 14. DERIVACIÓN HUMANA
// ======================================================

if (
  data.accion === 'DERIVAR_HUMANO'
) {

  if (
    data.requiere_humano !== true
  ) {
    return invalido(
      'DERIVAR_HUMANO debe tener requiere_humano=true.'
    );
  }

  if (
    data.motivo_derivacion === 'NINGUNO'
  ) {
    return invalido(
      'DERIVAR_HUMANO requiere un motivo_derivacion distinto de NINGUNO.'
    );
  }

  if (
    data.requiere_notificacion !== true
  ) {
    return invalido(
      'DERIVAR_HUMANO debe tener requiere_notificacion=true.'
    );
  }

  if (
    data.respuesta_sugerida.trim() === ''
  ) {
    return invalido(
      'DERIVAR_HUMANO debe enviar un mensaje de transición al prospecto.'
    );
  }
}


// ======================================================
// 15. NO DERIVACIÓN
// ======================================================

if (
  data.requiere_humano === false
) {

  if (
    data.accion === 'DERIVAR_HUMANO'
  ) {
    return invalido(
      'DERIVAR_HUMANO requiere requiere_humano=true.'
    );
  }

  if (
    data.motivo_derivacion !== 'NINGUNO'
  ) {
    return invalido(
      'Si no requiere humano, motivo_derivacion debe ser NINGUNO.'
    );
  }

  if (
    data.requiere_notificacion !== false
  ) {
    return invalido(
      'Si no requiere humano, requiere_notificacion debe ser false.'
    );
  }
}


// ======================================================
// 16. INTENCIONES HUMANAS OBLIGATORIAS
// ======================================================

const INTENCIONES_HUMANAS = [
  'REPORTAR_PAGO',
  'CONFIRMAR_PEDIDO',
  'SOLICITAR_LLAMADA',
  'SOLICITAR_HUMANO',
  'NEGOCIAR',
  'RECLAMO'
];

if (
  INTENCIONES_HUMANAS.includes(
    data.intencion
  ) &&
  data.accion !== 'DERIVAR_HUMANO'
) {
  return invalido(
    `${data.intencion} debe utilizar accion=DERIVAR_HUMANO.`
  );
}


// ======================================================
// 17. COHERENCIA MOTIVO / INTENCIÓN
// ======================================================

if (
  data.intencion === 'CONFIRMAR_PEDIDO' &&
  data.motivo_derivacion !== 'CONFIRMAR_PEDIDO'
) {
  return invalido(
    'CONFIRMAR_PEDIDO debe usar motivo_derivacion=CONFIRMAR_PEDIDO.'
  );
}

if (
  data.intencion === 'SOLICITAR_LLAMADA' &&
  data.motivo_derivacion !== 'SOLICITA_LLAMADA'
) {
  return invalido(
    'SOLICITAR_LLAMADA debe usar motivo_derivacion=SOLICITA_LLAMADA.'
  );
}

if (
  data.intencion === 'SOLICITAR_HUMANO' &&
  data.motivo_derivacion !== 'SOLICITA_HABLAR_CON_PERSONA'
) {
  return invalido(
    'SOLICITAR_HUMANO debe usar motivo_derivacion=SOLICITA_HABLAR_CON_PERSONA.'
  );
}

if (
  data.intencion === 'NEGOCIAR' &&
  data.motivo_derivacion !== 'NEGOCIACION'
) {
  return invalido(
    'NEGOCIAR debe usar motivo_derivacion=NEGOCIACION.'
  );
}

if (
  data.intencion === 'REPORTAR_PAGO' &&
  ![
    'REPORTA_PAGO',
    'ENVIA_COMPROBANTE'
  ].includes(
    data.motivo_derivacion
  )
) {
  return invalido(
    'REPORTAR_PAGO debe usar motivo REPORTA_PAGO o ENVIA_COMPROBANTE.'
  );
}


// ======================================================
// 18. CONSULTA DE PAGO: DOS CASOS
// ======================================================
//
// A) Metodología:
//    INFORMAR_METODOLOGIA_PAGO
//
// B) Cuenta/datos concretos:
//    DERIVAR_HUMANO + SOLICITA_DATOS_PAGO
//
// ======================================================

if (
  data.intencion === 'CONSULTAR_PAGO'
) {

  if (
    ![
      'INFORMAR_METODOLOGIA_PAGO',
      'DERIVAR_HUMANO'
    ].includes(
      data.accion
    )
  ) {
    return invalido(
      'CONSULTAR_PAGO solamente puede usar INFORMAR_METODOLOGIA_PAGO o DERIVAR_HUMANO.'
    );
  }

  if (
    data.accion === 'DERIVAR_HUMANO' &&
    data.motivo_derivacion !== 'SOLICITA_DATOS_PAGO'
  ) {
    return invalido(
      'Una consulta de pago derivada a humano debe usar motivo_derivacion=SOLICITA_DATOS_PAGO.'
    );
  }

  if (
    data.accion === 'DERIVAR_HUMANO' &&
    data.clasificacion_prospecto !== 'A'
  ) {
    return invalido(
      'Un prospecto que solicita datos concretos para pagar debe clasificarse A.'
    );
  }
}


// ======================================================
// 19. POSPONER DECISIÓN
// ======================================================

if (
  data.intencion === 'POSPONER_DECISION'
) {

  if (
    data.accion !== 'RESPONDER_GENERAL'
  ) {
    return invalido(
      'POSPONER_DECISION debe usar RESPONDER_GENERAL.'
    );
  }

  if (
    data.requiere_humano !== false
  ) {
    return invalido(
      'POSPONER_DECISION no debe derivar a humano.'
    );
  }
}


// ======================================================
// 20. RESPONDER GENERAL
// ======================================================

if (
  data.accion === 'RESPONDER_GENERAL' &&
  ![
    'OTRO',
    'APORTAR_DATOS',
    'POSPONER_DECISION'
  ].includes(
    data.intencion
  )
) {
  return invalido(
    'RESPONDER_GENERAL solo admite OTRO, APORTAR_DATOS o POSPONER_DECISION.'
  );
}


// ======================================================
// 21. CLASIFICACIÓN MÍNIMA
// ======================================================

const CASOS_A_OBLIGATORIOS =
  data.intencion === 'ACEPTAR_COTIZACION' ||
  data.intencion === 'CONFIRMAR_PEDIDO' ||
  data.intencion === 'REPORTAR_PAGO' ||
  data.motivo_derivacion === 'SOLICITA_DATOS_PAGO' ||
  data.motivo_derivacion === 'ENVIA_COMPROBANTE';

if (
  CASOS_A_OBLIGATORIOS &&
  data.clasificacion_prospecto !== 'A'
) {
  return invalido(
    'Este caso debe clasificar al prospecto como A.'
  );
}


// ======================================================
// 22. SALIDA
// ======================================================

return [
  {
    json: {
      ...data,

      valid:
        true,

      validation_reason:
        null
    }
  }
];

// ======================================================
// VALIDAR EXTRACCIÓN CEREBRO COMERCIAL - V2.3
// ======================================================
// Valida:
// - contrato del Cerebro Comercial;
// - enums;
// - cotización P4;
// - continuidad conversacional;
// - medidas no producibles;
// - derivación humana;
// - clasificación A/B/C;
// - motivo de derivación;
// - notificación.
// ======================================================


// ======================================================
// 1. RECUPERAR Y NORMALIZAR RESPUESTA
// ======================================================

const item = $input.first().json;

let data =
  item.output ??
  item;

if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (error) {
    return [
      {
        json: {
          valid: false,
          validation_reason:
            'La IA devolvió texto pero no JSON válido.',
          raw:
            data
        }
      }
    ];
  }
}

if (
  data &&
  typeof data === 'object' &&
  data.output &&
  typeof data.output === 'object'
) {
  data = data.output;
}


// ======================================================
// 2. CATÁLOGOS
// ======================================================

const INTENCIONES = [
  'SOLICITAR_COTIZACION',
  'APORTAR_DATOS',
  'CONSULTAR_PRECIO',
  'CONSULTAR_MATERIAL',
  'CONSULTAR_MINIMO',
  'CONSULTAR_UBICACION',
  'CONSULTAR_METODOLOGIA',
  'CONSULTAR_ENTREGA',
  'CONSULTAR_DISENO',
  'ACEPTAR_COTIZACION',
  'CONSULTAR_PAGO',
  'REPORTAR_PAGO',
  'CONFIRMAR_PEDIDO',
  'SOLICITAR_LLAMADA',
  'SOLICITAR_HUMANO',
  'POSPONER_DECISION',
  'NEGOCIAR',
  'RECLAMO',
  'OTRO'
];

const ACCIONES = [
  'PEDIR_MEDIDAS',
  'PEDIR_PRODUCTO',
  'PEDIR_FORMA',
  'INFORMAR_MATERIAL',
  'INFORMAR_MINIMO',
  'INFORMAR_UBICACION',
  'INFORMAR_METODOLOGIA',
  'INFORMAR_METODOLOGIA_PAGO',
  'INFORMAR_ENTREGA',
  'INFORMAR_DISENO',
  'COTIZAR_P4',

  // ----------------------------------------------
  // NUEVO:
  // medida conocida pero técnicamente no producible
  // ----------------------------------------------
  'MEDIDA_NO_PRODUCIBLE',

  'REGISTRAR_ACEPTACION',
  'DERIVAR_HUMANO',
  'RESPONDER_GENERAL'
];

const FORMAS = [
  'RECTANGULAR',
  'CIRCULAR',
  'REDONDEADA',
  'TROQUELADA',
  'NO_ESPECIFICADA'
];

const MOTIVOS_DERIVACION = [
  'NINGUNO',
  'CONFIRMAR_PEDIDO',
  'SOLICITA_DATOS_PAGO',
  'REPORTA_PAGO',
  'ENVIA_COMPROBANTE',
  'SOLICITA_LLAMADA',
  'SOLICITA_HABLAR_CON_PERSONA',
  'ARCHIVO_DISENO',
  'IMAGEN_REQUIERE_REVISION',
  'ARCHIVO_NO_PROCESABLE',
  'DISENO_ESPECIAL',
  'NEGOCIACION',
  'RECLAMO',
  'PROBLEMA_PEDIDO',
  'PROBLEMA_PAGO',
  'PROBLEMA_ENTREGA',
  'OTRO'
];

const CLASIFICACIONES = [
  'A',
  'B',
  'C'
];

const CAMPOS_REQUERIDOS = [
  'intencion',
  'accion',
  'producto',
  'material',
  'cantidad',
  'ancho_cm',
  'alto_cm',
  'forma',
  'ciudad_detectada',
  'provincia_detectada',
  'datos_suficientes_para_cotizar',
  'requiere_humano',
  'motivo_derivacion',
  'requiere_notificacion',
  'clasificacion_prospecto',
  'respuesta_sugerida'
];


// ======================================================
// 3. HELPERS
// ======================================================

function numeroONull(valor) {
  return (
    valor === null ||
    (
      typeof valor === 'number' &&
      Number.isFinite(valor)
    )
  );
}

function textoONull(valor) {
  return (
    valor === null ||
    typeof valor === 'string'
  );
}

function invalido(reason) {
  return [
    {
      json: {
        ...(data && typeof data === 'object' ? data : {}),
        valid: false,
        validation_reason:
          reason
      }
    }
  ];
}


// ======================================================
// 4. ESTRUCTURA GENERAL
// ======================================================

if (
  !data ||
  typeof data !== 'object' ||
  Array.isArray(data)
) {
  return invalido(
    'La IA no devolvió un objeto válido.'
  );
}

for (const campo of CAMPOS_REQUERIDOS) {
  if (!(campo in data)) {
    return invalido(
      `Falta el campo obligatorio: ${campo}`
    );
  }
}


// ======================================================
// 5. ENUMS
// ======================================================

if (!INTENCIONES.includes(data.intencion)) {
  return invalido(
    `Intención inválida: ${data.intencion}`
  );
}

if (!ACCIONES.includes(data.accion)) {
  return invalido(
    `Acción inválida: ${data.accion}`
  );
}

if (!FORMAS.includes(data.forma)) {
  return invalido(
    `Forma inválida: ${data.forma}`
  );
}

if (
  !MOTIVOS_DERIVACION.includes(
    data.motivo_derivacion
  )
) {
  return invalido(
    `motivo_derivacion inválido: ${data.motivo_derivacion}`
  );
}

if (
  !CLASIFICACIONES.includes(
    data.clasificacion_prospecto
  )
) {
  return invalido(
    `clasificacion_prospecto inválida: ${data.clasificacion_prospecto}`
  );
}


// ======================================================
// 6. TIPOS
// ======================================================

if (
  typeof data.datos_suficientes_para_cotizar !== 'boolean'
) {
  return invalido(
    'datos_suficientes_para_cotizar debe ser boolean.'
  );
}

if (
  typeof data.requiere_humano !== 'boolean'
) {
  return invalido(
    'requiere_humano debe ser boolean.'
  );
}

if (
  typeof data.requiere_notificacion !== 'boolean'
) {
  return invalido(
    'requiere_notificacion debe ser boolean.'
  );
}

if (
  typeof data.respuesta_sugerida !== 'string'
) {
  return invalido(
    'respuesta_sugerida debe ser string.'
  );
}

for (
  const campo of [
    'producto',
    'material',
    'ciudad_detectada',
    'provincia_detectada'
  ]
) {
  if (!textoONull(data[campo])) {
    return invalido(
      `${campo} debe ser string o null.`
    );
  }
}

for (
  const campo of [
    'cantidad',
    'ancho_cm',
    'alto_cm'
  ]
) {
  if (!numeroONull(data[campo])) {
    return invalido(
      `${campo} debe ser número o null.`
    );
  }

  if (
    data[campo] !== null &&
    data[campo] <= 0
  ) {
    return invalido(
      `${campo} debe ser mayor que cero.`
    );
  }
}


// ======================================================
// 7. RESPUESTA SUGERIDA
// ======================================================
//
// COTIZAR_P4 es la única acción que puede llegar con
// respuesta vacía porque el nodo de cotización construye
// el mensaje final con el precio.
//
// TODAS las demás acciones deben mantener continuidad.
// ======================================================

if (
  data.accion !== 'COTIZAR_P4' &&
  data.respuesta_sugerida.trim() === ''
) {
  return invalido(
    `${data.accion} requiere respuesta_sugerida no vacía.`
  );
}


// ======================================================
// 7.1. CONTROL DE TONO
// ======================================================

if (
  data.respuesta_sugerida.includes('😊')
) {
  return invalido(
    'respuesta_sugerida no debe utilizar el emoji 😊.'
  );
}

if (
  /^(¡?Perfecto!?|Entendemos|Con gusto le explico)\b/i.test(
    data.respuesta_sugerida.trim()
  )
) {
  return invalido(
    'respuesta_sugerida inicia con una muletilla comercial no permitida.'
  );
}


// ======================================================
// 7.2. CONTROL ANTI-REPETICIÓN
// ======================================================

function normalizarParaComparar(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s¡!¿?.,;:*-]+|[\s¡!¿?.,;:*-]+$/g, '');
}

let ultimoMensajeSaliente = '';

try {
  ultimoMensajeSaliente =
    $('Preparar contexto IA')
      .first()
      .json
      .ultimo_mensaje_saliente ?? '';
} catch (_) {
  ultimoMensajeSaliente = '';
}

if (
  data.accion !== 'COTIZAR_P4' &&
  data.respuesta_sugerida.trim() !== '' &&
  ultimoMensajeSaliente
) {
  const actualNormalizado =
    normalizarParaComparar(
      data.respuesta_sugerida
    );

  const anteriorNormalizado =
    normalizarParaComparar(
      ultimoMensajeSaliente
    );

  if (
    actualNormalizado !== '' &&
    actualNormalizado === anteriorNormalizado
  ) {
    return invalido(
      'respuesta_sugerida repite exactamente el último mensaje saliente.'
    );
  }
}


// ======================================================
// 8. COTIZACIÓN P4
// ======================================================

if (
  data.accion === 'COTIZAR_P4'
) {

  if (
    data.cantidad === null
  ) {
    return invalido(
      'COTIZAR_P4 requiere cantidad. Si el cliente no indicó cantidad, debe usarse 1000.'
    );
  }

  if (
    data.ancho_cm === null ||
    data.alto_cm === null
  ) {
    return invalido(
      'COTIZAR_P4 requiere ancho_cm y alto_cm.'
    );
  }

  // ------------------------------------------------------
  // REGLA TÉCNICA DE PRODUCIBILIDAD
  // ------------------------------------------------------

  if (
    Number(data.ancho_cm) <= 1 ||
    Number(data.alto_cm) <= 1
  ) {
    return invalido(
      'COTIZAR_P4 no corresponde porque la medida contiene un lado de 1 cm o menos. Debe utilizar MEDIDA_NO_PRODUCIBLE.'
    );
  }

  if (
    data.datos_suficientes_para_cotizar !== true
  ) {
    return invalido(
      'COTIZAR_P4 requiere datos_suficientes_para_cotizar=true.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'COTIZAR_P4 no puede tener requiere_humano=true.'
    );
  }

  if (
    data.clasificacion_prospecto === 'C'
  ) {
    return invalido(
      'Un prospecto con datos suficientes para cotizar no debe clasificarse C.'
    );
  }
}


// ======================================================
// 9. PEDIR MEDIDAS
// ======================================================

if (
  data.accion === 'PEDIR_MEDIDAS'
) {

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_MEDIDAS no corresponde porque ya existen ancho_cm y alto_cm.'
    );
  }

  if (
    data.datos_suficientes_para_cotizar === true
  ) {
    return invalido(
      'PEDIR_MEDIDAS no puede tener datos_suficientes_para_cotizar=true.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'PEDIR_MEDIDAS no debe requerir atención humana.'
    );
  }
}


// ======================================================
// 9.1. MEDIDA NO PRODUCIBLE
// ======================================================
//
// Pegaso no produce etiquetas con un lado de
// 1 cm o menos.
//
// En este caso:
//
// - las medidas YA existen;
// - no corresponde PEDIR_MEDIDAS;
// - no corresponde COTIZAR_P4;
// - no corresponde DERIVAR_HUMANO;
// - el BOT debe explicar la restricción y solicitar
//   otra medida.
//
// ======================================================

if (
  data.accion === 'MEDIDA_NO_PRODUCIBLE'
) {

  // ------------------------------------------------------
  // DEBE CONOCERSE ANCHO Y ALTO
  // ------------------------------------------------------

  if (
    data.ancho_cm === null ||
    data.alto_cm === null
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere ancho_cm y alto_cm.'
    );
  }


  // ------------------------------------------------------
  // LA MEDIDA DEBE SER REALMENTE NO PRODUCIBLE
  // ------------------------------------------------------

  const medidaNoProducible =
    Number(data.ancho_cm) <= 1 ||
    Number(data.alto_cm) <= 1;

  if (
    !medidaNoProducible
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE solamente corresponde cuando ancho_cm o alto_cm es 1 cm o menos.'
    );
  }


  // ------------------------------------------------------
  // NO PUEDE PASAR A COTIZACIÓN
  // ------------------------------------------------------

  if (
    data.datos_suficientes_para_cotizar !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere datos_suficientes_para_cotizar=false.'
    );
  }


  // ------------------------------------------------------
  // NO NECESITA HUMANO
  // ------------------------------------------------------

  if (
    data.requiere_humano !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE no debe requerir atención humana.'
    );
  }


  // ------------------------------------------------------
  // SIN MOTIVO DE DERIVACIÓN
  // ------------------------------------------------------

  if (
    data.motivo_derivacion !== 'NINGUNO'
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE debe usar motivo_derivacion=NINGUNO.'
    );
  }


  // ------------------------------------------------------
  // SIN NOTIFICACIÓN INTERNA
  // ------------------------------------------------------

  if (
    data.requiere_notificacion !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE debe usar requiere_notificacion=false.'
    );
  }


  // ------------------------------------------------------
  // RESPUESTA OBLIGATORIA
  // ------------------------------------------------------

  if (
    typeof data.respuesta_sugerida !== 'string' ||
    data.respuesta_sugerida.trim() === ''
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere respuesta_sugerida no vacía.'
    );
  }


  // ------------------------------------------------------
  // INTENCIÓN PERMITIDA
  //
  // Normalmente será APORTAR_DATOS porque el cliente
  // acaba de proporcionar una nueva medida.
  //
  // También permitimos SOLICITAR_COTIZACION y
  // CONSULTAR_PRECIO porque puede llegar directamente
  // con la medida en el primer mensaje.
  // ------------------------------------------------------

  if (
    ![
      'APORTAR_DATOS',
      'SOLICITAR_COTIZACION',
      'CONSULTAR_PRECIO'
    ].includes(
      data.intencion
    )
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE solamente admite APORTAR_DATOS, SOLICITAR_COTIZACION o CONSULTAR_PRECIO.'
    );
  }
}


// ======================================================
// 10. CANTIDAD COMERCIAL POR DEFECTO
// ======================================================
//
// Si ya existen ancho_cm y alto_cm y el cliente no indicó
// cantidad, usamos 1000 como mínimo comercial.
//
// Esto también aplica a MEDIDA_NO_PRODUCIBLE porque
// conservamos el contexto comercial completo, aunque
// obviamente no se vaya a calcular precio.
//
// ======================================================

if (
  data.ancho_cm !== null &&
  data.alto_cm !== null &&
  data.cantidad === null
) {
  data.cantidad = 1000;
}

if (
  data.ancho_cm !== null &&
  data.alto_cm !== null &&
  data.accion === 'PEDIR_MEDIDAS'
) {
  return invalido(
    'PEDIR_MEDIDAS no corresponde porque ya existen ancho_cm y alto_cm.'
  );
}


// ======================================================
// 11. PEDIR PRODUCTO / FORMA
// ======================================================

if (
  data.accion === 'PEDIR_PRODUCTO'
) {

  if (
    data.producto !== null &&
    String(
      data.producto
    ).trim() !== ''
  ) {
    return invalido(
      'PEDIR_PRODUCTO no corresponde porque producto ya existe.'
    );
  }

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_PRODUCTO no corresponde para cotización P4 cuando ya existen medidas.'
    );
  }
}

if (
  data.accion === 'PEDIR_FORMA'
) {

  if (
    data.forma !== 'NO_ESPECIFICADA'
  ) {
    return invalido(
      'PEDIR_FORMA solamente corresponde cuando forma=NO_ESPECIFICADA.'
    );
  }

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_FORMA no corresponde cuando ya existen medidas suficientes.'
    );
  }
}


// ======================================================
// 12. ACCIONES INFORMATIVAS
// ======================================================

const REGLAS_INFORMATIVAS = {

  INFORMAR_MATERIAL:
    'CONSULTAR_MATERIAL',

  INFORMAR_MINIMO:
    'CONSULTAR_MINIMO',

  INFORMAR_UBICACION:
    'CONSULTAR_UBICACION',

  INFORMAR_METODOLOGIA:
    'CONSULTAR_METODOLOGIA',

  INFORMAR_METODOLOGIA_PAGO:
    'CONSULTAR_PAGO',

  INFORMAR_ENTREGA:
    'CONSULTAR_ENTREGA',

  INFORMAR_DISENO:
    'CONSULTAR_DISENO'
};

for (
  const [accion, intencion]
  of Object.entries(
    REGLAS_INFORMATIVAS
  )
) {

  if (
    data.accion === accion &&
    data.intencion !== intencion
  ) {
    return invalido(
      `${accion} requiere intencion=${intencion}.`
    );
  }

  if (
    data.accion === accion &&
    data.requiere_humano === true
  ) {
    return invalido(
      `${accion} no debe requerir atención humana.`
    );
  }
}


// ======================================================
// 13. ACEPTACIÓN SIMPLE
// ======================================================

if (
  data.accion === 'REGISTRAR_ACEPTACION'
) {

  if (
    data.intencion !== 'ACEPTAR_COTIZACION'
  ) {
    return invalido(
      'REGISTRAR_ACEPTACION requiere intencion=ACEPTAR_COTIZACION.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'REGISTRAR_ACEPTACION no debe requerir humano.'
    );
  }

  if (
    data.clasificacion_prospecto !== 'A'
  ) {
    return invalido(
      'ACEPTAR_COTIZACION debe clasificar al prospecto como A.'
    );
  }
}


// ======================================================
// 14. DERIVACIÓN HUMANA
// ======================================================

if (
  data.accion === 'DERIVAR_HUMANO'
) {

  if (
    data.requiere_humano !== true
  ) {
    return invalido(
      'DERIVAR_HUMANO debe tener requiere_humano=true.'
    );
  }

  if (
    data.motivo_derivacion === 'NINGUNO'
  ) {
    return invalido(
      'DERIVAR_HUMANO requiere un motivo_derivacion distinto de NINGUNO.'
    );
  }

  if (
    data.requiere_notificacion !== true
  ) {
    return invalido(
      'DERIVAR_HUMANO debe tener requiere_notificacion=true.'
    );
  }

  if (
    data.respuesta_sugerida.trim() === ''
  ) {
    return invalido(
      'DERIVAR_HUMANO debe enviar un mensaje de transición al prospecto.'
    );
  }
}


// ======================================================
// 15. NO DERIVACIÓN
// ======================================================

if (
  data.requiere_humano === false
) {

  if (
    data.accion === 'DERIVAR_HUMANO'
  ) {
    return invalido(
      'DERIVAR_HUMANO requiere requiere_humano=true.'
    );
  }

  if (
    data.motivo_derivacion !== 'NINGUNO'
  ) {
    return invalido(
      'Si no requiere humano, motivo_derivacion debe ser NINGUNO.'
    );
  }

  if (
    data.requiere_notificacion !== false
  ) {
    return invalido(
      'Si no requiere humano, requiere_notificacion debe ser false.'
    );
  }
}


// ======================================================
// 16. INTENCIONES HUMANAS OBLIGATORIAS
// ======================================================

const INTENCIONES_HUMANAS = [
  'REPORTAR_PAGO',
  'CONFIRMAR_PEDIDO',
  'SOLICITAR_LLAMADA',
  'SOLICITAR_HUMANO',
  'NEGOCIAR',
  'RECLAMO'
];

if (
  INTENCIONES_HUMANAS.includes(
    data.intencion
  ) &&
  data.accion !== 'DERIVAR_HUMANO'
) {
  return invalido(
    `${data.intencion} debe utilizar accion=DERIVAR_HUMANO.`
  );
}


// ======================================================
// 17. COHERENCIA MOTIVO / INTENCIÓN
// ======================================================

if (
  data.intencion === 'CONFIRMAR_PEDIDO' &&
  data.motivo_derivacion !== 'CONFIRMAR_PEDIDO'
) {
  return invalido(
    'CONFIRMAR_PEDIDO debe usar motivo_derivacion=CONFIRMAR_PEDIDO.'
  );
}

if (
  data.intencion === 'SOLICITAR_LLAMADA' &&
  data.motivo_derivacion !== 'SOLICITA_LLAMADA'
) {
  return invalido(
    'SOLICITAR_LLAMADA debe usar motivo_derivacion=SOLICITA_LLAMADA.'
  );
}

if (
  data.intencion === 'SOLICITAR_HUMANO' &&
  data.motivo_derivacion !== 'SOLICITA_HABLAR_CON_PERSONA'
) {
  return invalido(
    'SOLICITAR_HUMANO debe usar motivo_derivacion=SOLICITA_HABLAR_CON_PERSONA.'
  );
}

if (
  data.intencion === 'NEGOCIAR' &&
  data.motivo_derivacion !== 'NEGOCIACION'
) {
  return invalido(
    'NEGOCIAR debe usar motivo_derivacion=NEGOCIACION.'
  );
}

if (
  data.intencion === 'REPORTAR_PAGO' &&
  ![
    'REPORTA_PAGO',
    'ENVIA_COMPROBANTE'
  ].includes(
    data.motivo_derivacion
  )
) {
  return invalido(
    'REPORTAR_PAGO debe usar motivo REPORTA_PAGO o ENVIA_COMPROBANTE.'
  );
}


// ======================================================
// 18. CONSULTA DE PAGO: DOS CASOS
// ======================================================
//
// A) Metodología:
//    INFORMAR_METODOLOGIA_PAGO
//
// B) Cuenta/datos concretos:
//    DERIVAR_HUMANO + SOLICITA_DATOS_PAGO
//
// ======================================================

if (
  data.intencion === 'CONSULTAR_PAGO'
) {

  if (
    ![
      'INFORMAR_METODOLOGIA_PAGO',
      'DERIVAR_HUMANO'
    ].includes(
      data.accion
    )
  ) {
    return invalido(
      'CONSULTAR_PAGO solamente puede usar INFORMAR_METODOLOGIA_PAGO o DERIVAR_HUMANO.'
    );
  }

  if (
    data.accion === 'DERIVAR_HUMANO' &&
    data.motivo_derivacion !== 'SOLICITA_DATOS_PAGO'
  ) {
    return invalido(
      'Una consulta de pago derivada a humano debe usar motivo_derivacion=SOLICITA_DATOS_PAGO.'
    );
  }

  if (
    data.accion === 'DERIVAR_HUMANO' &&
    data.clasificacion_prospecto !== 'A'
  ) {
    return invalido(
      'Un prospecto que solicita datos concretos para pagar debe clasificarse A.'
    );
  }
}


// ======================================================
// 19. POSPONER DECISIÓN
// ======================================================

if (
  data.intencion === 'POSPONER_DECISION'
) {

  if (
    data.accion !== 'RESPONDER_GENERAL'
  ) {
    return invalido(
      'POSPONER_DECISION debe usar RESPONDER_GENERAL.'
    );
  }

  if (
    data.requiere_humano !== false
  ) {
    return invalido(
      'POSPONER_DECISION no debe derivar a humano.'
    );
  }
}


// ======================================================
// 20. RESPONDER GENERAL
// ======================================================

if (
  data.accion === 'RESPONDER_GENERAL' &&
  ![
    'OTRO',
    'APORTAR_DATOS',
    'POSPONER_DECISION'
  ].includes(
    data.intencion
  )
) {
  return invalido(
    'RESPONDER_GENERAL solo admite OTRO, APORTAR_DATOS o POSPONER_DECISION.'
  );
}


// ======================================================
// 21. CLASIFICACIÓN MÍNIMA
// ======================================================

const CASOS_A_OBLIGATORIOS =
  data.intencion === 'ACEPTAR_COTIZACION' ||
  data.intencion === 'CONFIRMAR_PEDIDO' ||
  data.intencion === 'REPORTAR_PAGO' ||
  data.motivo_derivacion === 'SOLICITA_DATOS_PAGO' ||
  data.motivo_derivacion === 'ENVIA_COMPROBANTE';

if (
  CASOS_A_OBLIGATORIOS &&
  data.clasificacion_prospecto !== 'A'
) {
  return invalido(
    'Este caso debe clasificar al prospecto como A.'
  );
}


// ======================================================
// 22. SALIDA
// ======================================================

return [
  {
    json: {
      ...data,

      valid:
        true,

      validation_reason:
        null
    }
  }
];

// ======================================================
// VALIDAR EXTRACCIÓN CEREBRO COMERCIAL - V2.3
// ======================================================
// Valida:
// - contrato del Cerebro Comercial;
// - enums;
// - cotización P4;
// - continuidad conversacional;
// - medidas no producibles;
// - derivación humana;
// - clasificación A/B/C;
// - motivo de derivación;
// - notificación.
// ======================================================


// ======================================================
// 1. RECUPERAR Y NORMALIZAR RESPUESTA
// ======================================================

const item = $input.first().json;

let data =
  item.output ??
  item;

if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (error) {
    return [
      {
        json: {
          valid: false,
          validation_reason:
            'La IA devolvió texto pero no JSON válido.',
          raw:
            data
        }
      }
    ];
  }
}

if (
  data &&
  typeof data === 'object' &&
  data.output &&
  typeof data.output === 'object'
) {
  data = data.output;
}


// ======================================================
// 2. CATÁLOGOS
// ======================================================

const INTENCIONES = [
  'SOLICITAR_COTIZACION',
  'APORTAR_DATOS',
  'CONSULTAR_PRECIO',
  'CONSULTAR_MATERIAL',
  'CONSULTAR_MINIMO',
  'CONSULTAR_UBICACION',
  'CONSULTAR_METODOLOGIA',
  'CONSULTAR_ENTREGA',
  'CONSULTAR_DISENO',
  'ACEPTAR_COTIZACION',
  'CONSULTAR_PAGO',
  'REPORTAR_PAGO',
  'CONFIRMAR_PEDIDO',
  'SOLICITAR_LLAMADA',
  'SOLICITAR_HUMANO',
  'POSPONER_DECISION',
  'NEGOCIAR',
  'RECLAMO',
  'OTRO'
];

const ACCIONES = [
  'PEDIR_MEDIDAS',
  'PEDIR_PRODUCTO',
  'PEDIR_FORMA',
  'INFORMAR_MATERIAL',
  'INFORMAR_MINIMO',
  'INFORMAR_UBICACION',
  'INFORMAR_METODOLOGIA',
  'INFORMAR_METODOLOGIA_PAGO',
  'INFORMAR_ENTREGA',
  'INFORMAR_DISENO',
  'COTIZAR_P4',

  // ----------------------------------------------
  // NUEVO:
  // medida conocida pero técnicamente no producible
  // ----------------------------------------------
  'MEDIDA_NO_PRODUCIBLE',

  'REGISTRAR_ACEPTACION',
  'DERIVAR_HUMANO',
  'RESPONDER_GENERAL'
];

const FORMAS = [
  'RECTANGULAR',
  'CIRCULAR',
  'REDONDEADA',
  'TROQUELADA',
  'NO_ESPECIFICADA'
];

const MOTIVOS_DERIVACION = [
  'NINGUNO',
  'CONFIRMAR_PEDIDO',
  'SOLICITA_DATOS_PAGO',
  'REPORTA_PAGO',
  'ENVIA_COMPROBANTE',
  'SOLICITA_LLAMADA',
  'SOLICITA_HABLAR_CON_PERSONA',
  'ARCHIVO_DISENO',
  'IMAGEN_REQUIERE_REVISION',
  'ARCHIVO_NO_PROCESABLE',
  'DISENO_ESPECIAL',
  'NEGOCIACION',
  'RECLAMO',
  'PROBLEMA_PEDIDO',
  'PROBLEMA_PAGO',
  'PROBLEMA_ENTREGA',
  'OTRO'
];

const CLASIFICACIONES = [
  'A',
  'B',
  'C'
];

const CAMPOS_REQUERIDOS = [
  'intencion',
  'accion',
  'producto',
  'material',
  'cantidad',
  'ancho_cm',
  'alto_cm',
  'forma',
  'ciudad_detectada',
  'provincia_detectada',
  'datos_suficientes_para_cotizar',
  'requiere_humano',
  'motivo_derivacion',
  'requiere_notificacion',
  'clasificacion_prospecto',
  'respuesta_sugerida'
];


// ======================================================
// 3. HELPERS
// ======================================================

function numeroONull(valor) {
  return (
    valor === null ||
    (
      typeof valor === 'number' &&
      Number.isFinite(valor)
    )
  );
}

function textoONull(valor) {
  return (
    valor === null ||
    typeof valor === 'string'
  );
}

function invalido(reason) {
  return [
    {
      json: {
        ...(data && typeof data === 'object' ? data : {}),
        valid: false,
        validation_reason:
          reason
      }
    }
  ];
}


// ======================================================
// 4. ESTRUCTURA GENERAL
// ======================================================

if (
  !data ||
  typeof data !== 'object' ||
  Array.isArray(data)
) {
  return invalido(
    'La IA no devolvió un objeto válido.'
  );
}

for (const campo of CAMPOS_REQUERIDOS) {
  if (!(campo in data)) {
    return invalido(
      `Falta el campo obligatorio: ${campo}`
    );
  }
}


// ======================================================
// 5. ENUMS
// ======================================================

if (!INTENCIONES.includes(data.intencion)) {
  return invalido(
    `Intención inválida: ${data.intencion}`
  );
}

if (!ACCIONES.includes(data.accion)) {
  return invalido(
    `Acción inválida: ${data.accion}`
  );
}

if (!FORMAS.includes(data.forma)) {
  return invalido(
    `Forma inválida: ${data.forma}`
  );
}

if (
  !MOTIVOS_DERIVACION.includes(
    data.motivo_derivacion
  )
) {
  return invalido(
    `motivo_derivacion inválido: ${data.motivo_derivacion}`
  );
}

if (
  !CLASIFICACIONES.includes(
    data.clasificacion_prospecto
  )
) {
  return invalido(
    `clasificacion_prospecto inválida: ${data.clasificacion_prospecto}`
  );
}


// ======================================================
// 6. TIPOS
// ======================================================

if (
  typeof data.datos_suficientes_para_cotizar !== 'boolean'
) {
  return invalido(
    'datos_suficientes_para_cotizar debe ser boolean.'
  );
}

if (
  typeof data.requiere_humano !== 'boolean'
) {
  return invalido(
    'requiere_humano debe ser boolean.'
  );
}

if (
  typeof data.requiere_notificacion !== 'boolean'
) {
  return invalido(
    'requiere_notificacion debe ser boolean.'
  );
}

if (
  typeof data.respuesta_sugerida !== 'string'
) {
  return invalido(
    'respuesta_sugerida debe ser string.'
  );
}

for (
  const campo of [
    'producto',
    'material',
    'ciudad_detectada',
    'provincia_detectada'
  ]
) {
  if (!textoONull(data[campo])) {
    return invalido(
      `${campo} debe ser string o null.`
    );
  }
}

for (
  const campo of [
    'cantidad',
    'ancho_cm',
    'alto_cm'
  ]
) {
  if (!numeroONull(data[campo])) {
    return invalido(
      `${campo} debe ser número o null.`
    );
  }

  if (
    data[campo] !== null &&
    data[campo] <= 0
  ) {
    return invalido(
      `${campo} debe ser mayor que cero.`
    );
  }
}


// ======================================================
// 7. RESPUESTA SUGERIDA
// ======================================================
//
// COTIZAR_P4 es la única acción que puede llegar con
// respuesta vacía porque el nodo de cotización construye
// el mensaje final con el precio.
//
// TODAS las demás acciones deben mantener continuidad.
// ======================================================

if (
  data.accion !== 'COTIZAR_P4' &&
  data.respuesta_sugerida.trim() === ''
) {
  return invalido(
    `${data.accion} requiere respuesta_sugerida no vacía.`
  );
}


// ======================================================
// 7.1. CONTROL DE TONO
// ======================================================

if (
  data.respuesta_sugerida.includes('😊')
) {
  return invalido(
    'respuesta_sugerida no debe utilizar el emoji 😊.'
  );
}

if (
  /^(¡?Perfecto!?|Entendemos|Con gusto le explico)\b/i.test(
    data.respuesta_sugerida.trim()
  )
) {
  return invalido(
    'respuesta_sugerida inicia con una muletilla comercial no permitida.'
  );
}


// ======================================================
// 7.2. CONTROL ANTI-REPETICIÓN
// ======================================================

function normalizarParaComparar(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s¡!¿?.,;:*-]+|[\s¡!¿?.,;:*-]+$/g, '');
}

let ultimoMensajeSaliente = '';

try {
  ultimoMensajeSaliente =
    $('Preparar contexto IA')
      .first()
      .json
      .ultimo_mensaje_saliente ?? '';
} catch (_) {
  ultimoMensajeSaliente = '';
}

if (
  data.accion !== 'COTIZAR_P4' &&
  data.respuesta_sugerida.trim() !== '' &&
  ultimoMensajeSaliente
) {
  const actualNormalizado =
    normalizarParaComparar(
      data.respuesta_sugerida
    );

  const anteriorNormalizado =
    normalizarParaComparar(
      ultimoMensajeSaliente
    );

  if (
    actualNormalizado !== '' &&
    actualNormalizado === anteriorNormalizado
  ) {
    return invalido(
      'respuesta_sugerida repite exactamente el último mensaje saliente.'
    );
  }
}


// ======================================================
// 8. COTIZACIÓN P4
// ======================================================

if (
  data.accion === 'COTIZAR_P4'
) {

  if (
    data.cantidad === null
  ) {
    return invalido(
      'COTIZAR_P4 requiere cantidad. Si el cliente no indicó cantidad, debe usarse 1000.'
    );
  }

  if (
    data.ancho_cm === null ||
    data.alto_cm === null
  ) {
    return invalido(
      'COTIZAR_P4 requiere ancho_cm y alto_cm.'
    );
  }

  // ------------------------------------------------------
  // REGLA TÉCNICA DE PRODUCIBILIDAD
  // ------------------------------------------------------

  if (
    Number(data.ancho_cm) <= 1 ||
    Number(data.alto_cm) <= 1
  ) {
    return invalido(
      'COTIZAR_P4 no corresponde porque la medida contiene un lado de 1 cm o menos. Debe utilizar MEDIDA_NO_PRODUCIBLE.'
    );
  }

  if (
    data.datos_suficientes_para_cotizar !== true
  ) {
    return invalido(
      'COTIZAR_P4 requiere datos_suficientes_para_cotizar=true.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'COTIZAR_P4 no puede tener requiere_humano=true.'
    );
  }

  if (
    data.clasificacion_prospecto === 'C'
  ) {
    return invalido(
      'Un prospecto con datos suficientes para cotizar no debe clasificarse C.'
    );
  }
}


// ======================================================
// 9. PEDIR MEDIDAS
// ======================================================

if (
  data.accion === 'PEDIR_MEDIDAS'
) {

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_MEDIDAS no corresponde porque ya existen ancho_cm y alto_cm.'
    );
  }

  if (
    data.datos_suficientes_para_cotizar === true
  ) {
    return invalido(
      'PEDIR_MEDIDAS no puede tener datos_suficientes_para_cotizar=true.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'PEDIR_MEDIDAS no debe requerir atención humana.'
    );
  }
}


// ======================================================
// 9.1. MEDIDA NO PRODUCIBLE
// ======================================================
//
// Pegaso no produce etiquetas con un lado de
// 1 cm o menos.
//
// En este caso:
//
// - las medidas YA existen;
// - no corresponde PEDIR_MEDIDAS;
// - no corresponde COTIZAR_P4;
// - no corresponde DERIVAR_HUMANO;
// - el BOT debe explicar la restricción y solicitar
//   otra medida.
//
// ======================================================

if (
  data.accion === 'MEDIDA_NO_PRODUCIBLE'
) {

  // ------------------------------------------------------
  // DEBE CONOCERSE ANCHO Y ALTO
  // ------------------------------------------------------

  if (
    data.ancho_cm === null ||
    data.alto_cm === null
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere ancho_cm y alto_cm.'
    );
  }


  // ------------------------------------------------------
  // LA MEDIDA DEBE SER REALMENTE NO PRODUCIBLE
  // ------------------------------------------------------

  const medidaNoProducible =
    Number(data.ancho_cm) <= 1 ||
    Number(data.alto_cm) <= 1;

  if (
    !medidaNoProducible
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE solamente corresponde cuando ancho_cm o alto_cm es 1 cm o menos.'
    );
  }


  // ------------------------------------------------------
  // NO PUEDE PASAR A COTIZACIÓN
  // ------------------------------------------------------

  if (
    data.datos_suficientes_para_cotizar !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere datos_suficientes_para_cotizar=false.'
    );
  }


  // ------------------------------------------------------
  // NO NECESITA HUMANO
  // ------------------------------------------------------

  if (
    data.requiere_humano !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE no debe requerir atención humana.'
    );
  }


  // ------------------------------------------------------
  // SIN MOTIVO DE DERIVACIÓN
  // ------------------------------------------------------

  if (
    data.motivo_derivacion !== 'NINGUNO'
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE debe usar motivo_derivacion=NINGUNO.'
    );
  }


  // ------------------------------------------------------
  // SIN NOTIFICACIÓN INTERNA
  // ------------------------------------------------------

  if (
    data.requiere_notificacion !== false
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE debe usar requiere_notificacion=false.'
    );
  }


  // ------------------------------------------------------
  // RESPUESTA OBLIGATORIA
  // ------------------------------------------------------

  if (
    typeof data.respuesta_sugerida !== 'string' ||
    data.respuesta_sugerida.trim() === ''
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE requiere respuesta_sugerida no vacía.'
    );
  }


  // ------------------------------------------------------
  // INTENCIÓN PERMITIDA
  //
  // Normalmente será APORTAR_DATOS porque el cliente
  // acaba de proporcionar una nueva medida.
  //
  // También permitimos SOLICITAR_COTIZACION y
  // CONSULTAR_PRECIO porque puede llegar directamente
  // con la medida en el primer mensaje.
  // ------------------------------------------------------

  if (
    ![
      'APORTAR_DATOS',
      'SOLICITAR_COTIZACION',
      'CONSULTAR_PRECIO'
    ].includes(
      data.intencion
    )
  ) {
    return invalido(
      'MEDIDA_NO_PRODUCIBLE solamente admite APORTAR_DATOS, SOLICITAR_COTIZACION o CONSULTAR_PRECIO.'
    );
  }
}


// ======================================================
// 10. CANTIDAD COMERCIAL POR DEFECTO
// ======================================================
//
// Si ya existen ancho_cm y alto_cm y el cliente no indicó
// cantidad, usamos 1000 como mínimo comercial.
//
// Esto también aplica a MEDIDA_NO_PRODUCIBLE porque
// conservamos el contexto comercial completo, aunque
// obviamente no se vaya a calcular precio.
//
// ======================================================

if (
  data.ancho_cm !== null &&
  data.alto_cm !== null &&
  data.cantidad === null
) {
  data.cantidad = 1000;
}

if (
  data.ancho_cm !== null &&
  data.alto_cm !== null &&
  data.accion === 'PEDIR_MEDIDAS'
) {
  return invalido(
    'PEDIR_MEDIDAS no corresponde porque ya existen ancho_cm y alto_cm.'
  );
}


// ======================================================
// 11. PEDIR PRODUCTO / FORMA
// ======================================================

if (
  data.accion === 'PEDIR_PRODUCTO'
) {

  if (
    data.producto !== null &&
    String(
      data.producto
    ).trim() !== ''
  ) {
    return invalido(
      'PEDIR_PRODUCTO no corresponde porque producto ya existe.'
    );
  }

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_PRODUCTO no corresponde para cotización P4 cuando ya existen medidas.'
    );
  }
}

if (
  data.accion === 'PEDIR_FORMA'
) {

  if (
    data.forma !== 'NO_ESPECIFICADA'
  ) {
    return invalido(
      'PEDIR_FORMA solamente corresponde cuando forma=NO_ESPECIFICADA.'
    );
  }

  if (
    data.ancho_cm !== null &&
    data.alto_cm !== null
  ) {
    return invalido(
      'PEDIR_FORMA no corresponde cuando ya existen medidas suficientes.'
    );
  }
}


// ======================================================
// 12. ACCIONES INFORMATIVAS
// ======================================================

const REGLAS_INFORMATIVAS = {

  INFORMAR_MATERIAL:
    'CONSULTAR_MATERIAL',

  INFORMAR_MINIMO:
    'CONSULTAR_MINIMO',

  INFORMAR_UBICACION:
    'CONSULTAR_UBICACION',

  INFORMAR_METODOLOGIA:
    'CONSULTAR_METODOLOGIA',

  INFORMAR_METODOLOGIA_PAGO:
    'CONSULTAR_PAGO',

  INFORMAR_ENTREGA:
    'CONSULTAR_ENTREGA',

  INFORMAR_DISENO:
    'CONSULTAR_DISENO'
};

for (
  const [accion, intencion]
  of Object.entries(
    REGLAS_INFORMATIVAS
  )
) {

  if (
    data.accion === accion &&
    data.intencion !== intencion
  ) {
    return invalido(
      `${accion} requiere intencion=${intencion}.`
    );
  }

  if (
    data.accion === accion &&
    data.requiere_humano === true
  ) {
    return invalido(
      `${accion} no debe requerir atención humana.`
    );
  }
}


// ======================================================
// 13. ACEPTACIÓN SIMPLE
// ======================================================

if (
  data.accion === 'REGISTRAR_ACEPTACION'
) {

  if (
    data.intencion !== 'ACEPTAR_COTIZACION'
  ) {
    return invalido(
      'REGISTRAR_ACEPTACION requiere intencion=ACEPTAR_COTIZACION.'
    );
  }

  if (
    data.requiere_humano === true
  ) {
    return invalido(
      'REGISTRAR_ACEPTACION no debe requerir humano.'
    );
  }

  if (
    data.clasificacion_prospecto !== 'A'
  ) {
    return invalido(
      'ACEPTAR_COTIZACION debe clasificar al prospecto como A.'
    );
  }
}


// ======================================================
// 14. DERIVACIÓN HUMANA
// ======================================================

if (
  data.accion === 'DERIVAR_HUMANO'
) {

  if (
    data.requiere_humano !== true
  ) {
    return invalido(
      'DERIVAR_HUMANO debe tener requiere_humano=true.'
    );
  }

  if (
    data.motivo_derivacion === 'NINGUNO'
  ) {
    return invalido(
      'DERIVAR_HUMANO requiere un motivo_derivacion distinto de NINGUNO.'
    );
  }

  if (
    data.requiere_notificacion !== true
  ) {
    return invalido(
      'DERIVAR_HUMANO debe tener requiere_notificacion=true.'
    );
  }

  if (
    data.respuesta_sugerida.trim() === ''
  ) {
    return invalido(
      'DERIVAR_HUMANO debe enviar un mensaje de transición al prospecto.'
    );
  }
}


// ======================================================
// 15. NO DERIVACIÓN
// ======================================================

if (
  data.requiere_humano === false
) {

  if (
    data.accion === 'DERIVAR_HUMANO'
  ) {
    return invalido(
      'DERIVAR_HUMANO requiere requiere_humano=true.'
    );
  }

  if (
    data.motivo_derivacion !== 'NINGUNO'
  ) {
    return invalido(
      'Si no requiere humano, motivo_derivacion debe ser NINGUNO.'
    );
  }

  if (
    data.requiere_notificacion !== false
  ) {
    return invalido(
      'Si no requiere humano, requiere_notificacion debe ser false.'
    );
  }
}


// ======================================================
// 16. INTENCIONES HUMANAS OBLIGATORIAS
// ======================================================

const INTENCIONES_HUMANAS = [
  'REPORTAR_PAGO',
  'CONFIRMAR_PEDIDO',
  'SOLICITAR_LLAMADA',
  'SOLICITAR_HUMANO',
  'NEGOCIAR',
  'RECLAMO'
];

if (
  INTENCIONES_HUMANAS.includes(
    data.intencion
  ) &&
  data.accion !== 'DERIVAR_HUMANO'
) {
  return invalido(
    `${data.intencion} debe utilizar accion=DERIVAR_HUMANO.`
  );
}


// ======================================================
// 17. COHERENCIA MOTIVO / INTENCIÓN
// ======================================================

if (
  data.intencion === 'CONFIRMAR_PEDIDO' &&
  data.motivo_derivacion !== 'CONFIRMAR_PEDIDO'
) {
  return invalido(
    'CONFIRMAR_PEDIDO debe usar motivo_derivacion=CONFIRMAR_PEDIDO.'
  );
}

if (
  data.intencion === 'SOLICITAR_LLAMADA' &&
  data.motivo_derivacion !== 'SOLICITA_LLAMADA'
) {
  return invalido(
    'SOLICITAR_LLAMADA debe usar motivo_derivacion=SOLICITA_LLAMADA.'
  );
}

if (
  data.intencion === 'SOLICITAR_HUMANO' &&
  data.motivo_derivacion !== 'SOLICITA_HABLAR_CON_PERSONA'
) {
  return invalido(
    'SOLICITAR_HUMANO debe usar motivo_derivacion=SOLICITA_HABLAR_CON_PERSONA.'
  );
}

if (
  data.intencion === 'NEGOCIAR' &&
  data.motivo_derivacion !== 'NEGOCIACION'
) {
  return invalido(
    'NEGOCIAR debe usar motivo_derivacion=NEGOCIACION.'
  );
}

if (
  data.intencion === 'REPORTAR_PAGO' &&
  ![
    'REPORTA_PAGO',
    'ENVIA_COMPROBANTE'
  ].includes(
    data.motivo_derivacion
  )
) {
  return invalido(
    'REPORTAR_PAGO debe usar motivo REPORTA_PAGO o ENVIA_COMPROBANTE.'
  );
}


// ======================================================
// 18. CONSULTA DE PAGO: DOS CASOS
// ======================================================
//
// A) Metodología:
//    INFORMAR_METODOLOGIA_PAGO
//
// B) Cuenta/datos concretos:
//    DERIVAR_HUMANO + SOLICITA_DATOS_PAGO
//
// ======================================================

if (
  data.intencion === 'CONSULTAR_PAGO'
) {

  if (
    ![
      'INFORMAR_METODOLOGIA_PAGO',
      'DERIVAR_HUMANO'
    ].includes(
      data.accion
    )
  ) {
    return invalido(
      'CONSULTAR_PAGO solamente puede usar INFORMAR_METODOLOGIA_PAGO o DERIVAR_HUMANO.'
    );
  }

  if (
    data.accion === 'DERIVAR_HUMANO' &&
    data.motivo_derivacion !== 'SOLICITA_DATOS_PAGO'
  ) {
    return invalido(
      'Una consulta de pago derivada a humano debe usar motivo_derivacion=SOLICITA_DATOS_PAGO.'
    );
  }

  if (
    data.accion === 'DERIVAR_HUMANO' &&
    data.clasificacion_prospecto !== 'A'
  ) {
    return invalido(
      'Un prospecto que solicita datos concretos para pagar debe clasificarse A.'
    );
  }
}


// ======================================================
// 19. POSPONER DECISIÓN
// ======================================================

if (
  data.intencion === 'POSPONER_DECISION'
) {

  if (
    data.accion !== 'RESPONDER_GENERAL'
  ) {
    return invalido(
      'POSPONER_DECISION debe usar RESPONDER_GENERAL.'
    );
  }

  if (
    data.requiere_humano !== false
  ) {
    return invalido(
      'POSPONER_DECISION no debe derivar a humano.'
    );
  }
}


// ======================================================
// 20. RESPONDER GENERAL
// ======================================================

if (
  data.accion === 'RESPONDER_GENERAL' &&
  ![
    'OTRO',
    'APORTAR_DATOS',
    'POSPONER_DECISION'
  ].includes(
    data.intencion
  )
) {
  return invalido(
    'RESPONDER_GENERAL solo admite OTRO, APORTAR_DATOS o POSPONER_DECISION.'
  );
}


// ======================================================
// 21. CLASIFICACIÓN MÍNIMA
// ======================================================

const CASOS_A_OBLIGATORIOS =
  data.intencion === 'ACEPTAR_COTIZACION' ||
  data.intencion === 'CONFIRMAR_PEDIDO' ||
  data.intencion === 'REPORTAR_PAGO' ||
  data.motivo_derivacion === 'SOLICITA_DATOS_PAGO' ||
  data.motivo_derivacion === 'ENVIA_COMPROBANTE';

if (
  CASOS_A_OBLIGATORIOS &&
  data.clasificacion_prospecto !== 'A'
) {
  return invalido(
    'Este caso debe clasificar al prospecto como A.'
  );
}


// ======================================================
// 22. SALIDA
// ======================================================

return [
  {
    json: {
      ...data,

      valid:
        true,

      validation_reason:
        null
    }
  }
];

return [
  {
    json: {
      valid: false,
      success: false,
      can_quote: false,
      status: 'AI_EXTRACTION_FAILED',
      error_code: 'ALL_AI_FAILED',
      message: 'No se pudo interpretar la solicitud. Los modelos de IA no pudieron extraer datos válidos.',
      details: [],
      cantidad_detalles: 0,
      source: 'NONE'
    }
  }
];

// ======================================================
// NODO N8N: Normalizar decisión IA
// ARCHIVO: code/04-cerebro-comercial/normalizar-decision-ia.js
// VERSION: 2.2
// RESPONSABILIDAD:
// - Convertir la decisión YA VALIDADA (de cualquier proveedor) en un contrato único Pegaso con tipos normalizados.
// - Unir la decisión con el contexto de "Preparar contexto IA" (IDs, prospecto, tipo_actor, contexto_comercial) y resolver ciudad/provincia.
// - Aplicar la evidencia multimedia del turno (media_turno): comprobante detectado -> REPORTAR_PAGO + DERIVAR_HUMANO + ENVIA_COMPROBANTE;
//   imagen/archivo que requiere revisión -> DERIVAR_HUMANO + IMAGEN_REQUIERE_REVISION / ARCHIVO_NO_PROCESABLE.
//   Si la IA ya derivó por otro motivo, se respeta (salvo comprobante frente a motivos no prioritarios).
// - Impedir degradar la clasificación A/B/C: máximo entre anterior, IA y mínimo por intención/motivo.
// - Calcular etiqueta_grande (lado corto > 10 o lado largo > 15 cm) y banderas de continuidad.
// - Forzar requiere_notificacion=requiere_humano y calcular prioridad_derivacion (ALTA/MEDIA/NORMAL).
// - Limpiar el tono de respuesta_sugerida (😊 y aperturas robóticas).
// - Lanzar error si hay medidas/cantidad <= 0 o requiere_humano sin DERIVAR_HUMANO.
// - NO decidir la acción final (lo hace "Resolver contexto comercial").
// - NO escribir en PostgreSQL.
// ======================================================

const input = $json;

const decision =
  input.output ??
  input.data ??
  input.resultado ??
  input.decision ??
  input;


// ======================================================
// 1. HELPERS
// ======================================================

function texto(valor, defecto = null) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return defecto;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : defecto;
}

function numero(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}

function booleano(valor, defecto = false) {
  if (typeof valor === 'boolean') {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return defecto;
}

function rankingClasificacion(valor) {
  const v =
    texto(valor, 'C').toUpperCase();

  if (v === 'A') return 3;
  if (v === 'B') return 2;
  return 1;
}

function clasificacionPorEstado(estado) {
  const v =
    texto(estado, '').toUpperCase();

  if (
    [
      'INTERESADO',
      'ACEPTADO',
      'PAGO_PENDIENTE',
      'ABONO_REPORTADO',
      'EN_PROCESO'
    ].includes(v)
  ) {
    return 'A';
  }

  if (
    [
      'COTIZADO',
      'CALIFICADO',
      'EN_SEGUIMIENTO',
      'CONTACTADO'
    ].includes(v)
  ) {
    return 'B';
  }

  return 'C';
}

function maxClasificacion(...valores) {
  let mejor = 'C';
  let mejorRank = 1;

  for (const valor of valores) {
    const v =
      texto(valor, 'C').toUpperCase();

    const rank =
      rankingClasificacion(v);

    if (rank > mejorRank) {
      mejor = v;
      mejorRank = rank;
    }
  }

  return mejor;
}


// ======================================================
// 2. DECISIÓN COMERCIAL
// ======================================================

let intencion =
  texto(
    decision.intencion,
    'OTRO'
  ).toUpperCase();

let accion =
  texto(
    decision.accion,
    'RESPONDER_GENERAL'
  ).toUpperCase();

let respuestaSugerida =
  texto(
    decision.respuesta_sugerida,
    ''
  );


// ======================================================
// 3. DATOS EXTRAÍDOS
// ======================================================

const producto =
  texto(decision.producto);

const material =
  texto(decision.material);

const cantidad =
  numero(decision.cantidad);

const anchoCm =
  numero(decision.ancho_cm);

const altoCm =
  numero(decision.alto_cm);

// ------------------------------------------------------
// TRAZABILIDAD DE MEDIDAS DEL MENSAJE ACTUAL
// ------------------------------------------------------
//
// No basta con conocer el valor resultante.
// Necesitamos saber si ancho/alto vinieron explícitamente
// de la decisión actual para que el nodo siguiente pueda
// tratar el par de medidas de forma ATÓMICA.
//
// Ejemplo:
// anterior: 7 x 12
// actual:   8 x 11
//
// Debe resultar 8 x 11, nunca 7 x 11 ni 8 x 12.
// ------------------------------------------------------

const anchoActualExplicito =
  Object.prototype.hasOwnProperty.call(
    decision,
    'ancho_cm'
  ) &&
  decision.ancho_cm !== null &&
  decision.ancho_cm !== '' &&
  anchoCm !== null;

const altoActualExplicito =
  Object.prototype.hasOwnProperty.call(
    decision,
    'alto_cm'
  ) &&
  decision.alto_cm !== null &&
  decision.alto_cm !== '' &&
  altoCm !== null;

const medidasActualesCompletas =
  anchoActualExplicito &&
  altoActualExplicito;

const medidasActualesParciales =
  (
    anchoActualExplicito ||
    altoActualExplicito
  ) &&
  !medidasActualesCompletas;

const forma =
  texto(
    decision.forma,
    'NO_ESPECIFICADA'
  ).toUpperCase();

const ciudadDetectada =
  texto(
    decision.ciudad_detectada
  );

const provinciaDetectada =
  texto(
    decision.provincia_detectada
  );


// ======================================================
// 4. CONTROL IA
// ======================================================

const datosSuficientes =
  booleano(
    decision.datos_suficientes_para_cotizar,
    false
  );

let requiereHumano =
  booleano(
    decision.requiere_humano,
    false
  );

let motivoDerivacion =
  texto(
    decision.motivo_derivacion,
    'NINGUNO'
  ).toUpperCase();


// ======================================================
// 4.0. EVIDENCIA MULTIMEDIA DEL TURNO
// ======================================================
//
// La IA visual solo aporta evidencia; aquí se fijan los dos
// casos que no pueden quedar a criterio del cerebro:
// - comprobante de pago: nunca se confirma, siempre va a humano;
// - imagen/archivo que el bot no pudo interpretar.
// ======================================================

let mediaTurno = {};

try {
  mediaTurno =
    $('Preparar contexto IA').first().json?.media_turno ?? {};
} catch (e) {
  mediaTurno = {};
}

const MOTIVOS_QUE_PREVALECEN_SOBRE_COMPROBANTE = [
  'REPORTA_PAGO',
  'ENVIA_COMPROBANTE',
  'RECLAMO',
  'PROBLEMA_PAGO',
  'PROBLEMA_PEDIDO',
  'PROBLEMA_ENTREGA'
];

let derivacionPorMedia = null;

if (
  mediaTurno.comprobante_detectado === true &&
  !MOTIVOS_QUE_PREVALECEN_SOBRE_COMPROBANTE.includes(motivoDerivacion)
) {
  derivacionPorMedia = 'COMPROBANTE_PAGO';
  intencion = 'REPORTAR_PAGO';
  accion = 'DERIVAR_HUMANO';
  requiereHumano = true;
  motivoDerivacion = 'ENVIA_COMPROBANTE';
  respuestaSugerida =
    'Muchas gracias. En breve verificamos la información para continuar con su pedido.';
} else if (
  mediaTurno.requiere_revision_humana === true &&
  requiereHumano !== true &&
  ['IMAGEN_REQUIERE_REVISION', 'ARCHIVO_NO_PROCESABLE'].includes(mediaTurno.motivo_derivacion)
) {
  derivacionPorMedia = 'REVISION_MEDIA';
  accion = 'DERIVAR_HUMANO';
  requiereHumano = true;
  motivoDerivacion = mediaTurno.motivo_derivacion;
  respuestaSugerida =
    motivoDerivacion === 'IMAGEN_REQUIERE_REVISION'
      ? 'Permítame un momento por favor, ya revisamos la imagen que nos envió.'
      : 'Permítame un momento por favor, ya revisamos el archivo que nos envió.';
}


// ======================================================
// 4.1. NORMALIZACIÓN DE TONO V2.1
// ======================================================
//
// Defensa adicional después de validar:
// - elimina 😊;
// - elimina aperturas robóticas si algún proveedor las deja;
// - no modifica mensajes de transición humana salvo el emoji.
// ======================================================

respuestaSugerida =
  respuestaSugerida
    .replace(/😊/g, '')
    .replace(/\s{2,}/g, ' ')
    .trim();

if (
  requiereHumano !== true
) {
  respuestaSugerida =
    respuestaSugerida
      .replace(/^¡?Perfecto!?\s*[,.!:-]*\s*/i, '')
      .replace(/^Entendemos\s*[,.!:-]*\s*/i, '')
      .replace(/^Con gusto le explico\s*[,.!:-]*\s*/i, '')
      .replace(/^Con mucho gusto\s*[,.!:-]*\s*/i, '')
      .trim();
}


// ======================================================
// 5. RECUPERAR CONTEXTO REAL
// ======================================================

let contexto = {};

try {
  contexto =
    $('Preparar contexto IA').first().json ?? {};
} catch (e) {
  contexto = {};
}


// ======================================================
// 6. IDS
// ======================================================

const conversacionId =
  numero(contexto.conversacion_id);

const clienteId =
  numero(contexto.cliente_id);

const contactoId =
  numero(contexto.contacto_id);

const prospectoId =
  numero(contexto.prospecto_id);


// ======================================================
// 7. PROSPECTO
// ======================================================

const prospectoExiste =
  prospectoId !== null ||
  booleano(
    contexto.prospecto_existe,
    false
  );

const prospectoEstado =
  texto(
    contexto.prospecto_estado
  );

const prospectoNombre =
  texto(
    contexto.prospecto_nombre
  );

const prospectoProductoInteres =
  texto(
    contexto.prospecto_producto_interes
  );

const prospectoCiudadAnterior =
  texto(
    contexto.prospecto_ciudad
  );

const prospectoProvinciaAnterior =
  texto(
    contexto.prospecto_provincia
  );

const prospectoCiudadResuelta =
  ciudadDetectada ??
  prospectoCiudadAnterior;

const prospectoProvinciaResuelta =
  provinciaDetectada ??
  prospectoProvinciaAnterior;

const prospectoUltimaIntencion =
  texto(
    contexto.prospecto_ultima_intencion
  );

const prospectoUltimaAccion =
  texto(
    contexto.prospecto_ultima_accion
  );

const prospectoRequiereHumano =
  booleano(
    contexto.prospecto_requiere_humano,
    false
  );


// ======================================================
// 8. TIPO DE ACTOR
// ======================================================

let tipoActor =
  texto(
    contexto.tipo_actor
  );

if (!tipoActor) {
  if (
    booleano(
      contexto.es_cliente_registrado,
      false
    ) ||
    clienteId !== null
  ) {
    tipoActor = 'CLIENTE';
  } else if (
    prospectoId !== null
  ) {
    tipoActor = 'PROSPECTO';
  } else if (
    contactoId !== null
  ) {
    tipoActor = 'CONTACTO';
  } else {
    tipoActor = 'DESCONOCIDO';
  }
}

tipoActor =
  tipoActor.toUpperCase();


// ======================================================
// 9. CLASIFICACIÓN A/B/C
// ======================================================
//
// Nunca degradamos:
// A -> B/C NO
// B -> C   NO
//
// La IA propone, pero estas reglas fijan un mínimo.
// ======================================================

const clasificacionAnterior =
  texto(
    contexto.prospecto_clasificacion
  )?.toUpperCase() ??
  clasificacionPorEstado(
    prospectoEstado
  );

let clasificacionMinima =
  'C';

if (
  accion === 'COTIZAR_P4' ||
  [
    'CONSULTAR_PRECIO',
    'CONSULTAR_MATERIAL',
    'CONSULTAR_MINIMO',
    'CONSULTAR_UBICACION',
    'CONSULTAR_METODOLOGIA',
    'CONSULTAR_ENTREGA',
    'CONSULTAR_DISENO',
    'CONSULTAR_PAGO'
  ].includes(intencion)
) {
  clasificacionMinima =
    'B';
}

if (
  intencion === 'ACEPTAR_COTIZACION' ||
  intencion === 'CONFIRMAR_PEDIDO' ||
  intencion === 'REPORTAR_PAGO' ||
  motivoDerivacion === 'SOLICITA_DATOS_PAGO' ||
  motivoDerivacion === 'ENVIA_COMPROBANTE'
) {
  clasificacionMinima =
    'A';
}

const clasificacionIA =
  texto(
    decision.clasificacion_prospecto,
    'C'
  ).toUpperCase();

const clasificacionProspecto =
  maxClasificacion(
    clasificacionAnterior,
    clasificacionIA,
    clasificacionMinima
  );


// ======================================================
// 10. ETIQUETA GRANDE
// ======================================================
//
// Regla comercial:
// supera 10 x 15 cm, sin importar orientación.
//
// Normalizamos lados:
// corto <= largo
//
// Grande cuando:
// corto > 10
// O
// largo > 15
// ======================================================

let etiquetaGrande =
  false;

if (
  anchoCm !== null &&
  altoCm !== null
) {
  const ladoCorto =
    Math.min(
      anchoCm,
      altoCm
    );

  const ladoLargo =
    Math.max(
      anchoCm,
      altoCm
    );

  etiquetaGrande =
    ladoCorto > 10 ||
    ladoLargo > 15;
}


// ======================================================
// 11. BANDERAS DE CONTINUIDAD
// ======================================================

const debePedirCiudadDespuesCotizacion =
  accion === 'COTIZAR_P4' &&
  !prospectoCiudadResuelta;

const cierreCordial =
  intencion === 'POSPONER_DECISION';


// ======================================================
// 12. NOTIFICACIÓN Y PRIORIDAD
// ======================================================
//
// Toda derivación humana genera notificación interna.
// No confiamos únicamente en el booleano emitido por IA.
// ======================================================

const requiereNotificacion =
  requiereHumano === true;

let prioridadDerivacion =
  'NORMAL';

if (
  [
    'SOLICITA_DATOS_PAGO',
    'REPORTA_PAGO',
    'ENVIA_COMPROBANTE',
    'CONFIRMAR_PEDIDO',
    'RECLAMO',
    'PROBLEMA_PAGO',
    'PROBLEMA_PEDIDO',
    'PROBLEMA_ENTREGA'
  ].includes(motivoDerivacion)
) {
  prioridadDerivacion =
    'ALTA';
} else if (
  requiereHumano
) {
  prioridadDerivacion =
    'MEDIA';
}


// ======================================================
// 13. VALIDACIÓN DE SEGURIDAD
// ======================================================

for (
  const [nombre, valor] of Object.entries({
    cantidad,
    ancho_cm:
      anchoCm,
    alto_cm:
      altoCm
  })
) {
  if (
    valor !== null &&
    valor <= 0
  ) {
    throw new Error(
      `${nombre} inválido recibido desde IA: ${valor}`
    );
  }
}

if (
  requiereHumano &&
  accion !== 'DERIVAR_HUMANO'
) {
  throw new Error(
    'Decisión incoherente: requiere_humano=true pero accion no es DERIVAR_HUMANO.'
  );
}


// ======================================================
// 14. SALIDA ÚNICA PEGASO
// ======================================================

return {
  json: {

    // ----------------------------------------------
    // CONVERSACIÓN
    // ----------------------------------------------

    conversacion_id:
      conversacionId,

    cliente_id:
      clienteId,

    contacto_id:
      contactoId,

    telefono:
      texto(contexto.telefono),

    nombre_whatsapp:
      texto(contexto.nombre_whatsapp),

    es_cliente_registrado:
      booleano(
        contexto.es_cliente_registrado,
        false
      ),

    mensaje_actual:
      texto(
        contexto.mensaje_actual,
        ''
      ),

    tipo_mensaje:
      texto(
        contexto.tipo_mensaje,
        'TEXTO'
      ).toUpperCase(),


    // ----------------------------------------------
    // PROSPECTO
    // ----------------------------------------------

    prospecto_existe:
      prospectoExiste,

    prospecto_id:
      prospectoId,

    prospecto_estado:
      prospectoEstado,

    prospecto_clasificacion_anterior:
      clasificacionAnterior,

    clasificacion_prospecto:
      clasificacionProspecto,

    prospecto_nombre:
      prospectoNombre,

    prospecto_producto_interes:
      prospectoProductoInteres,

    prospecto_ciudad:
      prospectoCiudadResuelta,

    prospecto_provincia:
      prospectoProvinciaResuelta,

    prospecto_ultima_intencion:
      prospectoUltimaIntencion,

    prospecto_ultima_accion:
      prospectoUltimaAccion,

    prospecto_requiere_humano:
      prospectoRequiereHumano,


    // ----------------------------------------------
    // ACTOR
    // ----------------------------------------------

    tipo_actor:
      tipoActor,


    // ----------------------------------------------
    // DECISIÓN
    // ----------------------------------------------

    intencion,
    accion,


    // ----------------------------------------------
    // INFORMACIÓN DETECTADA
    // ----------------------------------------------

    producto,
    material,
    cantidad,

    ancho_cm:
      anchoCm,

    alto_cm:
      altoCm,

    // Trazabilidad para Resolver contexto comercial.
    // Estos campos son aditivos y no rompen el contrato existente.
    ancho_actual_explicito:
      anchoActualExplicito,

    alto_actual_explicito:
      altoActualExplicito,

    medidas_actuales_completas:
      medidasActualesCompletas,

    medidas_actuales_parciales:
      medidasActualesParciales,

    forma,

    ciudad_detectada:
      ciudadDetectada,

    provincia_detectada:
      provinciaDetectada,


    // ----------------------------------------------
    // ESTADO COMERCIAL
    // ----------------------------------------------

    datos_suficientes_para_cotizar:
      datosSuficientes,

    etiqueta_grande:
      etiquetaGrande,

    debe_pedir_ciudad_despues_cotizacion:
      debePedirCiudadDespuesCotizacion,

    cierre_cordial:
      cierreCordial,


    // ----------------------------------------------
    // DERIVACIÓN HUMANA
    // ----------------------------------------------

    requiere_humano:
      requiereHumano,

    motivo_derivacion:
      motivoDerivacion,

    requiere_notificacion:
      requiereNotificacion,

    prioridad_derivacion:
      prioridadDerivacion,

    derivacion_por_media:
      derivacionPorMedia,

    media_turno:
      mediaTurno,


    // ----------------------------------------------
    // RESPUESTA
    // ----------------------------------------------

    respuesta_sugerida:
      respuestaSugerida,


    // ----------------------------------------------
    // CONTEXTO
    // ----------------------------------------------

    contexto_comercial:
      contexto.contexto_comercial ?? {},


    // ----------------------------------------------
    // DIAGNÓSTICO
    // ----------------------------------------------

    decision_ia_valida:
      true
  }
};

// ======================================================
// PREPARAR RESPUESTA COMERCIAL - V2.3
// ======================================================
//
// Recibe la decisión comercial resuelta.
//
// Defensa adicional:
// - si la decisión trae omitir_envio (acción ya atendida,
//   medidas ya solicitadas sin dato nuevo) o la respuesta es
//   idéntica al último SALIENTE de "Preparar contexto IA",
//   NO se envía: respuesta_final queda como marcador
//   [RESPUESTA AUTOMÁTICA OMITIDA · motivo=...] para que el
//   SALIENTE registrado cierre el turno sin llegar al cliente.
//
// ======================================================

const PREFIJO_RESPUESTA_OMITIDA = '[RESPUESTA AUTOMÁTICA OMITIDA';

const items =
  $input.all();

let contextoIA = {};

try {
  contextoIA =
    $('Preparar contexto IA').first().json ?? {};
} catch (error) {
  contextoIA = {};
}


function normalizarParaComparar(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s¡!¿?.,;:*-]+|[\s¡!¿?.,;:*-]+$/g, '');
}


return items.map(
  (item) => {

    const data =
      item.json;

    const conversacionId =
      Number(
        data.conversacion_id
      );

    if (
      !conversacionId ||
      conversacionId <= 0
    ) {
      throw new Error(
        'No existe conversacion_id válido.'
      );
    }


    let respuesta =
      String(
        data.respuesta_sugerida ?? ''
      ).trim();


    const omisionSolicitada =
      data.omitir_envio === true;

    if (
      !respuesta &&
      !omisionSolicitada
    ) {
      throw new Error(
        `La acción ${data.accion ?? 'DESCONOCIDA'} no generó respuesta_sugerida.`
      );
    }


    // ==================================================
    // ANTI-REPETICIÓN
    // ==================================================

    const ultimoMensaje =
      String(
        data.ultimo_mensaje_saliente ??
        contextoIA.ultimo_saliente?.contenido ??
        contextoIA.ultimo_mensaje_saliente ??
        ''
      ).trim();

    const esDuplicado =
      !omisionSolicitada &&
      ultimoMensaje !== '' &&
      normalizarParaComparar(respuesta) ===
      normalizarParaComparar(ultimoMensaje);

    const omitirEnvio =
      omisionSolicitada ||
      esDuplicado;

    const motivoOmisionEnvio =
      omisionSolicitada
        ? (data.motivo_omision_envio ?? 'OMISION_SOLICITADA')
        : esDuplicado
          ? 'RESPUESTA_IDENTICA_A_ULTIMO_SALIENTE'
          : null;

    if (omitirEnvio) {
      respuesta =
        `${PREFIJO_RESPUESTA_OMITIDA} · motivo=${motivoOmisionEnvio}]`;
    }


    return {
      json: {
        ...data,

        respuesta_duplicada_evitable:
          esDuplicado,

        omitir_envio:
          omitirEnvio,

        motivo_omision_envio:
          motivoOmisionEnvio,

        respuesta_final:
          respuesta,

        mensaje_saliente: {
          conversacion_id:
            conversacionId,

          cliente_id:
            data.cliente_id != null
              ? Number(data.cliente_id)
              : null,

          direccion:
            'SALIENTE',

          tipo:
            'TEXTO',

          contenido:
            respuesta
        }
      }
    };
  }
);

