//
// NUEVO
// EN_CONVERSACION
// COTIZADO
// PEDIDO_CONFIRMADO
// REQUIERE_HUMANO
//
// Más adelante podremos ampliar el ciclo comercial.
// ======================================================

const ESTADOS_VALIDOS = [
  'NUEVO',
  'EN_CONVERSACION',
  'COTIZADO',
  'PEDIDO_CONFIRMADO',
  'REQUIERE_HUMANO'
];

if (!ESTADOS_VALIDOS.includes(estadoActual)) {
  throw new Error(
    `Estado comercial de prospecto inválido: ${estadoActual}`
  );
