  contextoAnterior = {};
}


const cotizacionAnterior =
  objeto(
    contextoAnterior.cotizacion
  );


// ======================================================
// 3. DATOS ANTERIORES
// ======================================================

const productoAnterior =
  texto(
    cotizacionAnterior.producto
  );

const materialAnterior =
  texto(
    cotizacionAnterior.material
  );

const cantidadAnterior =
  numero(
    cotizacionAnterior.cantidad_solicitada ??
    cotizacionAnterior.cantidad
  );

const anchoAnterior =
  numero(
    cotizacionAnterior.ancho_cm
  );

const altoAnterior =
  numero(
    cotizacionAnterior.alto_cm
  );

const formaAnterior =
  texto(
    cotizacionAnterior.forma
  );


// ======================================================
// 4. DATOS EXPLÍCITOS DEL MENSAJE ACTUAL
// ======================================================

// ------------------------------------------------------
// 4.1 NÚMEROS REALMENTE ESCRITOS EN EL TURNO
// ------------------------------------------------------
//
// La IA conserva datos anteriores y a veces toma como
// cantidad un número que no lo es ("botella de 500 ml").
// En un turno de solo texto, cantidad, ancho o alto
// cuentan como dato del turno solo si el número aparece
// escrito; la cantidad no puede ser volumen, peso ni
// medida. Con números en palabras, imagen o audio se
// confía en la IA.
//
// ------------------------------------------------------

const textoTurnoCrudo =
  String(
    contextoIA.mensaje_actual ??
    data.mensaje_actual ??
    ''
  );

const planoTurno =
  textoPlano(textoTurnoCrudo);

const UNIDADES_NO_CANTIDAD = [
  'ml', 'cc', 'l', 'lt', 'lts', 'litro', 'litros',
  'g', 'gr', 'grs', 'gramo', 'gramos', 'kg', 'kilo', 'kilos',
  'oz', 'onza', 'onzas', 'cm', 'mm', 'm', 'mt', 'mts', 'metro', 'metros'
];

const NUMEROS_EN_PALABRAS =
  /\b(dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|dieci\w+|veinte|veinti\w+|treinta|cuarenta|cincuenta|sesenta|setenta|ochenta|noventa|cien|ciento|\w+cientos|mil)\b/;

function numerosEscritos(valor) {
  const encontrados = [];

  const patron =
    /(\d{1,3}(?:[.,]\d{3})+(?!\d)|\d+(?:[.,]\d+)?)\s*(mil\b|ml\b|cc\b|lts?\b|litros?\b|l\b|grs?\b|gramos?\b|g\b|kg\b|kilos?\b|oz\b|onzas?\b|cm\b|mm\b|mts?\b|metros?\b|m\b)?/g;

  for (const m of String(valor ?? '').toLowerCase().matchAll(patron)) {
    const crudo = m[1];

    const valorNumero =
      /^\d{1,3}(?:[.,]\d{3})+$/.test(crudo)
        ? Number(crudo.replace(/[.,]/g, ''))
        : Number(crudo.replace(',', '.'));

    const unidad = m[2] ?? null;

    if (!Number.isFinite(valorNumero)) {
      continue;
    }

    encontrados.push(
      unidad === 'mil'
        ? { valor: valorNumero * 1000, unidad: null }
        : { valor: valorNumero, unidad }
    );
  }

  return encontrados;
}

const numerosTurno =
  numerosEscritos(textoTurnoCrudo);

const turnoSoloTexto =
  numero(contextoIA.media_turno?.cantidad_media) === null ||
  numero(contextoIA.media_turno?.cantidad_media) === 0;

const verificarNumerosTurno =
  turnoSoloTexto &&
  planoTurno !== '' &&
  !NUMEROS_EN_PALABRAS.test(planoTurno);

function cantidadEscrita(valor) {
  return numerosTurno.some(n =>
    igualesNumero(n.valor, valor) &&
    !UNIDADES_NO_CANTIDAD.includes(n.unidad)
  );
}

function medidaEscrita(valor) {
  return numerosTurno.some(n =>
    igualesNumero(n.valor, valor) ||
    (n.unidad === 'mm' && igualesNumero(n.valor / 10, valor)) ||
    (['m', 'mt', 'mts', 'metro', 'metros'].includes(n.unidad) && igualesNumero(n.valor * 100, valor))
  );
}

function datoDelTurno(valor, escrito) {
  if (valor === null || !verificarNumerosTurno) {
    return valor;
  }

  return escrito(valor) ? valor : null;
}


const productoActual =
  texto(data.producto);

const materialActual =
  texto(data.material);

const cantidadActual =
  datoDelTurno(numero(data.cantidad), cantidadEscrita);

const anchoActual =
  datoDelTurno(numero(data.ancho_cm), medidaEscrita);

const altoActual =
  datoDelTurno(numero(data.alto_cm), medidaEscrita);

const datosDescartadosTurno = [
  ['cantidad', numero(data.cantidad), cantidadActual],
  ['ancho_cm', numero(data.ancho_cm), anchoActual],
  ['alto_cm', numero(data.alto_cm), altoActual]
]
  .filter(([, ia, turno]) => ia !== null && turno === null)
  .map(([campo]) => campo);

let formaActual =
  texto(data.forma);

if (
  formaActual === 'NO_ESPECIFICADA'
) {
  formaActual = null;
}


// ======================================================
// 5. CONSOLIDAR DATOS
// ======================================================

const producto =
  productoActual ??
  productoAnterior;

const material =
  materialActual ??
  materialAnterior;

let cantidadSolicitada =
  cantidadActual ??
  cantidadAnterior;

// ------------------------------------------------------
// REGLA ATÓMICA DE MEDIDAS
// ------------------------------------------------------
//
// Si el mensaje actual trae LAS DOS medidas, ambas
// reemplazan juntas al par anterior.
//
// Esto evita estados híbridos:
//
// anterior: 7 x 12
// actual:   8 x 11
// incorrecto: 7 x 11
// correcto:   8 x 11
//
// Si el mensaje actual trae solo UNA medida explícita,
// sí permitimos conservar la otra anterior, porque puede
// ser una corrección parcial legítima.
// ------------------------------------------------------

const medidasActualesCompletas =
  anchoActual !== null &&
  altoActual !== null;

let anchoCm = null;
let altoCm = null;

if (medidasActualesCompletas) {
  anchoCm = anchoActual;
  altoCm = altoActual;
} else {
  anchoCm =
    anchoActual ??
    anchoAnterior;

  altoCm =
    altoActual ??
    altoAnterior;
}

let forma =
  formaActual ??
  formaAnterior ??
  'NO_ESPECIFICADA';


// ======================================================
// 6. FORMA DERIVADA
// ======================================================

if (
  forma === 'NO_ESPECIFICADA' &&
  anchoCm !== null &&
  altoCm !== null
) {
  forma =
    anchoCm === altoCm
      ? 'RECTANGULAR'
      : 'RECTANGULAR';
}


// ======================================================
// 7. CANTIDAD POR DEFECTO
// ======================================================
//
// Si ya tenemos medidas y el cliente no indicó cantidad,
// trabajamos con el mínimo comercial de 1000.
//
// NO se pregunta cantidad.
//
// ======================================================

let cantidadAsumida = false;

if (
  cantidadSolicitada === null &&
  anchoCm !== null &&
  altoCm !== null
) {
  cantidadSolicitada = 1000;
  cantidadAsumida = true;
}


// ======================================================
// 8. NORMALIZAR CANTIDAD IMPRIMIBLE
// ======================================================

let cantidadCotizable = null;
let cantidadAjustada = false;

if (
  cantidadSolicitada !== null &&
  cantidadSolicitada > 0
) {
  cantidadCotizable =
    Math.max(
      1000,
      Math.ceil(
        cantidadSolicitada / 1000
      ) * 1000
    );

  cantidadAjustada =
    cantidadCotizable !== cantidadSolicitada;
}


// ======================================================
// 9. DETECTAR CAMBIOS REALES DE COTIZACIÓN
// ======================================================

const modificoCantidad =
  cantidadActual !== null &&
  (
    cantidadAnterior === null ||
    !igualesNumero(
      cantidadActual,
      cantidadAnterior
    )
  );

const modificoAncho =
  anchoActual !== null &&
  (
    anchoAnterior === null ||
    !igualesNumero(
      anchoActual,
      anchoAnterior
    )
  );

const modificoAlto =
  altoActual !== null &&
  (
    altoAnterior === null ||
    !igualesNumero(
      altoActual,
      altoAnterior
    )
  );

const modificoForma =
  formaActual !== null &&
  (
    !formaAnterior ||
    formaActual !== formaAnterior
  );

const modificoParMedidas =
  medidasActualesCompletas &&
  (
    anchoAnterior === null ||
    altoAnterior === null ||
    !igualesNumero(
      anchoCm,
      anchoAnterior
    ) ||
    !igualesNumero(
      altoCm,
      altoAnterior
    )
  );

const modificoDatosCotizacion =
  modificoCantidad ||
  modificoAncho ||
  modificoAlto ||
  modificoForma ||
  modificoParMedidas;


// ======================================================
// 10. DATOS SUFICIENTES
// ======================================================

const faltaMedidas =
  anchoCm === null ||
  altoCm === null;

const datosSuficientes =
  !faltaMedidas &&
  cantidadCotizable !== null;


// ======================================================
// 11. RESOLVER ACCIÓN REAL
// ======================================================

const accionIA =
  texto(data.accion) ??
  'RESPONDER_GENERAL';

const intencion =
  texto(data.intencion) ??
  'OTRO';

let accion =
  accionIA;


// ------------------------------------------------------
// A. HUMANO SIEMPRE SE RESPETA
// ------------------------------------------------------

if (
  data.requiere_humano === true ||
  accionIA === 'DERIVAR_HUMANO'
) {
  accion =
    'DERIVAR_HUMANO';
}


// ------------------------------------------------------
// B. ACCIONES INFORMATIVAS SE RESPETAN
// ------------------------------------------------------
//
// Esta es la corrección clave:
// una pregunta de diseño, material, pago, ubicación, etc.
// NO puede convertirse en cotización solamente porque
// ya existan medidas previas.
//
// ------------------------------------------------------

else if (
  [
    'INFORMAR_MATERIAL',
    'INFORMAR_MINIMO',
    'INFORMAR_UBICACION',
    'INFORMAR_METODOLOGIA',
    'INFORMAR_METODOLOGIA_PAGO',
    'INFORMAR_ENTREGA',
    'INFORMAR_DISENO',
    'REGISTRAR_ACEPTACION',
    'RESPONDER_GENERAL'
  ].includes(accionIA)
) {
  accion =
    accionIA;
}


// ------------------------------------------------------
// C. SI QUIERE COTIZAR Y FALTAN MEDIDAS
// ------------------------------------------------------

else if (
  faltaMedidas &&
  [
    'SOLICITAR_COTIZACION',
    'CONSULTAR_PRECIO',
    'APORTAR_DATOS'
  ].includes(intencion)
) {
  accion =
    'PEDIR_MEDIDAS';
}


// ------------------------------------------------------
// D. COTIZACIÓN INICIAL
// ------------------------------------------------------

else if (
  datosSuficientes &&
  [
    'SOLICITAR_COTIZACION',
    'CONSULTAR_PRECIO'
  ].includes(intencion)
) {
  accion =
    'COTIZAR_P4';
}


// ------------------------------------------------------
// E. MODIFICACIÓN DE UNA COTIZACIÓN
// ------------------------------------------------------

else if (
  datosSuficientes &&
  intencion === 'APORTAR_DATOS' &&
  modificoDatosCotizacion
) {
  accion =
    'COTIZAR_P4';
}


// ------------------------------------------------------
// F. SI LA IA YA DECIDIÓ COTIZAR
// ------------------------------------------------------

else if (
  datosSuficientes &&
  accionIA === 'COTIZAR_P4'
) {
  accion =
    'COTIZAR_P4';
}


// ------------------------------------------------------
// G. PROTECCIÓN: NO PEDIR PRODUCTO PARA P4
// ------------------------------------------------------

else if (
  accionIA === 'PEDIR_PRODUCTO'
) {
  accion =
    faltaMedidas
      ? 'PEDIR_MEDIDAS'
      : 'COTIZAR_P4';
}


// ------------------------------------------------------
// J. NO RECOTIZAR SIN UN CAMBIO REAL EN ESTE TURNO
// ------------------------------------------------------
//
// Las medidas guardadas no bastan para volver a cotizar:
// - "son en otras medidas" sin medidas nuevas -> se piden;
// - sesión nueva sin datos ni referencia a lo anterior ->
//   no se reutiliza la cotización vieja;
// - cotización vigente sin cambios y sin pedir precio ->
//   se responde lo que preguntó, sin recotizar.
//
// ------------------------------------------------------

const PIDE_PRECIO =
  /\b(precios?|cuanto (cuesta|cuestan|vale|valen|sale|salen|seria|serian|costaria|costarian|me sale|me salen|me cobra|me cobran)|cotiza\w*|cotizacion(es)?|presupuesto|valor)\b/;

const REFIERE_COTIZACION_ANTERIOR =
  /\b(la cotizacion (que|de|anterior)|lo de (ayer|antes|la otra vez)|las mismas|los mismos|la misma|lo mismo|como (la vez pasada|antes|la anterior)|anterior|seguir con|continuar con)\b/;

const PIDE_OTRAS_MEDIDAS =
  /\b(otr[ao]s? (medidas?|tamanos?|dimensiones)|no son (esas|esa|estas|esta) medidas?|(cambiar|cambio|modificar) (de |las |la )?(medidas?|tamano)|(diferentes?|distint[ao]s?) (medidas?|tamanos?))\b/;

const cotizacionVigente =
  cotizacionAnterior.estado === 'COTIZADA' ||
  numero(cotizacionAnterior.total) !== null ||
  numero(cotizacionAnterior.cotizacion_id) !== null;

const sesionConversacionalNueva =
  contextoIA.sesion_conversacional_nueva === true;

let ajusteRecotizacion = null;

if (
  accion === 'COTIZAR_P4' &&
  !modificoDatosCotizacion
) {
  if (PIDE_OTRAS_MEDIDAS.test(planoTurno)) {
    ajusteRecotizacion = 'PIDE_OTRAS_MEDIDAS';
    accion = 'PEDIR_MEDIDAS';
  } else if (
    sesionConversacionalNueva &&
    !REFIERE_COTIZACION_ANTERIOR.test(planoTurno)
  ) {
    ajusteRecotizacion = 'SESION_NUEVA_SIN_DATOS';
    accion =
      PIDE_PRECIO.test(planoTurno)
        ? 'PEDIR_MEDIDAS'
        : 'RESPONDER_GENERAL';
  } else if (
    cotizacionVigente &&
    !PIDE_PRECIO.test(planoTurno) &&
    !REFIERE_COTIZACION_ANTERIOR.test(planoTurno)
  ) {
    ajusteRecotizacion = 'COTIZACION_VIGENTE_SIN_CAMBIOS';
    accion = 'RESPONDER_GENERAL';
  }
}


// ------------------------------------------------------
// H. CANTIDAD MAYORISTA -> HUMANO
// ------------------------------------------------------
//
// Desde 6000 etiquetas (ya normalizadas a multiplos de
// 1000) no existe precio automatico. Tiene prioridad
// sobre COTIZAR_P4 y sobre pedir datos de cotizacion,
// para que nunca se entre al extractor ni al calculo.
//
// Si la IA ya derivo por otro motivo, se respeta ese
// motivo. Las acciones informativas sin cantidad nueva
// en este turno se conservan.
//
// ------------------------------------------------------

const CANTIDAD_DERIVACION_HUMANA = 6000;

const ACCIONES_RUTA_COTIZACION = [
  'COTIZAR_P4',
  'PEDIR_MEDIDAS',
  'PEDIR_CANTIDAD',
  'PEDIR_PRODUCTO',
  'PEDIR_FORMA'
];

const INTENCIONES_PRECIO = [
  'SOLICITAR_COTIZACION',
  'CONSULTAR_PRECIO',
  'APORTAR_DATOS'
];

const cantidadMayorista =
  cantidadCotizable !== null &&
  cantidadCotizable >=
    CANTIDAD_DERIVACION_HUMANA;

const derivacionPorCantidad =
  cantidadMayorista &&
  accion !== 'DERIVAR_HUMANO' &&
  (
    ACCIONES_RUTA_COTIZACION.includes(accion) ||
    (
      cantidadActual !== null &&
      INTENCIONES_PRECIO.includes(intencion)
    )
  );

if (derivacionPorCantidad) {
  accion =
    'DERIVAR_HUMANO';
}


// ------------------------------------------------------
// I. REGLAS PRE-IA
// ------------------------------------------------------
//
// PRODUCTO_NO_P4: impreso que no es etiqueta adhesiva.
// Nunca se piden medidas ni se cotiza P4: lo atiende un
// humano como COTIZACION_ESPECIAL.
//
// ------------------------------------------------------

const reglaPreIA =
  texto(contextoIA.regla_pre_ia);

const productoNoP4 =
  texto(contextoIA.producto_no_p4);

const derivacionPorProductoNoP4 =
  reglaPreIA === 'PRODUCTO_NO_P4' &&
  !derivacionPorCantidad;

if (derivacionPorProductoNoP4) {
  accion =
    'DERIVAR_HUMANO';
}


// ------------------------------------------------------
// K. CONFIRMAR MEDIDAS GRANDES (precio / 1000 > $140)
// ------------------------------------------------------
//
// Medidas muy grandes (p. ej. 20x30, 15x30, 100x100)
// generan precios altos. Antes de cotizar se confirma
// con el prospecto. La estimación sigue la misma lógica
// comercial de "Calcular precio detalle" (precio por
// 1000); la fuente de verdad del cobro sigue siendo ese
// nodo en la ruta de cotización.
//
// ------------------------------------------------------

const LIMITE_CONFIRMACION_PRECIO_1000 = 140;

function formatoMedidaCm(valor) {
  const n = numero(valor);
  if (n === null) {
    return '';
  }
  return Number.isInteger(n)
    ? String(n)
    : String(n);
}

function estimarPrecio1000Comercial(
  anchoValor,
  altoValor,
  formaValor,
  cantidadValor
) {
  const ancho = numero(anchoValor);
  const alto = numero(altoValor);
  const cantidad = numero(cantidadValor);

  if (
    ancho === null ||
    alto === null ||
    cantidad === null ||
    cantidad < 1000
  ) {
    return null;
  }

  if (
    ancho >= 2 && ancho < 4 &&
    alto >= 2 && alto < 4
  ) {
    return 18;
  }

  if (ancho === 4 && alto === 4) {
    return 20;
  }

  let anchoCalc = ancho;
  let altoCalc = alto;

  if (ancho === 5 && alto === 5) {
    anchoCalc += 1;
    altoCalc += 1;
  }

  const formaNorm =
    String(formaValor ?? '')
      .trim()
      .toUpperCase();

  if (
    formaNorm === 'CIRCULAR' ||
    formaNorm === 'TROQUELADA' ||
    formaNorm === 'REDONDEADA'
  ) {
    anchoCalc += 1;
    altoCalc += 1;
  }

  const factorRango =
    cantidad <= 2000
      ? 0.75
      : cantidad <= 5000
        ? 0.67
        : null;

  if (factorRango === null) {
    return null;
  }

  const precio1000Rango =
    anchoCalc * altoCalc * factorRango;

  const factor =
    precio1000Rango > 130 && 0.67 < factorRango
      ? 0.67
      : factorRango;

  return Math.ceil(anchoCalc * altoCalc * factor);
}

const confirmacionMedidasAnterior =
  objeto(contextoAnterior.confirmacion_medidas_grandes);

const precio1000Estimado =
  datosSuficientes
    ? estimarPrecio1000Comercial(
        anchoCm,
        altoCm,
        forma,
        cantidadCotizable
      )
    : null;

const medidasGrandesYaConfirmadas =
  confirmacionMedidasAnterior.confirmadas === true &&
  igualesNumero(
    confirmacionMedidasAnterior.ancho_cm,
    anchoCm
  ) &&
  igualesNumero(
    confirmacionMedidasAnterior.alto_cm,
    altoCm
  );

const AFIRMA_MEDIDAS =
  /^(si|ok|okay)\b|\b(correct[oa]s?|confirmo|confirmad[oa]s?|estan bien|estan correctas|asi es|exacto|afirmativo|dale|de acuerdo|esas? (son|es)|son (esas|correctas|asi)|si(,| )?(confirmo|estan bien|son correctas|son esas)|confirmo( las)? medidas|medidas? correctas)\b/;

const NIEGA_MEDIDAS =
  /^(no)\b|\b(incorrect[oa]s?|estan mal|esta mal|equivocad|error|no (son|es)( las)?( esas)?( correctas)?|otras medidas|me equivoque)\b/;

let confirmacionMedidasGrandes =
  Object.keys(confirmacionMedidasAnterior).length > 0
    ? { ...confirmacionMedidasAnterior }
    : null;

let pideConfirmacionMedidasGrandes = false;
let niegaMedidasGrandes = false;

if (
  confirmacionMedidasAnterior.pendiente === true &&
  !derivacionPorCantidad &&
  !derivacionPorProductoNoP4
) {
  const mismasMedidasPendientes =
    igualesNumero(
      confirmacionMedidasAnterior.ancho_cm,
      anchoCm
    ) &&
    igualesNumero(
      confirmacionMedidasAnterior.alto_cm,
      altoCm
    );

  const aportoMedidasDistintas =
    modificoParMedidas &&
    !mismasMedidasPendientes;

  if (aportoMedidasDistintas) {
    confirmacionMedidasGrandes = null;
  } else if (
    AFIRMA_MEDIDAS.test(planoTurno) &&
    !NIEGA_MEDIDAS.test(planoTurno)
  ) {
    accion = 'COTIZAR_P4';
    confirmacionMedidasGrandes = {
      pendiente: false,
      confirmadas: true,
      ancho_cm: anchoCm,
      alto_cm: altoCm,
      forma,
      cantidad: cantidadCotizable,
      precio_1000_estimado:
        precio1000Estimado ??
        confirmacionMedidasAnterior.precio_1000_estimado ??
        null,
      confirmada_at: new Date().toISOString()
    };
  } else if (NIEGA_MEDIDAS.test(planoTurno)) {
    accion = 'PEDIR_MEDIDAS';
    confirmacionMedidasGrandes = null;
    niegaMedidasGrandes = true;
  } else if (
    !modificoDatosCotizacion &&
    accion !== 'DERIVAR_HUMANO'
  ) {
    pideConfirmacionMedidasGrandes = true;
    accion = 'RESPONDER_GENERAL';
  }
}

const medidasGrandesConfirmadasEsteTurno =
  confirmacionMedidasGrandes?.confirmadas === true &&
  igualesNumero(confirmacionMedidasGrandes.ancho_cm, anchoCm) &&
  igualesNumero(confirmacionMedidasGrandes.alto_cm, altoCm);

if (
  accion === 'COTIZAR_P4' &&
  !derivacionPorCantidad &&
  !derivacionPorProductoNoP4 &&
  precio1000Estimado !== null &&
  precio1000Estimado > LIMITE_CONFIRMACION_PRECIO_1000 &&
  !medidasGrandesYaConfirmadas &&
  !medidasGrandesConfirmadasEsteTurno
) {
  pideConfirmacionMedidasGrandes = true;
  accion = 'RESPONDER_GENERAL';
  confirmacionMedidasGrandes = {
    pendiente: true,
    confirmadas: false,
    ancho_cm: anchoCm,
    alto_cm: altoCm,
    forma,
    cantidad: cantidadCotizable,
    precio_1000_estimado: precio1000Estimado,
    solicitada_at: new Date().toISOString()
  };
}


// ======================================================
// 12. RESPUESTA SUGERIDA
// ======================================================

let respuestaSugerida =
  texto(
    data.respuesta_sugerida
  ) ?? '';

if (pideConfirmacionMedidasGrandes) {
  const anchoTxt =
    formatoMedidaCm(
      confirmacionMedidasGrandes?.ancho_cm ?? anchoCm
    );
  const altoTxt =
    formatoMedidaCm(
      confirmacionMedidasGrandes?.alto_cm ?? altoCm
    );

  respuestaSugerida =
    `Solo por confirmar: ¿requiere sus etiquetas de ${anchoTxt}x${altoTxt} cm? ` +
    `Le consulto porque son medidas grandes y el precio se calcula en base a ellas. ` +
    `Confírmenos por favor si esas son las medidas correctas en las que necesita sus etiquetas.`;
}

else if (niegaMedidasGrandes) {
  respuestaSugerida =
    'Entendido. Indíquenos por favor las medidas correctas de sus etiquetas (ancho y alto en centímetros) para cotizarle.';
}

else if (
  accion === 'PEDIR_MEDIDAS'
) {
  respuestaSugerida =
    '¿En qué medidas necesita sus etiquetas? Indíquenos ancho y alto por favor.';
}

else if (
  accion === 'COTIZAR_P4' ||
  derivacionPorCantidad
) {
  respuestaSugerida =
    '';
}

if (
  !pideConfirmacionMedidasGrandes &&
  !niegaMedidasGrandes &&
  ajusteRecotizacion === 'PIDE_OTRAS_MEDIDAS'
) {
  respuestaSugerida =
    'Indíquenos por favor las nuevas medidas de sus etiquetas (ancho y alto en centímetros) para cotizarle.';
}

else if (
  !pideConfirmacionMedidasGrandes &&
  !niegaMedidasGrandes &&
  accion === 'RESPONDER_GENERAL' &&
  ajusteRecotizacion !== null &&
  respuestaSugerida === ''
) {
  respuestaSugerida =
    ajusteRecotizacion === 'SESION_NUEVA_SIN_DATOS'
      ? '¿En qué podemos ayudarle con sus etiquetas?'
      : 'Gracias por la información. Si necesita cotizar otra medida o cantidad, indíquenos por favor ancho, alto y cantidad.';
}


// ------------------------------------------------------
// 12.1 FECHA DESEADA POR EL CLIENTE
// ------------------------------------------------------
//
// Pedidos de lunes a miércoles, producción miércoles y
// jueves, entregas viernes desde las 17:00. La fecha que
// pide el cliente se guarda, pero nunca se confirma.
//
// ------------------------------------------------------

const RESPUESTA_METODOLOGIA =
  'Trabajamos con una metodología semanal: recibimos pedidos de lunes a miércoles, ' +
  'producimos miércoles y jueves, y realizamos entregas y envíos los viernes a partir de las 17:00. ' +
  'El viernes de entrega se confirma según el día en que ingrese su pedido.';

function textoPlano(valor) {
  return String(valor ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const DIAS_SEMANA =
  '(lunes|martes|miercoles|jueves|viernes|sabado|domingo)';

const MESES =
  '(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)';

const PATRONES_FECHA_DESEADA = [
  new RegExp(`\\b(para|hasta|antes del?) (el )?(dia )?(proximo )?${DIAS_SEMANA}\\b`),
  /\b(para|hasta|antes del?) (el )?(dia )?\d{1,2}\b(?! ?(x|cm|mm|ml|cc|gr|g|kg|lt|l|litros?|onzas?|oz|unidades|etiquetas|mil|por|disenos?|modelos?|sabor(?:es)?|nombres?|variedad(?:es)?|version(?:es)?|textos?|tipos?|referencias?|artes?|marcas?|color(?:es)?|productos?|presentacion(?:es)?|diferentes|distint[oa]s))/,
  new RegExp(`\\b\\d{1,2} de ${MESES}\\b`),
  /\b(para|hasta|antes de) (hoy|manana|pasado manana|esta semana|la proxima semana|el fin de semana|fin de mes)\b/,
  /\b(las|los|la|lo) (necesito|necesitamos|requiero|requerimos|quiero|queremos) (para|hasta|antes)\b/
];

const PATRON_PROMESA =
  /\b(se (lo|la|los|las) (entregamos|tenemos|tendremos)|(estara|estaran) list[oa]s? (para|el)|le (confirmamos|garantizamos) (la entrega|que)|sin problema (para|el))\b/;

const mensajeTurnoPlano =
  textoPlano(
    contextoIA.mensaje_actual ??
    data.mensaje_actual
  );

const coincidenciaFecha =
  PATRONES_FECHA_DESEADA
    .map(patron => mensajeTurnoPlano.match(patron))
    .find(Boolean) ?? null;


// ------------------------------------------------------
// 12.2 NO REPETIR PEDIR_MEDIDAS
// ------------------------------------------------------
//
// Si el último SALIENTE con acción reconocible ya pidió
// medidas (bot, automatización de WhatsApp Business o
// humano), no se vuelve a hacer la pregunta completa:
// - con información nueva en el turno, se agradece y se
//   pide solo lo que falta;
// - sin información nueva, no se envía nada.
//
// ------------------------------------------------------

const ultimoSaliente =
  objeto(contextoIA.ultimo_saliente);

const medidasYaSolicitadas =
  contextoIA.medidas_ya_solicitadas === true;

const turnoAportaInformacion =
  anchoActual !== null ||
  altoActual !== null ||
  cantidadActual !== null ||
  materialActual !== null ||
  formaActual !== null ||
  coincidenciaFecha !== null ||
  (
    productoActual !== null &&
    productoActual !== productoAnterior
  );

let omitirEnvio = false;

let motivoOmisionEnvio = null;

let preguntaMedidasFaltantes = null;

if (
  accion === 'PEDIR_MEDIDAS' &&
  medidasYaSolicitadas &&
  ajusteRecotizacion !== 'PIDE_OTRAS_MEDIDAS' &&
  !pideConfirmacionMedidasGrandes &&
  !niegaMedidasGrandes
) {
  if (turnoAportaInformacion) {
    const faltante =
      anchoCm === null && altoCm === null
        ? 'el ancho y alto'
        : anchoCm === null
          ? 'el ancho'
          : 'el alto';

    preguntaMedidasFaltantes =
      `Para cotizar sus etiquetas solo nos falta ${faltante} en centímetros.`;

    respuestaSugerida =
      `Gracias. ${preguntaMedidasFaltantes}`;
  } else {
    omitirEnvio = true;
    motivoOmisionEnvio = 'MEDIDAS_YA_SOLICITADAS';
  }
}


// ------------------------------------------------------
// 12.3 METODOLOGÍA EN LUGAR DE PROMESA DE FECHA
// ------------------------------------------------------

const respuestaPrometeFecha =
  PATRON_PROMESA.test(
    textoPlano(respuestaSugerida)
  );

let fechaDeseadaCliente =
  objeto(contextoAnterior.fecha_deseada_cliente);

const aplicaMetodologia =
  (coincidenciaFecha !== null || respuestaPrometeFecha) &&
  !omitirEnvio &&
  !pideConfirmacionMedidasGrandes &&
  !niegaMedidasGrandes &&
  !['COTIZAR_P4', 'DERIVAR_HUMANO'].includes(accion);

if (coincidenciaFecha !== null) {
  fechaDeseadaCliente = {
    texto:
      coincidenciaFecha[0],
    detectada_at:
      new Date().toISOString()
  };
}

if (aplicaMetodologia) {
  const preguntaPendiente =
    accion === 'PEDIR_MEDIDAS'
      ? (
          preguntaMedidasFaltantes !== null
            ? ` ${preguntaMedidasFaltantes}`
            : ' Para cotizar, ¿en qué medidas necesita sus etiquetas? Indíquenos ancho y alto por favor.'
        )
      : '';

  respuestaSugerida =
    `${RESPUESTA_METODOLOGIA}${preguntaPendiente}`.trim();
}


// ------------------------------------------------------
// 12.4 ACCIÓN YA ATENDIDA DURANTE EL TURNO
// ------------------------------------------------------
//
// El eco automático de WhatsApp Business (por ejemplo la
// respuesta de anuncio que pide medidas o explica el
// material) puede llegar después de iniciado el turno. Si
// ya cubrió la misma acción, el bot no la repite. Una
// respuesta automática sin acción reconocida (detectada
// por velocidad en la apertura) cubre las preguntas
// informativas del turno.
//
// Si lo que respondió la automatización es informativo y
// aún faltan medidas, el bot solo continúa con la pregunta
// de medidas para no dejar la conversación sin siguiente
// paso.
//
// ------------------------------------------------------

const ACCIONES_ATENDIBLES_POR_AUTOMATIZACION = [
  'INFORMAR_MATERIAL',
  'INFORMAR_MINIMO',
  'INFORMAR_UBICACION',
  'INFORMAR_METODOLOGIA',
  'INFORMAR_METODOLOGIA_PAGO',
  'INFORMAR_ENTREGA',
  'INFORMAR_DISENO',
  'RESPONDER_GENERAL'
];

const accionAutomatizacion =
  texto(ultimoSaliente.accion_equivalente);

const automatizacionAtendioTurno =
  !omitirEnvio &&
  !aplicaMetodologia &&
  !pideConfirmacionMedidasGrandes &&
  !niegaMedidasGrandes &&
  ultimoSaliente.posterior_al_turno === true &&
  ultimoSaliente.origen === 'AUTOMATICO' &&
  (
    accionAutomatizacion === accion ||
    (
      reglaPreIA === 'SALUDO_SIMPLE' &&
      accionAutomatizacion !== null
    ) ||
    (
      accionAutomatizacion === null &&
      ACCIONES_ATENDIBLES_POR_AUTOMATIZACION.includes(accion)
    )
  );

let seguimientoTrasAutomatizacion = false;

if (automatizacionAtendioTurno) {
  seguimientoTrasAutomatizacion =
    reglaPreIA !== 'SALUDO_SIMPLE' &&
    ACCIONES_ATENDIBLES_POR_AUTOMATIZACION.includes(accion) &&
    faltaMedidas &&
    !medidasYaSolicitadas;

  if (seguimientoTrasAutomatizacion) {
    respuestaSugerida =
      '¿En qué medidas necesita sus etiquetas? Indíquenos ancho y alto por favor.';
  } else {
    omitirEnvio = true;
    motivoOmisionEnvio = 'ACCION_YA_ATENDIDA_POR_AUTOMATIZACION';
  }
}


// ------------------------------------------------------
// 12.5 IMAGEN INFORMATIVA (MATERIAL / METODOLOGÍA)
// ------------------------------------------------------
//
// Las respuestas de material y de metodología de
// producción van acompañadas de una imagen configurada en
// configuracion_bot (valor_json { activo, url }), una sola
// vez por conversación y por imagen: el contexto comercial
// guarda cuándo se envió cada una. "Preparar envío
// WhatsApp" la manda antes del texto.
//
// METODOLOGIA cubre INFORMAR_ENTREGA (tiempos, despacho),
// INFORMAR_METODOLOGIA y la respuesta de metodología que
// reemplaza a una fecha pedida (12.3).
//
// ------------------------------------------------------

const IMAGENES_INFORMATIVAS = {
  MATERIAL: {
    clave: 'IMAGEN_MATERIAL',
    contexto: 'imagen_material'
  },
  METODOLOGIA: {
    clave: 'IMAGEN_METODOLOGIA',
    contexto: 'imagen_metodologia'
  }
};

const temaImagenInformativa =
  aplicaMetodologia ||
  ['INFORMAR_ENTREGA', 'INFORMAR_METODOLOGIA'].includes(accion)
    ? 'METODOLOGIA'
    : accion === 'INFORMAR_MATERIAL'
      ? 'MATERIAL'
      : null;

const imagenInformativa =
  temaImagenInformativa !== null
    ? IMAGENES_INFORMATIVAS[temaImagenInformativa]
    : null;

let filasConfiguracion = [];

try {
  filasConfiguracion =
    $('Obtener configuración MODO_PRUEBA')
      .all()
      .map(item => item.json ?? {});
} catch (_) {
  filasConfiguracion = [];
}

const configImagenInformativa =
  imagenInformativa !== null
    ? objeto(
        filasConfiguracion.find(
          fila => fila.clave === imagenInformativa.clave
        )?.valor_json
      )
    : {};

const urlConfiguradaImagenInformativa =
  texto(configImagenInformativa.url);

const urlImagenInformativa =
  configImagenInformativa.activo === true &&
  urlConfiguradaImagenInformativa !== null &&
  /^https:\/\/\S+$/i.test(urlConfiguradaImagenInformativa)
    ? urlConfiguradaImagenInformativa
    : null;

const imagenInformativaYaEnviada =
  imagenInformativa !== null &&
  texto(
    objeto(contextoAnterior[imagenInformativa.contexto]).enviada_at
  ) !== null;

const enviarImagenInformativa =
  imagenInformativa !== null &&
  !omitirEnvio &&
  urlImagenInformativa !== null &&
  !imagenInformativaYaEnviada;


// ======================================================
// 13. CONTEXTO COMERCIAL NUEVO
// ======================================================

// ------------------------------------------------------
// INVALIDAR RESULTADO DE COTIZACIÓN ANTERIOR SI CAMBIARON
// SUS DATOS BASE
// ------------------------------------------------------
//
// El objeto contexto_comercial.cotizacion funciona como
// snapshot de la cotización vigente.
//
// Si cambia cantidad, medidas o forma, ya no podemos
// conservar como vigentes:
//
// - id / cotizacion_id
// - total / precio_total
// - estado
// - cotizada_at
// - flags de producibilidad del intento anterior
//
// Esos datos serán escritos nuevamente por la ruta real
// de cotización cuando termine el cálculo.
// ------------------------------------------------------

const cotizacionBaseNueva =
  modificoDatosCotizacion
    ? {
        ...cotizacionAnterior,

        id: null,
        cotizacion_id: null,

        existe: false,

        estado: null,

        total: null,
        precio_total: null,
        moneda:
          cotizacionAnterior.moneda ??
          'USD',

        cotizada_at: null,

        cantidad_detalles: null,

        producible: null,
        restriccion_codigo: null,
        restriccion_tipo: null,

        ultimo_error_produccion: null,
        ultimo_intento_producible: null
      }
    : {
        ...cotizacionAnterior
      };

const contextoComercialNuevo = {
  ...contextoAnterior,

  ...(
    Object.keys(fechaDeseadaCliente).length > 0
      ? { fecha_deseada_cliente: fechaDeseadaCliente }
      : {}
  ),

  ...(
    derivacionPorProductoNoP4
      ? {
          producto_no_p4: {
            producto: productoNoP4,
            detectado_at: new Date().toISOString()
          }
        }
      : {}
  ),

  ...(
    enviarImagenInformativa
      ? {
          [imagenInformativa.contexto]: {
            url: urlImagenInformativa,
            enviada_at: new Date().toISOString()
          }
        }
      : {}
  ),

  cotizacion: {
    ...cotizacionBaseNueva,

    producto,
    material,

    cantidad_solicitada:
      cantidadSolicitada,

    cantidad_cotizable:
      cantidadCotizable,

    cantidad_ajustada:
      cantidadAjustada,

    cantidad_asumida:
      cantidadAsumida,

    ancho_cm:
      anchoCm,

    alto_cm:
      altoCm,

    forma
  }
};

if (confirmacionMedidasGrandes !== null) {
  contextoComercialNuevo.confirmacion_medidas_grandes =
    confirmacionMedidasGrandes;
} else {
  delete contextoComercialNuevo.confirmacion_medidas_grandes;
}


// ======================================================
// 14. SALIDA
// ======================================================

return [
  {
    json: {
      ...data,

      producto,
      material,

      cantidad_solicitada:
        cantidadSolicitada,

      cantidad_cotizable:
        cantidadCotizable,

      cantidad_ajustada:
        cantidadAjustada,

      cantidad_asumida:
        cantidadAsumida,

      cantidad:
        cantidadCotizable,

      ancho_cm:
        anchoCm,

      alto_cm:
        altoCm,

      forma,

      modifico_datos_cotizacion:
        modificoDatosCotizacion,

      modifico_par_medidas:
        modificoParMedidas,

      medidas_actuales_completas:
        medidasActualesCompletas,

      accion,

      ...(
        derivacionPorCantidad
          ? {
              requiere_humano:
                true,

              motivo_derivacion:
                'COTIZACION_ESPECIAL',

              requiere_notificacion:
                true,

              regla_derivacion:
                'CANTIDAD_MAYORISTA'
            }
          : {}
      ),

      ...(
        derivacionPorProductoNoP4
          ? {
              requiere_humano:
                true,

              motivo_derivacion:
                'COTIZACION_ESPECIAL',

              requiere_notificacion:
                true,

              regla_derivacion:
                'PRODUCTO_NO_P4',

              producto_no_p4:
                productoNoP4
            }
          : {}
      ),

      derivacion_por_cantidad:
        derivacionPorCantidad,

      regla_pre_ia:
        reglaPreIA,

      fecha_deseada_cliente:
        Object.keys(fechaDeseadaCliente).length > 0
          ? fechaDeseadaCliente
          : null,

      omitir_envio:
        omitirEnvio,

      motivo_omision_envio:
        motivoOmisionEnvio,

      ajuste_recotizacion:
        ajusteRecotizacion,

      datos_descartados_turno:
        datosDescartadosTurno,

      seguimiento_tras_automatizacion:
        seguimientoTrasAutomatizacion,

      pide_confirmacion_medidas_grandes:
        pideConfirmacionMedidasGrandes,

      precio_1000_estimado:
        precio1000Estimado,

      enviar_imagen_informativa:
        enviarImagenInformativa,

      imagen_informativa:
        enviarImagenInformativa
          ? temaImagenInformativa
          : null,

      imagen_informativa_url:
        enviarImagenInformativa
          ? urlImagenInformativa
          : null,

      datos_suficientes_para_cotizar:
        datosSuficientes,

      respuesta_sugerida:
        respuestaSugerida,

      contexto_comercial:
        contextoComercialNuevo
    }
  }
];

// ======================================================
// PREPARAR CONTEXTO POST COTIZACIÓN
// PEGASO ADHESIVOS - V2.6
// ======================================================
//
// OBJETIVO:
//
// Actualizar contexto_comercial después del intento
// de cotización.
//
// IMPORTANTE:
//
// Existen DOS resultados posibles:
//
// 1. COTIZACIÓN PRODUCIBLE
// 2. COTIZACIÓN NO PRODUCIBLE
//
// Este nodo NO puede asumir que:
// "Preparar mensaje cotización"
// siempre fue ejecutado.
//
// Tampoco debe marcar como COTIZADO a un prospecto
// cuando las medidas no son producibles.
//
// PostgreSQL continúa siendo la fuente de verdad.
// ======================================================


// ======================================================
// 1. HELPERS
// ======================================================

function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const texto =
    String(valor).trim();

  return texto !== ''
    ? texto
    : null;
}


function objeto(valor) {

  if (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return valor;
  }

  if (typeof valor === 'string') {

    try {

      const parsed =
        JSON.parse(valor);

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }

    } catch (_) {
      // Ignorar
    }
  }

  return {};
}


// ======================================================
// 2. RECUPERAR DECISIÓN COMERCIAL
// ======================================================

let decision = {};

try {

  decision =
    $('Recuperar decisión comercial')
      .first()
      .json ?? {};

} catch (_) {

  decision = {};

}


// ======================================================
// 3. RECUPERAR CONTEXTO COMERCIAL ANTERIOR
// ======================================================

let contextoAnterior = {};

try {

  const resolver =
    $('Resolver contexto comercial')
      .first()
      .json ?? {};

  contextoAnterior =
    objeto(
      resolver.contexto_comercial
    );

} catch (_) {

  contextoAnterior = {};

}


// ======================================================
// 4. RECUPERAR RESULTADO DE COTIZACIÓN
// ======================================================
//
// Nunca acceder directamente a un nodo que quizá
// no se ejecutó.
//
// Intentamos primero cotización normal.
// Después cotización no producible.
//
// ======================================================

let resultadoComercial = null;


// ------------------------------------------------------
// 4.1 COTIZACIÓN PRODUCIBLE
// ------------------------------------------------------

try {

  if (
    $('Preparar mensaje cotización')
      .isExecuted
  ) {

    resultadoComercial =
      $('Preparar mensaje cotización')
        .first()
        .json ?? null;

  }

} catch (_) {

  resultadoComercial = null;

}


// ------------------------------------------------------
// 4.2 RESPUESTA NO PRODUCIBLE
// ------------------------------------------------------

if (!resultadoComercial) {

  try {

    if (
      $('Construir mensaje no producible')
        .isExecuted
    ) {

      resultadoComercial =
        $('Construir mensaje no producible')
          .first()
          .json ?? null;

    }

  } catch (_) {

    resultadoComercial = null;

  }

}


// ======================================================
// 5. FALLBACK
// ======================================================
//
// Como protección adicional:
//
// "Guardar mensaje comercial" sí está en la ruta común,
// pero el INSERT normalmente devuelve la fila DB y puede
// no conservar todos los campos comerciales.
//
// Por eso solamente lo utilizamos como fallback.
//
// ======================================================

if (!resultadoComercial) {

  try {

    resultadoComercial =
      $('Guardar mensaje comercial')
        .first()
        .json ?? {};

  } catch (_) {

    resultadoComercial = {};

  }

}


// ======================================================
// 6. IDENTIDAD
// ======================================================

const conversacionId =
  numeroONull(
    decision.conversacion_id
  );

const prospectoId =
  numeroONull(
    decision.prospecto_id
  );

const clienteId =
  numeroONull(
    decision.cliente_id
  );

const contactoId =
  numeroONull(
    decision.contacto_id
  );


if (
  conversacionId === null ||
  conversacionId <= 0
) {

  throw new Error(
    'Preparar contexto post cotización: conversacion_id inválido.'
  );

}


// ======================================================
// 7. DETERMINAR TIPO DE RESULTADO
// ======================================================
//
// Aceptamos diferentes banderas para mantener
// compatibilidad entre versiones.
//
// ======================================================

const tipoRespuesta =
  (
    textoONull(
      resultadoComercial?.tipo_respuesta_comercial
    ) ??
    ''
  ).toUpperCase();


const cotizacionProducible =
  resultadoComercial?.cotizacion_producible === true ||
  tipoRespuesta === 'COTIZACION';


const cotizacionNoProducible =
  resultadoComercial?.cotizacion_producible === false ||
  resultadoComercial?.bloquear_cotizacion === true ||
  tipoRespuesta === 'NO_PRODUCIBLE';


// ======================================================
// 8. DATOS DEL PEDIDO ACTUAL
// ======================================================

const cotizacionAnterior =
  objeto(
    contextoAnterior.cotizacion
  );


const producto =
  decision.producto ??
  cotizacionAnterior.producto ??
  null;


const material =
  decision.material ??
  cotizacionAnterior.material ??
  null;


const cantidadSolicitada =
  decision.cantidad_solicitada ??
  decision.cantidad ??
  cotizacionAnterior.cantidad_solicitada ??
  null;


const cantidadCotizable =
  decision.cantidad_cotizable ??
  decision.cantidad ??
  cotizacionAnterior.cantidad_cotizable ??
  null;


const cantidadAjustada =
  decision.cantidad_ajustada ??
  cotizacionAnterior.cantidad_ajustada ??
  false;


const anchoCm =
  decision.ancho_cm ??
  cotizacionAnterior.ancho_cm ??
  null;


const altoCm =
  decision.alto_cm ??
  cotizacionAnterior.alto_cm ??
  null;


const forma =
  decision.forma ??
  cotizacionAnterior.forma ??
  'NO_ESPECIFICADA';


// ======================================================
// 9. MENSAJE COMERCIAL
// ======================================================

const mensajeComercial =
  textoONull(
    resultadoComercial?.mensaje_comercial
  ) ??
  '';


// ======================================================
// 10. COTIZACIÓN PRODUCIBLE
// ======================================================

if (cotizacionProducible) {

  const cotizacionId =
    numeroONull(
      resultadoComercial.cotizacion_id
    );

  const total =
    numeroONull(
      resultadoComercial.total
    );


  if (
    cotizacionId === null ||
    cotizacionId <= 0
  ) {

    throw new Error(
      'Preparar contexto post cotización: cotización producible sin cotizacion_id válido.'
    );

  }


  if (
    total === null ||
    total < 0
  ) {

    throw new Error(
      'Preparar contexto post cotización: cotización producible sin total válido.'
    );

  }


  const contextoNuevo = {

    ...contextoAnterior,

    cotizacion: {

      ...cotizacionAnterior,

      cotizacion_id:
        cotizacionId,

      producto,

      material,

      cantidad_solicitada:
        cantidadSolicitada,

      cantidad_cotizable:
        cantidadCotizable,

      cantidad_ajustada:
        Boolean(
          cantidadAjustada
        ),

      ancho_cm:
        anchoCm,

      alto_cm:
        altoCm,

      forma,

      total,

      cantidad_detalles:
        Number(
          resultadoComercial.cantidad_detalles ?? 0
        ),

      estado:
        'COTIZADA',

      cotizada_at:
        new Date().toISOString(),

      ultimo_intento_producible:
        true,

      ultimo_error_produccion:
        null
    }

  };


  return [
    {
      json: {

        conversacion_id:
          conversacionId,

        prospecto_id:
          prospectoId,

        cliente_id:
          clienteId,

        contacto_id:
          contactoId,

        cotizacion_id:
          cotizacionId,

        total,

        mensaje_comercial:
          mensajeComercial,

        contexto_comercial:
          contextoNuevo,

        cotizacion_generada:
          true,

        cotizacion_producible:
          true,

        bloquear_cotizacion:
          false,

        estado_comercial:
          'COTIZADO',

        actualizar_estado_prospecto:
          true
      }
    }
  ];

}


// ======================================================
// 11. COTIZACIÓN NO PRODUCIBLE
// ======================================================
//
// MUY IMPORTANTE:
//
// No debemos:
//
// - marcar COTIZADO
// - fingir que existe una cotización
// - sobrescribir la última cotización válida
//
// Sí guardamos memoria del intento.
//
// ======================================================

if (cotizacionNoProducible) {

  const motivoNoProducible =
    textoONull(
      resultadoComercial.motivo_no_producible
    ) ??
    textoONull(
      resultadoComercial.motivo
    ) ??
    'MEDIDAS_NO_PRODUCIBLES';


  const contextoNuevo = {

    ...contextoAnterior,

    cotizacion: {

      ...cotizacionAnterior,

      producto,

      material,

      cantidad_solicitada:
        cantidadSolicitada,

      cantidad_cotizable:
        cantidadCotizable,

      cantidad_ajustada:
        Boolean(
          cantidadAjustada
        ),

      ancho_cm:
        anchoCm,

      alto_cm:
        altoCm,

      forma,

      ultimo_intento_producible:
        false,

      ultimo_error_produccion:
        motivoNoProducible,

      ultimo_intento_at:
        new Date().toISOString()
    }

  };


  return [
    {
      json: {

        conversacion_id:
          conversacionId,

        prospecto_id:
          prospectoId,

        cliente_id:
          clienteId,

        contacto_id:
          contactoId,

        cotizacion_id:
          null,

        total:
          null,

        mensaje_comercial:
          mensajeComercial,

        contexto_comercial:
          contextoNuevo,

        cotizacion_generada:
          false,

        cotizacion_producible:
          false,

        bloquear_cotizacion:
          true,

        motivo_no_producible:
          motivoNoProducible,

        // NO convertirlo a COTIZADO
        estado_comercial:
          decision.prospecto_estado ??
          'EN_CONVERSACION',

        actualizar_estado_prospecto:
          false
      }
    }
  ];

}


// ======================================================
// 12. ESTADO INDETERMINADO
// ======================================================

throw new Error(
  'Preparar contexto post cotización: no se pudo determinar si el resultado comercial fue producible o no producible.'
);

// ======================================================
// RESOLVER ESTADO POST COTIZACIÓN
// ======================================================

const contexto =
  $('Preparar contexto post cotización').first().json ?? {};

const prospectoId =
  contexto.prospecto_id != null
    ? Number(contexto.prospecto_id)
    : null;

const existeProspecto =
  Number.isFinite(prospectoId) &&
  prospectoId > 0;


// Si es un prospecto y acabamos de cotizar,
// lo llevamos a COTIZADO.
//
// Si más adelante descubrimos restricciones específicas
// en la columna estado, ajustamos únicamente este valor.

return [
  {
    json: {
      ...contexto,

      prospecto_id_estado_update:
        existeProspecto
          ? prospectoId
          : null,

      prospecto_estado_nuevo:
        existeProspecto
          ? 'COTIZADO'
          : null,

      actualizar_estado_prospecto:
        existeProspecto,

      estado_resuelto_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// FINALIZAR COTIZACIÓN COMERCIAL
// PEGASO ADHESIVOS - V2
// ======================================================
//
// Objetivo:
//
// Cerrar formalmente el flujo de cotización.
//
// Este nodo soporta DOS resultados válidos:
//
// 1. COTIZACIÓN PRODUCIBLE
//    - existe cotizacion_id
//    - existe total
//    - cotizacion_generada = true
//
// 2. COTIZACIÓN NO PRODUCIBLE
//    - NO existe cotizacion_id
//    - NO existe total
//    - cotizacion_generada = false
//    - existe mensaje comercial explicando el motivo
//
// Una cotización no producible NO constituye un error.
//
// ======================================================


// ======================================================
// 1. RECUPERAR ESTADO RESUELTO
// ======================================================

const data =
  $('Resolver estado post cotización')
    .first()
    .json ?? {};


// ======================================================
// 2. HELPERS
// ======================================================

function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleano(
  valor,
  defecto = false
) {

  if (typeof valor === 'boolean') {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return defecto;
}


function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


// ======================================================
// 3. DATOS BASE
// ======================================================

const conversacionId =
  numeroONull(
    data.conversacion_id
  );


const prospectoId =
  numeroONull(
    data.prospecto_id
  );


const clienteId =
  numeroONull(
    data.cliente_id
  );


const cotizacionId =
  numeroONull(
    data.cotizacion_id
  );


const total =
  numeroONull(
    data.total
  );


const mensajeComercial =
  textoONull(
    data.mensaje_comercial
  ) ??
  '';


// ======================================================
// 4. VALIDACIÓN COMÚN
// ======================================================

if (
  conversacionId === null ||
  conversacionId <= 0
) {

  throw new Error(
    'Finalizar cotización: no existe conversacion_id válido.'
  );

}


// ======================================================
// 5. DETERMINAR SI REALMENTE SE GENERÓ COTIZACIÓN
// ======================================================
//
// Preferimos flags explícitos.
//
// Si por compatibilidad todavía no existen,
// la presencia de cotizacion_id permite inferir
// una cotización real.
//
// ======================================================

let cotizacionGenerada;


if (
  data.cotizacion_generada !== undefined &&
  data.cotizacion_generada !== null
) {

  cotizacionGenerada =
    booleano(
      data.cotizacion_generada
    );

}

else if (
  data.cotizacion_producible !== undefined &&
  data.cotizacion_producible !== null
) {

  cotizacionGenerada =
    booleano(
      data.cotizacion_producible
    );

}

else {

  cotizacionGenerada =
    cotizacionId !== null;

}


// ======================================================
// 6. CASO A:
// COTIZACIÓN PRODUCIBLE
// ======================================================

if (cotizacionGenerada) {

  if (
    cotizacionId === null ||
    cotizacionId <= 0
  ) {

    throw new Error(
      'Finalizar cotización: se marcó como generada pero no existe cotizacion_id.'
    );

  }


  if (
    total === null ||
    total < 0
  ) {

    throw new Error(
      'Finalizar cotización: se marcó como generada pero no existe total válido.'
    );

  }


  return [
    {
      json: {

        success:
          true,

        flujo:
          'COTIZACION',

        resultado_cotizacion:
          'COTIZADA',


        // ----------------------------------------------
        // IDENTIDAD
        // ----------------------------------------------

        conversacion_id:
          conversacionId,

        prospecto_id:
          prospectoId,

        cliente_id:
          clienteId,


        // ----------------------------------------------
        // COTIZACIÓN
        // ----------------------------------------------

        cotizacion_id:
          cotizacionId,

        total:
          total,

        estado_comercial:
          'COTIZADO',

        cotizacion_generada:
          true,

        cotizacion_producible:
          true,


        // ----------------------------------------------
        // MENSAJE
        // ----------------------------------------------

        mensaje_comercial:
          mensajeComercial,

        esperando_respuesta_cliente:
          true,


        // ----------------------------------------------
        // CONTROL
        // ----------------------------------------------

        finalizado_at:
          new Date().toISOString()

      }
    }
  ];

}


// ======================================================
// 7. CASO B:
// SOLICITUD NO PRODUCIBLE
// ======================================================
//
// Aquí NO debe existir cotizacion_id.
//
// Esto NO es un error.
//
// El prospecto debe poder cambiar la medida y continuar.
//
// ======================================================

if (!mensajeComercial) {

  throw new Error(
    'Finalizar cotización no producible: no existe mensaje comercial para responder al prospecto.'
  );

}


return [
  {
    json: {

      success:
        true,

      flujo:
        'COTIZACION_NO_PRODUCIBLE',

      resultado_cotizacion:
        'NO_PRODUCIBLE',


      // ----------------------------------------------
      // IDENTIDAD
      // ----------------------------------------------

      conversacion_id:
        conversacionId,

      prospecto_id:
        prospectoId,

      cliente_id:
        clienteId,


      // ----------------------------------------------
      // SIN COTIZACIÓN REAL
      // ----------------------------------------------

      cotizacion_id:
        null,

      total:
        null,

      estado_comercial:
        'NO_COTIZABLE',

      cotizacion_generada:
        false,

      cotizacion_producible:
        false,


      // ----------------------------------------------
      // MENSAJE
      // ----------------------------------------------

      mensaje_comercial:
        mensajeComercial,

      // Queremos que responda con otra medida.
      esperando_respuesta_cliente:
        true,

      siguiente_accion_esperada:
        'SOLICITAR_NUEVA_MEDIDA',


      // ----------------------------------------------
      // CONTROL
      // ----------------------------------------------

      finalizado_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// NODO N8N: Preparar derivación humana
// ARCHIVO: code/06-derivacion-humana/preparar-derivacion-humana.js
// VERSION: 3.1
// RESPONSABILIDAD:
// - Recibir la salida DERIVAR_HUMANO de "Enrutar acción comercial" y validar conversacion_id y prospecto_id
// - Convertir la decisión comercial en un contrato estable de HANDOFF (respaldo en "Recuperar decisión comercial")
// - Decidir el motivo funcional (explícito o derivado de la intención) y la clasificación del handoff
// - Decidir la prioridad (IA + reglas deterministas ALTA/MEDIA por motivo)
// - Decidir si requiere notificación interna (motivos notificables o prioridad ALTA)
// - Preservar el mensaje original del cliente, separado del mensaje de transición de Pegaso
// - NO escribir en PostgreSQL (lo hace "Marcar prospecto requiere humano")
// - NO dejar que los nodos posteriores reinterpreten estas decisiones: solo deben preservarlas
// ======================================================

const input = $input.first().json;


// ======================================================
// 1. HELPERS
// ======================================================

function texto(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleano(valor, defecto = false) {

  if (typeof valor === 'boolean') {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return defecto;
}


// ======================================================
// 2. IDENTIDAD
// ======================================================

const conversacionId =
  numeroONull(
    input.conversacion_id
  );

const prospectoId =
  numeroONull(
    input.prospecto_id
  );

const clienteId =
  numeroONull(
    input.cliente_id
  );

const contactoId =
  numeroONull(
    input.contacto_id
  );


if (
  conversacionId === null ||
  conversacionId <= 0
) {

  throw new Error(
    'PREPARAR DERIVACIÓN HUMANA: conversacion_id inválido.'
  );

}


if (
  prospectoId === null ||
  prospectoId <= 0
) {

  throw new Error(
    'PREPARAR DERIVACIÓN HUMANA: prospecto_id inválido.'
  );

}


// ======================================================
// 3. RECUPERAR DECISIÓN COMERCIAL
// ======================================================
//
// El input normalmente ya la contiene.
// Sin embargo dejamos respaldo directo al nodo anterior
// para no perderla si en el futuro cambia la conexión.
//
// ======================================================

let decisionAnterior = {};

try {

  decisionAnterior =
    $('Recuperar decisión comercial')
      .first()
      .json ?? {};

} catch (_) {

  decisionAnterior = {};

}


// ======================================================
// 4. INTENCIÓN / ACCIÓN
// ======================================================

const intencion =
  (
    texto(
      input.intencion
    ) ??
    texto(
      decisionAnterior.intencion
    ) ??
    'OTRO'
  ).toUpperCase();


const accionOriginal =
  (
    texto(
      input.accion
    ) ??
    texto(
      decisionAnterior.accion
    ) ??
    'DERIVAR_HUMANO'
  ).toUpperCase();


// ======================================================
// 5. MENSAJE ORIGINAL DEL CLIENTE
// ======================================================
//
// MUY IMPORTANTE:
//
// Este campo representa exclusivamente lo que escribió
// el prospecto.
//
// Jamás debe reemplazarse posteriormente con el mensaje
// de transición generado por Pegaso.
//
// ======================================================

const mensajeClienteOriginal =
  texto(
    input.mensaje_actual
  ) ??
  texto(
    decisionAnterior.mensaje_actual
  ) ??
  texto(
    input.handoff_mensaje_cliente
  ) ??
  null;


// ======================================================
// 6. DATOS DEL PROSPECTO
// ======================================================

const nombreProspecto =
  texto(
    input.prospecto_nombre
  ) ??
  texto(
    decisionAnterior.prospecto_nombre
  ) ??
  texto(
    input.nombre_whatsapp
  ) ??
  texto(
    decisionAnterior.nombre_whatsapp
  );


const telefono =
  texto(
    input.telefono
  ) ??
  texto(
    decisionAnterior.telefono
  );


const ciudad =
  texto(
    input.prospecto_ciudad
  ) ??
  texto(
    decisionAnterior.prospecto_ciudad
  ) ??
  texto(
    input.ciudad_detectada
  ) ??
  texto(
    decisionAnterior.ciudad_detectada
  );


const provincia =
  texto(
    input.prospecto_provincia
  ) ??
  texto(
    decisionAnterior.prospecto_provincia
  ) ??
  texto(
    input.provincia_detectada
  ) ??
  texto(
    decisionAnterior.provincia_detectada
  );


const clasificacionProspecto =
  texto(
    input.clasificacion_prospecto
  ) ??
  texto(
    input.prospecto_clasificacion
  ) ??
  texto(
    decisionAnterior.clasificacion_prospecto
  ) ??
  texto(
    decisionAnterior.prospecto_clasificacion
  );


// ======================================================
// 7. MOTIVO FUNCIONAL
// ======================================================
//
// Primero respetamos un motivo explícito si ya existe.
//
// Si no existe, lo derivamos desde la intención.
//
// ======================================================

let motivo =
  (
    texto(
      input.handoff_motivo
    ) ??
    texto(
      input.motivo_derivacion
    ) ??
    texto(
      decisionAnterior.handoff_motivo
    ) ??
    texto(
      decisionAnterior.motivo_derivacion
    )
  );


if (motivo) {

  motivo =
    motivo.toUpperCase();

}


if (!motivo) {

  switch (intencion) {

    case 'CONSULTAR_PAGO':

      motivo =
        'SOLICITA_DATOS_PAGO';

      break;


    case 'REPORTAR_PAGO':

      motivo =
        'REPORTA_PAGO';

      break;


    case 'CONFIRMAR_PEDIDO':

      motivo =
        'DESEA_CONTINUAR_PEDIDO';

      break;


    case 'NEGOCIAR':

      motivo =
        'NEGOCIACION_COMERCIAL';

      break;


    case 'RECLAMO':

      motivo =
        'RECLAMO';

      break;


    case 'SOLICITAR_LLAMADA':

      motivo =
        'SOLICITA_LLAMADA';

      break;


    default:

      motivo =
        'ATENCION_COMERCIAL';

  }

}


// ======================================================
// 8. CLASIFICACIÓN HANDOFF
// ======================================================

let clasificacionHandoff =
  texto(
    input.handoff_clasificacion
  ) ??
  texto(
    input.clasificacion_handoff
  ) ??
  texto(
    decisionAnterior.handoff_clasificacion
  ) ??
  texto(
    decisionAnterior.clasificacion_handoff
  );


if (clasificacionHandoff) {

  clasificacionHandoff =
    clasificacionHandoff.toUpperCase();

}


if (!clasificacionHandoff) {

  switch (motivo) {

    case 'SOLICITA_DATOS_PAGO':
    case 'REPORTA_PAGO':
    case 'ENVIA_COMPROBANTE':
    case 'DESEA_CONTINUAR_PEDIDO':

      clasificacionHandoff =
        'CIERRE_COMERCIAL';

      break;


    case 'RECLAMO':

      clasificacionHandoff =
        'POSTVENTA';

      break;


    case 'NEGOCIACION_COMERCIAL':

      clasificacionHandoff =
        'NEGOCIACION';

      break;


    case 'SOLICITA_LLAMADA':

      clasificacionHandoff =
        'CONTACTO_DIRECTO';

      break;


    default:

      clasificacionHandoff =
        'REVISION_COMERCIAL';

  }

}


// ======================================================
// 9. PRIORIDAD
// ======================================================
//
// MUY IMPORTANTE:
//
// La IA ya puede entregar:
//
// prioridad_derivacion = ALTA
//
// Antes nuestro flujo ignoraba ese campo.
//
// ======================================================

let prioridad =
  (
    texto(
      input.handoff_prioridad
    ) ??
    texto(
      input.prioridad_derivacion
    ) ??
    texto(
      decisionAnterior.handoff_prioridad
    ) ??
    texto(
      decisionAnterior.prioridad_derivacion
    ) ??
    'NORMAL'
  ).toUpperCase();


// Reglas determinísticas tienen autoridad mínima.

if (
  motivo === 'SOLICITA_DATOS_PAGO' ||
  motivo === 'REPORTA_PAGO' ||
  motivo === 'ENVIA_COMPROBANTE' ||
  motivo === 'DESEA_CONTINUAR_PEDIDO' ||
  motivo === 'RECLAMO'
) {

  prioridad =
    'ALTA';

}


else if (
  motivo === 'NEGOCIACION_COMERCIAL' ||
  motivo === 'SOLICITA_LLAMADA'
) {

  if (prioridad !== 'ALTA') {

    prioridad =
      'MEDIA';

  }

}


// ======================================================
// 10. RESOLVER NOTIFICACIÓN
// ======================================================
//
// Regla:
// No dependemos solo de la IA.
//
// Los eventos comerciales que necesitan atención pronta
// notifican siempre.
//
// ======================================================

let requiereNotificacion =
  booleano(
    input.requiere_notificacion ??
    input.handoff_requiere_notificacion ??
    decisionAnterior.requiere_notificacion ??
    decisionAnterior.handoff_requiere_notificacion,
    false
  );


const motivosNotificables =
  new Set([
    'SOLICITA_DATOS_PAGO',
    'REPORTA_PAGO',
    'DESEA_CONTINUAR_PEDIDO',
    'NEGOCIACION_COMERCIAL',
    'RECLAMO',
    'SOLICITA_LLAMADA',
    'ENVIA_COMPROBANTE',
    'IMAGEN_REQUIERE_REVISION',
    'ARCHIVO_NO_PROCESABLE',
    'ARCHIVO_DISENO',
    'ARCHIVO_REQUIERE_REVISION',
    'DISENO_REQUIERE_REVISION',
    'COTIZACION_ESPECIAL'
  ]);


if (
  motivosNotificables.has(
    motivo
  )
) {

  requiereNotificacion =
    true;

}


// Prioridad ALTA también obliga notificación.

if (
  prioridad === 'ALTA'
) {

  requiereNotificacion =
    true;

}


// ======================================================
// 11. SALIDA
// ======================================================

return [
  {
    json: {

      ...input,

      // ----------------------------------------------
      // IDENTIDAD
      // ----------------------------------------------

      conversacion_id:
        conversacionId,

      prospecto_id:
        prospectoId,

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      telefono,

      nombre_whatsapp:
        nombreProspecto,

      prospecto_nombre:
        nombreProspecto,

      prospecto_ciudad:
        ciudad,

      prospecto_provincia:
        provincia,

      prospecto_clasificacion:
        clasificacionProspecto,


      // ----------------------------------------------
      // DECISIÓN
      // ----------------------------------------------

      intencion,

      accion_original:
        accionOriginal,

      accion:
        'DERIVAR_HUMANO',

      requiere_humano:
        true,


      // ----------------------------------------------
      // HANDOFF
      // ----------------------------------------------

      handoff_motivo:
        motivo,

      handoff_clasificacion:
        clasificacionHandoff,

      clasificacion_handoff:
        clasificacionHandoff,

      handoff_prioridad:
        prioridad,

      prioridad_derivacion:
        prioridad,


      // ----------------------------------------------
      // NOTIFICACIÓN
      // ----------------------------------------------

      requiere_notificacion:
        requiereNotificacion,

      handoff_requiere_notificacion:
        requiereNotificacion,


      // ----------------------------------------------
      // MENSAJE ORIGINAL CLIENTE
      // ----------------------------------------------

      mensaje_cliente_original:
        mensajeClienteOriginal,

      handoff_mensaje_cliente:
        mensajeClienteOriginal,


      // ----------------------------------------------
      // CONTROL
      // ----------------------------------------------

      handoff_at:
