function booleano(
  valor,
  defecto = false
) {

  if (
    typeof valor === 'boolean'
  ) {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return defecto;
}


function textoONull(
  valor
) {

  if (
