  mensaje =
    $('Normalizar mensaje').first().json ?? {};
} catch (error) {
  mensaje = {};
}


// ======================================================
// 2. RECUPERAR CONFIGURACIÓN
// ======================================================

function objetoJSON(valor) {
  if (valor && typeof valor === 'object' && !Array.isArray(valor)) {
    return valor;
  }

  if (typeof valor === 'string') {
    try {
      const parsed = JSON.parse(valor);

      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        return parsed;
      }
    } catch (error) {
      return null;
    }
  }

  return null;
}

const filasConfig =
  $input.all().map(item => item.json ?? {});

function configPorClave(clave) {
  const fila = filasConfig.find(f => f.clave === clave);

  return fila ? objetoJSON(fila.valor_json) : null;
}

const config =
  configPorClave('MODO_PRUEBA') ?? {
    activo: true,
    telefonos_permitidos: []
  };


// ======================================================
// 2.1. CONFIGURACIÓN DEL TURNO CONVERSACIONAL
// ======================================================

const configDebounce =
  configPorClave('DEBOUNCE_WHATSAPP') ?? {};

function enteroEnRango(valor, minimo, maximo, defecto) {
  const n = Number(valor);

  if (valor === null || valor === undefined || valor === '' || !Number.isFinite(n)) {
    return defecto;
  }

  return Math.min(maximo, Math.max(minimo, Math.round(n)));
}

const debounceMsNormal = enteroEnRango(
  configDebounce.debounce_ms,
  0,
  DEBOUNCE_WHATSAPP_MS_MAXIMO,
  DEBOUNCE_WHATSAPP_MS_DEFECTO
);

const debouncePrimerContactoMs = enteroEnRango(
  configDebounce.debounce_primer_contacto_ms,
  0,
  DEBOUNCE_WHATSAPP_MS_MAXIMO,
  Math.max(debounceMsNormal, DEBOUNCE_PRIMER_CONTACTO_MS_DEFECTO)
);

const turnoMaxAntiguedadSegundos = enteroEnRango(
  configDebounce.turno_max_antiguedad_segundos,
  60,
  86400,
  TURNO_MAX_ANTIGUEDAD_SEGUNDOS_DEFECTO
);


// ======================================================
// 3. NORMALIZAR TELÉFONO
// ======================================================

const telefono = String(
  mensaje.telefono ??
  mensaje.wa_id ??
  mensaje.from ??
  ''
)
  .replace(/\D/g, '')
  .trim();


// ======================================================
// 4. RESOLVER MODO PRUEBA
// ======================================================

const modoPrueba =
  config.activo === true;


// ======================================================
// 5. NORMALIZAR TELÉFONOS AUTORIZADOS
// ======================================================

const telefonosPermitidos =
  Array.isArray(config.telefonos_permitidos)
    ? config.telefonos_permitidos
        .map(t =>
          String(t ?? '')
            .replace(/\D/g, '')
            .trim()
        )
        .filter(Boolean)
    : [];


// ======================================================
// 6. COMPROBAR AUTORIZACIÓN
// ======================================================

const telefonoPermitido =
  telefono !== '' &&
  telefonosPermitidos.includes(telefono);


// ======================================================
// 7. DECISIÓN
// ======================================================
//
// Si modo prueba está apagado:
//   BOT habilitado.
//
// Si modo prueba está encendido:
//   BOT solamente para teléfonos autorizados.
// ======================================================

const puedeResponderBot =
  modoPrueba === false ||
  telefonoPermitido === true;


// ======================================================
// 8. MOTIVO
// ======================================================

let motivoBloqueo = null;

if (!puedeResponderBot) {

  if (!telefono) {
    motivoBloqueo =
      'MODO_PRUEBA_TELEFONO_NO_IDENTIFICADO';
  } else {
    motivoBloqueo =
      'MODO_PRUEBA_TELEFONO_NO_AUTORIZADO';
  }

}


// ======================================================
// 9. RECUPERAR INFORMACIÓN DE CONVERSACIÓN
// ======================================================
//
// Nos interesa conservar IDs para diagnóstico.
// ======================================================

let conversacion = {};

try {
  conversacion =
    $('Preparar conversación').first().json ?? {};
} catch (error) {
  conversacion = {};
}


// ======================================================
// 9.1. PRIMER CONTACTO (DEBOUNCE EXTENDIDO)
// ======================================================

let eventoWhatsApp = {};

try {
  eventoWhatsApp =
    $('Normalizar evento WhatsApp').first().json?.evento_whatsapp ?? {};
} catch (error) {
  eventoWhatsApp = {};
}

const sesionActualizadaMs = Date.parse(
  conversacion.contexto_comercial?.sesion?.actualizado_at ?? ''
);

const sinTurnoBotReciente =
  !Number.isFinite(sesionActualizadaMs) ||
  Date.now() - sesionActualizadaMs > SESION_PRIMER_CONTACTO_HORAS * 3600 * 1000;

let debounceMotivo = 'NORMAL';

if (eventoWhatsApp.es_lead_anuncio === true) {
  debounceMotivo = 'PRIMER_CONTACTO_ANUNCIO';
} else if (conversacion.conversacion_nueva === true) {
  debounceMotivo = 'PRIMER_CONTACTO_CONVERSACION_NUEVA';
} else if (sinTurnoBotReciente) {
  debounceMotivo = 'PRIMER_CONTACTO_SESION_NUEVA';
}

const debounceMs =
  debounceMotivo === 'NORMAL'
    ? debounceMsNormal
    : Math.max(debounceMsNormal, debouncePrimerContactoMs);


// ======================================================
// 10. SALIDA
// ======================================================

return [
  {
    json: {

      // ----------------------------------------------
      // Identidad del mensaje
      // ----------------------------------------------

      telefono,

      mensaje_actual:
        mensaje.mensaje_actual ??
        mensaje.contenido ??
        mensaje.texto ??
        null,

      tipo_mensaje:
        mensaje.tipo_mensaje ??
        mensaje.tipo ??
        null,


      // ----------------------------------------------
      // Conversación
      // ----------------------------------------------

      conversacion_id:
        conversacion.conversacion_id ??
        conversacion.id ??
        null,

      prospecto_id:
        conversacion.prospecto_id ??
        null,

      cliente_id:
        conversacion.cliente_id ??
        null,


      // ----------------------------------------------
      // Configuración BOT
      // ----------------------------------------------

      modo_prueba:
        modoPrueba,

      telefono_prueba_permitido:
        telefonoPermitido,

      puede_responder_bot:
        puedeResponderBot,

      motivo_bloqueo_bot:
        motivoBloqueo,


      // ----------------------------------------------
      // Turno conversacional (debounce)
      // ----------------------------------------------

      debounce_ms:
        debounceMs,

      debounce_segundos:
        debounceMs / 1000,

      debounce_motivo:
        debounceMotivo,

      turno_max_antiguedad_segundos:
        turnoMaxAntiguedadSegundos,

      debounce_configurado:
        Object.keys(configDebounce).length > 0,


      // ----------------------------------------------
      // Diagnóstico
      // ----------------------------------------------

      telefonos_permitidos_configurados:
        telefonosPermitidos.length,

      permiso_resuelto_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// FINALIZAR MENSAJE - MODO PRUEBA
// ======================================================
//
// El mensaje YA fue guardado.
//
// Este número no tiene autorización para ser atendido
// automáticamente mientras MODO_PRUEBA esté activo.
//
// No llamar IA.
// No cotizar.
// No responder WhatsApp.
// No modificar la conversación comercial.
// ======================================================

const input =
  $input.first()?.json ?? {};

return [
  {
    json: {

      success: true,

      flujo:
        'MODO_PRUEBA',

      mensaje_guardado:
        true,

      respuesta_automatica:
        false,

      automatizacion_ejecutada:
        false,

      modo_prueba:
        input.modo_prueba === true,

      telefono_prueba_permitido:
        input.telefono_prueba_permitido === true,

      puede_responder_bot:
        false,

      motivo:
        input.motivo_bloqueo_bot ??
        'MODO_PRUEBA_TELEFONO_NO_AUTORIZADO',

      telefono:
        input.telefono ?? null,

      conversacion_id:
        input.conversacion_id ?? null,

      prospecto_id:
        input.prospecto_id ?? null,

      finalizado_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// VALIDAR VERIFICACIÓN DE WEBHOOK DE META / WHATSAPP
// ======================================================

const input = $input.first().json;

// Query parameters enviados por Meta
const query = input.query ?? {};

// Datos de verificación
const mode = query['hub.mode'] ?? null;
const verifyToken = query['hub.verify_token'] ?? null;
const challenge = query['hub.challenge'] ?? null;

// IMPORTANTE:
// Debe ser exactamente el mismo token colocado en Meta.
const EXPECTED_VERIFY_TOKEN = 'pegaso_whatsapp_verify_2026';

// Validación
const tokenValido =
  mode === 'subscribe' &&
  verifyToken === EXPECTED_VERIFY_TOKEN &&
  challenge !== null &&
  challenge !== undefined &&
  String(challenge).trim() !== '';

// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      ...input,

      meta_verificacion: {
        valido: tokenValido,

        mode,
        challenge:
          challenge !== null && challenge !== undefined
            ? String(challenge)
            : null,

        token_recibido: verifyToken !== null,

        motivo: tokenValido
          ? 'VERIFICACION_META_OK'
          : 'VERIFICACION_META_RECHAZADA'
      }
    }
  }
];

// ======================================================
// NODO N8N: Normalizar evento WhatsApp
// ARCHIVO: code/01-entrada/normalizar-evento-whatsapp.js
// VERSION: 2.2
// RESPONSABILIDAD:
// - Detectar el origen del webhook:
//      1. YCloud inbound:
//         whatsapp.inbound_message.received
//
//      2. YCloud WhatsApp Business App / dispositivo:
//         whatsapp.smb.message.echoes
//
//      3. Meta Cloud API directo:
//         body.entry
//
// - Extraer cuenta Pegaso, cliente y mensaje a un objeto
//   evento_whatsapp uniforme.
//
// - Mantener compatibilidad con todo el flujo existente:
//      telefono_cliente
//      wa_id
//      user_id
//      nombre_cliente
//      mensaje_id
//      timestamp
//      tipo_mensaje
//      texto
//      caption
//      media_*
//
// - Extraer multimedia:
//      imagen
//      audio
//      documento
//      video
//
// - Identificar mensajes enviados manualmente desde
//   WhatsApp Business de Pegaso.
//
// - Clasificar cada evento en clasificacion_mensaje:
//      ENTRANTE_CLIENTE / SALIENTE_HUMANO / SALIENTE_AUTOMATICO.
//   Todo echo es direccion SALIENTE y va a la ruta de
//   salida; nunca entra como mensaje del cliente.
//   SALIENTE_AUTOMATICO = automatización de la app
//   WhatsApp Business (bienvenida / respuestas de las
//   preguntas rápidas del anuncio): se registra pero NO
//   marca atención humana.
//
// - Exponer el contexto de anuncio (referral CTWA) del
//   mensaje entrante: es_lead_anuncio y anuncio.
//
// - NO guardar mensajes.
// - NO modificar prospectos.
// - NO decidir si debe intervenir humano.
// - NO descargar multimedia.
// ======================================================

const input = $input.first().json;
const body = input.body ?? {};


// ======================================================
// 0. AUTOMATIZACIONES DE WHATSAPP BUSINESS
// ======================================================
//
// YCloud entrega los mensajes automáticos de la app
// WhatsApp Business (bienvenida, respuesta del anuncio)
// como whatsapp.smb.message.echoes, con exactamente los
// mismos campos que un mensaje escrito por una persona.
// No existe bandera que los distinga, por eso se
// reconocen por su texto configurado.
//
// Si se cambia una automatización en la app, actualizar
// aquí su texto normalizado (minúsculas, sin tildes,
// sin signos ni emojis).
//
// exacto = true: el mensaje debe ser solo esa frase.
// exacto = false: basta con que empiece por esa frase.
//
// accion_equivalente: lo que ese mensaje ya le pidió o
// dijo al cliente, para no repetirlo desde el BOT.
// ======================================================

const AUTOMATIZACIONES_WHATSAPP_BUSINESS = [
  {
    codigo: 'RESPUESTA_ANUNCIO_MEDIDAS',
    texto: 'claro con mucho gusto le podemos ayudar en que medidas requiere sus etiquetas',
    exacto: false,
    accion_equivalente: 'PEDIR_MEDIDAS'
  },
  {
    codigo: 'BIENVENIDA_PEGASO',
    texto: 'gracias por comunicarte con pegaso adhesivos le saluda borys espinoza',
    exacto: false,
    accion_equivalente: 'SALUDO'
  },
  {
    codigo: 'BIENVENIDA_ANUNCIO',
    texto: 'hola le saluda borys espinoza como puedo ayudarle',
    exacto: true,
    accion_equivalente: 'SALUDO'
  },
  {
    codigo: 'RESPUESTA_ANUNCIO_MATERIAL',
    texto: 'trabajamos con plastico polipropileno de alta adherencia',
    exacto: false,
    accion_equivalente: 'INFORMAR_MATERIAL'
  }
];


// ======================================================
// 1. HELPERS
// ======================================================

const limpiarTelefono = (valor) => {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const limpio = String(valor)
    .replace(/[^\d]/g, '')
    .trim();

  return limpio || null;
};


const textoONull = (valor) => {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
};


const isoAUnix = (valor) => {
  if (!valor) {
    return null;
  }

  const fecha =
    new Date(valor);

  if (
    Number.isNaN(
      fecha.getTime()
    )
  ) {
    return valor;
  }

  return String(
    Math.floor(
      fecha.getTime() / 1000
    )
  );
};


const normalizarHuella = (valor) =>
  String(valor ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();


const resolverAutomatizacion = (valor) => {
  const huella =
    normalizarHuella(valor);

  if (!huella) {
    return null;
  }

  return AUTOMATIZACIONES_WHATSAPP_BUSINESS.find(
    a =>
      a.exacto
        ? huella === a.texto
        : huella.startsWith(a.texto)
  ) ?? null;
};


const extraerAnuncio = (referral) => {
  if (
    !referral ||
    typeof referral !== 'object'
  ) {
    return null;
  }

  const sourceType =
    textoONull(referral.source_type)?.toLowerCase() ?? null;

  const ctwaClid =
    textoONull(referral.ctwa_clid);

  if (
    sourceType !== 'ad' &&
    !ctwaClid
  ) {
    return null;
  }

  return {
    source_type: sourceType,
    source_id: textoONull(referral.source_id),
    source_url: textoONull(referral.source_url),
    headline: textoONull(referral.headline),
    ctwa_clid: ctwaClid,
    welcome_message:
      textoONull(referral.welcome_message?.text)
  };
};


// ======================================================
// 2. DETECTAR TIPO DE EVENTO
// ======================================================

const tipoEvento =
  textoONull(
    body.type
  );


// ------------------------------------------------------
// YCLOUD - MENSAJE ENTRANTE DEL CLIENTE
// ------------------------------------------------------

const esYCloudInbound =
  tipoEvento ===
    'whatsapp.inbound_message.received' &&
  !!body.whatsappInboundMessage;


// ------------------------------------------------------
// YCLOUD - MENSAJE ENVIADO DESDE WHATSAPP BUSINESS
// ------------------------------------------------------
//
// Este evento aparece cuando alguien escribe desde:
//
// - WhatsApp Business App
// - WhatsApp Web vinculado
// - dispositivo vinculado
//
// No corresponde al webhook inbound del cliente.
//
// Ejemplo:
// from = número Pegaso
// to   = número cliente
//
// ------------------------------------------------------

const esYCloudEchoHumano =
  tipoEvento ===
    'whatsapp.smb.message.echoes' &&
  !!body.whatsappMessage;


// ------------------------------------------------------
// META CLOUD API DIRECTO
// ------------------------------------------------------

const esMeta =
  Array.isArray(
    body.entry
  );


// ======================================================
// 3. VALORES NORMALIZADOS
// ======================================================

let procesable = false;

let object = null;
let field = null;

let phoneNumberId = null;
let displayPhoneNumber = null;

let telefonoCliente = null;
let waId = null;
let userId = null;
let nombreCliente = null;

let mensajeId = null;
let timestamp = null;
let tipo = null;

let texto = null;
let caption = null;

let mediaId = null;
let mediaMimeType = null;
let mediaSha256 = null;
let mediaLink = null;

let origen = null;

let proveedorEventoId = null;
let wabaId = null;


// ======================================================
// 4. NUEVOS CAMPOS DE CONTROL
// ======================================================

let direccion = null;

let actor = null;

let esMensajeEntrante = false;

let esMensajeHumanoPegaso = false;

let esMensajeAutomaticoPegaso = false;

let clasificacionMensaje = null;

let automatizacion = null;

let anuncio = null;

let eventoConversacional = false;


// ======================================================
// 5. HELPER MULTIMEDIA YCLOUD
// ======================================================
//
// Tanto whatsappInboundMessage como whatsappMessage
// pueden contener estructuras multimedia similares.
//
// ======================================================

function extraerMediaYCloud(message, tipoMensaje) {

  if (
    !message ||
    !tipoMensaje
  ) {
    return {
      id: null,
      mimeType: null,
      sha256: null,
      caption: null,
      link: null
    };
  }


  if (
    ![
      'image',
      'audio',
      'document',
      'video',
      'sticker'
    ].includes(tipoMensaje)
  ) {
    return {
      id: null,
      mimeType: null,
      sha256: null,
      caption: null,
      link: null
    };
  }


  const media =
    message[tipoMensaje] ?? {};


  return {

    id:
      media.id ??
      media.mediaId ??
      null,

    mimeType:
      media.mimeType ??
      media.mime_type ??
      null,

    sha256:
      media.sha256 ??
      null,

    caption:
      media.caption ??
      null,

    link:
      media.link ??
      null
  };
}


// ======================================================
// 6. YCLOUD - MENSAJE ENTRANTE
// ======================================================

if (esYCloudInbound) {

  const message =
    body.whatsappInboundMessage ?? {};


  // ----------------------------------------------------
  // ORIGEN
  // ----------------------------------------------------

  origen =
    'YCLOUD';

  proveedorEventoId =
    body.id ?? null;


  // ----------------------------------------------------
  // COMPATIBILIDAD
  // ----------------------------------------------------

  object =
    'whatsapp_business_account';

  field =
    'messages';


  // ----------------------------------------------------
  // CLASIFICACIÓN
  // ----------------------------------------------------

  direccion =
    'ENTRANTE';

  actor =
    'PROSPECTO';

  esMensajeEntrante =
    true;

  esMensajeHumanoPegaso =
    false;

  clasificacionMensaje =
    'ENTRANTE_CLIENTE';

  eventoConversacional =
    true;


  // ----------------------------------------------------
  // ANUNCIO (Click to WhatsApp)
  // ----------------------------------------------------
  //
  // Meta adjunta referral al primer mensaje que llega
  // desde un anuncio. La app WhatsApp Business responde
  // sola a ese mensaje y su eco llega segundos después.
  //
  // ----------------------------------------------------

  anuncio =
    extraerAnuncio(
      message.referral
    );


  // ----------------------------------------------------
  // CUENTA PEGASO
  // ----------------------------------------------------

  wabaId =
    message.wabaId ??
    null;


  // YCloud no entrega aquí Meta phone_number_id.
  phoneNumberId =
    null;


  displayPhoneNumber =
    limpiarTelefono(
      message.to
    );


  // ----------------------------------------------------
  // CLIENTE
  // ----------------------------------------------------

  telefonoCliente =
    limpiarTelefono(
      message.from
    );


  waId =
    limpiarTelefono(
      message.from
    );


  userId =
    message.fromUserId ??
    null;


  nombreCliente =
    message.customerProfile?.name ??
    null;


  // ----------------------------------------------------
  // MENSAJE
  // ----------------------------------------------------

  mensajeId =
    message.wamid ??
    message.id ??
    null;


  timestamp =
    isoAUnix(
      message.sendTime ??
      message.createTime
    );


  tipo =
    textoONull(
      message.type
    )?.toLowerCase() ??
    null;


  // ----------------------------------------------------
  // TEXTO
  // ----------------------------------------------------

  if (
    tipo === 'text'
  ) {

    texto =
      message.text?.body ??
      null;
  }


  // ----------------------------------------------------
  // MULTIMEDIA
  // ----------------------------------------------------

  const media =
    extraerMediaYCloud(
      message,
      tipo
    );


  mediaId =
    media.id;

  mediaMimeType =
    media.mimeType;

  mediaSha256 =
    media.sha256;

  mediaLink =
    media.link;

  caption =
    media.caption;


  // ----------------------------------------------------
  // PROCESABLE
  // ----------------------------------------------------

  procesable =
    !!mensajeId &&
    !!telefonoCliente &&
    !!tipo;
}


// ======================================================
// 7. YCLOUD - MENSAJE HUMANO DE PEGASO
// ======================================================
//
// Ejemplo real:
//
// type:
// whatsapp.smb.message.echoes
//
// whatsappMessage:
// {
//   from: "+593962645735",
//   to: "+593996588558",
//   type: "text",
//   text: {
//     body: "hola otra vez"
//   }
// }
//
// IMPORTANTE:
//
// En este evento:
//
// from = PEGASO
// to   = CLIENTE
//
// Por eso telefono_cliente sale de message.to.
//
// ======================================================

else if (esYCloudEchoHumano) {

  const message =
    body.whatsappMessage ?? {};


  // ----------------------------------------------------
  // ORIGEN
  // ----------------------------------------------------

  origen =
    'YCLOUD';

  proveedorEventoId =
    body.id ?? null;


  // ----------------------------------------------------
  // COMPATIBILIDAD
  // ----------------------------------------------------
  //
  // Conservamos estos valores para no romper nodos que
  // esperan la estructura histórica.
  //
  // ----------------------------------------------------

  object =
    'whatsapp_business_account';

  field =
    'messages';


  // ----------------------------------------------------
  // CLASIFICACIÓN
  // ----------------------------------------------------

  direccion =
    'SALIENTE';

  automatizacion =
    textoONull(message.type)?.toLowerCase() === 'text'
      ? resolverAutomatizacion(
          message.text?.body
        )
      : null;

  esMensajeAutomaticoPegaso =
    automatizacion !== null;

  actor =
    esMensajeAutomaticoPegaso
      ? 'AUTOMATIZACION_WHATSAPP_BUSINESS'
      : 'HUMANO_PEGASO';

  esMensajeEntrante =
    false;

  esMensajeHumanoPegaso =
    !esMensajeAutomaticoPegaso;

  clasificacionMensaje =
    esMensajeAutomaticoPegaso
      ? 'SALIENTE_AUTOMATICO'
      : 'SALIENTE_HUMANO';

  eventoConversacional =
    true;


  // ----------------------------------------------------
  // CUENTA PEGASO
  // ----------------------------------------------------

  wabaId =
    message.wabaId ??
    null;


  phoneNumberId =
    null;


  // En echo:
  // FROM = PEGASO

  displayPhoneNumber =
    limpiarTelefono(
      message.from
    );


  // ----------------------------------------------------
  // CLIENTE
  // ----------------------------------------------------
  //
  // En echo:
  // TO = CLIENTE
  //
  // ----------------------------------------------------

  telefonoCliente =
    limpiarTelefono(
      message.to
    );


  waId =
    limpiarTelefono(
      message.to
    );


  userId =
    message.toUserId ??
    null;


  // El evento echo normalmente no trae
  // customerProfile del cliente.
  nombreCliente =
    message.customerProfile?.name ??
    null;


  // ----------------------------------------------------
  // MENSAJE
  // ----------------------------------------------------

  mensajeId =
    message.wamid ??
    message.id ??
    null;


  timestamp =
    isoAUnix(
      message.sendTime ??
      message.createTime
    );


  tipo =
    textoONull(
      message.type
    )?.toLowerCase() ??
    null;


  // ----------------------------------------------------
  // TEXTO
  // ----------------------------------------------------

  if (
    tipo === 'text'
  ) {

    texto =
      message.text?.body ??
      null;
  }


  // ----------------------------------------------------
  // MULTIMEDIA
  // ----------------------------------------------------
  //
  // Dejamos soporte también para que una persona de
  // Pegaso pueda enviar imagen/documento/video/etc.
  //
  // ----------------------------------------------------

  const media =
    extraerMediaYCloud(
      message,
      tipo
    );


  mediaId =
    media.id;

  mediaMimeType =
    media.mimeType;

  mediaSha256 =
    media.sha256;

  mediaLink =
    media.link;

  caption =
    media.caption;


  // ----------------------------------------------------
  // PROCESABLE
  // ----------------------------------------------------
  //
  // Sí es un evento conversacional válido.
  //
  // El IF "¿Mensaje humano de Pegaso?" debe interceptarlo
  // ANTES del flujo normal del prospecto.
  //
  // ----------------------------------------------------

  procesable =
    !!mensajeId &&
    !!telefonoCliente &&
    !!tipo;
}


// ======================================================
// 8. META CLOUD API DIRECTO
// ======================================================

else if (esMeta) {

  const entry =
    body.entry?.[0] ?? {};

  const change =
    entry.changes?.[0] ?? {};


  field =
    change.field ??
    null;


  const value =
    change.value ?? {};

  const metadata =
    value.metadata ?? {};

  const contacts =
    value.contacts ?? [];

  const messages =
    value.messages ?? [];


  const contact =
    contacts[0] ?? {};

  const message =
    messages[0] ?? {};


  tipo =
    textoONull(
      message.type
    )?.toLowerCase() ??
    null;


  origen =
    'META_CLOUD_API';


  object =
    body.object ??
    null;


  // ----------------------------------------------------
  // CLASIFICACIÓN
  // ----------------------------------------------------

  direccion =
    'ENTRANTE';

  actor =
    'PROSPECTO';

  esMensajeEntrante =
    messages.length > 0;

  esMensajeHumanoPegaso =
    false;

  clasificacionMensaje =
    messages.length > 0
      ? 'ENTRANTE_CLIENTE'
      : null;

  eventoConversacional =
    messages.length > 0;


  // ----------------------------------------------------
  // CUENTA PEGASO
  // ----------------------------------------------------

  phoneNumberId =
    metadata.phone_number_id ??
    null;


  displayPhoneNumber =
    limpiarTelefono(
      metadata.display_phone_number
    );


  wabaId =
    entry.id ??
    null;


  // ----------------------------------------------------
  // CLIENTE
  // ----------------------------------------------------

  telefonoCliente =
    limpiarTelefono(
      message.from ??
      contact.wa_id
    );


  waId =
    limpiarTelefono(
      contact.wa_id
    );


  userId =
    contact.user_id ??
    null;


  nombreCliente =
    contact.profile?.name ??
    null;


  // ----------------------------------------------------
  // MENSAJE
  // ----------------------------------------------------

  mensajeId =
    message.id ??
    null;


  timestamp =
    message.timestamp ??
    null;


  // ----------------------------------------------------
  // TEXTO
  // ----------------------------------------------------

  if (
    tipo === 'text'
  ) {

    texto =
      message.text?.body ??
      null;
  }


  // ----------------------------------------------------
  // IMAGEN
  // ----------------------------------------------------

  if (
    tipo === 'image'
  ) {

    mediaId =
      message.image?.id ??
      null;

    mediaMimeType =
      message.image?.mime_type ??
      null;

    mediaSha256 =
      message.image?.sha256 ??
