}


function mimeBase(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .trim()
      .toLowerCase();

  if (!limpio) {
    return null;
  }

  return limpio
    .split(';')[0]
    .trim() || null;
}


function normalizarCaption(valor) {
  if (
