    input.mensaje_db_id
  );


const conversacionId =
  numeroONull(
    input.conversacion_id ??
    prepararMensajeHumano.conversacion_id ??
    prepararDerivacionHumana.conversacion_id ??
    guardarContextoHandoff.conversacion_id ??
    decision.conversacion_id ??
    entradaWhatsApp.conversacion_id
  );


// ======================================================
// 5. RESOLVER TEXTO DE SALIDA
// ======================================================
//
// Primera opción:
// contenido ya persistido en mensajes.
//
// Los demás son únicamente fallbacks de seguridad.
//
// ======================================================

const textoSalida =
  textoONull(
    input.contenido
  ) ??

  textoONull(
    input.texto_salida
  ) ??

  // Handoff humano
  textoONull(
    prepararMensajeHumano.mensaje_salida
  ) ??

  textoONull(
    prepararMensajeHumano.mensaje_transicion
  ) ??

  textoONull(
    prepararMensajeHumano.handoff_mensaje_transicion
  ) ??

  // Respuesta comercial
  textoONull(
    prepararRespuestaComercial.mensaje_salida
  ) ??

  textoONull(
    prepararRespuestaComercial.mensaje_comercial
  ) ??

  // Cotización
  textoONull(
    prepararMensajeCotizacion.mensaje_salida
  ) ??

  textoONull(
    prepararMensajeCotizacion.mensaje_comercial
  ) ??

  null;


if (!textoSalida) {

  throw new Error(
    'PREPARAR ENVÍO WHATSAPP: el mensaje saliente no contiene texto.'
  );

}


// ======================================================
// 6. RESOLVER TELÉFONO DESTINO
// ======================================================
//
// El mensaje guardado puede NO conservar teléfono.
//
// Prioridad:
//
// 1. input actual
// 2. decisión comercial
// 3. mensaje humano
// 4. derivación humana
// 5. contexto handoff
// 6. entrada WhatsApp
// 7. evento normalizado
//
// ======================================================

let telefonoDestino =
  limpiarTelefono(
    input.telefono_destino
  ) ??

  limpiarTelefono(
    input.telefono
  ) ??

  limpiarTelefono(
    decision.telefono
  ) ??

  limpiarTelefono(
    prepararMensajeHumano.telefono
  ) ??

  limpiarTelefono(
    prepararDerivacionHumana.telefono
  ) ??

  limpiarTelefono(
    guardarContextoHandoff.telefono
  ) ??

  limpiarTelefono(
    prepararContextoHandoff.telefono
  ) ??

  limpiarTelefono(
    entradaWhatsApp.telefono
  ) ??

  limpiarTelefono(
    eventoWhatsApp.telefono_cliente
  ) ??

  limpiarTelefono(
    eventoWhatsApp.from
  ) ??

  limpiarTelefono(
    eventoWhatsApp.wa_id
  );


if (!telefonoDestino) {

  throw new Error(
    'PREPARAR ENVÍO WHATSAPP: no se pudo resolver el teléfono destino.'
  );

}


// ======================================================
// 7. DETERMINAR SI VIENE DE WHATSAPP REAL
// ======================================================
//
// Camino real:
//
// Webhook YCloud
//   → Normalizar evento WhatsApp
//   → Preparar entrada WhatsApp
//   → ...
//
// Camino TEST:
//
// Execute workflow
//   → Mensaje TEST
//
// Solo enviamos físicamente cuando la ejecución pertenece
// a un mensaje WhatsApp real.
//
// ======================================================

const canalEntrada =
  String(
    entradaWhatsApp.canal ??
    eventoWhatsApp.canal ??
    ''
  )
    .trim()
    .toUpperCase();


const entradaPreparada =
  entradaWhatsApp
    .entrada_whatsapp_preparada === true;


const eventoProcesable =
  eventoWhatsApp.procesable === true;


const vieneDeWhatsAppReal =
  (
    entradaPreparada &&
    canalEntrada === 'WHATSAPP'
  )
  ||
  (
    eventoProcesable &&
    String(
      eventoWhatsApp.canal ?? ''
    )
      .trim()
      .toUpperCase() === 'WHATSAPP'
  );


// ======================================================
// 8. RESOLVER PROVEEDOR
// ======================================================
//
// El proveedor puede venir explícitamente del evento.
//
// También aceptamos el hecho de que el evento normalizado
// venga del webhook YCloud.
//
// ======================================================

let proveedor =
  textoONull(
    eventoWhatsApp.origen
  ) ??

  textoONull(
    eventoWhatsApp.proveedor
  ) ??

  textoONull(
    entradaWhatsApp.origen
  ) ??

  textoONull(
    entradaWhatsApp.proveedor_whatsapp
  ) ??

  null;


if (proveedor) {
  proveedor =
    proveedor.toUpperCase();
}


// Si existe un evento real YCloud pero el normalizador
// todavía no expone origen explícitamente, podemos
// reconocerlo por la estructura del evento.
//
// NO se aplica en ejecuciones manuales.
if (
  !proveedor &&
  vieneDeWhatsAppReal &&
  (
    eventoWhatsApp.waba_id ||
    eventoWhatsApp.mensaje_id ||
    entradaWhatsApp.meta_whatsapp
  )
) {

  proveedor =
    'YCLOUD';

}


const vieneDeYCloud =
  proveedor === 'YCLOUD';


// ======================================================
// 9. RESOLVER NÚMERO EMISOR PEGASO
// ======================================================
//
// YCloud inbound:
//
// from = cliente
// to   = Pegaso
//
// En la normalización normalmente:
//
// display_phone_number = número Pegaso.
//
// ======================================================

const metaWhatsApp =
  (
    entradaWhatsApp.meta_whatsapp &&
    typeof entradaWhatsApp.meta_whatsapp === 'object'
  )
    ? entradaWhatsApp.meta_whatsapp
    : {};


let telefonoEmisor =
  limpiarTelefono(
    eventoWhatsApp.display_phone_number
  ) ??

  limpiarTelefono(
    eventoWhatsApp.telefono_emisor
  ) ??

  limpiarTelefono(
    entradaWhatsApp.display_phone_number
  ) ??

  limpiarTelefono(
    metaWhatsApp.display_phone_number
  ) ??

  null;


// ------------------------------------------------------
// Fallback operativo.
//
// Número oficial actualmente conectado a YCloud.
//
// Si Pegaso trabaja después con múltiples números,
// este fallback debe desaparecer y resolverse por WABA.
// ------------------------------------------------------

if (!telefonoEmisor) {

  telefonoEmisor =
    '593962645735';

}


// ======================================================
// 10. RESOLVER TIPO DE MENSAJE
// ======================================================
//
// `HANDOFF_HUMANO` describe el propósito comercial,
// pero físicamente sigue siendo un mensaje de texto.
//
// ======================================================

const tipoOriginal =
  String(
    input.tipo ??
    input.tipo_salida ??
    input.tipo_mensaje_salida ??
    prepararMensajeHumano.tipo_mensaje_salida ??
    'TEXTO'
  )
    .trim()
    .toUpperCase();


const tiposTransportablesComoTexto = [
  'TEXTO',
  'TEXT',
  'HANDOFF_HUMANO',
  'RESPUESTA_COMERCIAL',
  'COTIZACION'
];


const esTexto =
  tiposTransportablesComoTexto
    .includes(tipoOriginal);


// Para YCloud siempre será físicamente "text".
const tipoYCloud =
  'text';


// ======================================================
// 11. DECIDIR SI SE ENVÍA
// ======================================================

const respuestaOmitida =
  String(textoSalida ?? '')
    .trim()
    .startsWith('[RESPUESTA AUTOMÁTICA OMITIDA') ||
  (
    prepararRespuestaComercial.omitir_envio === true &&
    String(textoSalida ?? '').trim() ===
      String(prepararRespuestaComercial.respuesta_final ?? '').trim()
  );


const enviarWhatsApp =
  !respuestaOmitida &&
  vieneDeWhatsAppReal &&
  vieneDeYCloud &&
  esTexto &&
  Boolean(telefonoDestino) &&
  Boolean(telefonoEmisor) &&
  Boolean(textoSalida);


// ======================================================
// 12. MOTIVO DE NO ENVÍO
// ======================================================

let motivoNoEnvio =
  null;


if (!enviarWhatsApp) {

  if (respuestaOmitida) {

    motivoNoEnvio =
      'RESPUESTA_OMITIDA_DUPLICADA';

  }

  else if (!vieneDeWhatsAppReal) {

    motivoNoEnvio =
      'EJECUCION_NO_ORIGINADA_EN_WEBHOOK_WHATSAPP';

  }

  else if (!vieneDeYCloud) {

    motivoNoEnvio =
      'ORIGEN_NO_ES_YCLOUD';

  }

  else if (!esTexto) {

    motivoNoEnvio =
      'TIPO_MENSAJE_NO_SOPORTADO';

  }

  else if (!telefonoDestino) {

    motivoNoEnvio =
      'TELEFONO_DESTINO_FALTANTE';

  }

  else if (!telefonoEmisor) {

    motivoNoEnvio =
      'TELEFONO_EMISOR_FALTANTE';

  }

  else if (!textoSalida) {

    motivoNoEnvio =
      'TEXTO_SALIDA_FALTANTE';

  }

  else {

    motivoNoEnvio =
      'DATOS_ENVIO_INCOMPLETOS';

  }

}


// ======================================================
// 13. BODY YCLOUD
// ======================================================

const bodyYCloud = {

  from:
    telefonoE164(
      telefonoEmisor
    ),

  to:
    telefonoE164(
      telefonoDestino
    ),

  type:
    tipoYCloud,

  text: {
    body:
      textoSalida
  }

};


// ======================================================
// 13.1 IMAGEN INFORMATIVA (ANTES DEL TEXTO)
// ======================================================
//
// Solo cuando "Resolver contexto comercial" marcó
// enviar_imagen_informativa (material o metodología) y el
// texto sí se envía. "YCloud Enviar imagen" continúa ante
// error, así que el texto sale aunque la imagen falle.
//
// ======================================================

const urlImagenInformativa =
  decision.enviar_imagen_informativa === true
    ? textoONull(decision.imagen_informativa_url)
    : null;

const enviarImagen =
  enviarWhatsApp &&
  urlImagenInformativa !== null;

const bodyYCloudImagen =
  enviarImagen
    ? {
        from:
          telefonoE164(
            telefonoEmisor
          ),

        to:
          telefonoE164(
            telefonoDestino
          ),

        type:
          'image',

        image: {
          link:
            urlImagenInformativa
        }
      }
    : null;


// ======================================================
// 14. DIAGNÓSTICO DE ORIGEN
// ======================================================
//
// Muy útil mientras estabilizamos todas las rutas.
//
// Permite ver exactamente de dónde se recuperó teléfono.
//
// ======================================================

let telefonoDestinoOrigen =
  null;


if (
  limpiarTelefono(
    input.telefono_destino ??
    input.telefono
  )
) {

  telefonoDestinoOrigen =
    'INPUT_ACTUAL';

}

else if (
  limpiarTelefono(
    decision.telefono
  )
) {

  telefonoDestinoOrigen =
    'RECUPERAR_DECISION_COMERCIAL';

}

else if (
  limpiarTelefono(
    prepararMensajeHumano.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_MENSAJE_TRANSICION_HUMANO';

}

else if (
  limpiarTelefono(
    prepararDerivacionHumana.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_DERIVACION_HUMANA';

}

else if (
  limpiarTelefono(
    guardarContextoHandoff.telefono
  )
) {

  telefonoDestinoOrigen =
    'GUARDAR_CONTEXTO_HANDOFF';

}

else if (
  limpiarTelefono(
    prepararContextoHandoff.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_CONTEXTO_HANDOFF';

}

else if (
  limpiarTelefono(
    entradaWhatsApp.telefono
  )
) {

  telefonoDestinoOrigen =
    'PREPARAR_ENTRADA_WHATSAPP';

}

else {

  telefonoDestinoOrigen =
    'EVENTO_WHATSAPP';

}


// ======================================================
// 15. SALIDA
// ======================================================

return [
  {
    json: {

      // ----------------------------------------------
      // IDENTIFICACIÓN
      // ----------------------------------------------

      mensaje_db_id:
        mensajeDbId,

      conversacion_id:
        conversacionId,


      // ----------------------------------------------
      // DESTINO / EMISOR
      // ----------------------------------------------

      telefono_destino:
        telefonoDestino,

      telefono_destino_origen:
        telefonoDestinoOrigen,

      telefono_emisor:
        telefonoEmisor,

      telefono_destino_e164:
        telefonoE164(
          telefonoDestino
        ),

      telefono_emisor_e164:
        telefonoE164(
          telefonoEmisor
        ),


      // ----------------------------------------------
      // CONTENIDO
      // ----------------------------------------------

      texto_salida:
        textoSalida,

      tipo_salida:
        tipoOriginal,

      tipo_ycloud:
        tipoYCloud,


      // ----------------------------------------------
      // CONTROL
      // ----------------------------------------------

      proveedor_whatsapp:
        proveedor,

      viene_de_ycloud:
        vieneDeYCloud,

      viene_de_whatsapp_real:
        vieneDeWhatsAppReal,

      enviar_whatsapp:
        enviarWhatsApp,

      motivo_no_envio:
        motivoNoEnvio,


      // ----------------------------------------------
      // REQUEST YCLOUD
      // ----------------------------------------------

      ycloud_request: {
        body:
          bodyYCloud
      },

      enviar_imagen:
        enviarImagen,

      imagen_informativa:
        enviarImagen
          ? textoONull(decision.imagen_informativa)
          : null,

      ycloud_request_imagen: {
        body:
          bodyYCloudImagen
      },


      // ----------------------------------------------
      // DIAGNÓSTICO
      // ----------------------------------------------

      waba_id:
        eventoWhatsApp.waba_id ??
        metaWhatsApp.waba_id ??
        null,

      mensaje_entrante_id:
        eventoWhatsApp.mensaje_id ??
        entradaWhatsApp.mensaje_externo_id ??
        null,

      preparado_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// NODO N8N: Peparar notificacion humano
// ARCHIVO: code/06-derivacion-humana/preparar-notificacion-humano.js
// VERSION: 2.1
// RESPONSABILIDAD:
// - Construir una notificación INTERNA para Pegaso cuando una conversación requiere intervención humana
// - Clasificar la alerta en una categoría (INTERESADO_PAGO, PAGO_REPORTADO, SOLICITA_CONTACTO, ARCHIVO_REQUIERE_REVISION, NEGOCIACION, RECLAMO, REVISION_GENERAL)
// - Ajustar la prioridad de la alerta según la categoría
// - Generar asunto, texto plano y HTML del email con datos del prospecto y su último mensaje
// - Marcar canal_notificacion = EMAIL (destinos previstos: email Brevo/Resend; WhatsApp interno a futuro)
// - NO enviar el correo (lo hacen los nodos HTTP "Brevo - Enviar notificación humana" y, como respaldo, "Resend - Enviar notificación humana")
// - NO enviar nada al prospecto
// ======================================================

const input =
  $input.first().json;


// ======================================================
// 1. HELPERS
// ======================================================

function texto(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


// ======================================================
// 2. DATOS PRINCIPALES
// ======================================================

const conversacionId =
  numeroONull(
    input.conversacion_id
  );


const prospectoId =
  numeroONull(
    input.prospecto_id
  );


const nombre =
  texto(
    input.prospecto_nombre
  ) ??
  texto(
    input.nombre_whatsapp
  ) ??
  'Sin nombre';


const telefono =
  texto(
    input.telefono
  ) ??
  'No disponible';


const ciudad =
  texto(
    input.prospecto_ciudad
  ) ??
  texto(
    input.ciudad_detectada
  ) ??
  'No registrada';


const intencion =
  (
    texto(
      input.intencion
    ) ??
    'OTRO'
  ).toUpperCase();


const motivo =
  (
    texto(
      input.handoff_motivo
    ) ??
    texto(
      input.motivo_derivacion
    ) ??
    'OTRO'
  ).toUpperCase();


const prioridad =
  (
    texto(
      input.handoff_prioridad
    ) ??
    texto(
      input.prioridad_derivacion
    ) ??
    'NORMAL'
  ).toUpperCase();


const mensajeCliente =
  texto(
    input.handoff_mensaje_cliente
  ) ??
  texto(
    input.mensaje_actual
  ) ??
  'No disponible';


const clasificacionProspecto =
  texto(
    input.clasificacion_prospecto
  ) ??
  texto(
    input.prospecto_clasificacion
  ) ??
  null;


// ======================================================
// 3. CLASIFICAR TIPO DE ALERTA
// ======================================================

let categoriaNotificacion =
  'REVISION_GENERAL';


if (
  [
    'SOLICITA_CUENTA',
    'SOLICITA_DATOS_BANCARIOS',
    'PIDE_CUENTA',
    'PIDE_NUMERO_CUENTA',
    'INTERES_PAGO'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'INTERESADO_PAGO';

}


else if (
  [
    'REPORTA_PAGO',
    'ENVIA_COMPROBANTE',
    'COMPROBANTE_PAGO',
    'PAGO_REALIZADO'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'PAGO_REPORTADO';

}


else if (
  [
    'SOLICITA_LLAMADA',
    'QUIERE_LLAMAR',
    'QUIERE_QUE_LO_LLAMEN',
    'ATENCION_TELEFONICA'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'SOLICITA_CONTACTO';

}


else if (
  [
    'IMAGEN_REQUIERE_REVISION',
    'ARCHIVO_NO_PROCESABLE',
    'ARCHIVO_DISENO',
    'ARCHIVO_NO_ANALIZABLE',
    'IMAGEN_NO_ANALIZABLE',
    'ARCHIVO_REQUIERE_REVISION',
    'DISENO_REQUIERE_REVISION'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'ARCHIVO_REQUIERE_REVISION';

}


else if (
  [
    'NEGOCIACION',
    'NEGOCIAR_PRECIO',
    'PRECIO_ESPECIAL',
    'DESCUENTO'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'NEGOCIACION';

}


else if (
  [
    'RECLAMO',
    'INCONVENIENTE',
    'QUEJA'
  ].includes(motivo)
) {

  categoriaNotificacion =
    'RECLAMO';

}


// ======================================================
// 4. RESOLVER PRIORIDAD REAL
// ======================================================

let prioridadFinal =
  prioridad;


if (
  categoriaNotificacion ===
  'PAGO_REPORTADO'
) {

  prioridadFinal =
    'ALTA';

}


else if (
  categoriaNotificacion ===
  'INTERESADO_PAGO'
) {

  prioridadFinal =
    'ALTA';

}


else if (
  categoriaNotificacion ===
  'RECLAMO'
) {

  prioridadFinal =
    'ALTA';

}


else if (
  categoriaNotificacion ===
  'SOLICITA_CONTACTO'
) {

  prioridadFinal =
    'MEDIA';

}


// ======================================================
// 5. ASUNTO EMAIL
// ======================================================

let asunto =
  'Pegaso - Prospecto requiere revisión';


if (
  categoriaNotificacion ===
  'INTERESADO_PAGO'
) {

  asunto =
    '🔥 Pegaso - Prospecto solicita datos de pago';

}


else if (
  categoriaNotificacion ===
  'PAGO_REPORTADO'
) {

  asunto =
    '💰 Pegaso - Prospecto reportó un pago';

}


else if (
  categoriaNotificacion ===
  'RECLAMO'
) {

  asunto =
    '⚠️ Pegaso - Reclamo requiere atención';

}


else if (
  categoriaNotificacion ===
  'ARCHIVO_REQUIERE_REVISION'
) {

  asunto =
    '📎 Pegaso - Archivo requiere revisión';

}


// ======================================================
// 6. TEXTO INTERNO
// ======================================================

const lineas = [
  'PEGASO ADHESIVOS',
  '',
  'Nueva conversación requiere atención.',
  '',
  `Prioridad: ${prioridadFinal}`,
  `Categoría: ${categoriaNotificacion}`,
  `Motivo: ${motivo}`,
  `Intención: ${intencion}`,
  '',
  `Prospecto: ${nombre}`,
  `Teléfono: ${telefono}`,
  `Ciudad: ${ciudad}`,
  `Clasificación: ${clasificacionProspecto ?? 'No definida'}`,
  '',
  'Último mensaje:',
  mensajeCliente,
  '',
  `Conversación ID: ${conversacionId ?? 'N/D'}`,
  `Prospecto ID: ${prospectoId ?? 'N/D'}`
];


const mensajeNotificacion =
  lineas.join('\n');


// ======================================================
// 7. HTML EMAIL
// ======================================================

const htmlEmail = `
<h2>Pegaso Adhesivos</h2>

<p><strong>Nueva conversación requiere atención.</strong></p>

<table style="border-collapse:collapse;">
  <tr>
    <td><strong>Prioridad</strong></td>
    <td>${prioridadFinal}</td>
  </tr>
  <tr>
    <td><strong>Categoría</strong></td>
    <td>${categoriaNotificacion}</td>
  </tr>
  <tr>
    <td><strong>Motivo</strong></td>
    <td>${motivo}</td>
  </tr>
  <tr>
    <td><strong>Intención</strong></td>
    <td>${intencion}</td>
  </tr>
  <tr>
    <td><strong>Prospecto</strong></td>
    <td>${nombre}</td>
  </tr>
  <tr>
    <td><strong>Teléfono</strong></td>
    <td>${telefono}</td>
  </tr>
  <tr>
    <td><strong>Ciudad</strong></td>
    <td>${ciudad}</td>
  </tr>
  <tr>
    <td><strong>Clasificación</strong></td>
    <td>${clasificacionProspecto ?? 'No definida'}</td>
  </tr>
</table>

<h3>Último mensaje</h3>

<p>${mensajeCliente}</p>

<hr>

<p>
Conversación ID: ${conversacionId ?? 'N/D'}<br>
Prospecto ID: ${prospectoId ?? 'N/D'}
</p>
`;


// ======================================================
// 8. SALIDA
// ======================================================

return [
  {
    json: {

      ...input,

      notificacion_interna: true,

      categoria_notificacion:
        categoriaNotificacion,

      prioridad_notificacion:
        prioridadFinal,

      asunto_notificacion:
        asunto,

      mensaje_notificacion:
        mensajeNotificacion,

      html_notificacion:
        htmlEmail,

      // Inicialmente usaremos EMAIL.
      canal_notificacion:
        'EMAIL',

      enviar_notificacion:
        true,

      notificacion_preparada_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// VALIDAR PRODUCIBILIDAD P4
// PEGASO ADHESIVOS - V1
// ======================================================
//
// OBJETIVO:
//
// Validar restricciones físicas/comerciales ANTES de:
//
// - INSERT cotizacion_detalles
// - cálculo de precios
// - persistencia de una cotización inválida
//
// IMPORTANTE:
//
// Las REGLAS DE PRECIO siguen perteneciendo a:
// "Calcular precio detalle"
//
// Este nodo solamente valida si la medida se puede
// producir.
//
// REGLA PEGASO:
//
// No se producen etiquetas que tengan 1 cm o menos
// en cualquiera de sus lados.
//
// Ejemplos NO válidos:
//
// 1x1
// 1x5
// 5x1
// 0.5x10
// 10x0.8
//
// Ejemplos válidos:
//
// 2x2
// 2x5
// 3x3
// 4x4
// 5x8
//
// ======================================================


const items =
  $input.all();


// ======================================================
// 1. VALIDACIÓN GENERAL
// ======================================================

if (
  !Array.isArray(items) ||
  items.length === 0
) {
  throw new Error(
    'No existen detalles para validar producibilidad.'
  );
}


// ======================================================
// 2. HELPERS
// ======================================================

function numero(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function medidaTexto(valor) {

  const n =
    numero(valor);

  if (n === null) {
    return '';
  }

  if (
    Number.isInteger(n)
  ) {
    return String(n);
  }

  return String(
    Number(
      n.toFixed(2)
    )
  );
}


// ======================================================
// 3. REGLAS DE PRODUCCIÓN
// ======================================================

const MEDIDA_MINIMA_CM = 2;


// ======================================================
// 4. BUSCAR DETALLES NO PRODUCIBLES
// ======================================================

const detallesInvalidos = [];


items.forEach(
  (item, index) => {

    const data =
      item.json ?? {};


    const ancho =
      numero(
        data.ancho_cm
      );


    const alto =
      numero(
        data.alto_cm
      );


    // --------------------------------------------------
    // Datos incompletos
    // --------------------------------------------------

    if (
      ancho === null ||
      alto === null
    ) {

      detallesInvalidos.push({
        index,
        motivo:
          'MEDIDAS_INCOMPLETAS',

        ancho_cm:
          ancho,

        alto_cm:
          alto
      });

      return;
    }


    // --------------------------------------------------
    // Medidas físicamente no producibles
    // --------------------------------------------------

    if (
      ancho < MEDIDA_MINIMA_CM ||
      alto < MEDIDA_MINIMA_CM
    ) {

      detallesInvalidos.push({
        index,

        motivo:
          'MEDIDA_NO_PRODUCIBLE',

        ancho_cm:
          ancho,

        alto_cm:
          alto
      });

    }

  }
);


// ======================================================
// 5. SI EXISTE ALGÚN DETALLE INVÁLIDO
// ======================================================

if (
  detallesInvalidos.length > 0
) {

  const primerInvalido =
    detallesInvalidos[0];


  const ancho =
    primerInvalido.ancho_cm;


  const alto =
    primerInvalido.alto_cm;


  let mensaje;


  // --------------------------------------------------
  // Medidas conocidas
  // --------------------------------------------------

  if (
    ancho !== null &&
    alto !== null
  ) {

    mensaje =
      `La medida de ${medidaTexto(ancho)}x${medidaTexto(alto)} cm ` +
      `no es posible de producir.\n\n` +

      `No trabajamos etiquetas que tengan 1 cm o menos ` +
      `en cualquiera de sus lados. La medida mínima que ` +
      `podemos producir es de 2 cm.\n\n` +

      `Indíquenos otra medida y con gusto le cotizamos.`;

  }


  // --------------------------------------------------
  // Medidas incompletas
  // --------------------------------------------------

  else {

    mensaje =
      `No pudimos determinar correctamente las medidas de la etiqueta. ` +
      `Indíquenos ancho y alto en centímetros por favor.`;

  }


  // --------------------------------------------------
  // Conservar el contexto principal
  // --------------------------------------------------

  const base =
    items[0].json ?? {};


  return [
    {
      json: {

        ...base,


        // ============================================
        // VALIDACIÓN
        // ============================================

        cotizacion_producible:
          false,

        validacion_produccion_ok:
          false,

        motivo_bloqueo:
          primerInvalido.motivo,

        medida_minima_cm:
          MEDIDA_MINIMA_CM,

        detalles_invalidos:
          detallesInvalidos,


        // ============================================
        // NO DEBE CONTINUAR A PRECIO
        // ============================================

        bloquear_cotizacion:
          true,

        calcular_precio:
          false,


        // ============================================
        // CONTRATO COMPATIBLE CON MENSAJERÍA
        // ============================================

        mensaje_comercial:
          mensaje,

        mensajes_comerciales: [
          mensaje
        ],

        cantidad_mensajes_comerciales:
          1,


        // ============================================
        // DIAGNÓSTICO
        // ============================================

        validacion_produccion_at:
          new Date().toISOString()

      }
    }
  ];

}


// ======================================================
// 6. TODO ES PRODUCIBLE
// ======================================================
//
// Conservamos cada item porque posteriormente el flujo
// puede contener varios detalles de cotización.
//
// ======================================================

return items.map(
  item => {

    return {
      json: {

        ...item.json,

        cotizacion_producible:
          true,

        validacion_produccion_ok:
          true,

        motivo_bloqueo:
          null,

        medida_minima_cm:
          MEDIDA_MINIMA_CM,

        detalles_invalidos:
          [],

        bloquear_cotizacion:
          false,

        calcular_precio:
          true

      }
    };

  }
);

// ======================================================
// PREPARAR MENSAJE NO PRODUCIBLE
// PEGASO ADHESIVOS
// ======================================================

const input =
  $input.first().json ?? {};


// ======================================================
// HELPERS
// ======================================================

function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function medidaTexto(valor) {

  const n =
    numeroONull(valor);

  if (n === null) {
    return null;
  }

  if (Number.isInteger(n)) {
    return String(n);
  }

  return String(
    Number(
      n.toFixed(2)
    )
  );
}


// ======================================================
// DETALLE INVÁLIDO
// ======================================================

const detallesInvalidos =
  Array.isArray(input.detalles_invalidos)
    ? input.detalles_invalidos
    : [];


const detalle =
  detallesInvalidos[0] ?? {};


const ancho =
  numeroONull(
    detalle.ancho_cm ??
    input.ancho_cm
  );


const alto =
  numeroONull(
    detalle.alto_cm ??
    input.alto_cm
  );


// ======================================================
// MENSAJE
// ======================================================

let mensaje;


if (
  ancho !== null &&
  alto !== null &&
  (
    ancho <= 1 ||
    alto <= 1
  )
) {

  mensaje =
    `La medida de ${medidaTexto(ancho)}x${medidaTexto(alto)} cm no es posible de producir.\n\n` +
    `No trabajamos etiquetas que tengan 1 cm o menos en cualquiera de sus lados.\n\n` +
    `Indíquenos otra medida y con gusto le cotizamos.`;

} else {

  mensaje =
    `No podemos producir las etiquetas con las medidas indicadas. ` +
    `Indíquenos otra medida y con gusto le cotizamos.`;

}


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      ...input,

      tipo_respuesta_comercial:
        'NO_PRODUCIBLE',

      mensaje_comercial:
        mensaje,

      mensaje_variacion_precio:
        null,

      mensajes_comerciales: [
        mensaje
      ],

      cantidad_mensajes_comerciales:
        1,

      cotizacion_producible:
        false,

      respuesta_comercial_lista:
        true
    }
  }
];

// ======================================================
// PREPARAR MENSAJE COTIZACIÓN
// PEGASO ADHESIVOS - V2.8
// ======================================================
//
// V2.8: el cierre "Veo que estamos comparando varias
// alternativas..." se envía una sola vez. Si ya está en
// los salientes recientes, las cotizaciones siguientes
// cierran con "Verifíquele a detalle por favor."
//
// V2.7: si un detalle supera el minimo de su rango de
// cantidad y "Calcular precio detalle" indica una
// mejora real en el siguiente rango, se informa desde
// que cantidad mejora el precio (sin calcularlo aqui).
//
// ======================================================
//
// Objetivo:
//
// Construir el mensaje FINAL que recibe el prospecto
// después de calcular una cotización válida.
//
// CONTRATO:
//
// Este nodo y "Construir mensaje no producible"
// deben entregar una estructura compatible para que
// ambos puedan converger en:
//
// "Construir mensaje comercial"
//      ↓
// "Guardar mensaje comercial"
//
// REGLAS DE PRESENTACIÓN:
//
// 1. No mostrar nombre largo del producto.
// 2. Usar siempre "Etiquetas adhesivas".
// 3. No mostrar línea "Total".
// 4. No mostrar "IVA incluido".
// 5. No repetir información del material.
// 6. No cerrar siempre con la misma frase.
// 7. Adaptar el cierre según cotizaciones recientes.
// 8. Mantener mensaje independiente sobre variación
//    de precio según medidas.
// 9. NO usar IA para elegir el cierre.
// 10. Mantener compatibilidad con nodos posteriores.
//
// ======================================================


// ======================================================
// 1. RECUPERAR RESUMEN
// ======================================================

const resumen =
  $('Update rows in a table')
    .first()
    .json;


// ======================================================
// 2. RECUPERAR DETALLES CALCULADOS
// ======================================================

const detalles =
  $('Recuperar detalles calculados')
    .all()
    .map(
      item => item.json
    );


// ======================================================
// 3. RECUPERAR DECISIÓN COMERCIAL
// ======================================================
//
// Conservamos identidad de conversación,
// cliente y prospecto para nodos posteriores.
//
// ======================================================

let decision = {};

try {

  decision =
    $('Recuperar decisión comercial')
      .first()
      .json ?? {};

} catch (_) {

  decision = {};

}


// ======================================================
// 4. RECUPERAR CONTEXTO CONVERSACIONAL
// ======================================================
//
// Se utiliza únicamente para mejorar el cierre.
//
// Si este nodo no estuviera disponible por alguna
// razón, la cotización debe seguir funcionando.
//
// ======================================================

let contextoIA = {};

try {

  contextoIA =
    $('Preparar contexto IA')
      .first()
      .json ?? {};

} catch (_) {

  contextoIA = {};

}


// ======================================================
// 5. VALIDACIONES
// ======================================================

if (
  !Array.isArray(detalles) ||
  detalles.length === 0
) {

  throw new Error(
    'No existen detalles calculados para construir el mensaje comercial.'
  );

}


// ======================================================
// 6. HELPERS GENERALES
// ======================================================

function numero(valor) {

  const n =
    Number(
      valor ?? 0
    );

  return Number.isFinite(n)
    ? n
    : 0;

}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;

}


function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;

}


// ------------------------------------------------------
// DINERO
// ------------------------------------------------------

function dinero(valor) {

  return `$${numero(valor).toFixed(2)}`;

}


// ------------------------------------------------------
// CANTIDAD
// ------------------------------------------------------

function cantidadTexto(valor) {

  return numero(valor)
    .toLocaleString(
      'es-EC'
    );

}


// ------------------------------------------------------
// MEDIDA
// ------------------------------------------------------

function medidaTexto(valor) {

  const n =
    numero(valor);

  if (
    Number.isInteger(n)
  ) {

    return String(n);

  }

  return String(
    Number(
      n.toFixed(2)
    )
  );

}


// ======================================================
// 7. DESCRIBIR MEDIDA + FORMA
// ======================================================

function describirForma(detalle) {

  const forma =
    String(
      detalle.forma ||
      'RECTANGULAR'
    )
      .trim()
      .toUpperCase();


  const ancho =
    medidaTexto(
      detalle.ancho_cm
    );


  const alto =
    medidaTexto(
      detalle.alto_cm
    );


  // ----------------------------------------------------
  // CIRCULAR
  // ----------------------------------------------------

  if (
    forma === 'CIRCULAR'
  ) {

    return `${ancho} cm circulares`;

  }


  // ----------------------------------------------------
  // REDONDEADAS
  // ----------------------------------------------------

  if (
    forma === 'REDONDEADA' ||
    forma === 'REDONDEADO' ||
    forma === 'PUNTAS_REDONDEADAS'
  ) {

    return (
      `${ancho}x${alto} cm ` +
      `con puntas redondeadas`
    );

  }


  // ----------------------------------------------------
  // TROQUELADAS / IRREGULARES
  // ----------------------------------------------------

  if (
    forma === 'TROQUELADA' ||
    forma === 'TROQUELADO' ||
    forma === 'IRREGULAR'
  ) {

    return (
      `${ancho}x${alto} cm ` +
      `troqueladas`
    );

  }


  // ----------------------------------------------------
  // RECTANGULAR / CUADRADA
  // ----------------------------------------------------

  return (
    `${ancho}x${alto} cm ` +
    `rectangulares`
  );

}


// ======================================================
// 8. DETECTAR COTIZACIONES RECIENTES
// ======================================================
//
// "Preparar contexto IA" ya entrega:
//
// mensajes_salientes_recientes
//
// No contamos toda la historia de la conversación.
// Solo la ventana reciente que ya decidió ese nodo.
//
// ======================================================

function pareceCotizacion(texto) {

  const t =
    String(
      texto ?? ''
    )
      .toLowerCase()
      .replace(/\s+/g, ' ')
      .trim();

  if (!t) {
    return false;
  }

  // Patrón principal que usamos actualmente.
  if (
    t.includes(
      'le adjunto la cotización'
    )
  ) {
    return true;
  }

  // Fallback por si posteriormente cambia ligeramente
  // el encabezado de la respuesta.
  if (
    t.includes('etiquetas adhesivas') &&
    (
      t.includes('le saldrían en') ||
      t.includes('le saldrian en')
    ) &&
    t.includes('$')
  ) {
    return true;
  }

  return false;

}


function obtenerMensajesSalientesRecientes() {

  if (
    Array.isArray(
      contextoIA.mensajes_salientes_recientes
    )
  ) {

    return contextoIA
      .mensajes_salientes_recientes
      .map(textoONull)
      .filter(Boolean);

  }

  return [];

}


const mensajesSalientesRecientes =
  obtenerMensajesSalientesRecientes();


const cotizacionesRecientes =
  mensajesSalientesRecientes.filter(
    pareceCotizacion
  );


const cantidadCotizacionesRecientes =
  cotizacionesRecientes.length;


const CIERRE_COMPARACION =
  'Veo que estamos comparando varias alternativas. ' +
  'Si gusta, indíquenos cuáles son sus opciones favoritas ' +
  'y le ayudamos a definir la más conveniente.';

const cierreComparacionYaEnviado =
  mensajesSalientesRecientes.some(
    texto =>
      texto
        .toLowerCase()
        .includes('comparando varias alternativas')
  );


// ======================================================
// 9. RESOLVER CIERRE DE COTIZACIÓN
// ======================================================
//
// IMPORTANTE:
//
// Esta lógica es DETERMINÍSTICA.
//
// No queremos que el LLM improvise el cierre de
// una cotización.
//
// La cantidad representa cotizaciones PREVIAS,
// ya que la actual todavía no se ha guardado.
//
// ======================================================

function resolverCierreCotizacion({
  cantidadCotizacionesPrevias,
  cantidadDetallesActuales
}) {

  const multiplesOpcionesActuales =
    cantidadDetallesActuales > 1;


  // ----------------------------------------------------
  // PRIMERA COTIZACIÓN RECIENTE
  // ----------------------------------------------------

  if (
    cantidadCotizacionesPrevias <= 0
  ) {

    if (multiplesOpcionesActuales) {

      return (
        'Le dejo estas opciones para que pueda compararlas. ' +
        'Si ya cuenta con su diseño, adjúntenoslo para verificarlo por favor.'
      );

    }

    return (
      'Adjúntenos su diseño para verificarle por favor.'
    );

  }


  // ----------------------------------------------------
  // YA EXISTE 1 COTIZACIÓN PREVIA
  // ----------------------------------------------------

  if (
    cantidadCotizacionesPrevias === 1
  ) {

    if (multiplesOpcionesActuales) {

      return (
        'Si desea revisar otra medida también podemos cotizársela.'
      );

    }

    return (
      'Si desea, también podemos revisarle otra medida ' +
      'para que pueda comparar opciones.'
    );

  }


  // ----------------------------------------------------
  // YA EXISTEN 2 COTIZACIONES PREVIAS
  // ----------------------------------------------------

  if (
    cantidadCotizacionesPrevias === 2
  ) {

    return (
      'Verifíquele por favor.'
    );

  }


  // ----------------------------------------------------
  // 3 O MÁS COTIZACIONES PREVIAS
  // ----------------------------------------------------
  //
  // La invitación a elegir favoritas va una sola vez
  // dentro de la ventana de salientes recientes.
  // ----------------------------------------------------

  if (!cierreComparacionYaEnviado) {

    return CIERRE_COMPARACION;

  }

  return (
    'Verifíquele a detalle por favor.'
  );

}


// ======================================================
// 10. DATOS GENERALES
// ======================================================

const total =
  numero(
    resumen.total
  );


const conversacionId =
  numeroONull(
    decision.conversacion_id
  );


const clienteId =
  numeroONull(
    decision.cliente_id
  );


const prospectoId =
  numeroONull(
    decision.prospecto_id
  );


// ======================================================
// 11. DETECTAR AJUSTE DE CANTIDAD
// ======================================================

const detallesCantidadAjustada =
  detalles.filter(
    d =>
      Boolean(
        d.minimo_aplicado
      ) &&
      !Boolean(
        d.cantidad_asumida
      ) &&
      d.cantidad_original !== null &&
      d.cantidad_original !== undefined
  );


const huboAjusteCantidad =
  detallesCantidadAjustada.length > 0;


// ======================================================
// 12. CONSTRUIR MENSAJE PRINCIPAL
// ======================================================

let mensaje =
  `Le adjunto la cotización:\n\n`;


// ======================================================
// 13. ACLARACIÓN DE CANTIDAD
// ======================================================

if (
  huboAjusteCantidad
) {

  const ajustes =
    detallesCantidadAjustada.map(
      d => {

        return (
          `${cantidadTexto(
            d.cantidad_original
          )} → ` +
          `${cantidadTexto(
            d.cantidad
          )}`
        );

      }
    );


  mensaje +=
    `Trabajamos únicamente en múltiplos de 1000 unidades, ` +
    `por lo que las cantidades solicitadas podrían ser: ` +
    `${ajustes.join(', ')}.\n\n`;

}


// ======================================================
// 14. DETALLES DE COTIZACIÓN
// ======================================================

detalles.forEach(
  (detalle) => {

    const cantidad =
      cantidadTexto(
        detalle.cantidad
      );


    const medidaForma =
      describirForma(
        detalle
      );


    const precio =
      dinero(
        detalle.total ??
        detalle.precio_total
      );


    mensaje +=
      `-${cantidad} Etiquetas adhesivas ` +
      `de ${medidaForma} ` +
      `le saldrían en ${precio} dólares\n`;

  }
);


// ======================================================
// 14.1 MEJORA DE PRECIO POR RANGO DE CANTIDAD
// ======================================================

const cantidadesMejora =
  detalles
    .filter(
      d =>
        numeroONull(d.mejora_precio_desde_cantidad) !== null &&
        numeroONull(d.rango_cantidad_desde) !== null &&
        numero(d.cantidad) > numero(d.rango_cantidad_desde)
    )
    .map(
      d => numero(d.mejora_precio_desde_cantidad)
    );


const mejoraPrecioDesdeCantidad =
  cantidadesMejora.length > 0
    ? Math.min(...cantidadesMejora)
    : null;


if (
  mejoraPrecioDesdeCantidad !== null
) {

  mensaje +=
    `\nA partir de ${cantidadTexto(
      mejoraPrecioDesdeCantidad
    )} etiquetas podemos mejorarle el precio.\n`;

}


// ======================================================
// 15. CIERRE DINÁMICO
// ======================================================

const cierreCotizacion =
  resolverCierreCotizacion({

    cantidadCotizacionesPrevias:
      cantidadCotizacionesRecientes,

    cantidadDetallesActuales:
      detalles.length

  });


mensaje +=
  `\n${cierreCotizacion}`;


// ======================================================
// 16. MENSAJE INDEPENDIENTE DE VARIACIÓN DE PRECIO
// ======================================================
//
// Se mantiene exactamente como concepto independiente.
//
// Esto conserva compatibilidad con el flujo actual.
//
// ======================================================

const mensajeVariacionPrecio =
  'El precio se calcula en base a las medidas de la etiqueta. ' +
  'Si aumenta o disminuye las medidas, el precio también varía.';


// ======================================================
// 17. SALIDA
// ======================================================

return [
  {
    json: {

      // ----------------------------------------------
      // Identidad
      // ----------------------------------------------

      conversacion_id:
        conversacionId,

      cliente_id:
        clienteId,

      prospecto_id:
        prospectoId,


      // ----------------------------------------------
      // Tipo
      // ----------------------------------------------

      tipo_respuesta_comercial:
        'COTIZACION',


      // ----------------------------------------------
      // Cotización
      // ----------------------------------------------

      cotizacion_id:
        resumen.cotizacion_id ??
        resumen.id ??
        null,

      total,

      cantidad_detalles:
        detalles.length,


      // ----------------------------------------------
      // Mensajería
      // ----------------------------------------------

      mensaje_comercial:
        mensaje,

      mensaje_variacion_precio:
        mensajeVariacionPrecio,

      mensajes_comerciales: [
        mensaje,
        mensajeVariacionPrecio
      ],

      cantidad_mensajes_comerciales:
        2,


      // ----------------------------------------------
      // Información del cierre
      // ----------------------------------------------
      //
      // Estos campos son informativos.
      // No rompen contratos posteriores.
      //
      // Nos servirán para diagnóstico y futuras reglas.
      // ----------------------------------------------

      cierre_cotizacion:
        cierreCotizacion,

      cotizaciones_recientes_detectadas:
        cantidadCotizacionesRecientes,

      cierre_comparacion_ya_enviado:
        cierreComparacionYaEnviado,

      multiples_opciones_en_cotizacion:
        detalles.length > 1,

      mejora_precio_desde_cantidad:
        mejoraPrecioDesdeCantidad,


      // ----------------------------------------------
      // Control
      // ----------------------------------------------

      cotizacion_producible:
        true,

      bloquear_cotizacion:
        false,

      respuesta_comercial_lista:
        true

    }
  }
];

// ======================================================
// CONSTRUIR MENSAJE COMERCIAL
// PEGASO ADHESIVOS - V1.1
// CONTRATO FINAL COMÚN
// ======================================================
//
// Objetivo:
//
// Ser el ÚNICO punto de salida de respuestas comerciales.
//
// Puede recibir:
//
// 1. "Preparar mensaje cotización"
// 2. "Construir mensaje no producible"
//
// Este nodo NO:
//
// - calcula precios
// - decide cierres comerciales
// - consulta detalles de cotización
// - depende de nodos exclusivos de una rama
// - llama a IA
//
// De esta manera:
//
// Guardar mensaje comercial
//
// siempre puede leer:
//
// $('Construir mensaje comercial')
//   .first()
//   .json
//   .mensaje_comercial
//
// ======================================================


const input =
  $input.first().json ?? {};


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const t =
    String(valor).trim();

  return t !== ''
    ? t
    : null;

}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;

}


// ======================================================
// 2. VALIDAR MENSAJE PRINCIPAL
// ======================================================

const mensajeComercial =
  textoONull(
    input.mensaje_comercial
  );


if (!mensajeComercial) {

  throw new Error(
    'CONSTRUIR MENSAJE COMERCIAL: no existe mensaje_comercial para finalizar la respuesta comercial.'
  );

}


// ======================================================
// 3. RECUPERAR IDENTIDAD COMERCIAL
// ======================================================
//
// Las ramas deberían conservar estos datos.
//
// Como respaldo recuperamos:
//
// "Recuperar decisión comercial"
//
// ======================================================

let decision = {};

try {

  decision =
    $('Recuperar decisión comercial')
      .first()
      .json ?? {};

} catch (_) {

  decision = {};

}


// ======================================================
// 4. IDENTIDAD
// ======================================================

const conversacionId =
  numeroONull(
    input.conversacion_id
  ) ??
  numeroONull(
    decision.conversacion_id
  );


const clienteId =
  numeroONull(
    input.cliente_id
  ) ??
  numeroONull(
    decision.cliente_id
  );


const prospectoId =
  numeroONull(
    input.prospecto_id
  ) ??
  numeroONull(
    decision.prospecto_id
  );


// ======================================================
// 5. MENSAJE SECUNDARIO
// ======================================================

const mensajeVariacionPrecio =
  textoONull(
    input.mensaje_variacion_precio
  );


// ======================================================
// 6. COLECCIÓN DE MENSAJES
// ======================================================

let mensajesComerciales =
  Array.isArray(
    input.mensajes_comerciales
  )
    ? input
        .mensajes_comerciales
        .map(
          mensaje =>
            textoONull(mensaje)
        )
        .filter(Boolean)
    : [];


// ------------------------------------------------------
// Si la rama no entregó colección,
// utilizamos el mensaje principal.
// ------------------------------------------------------

if (
  mensajesComerciales.length === 0
) {

  mensajesComerciales = [
    mensajeComercial
  ];

}


// ------------------------------------------------------
// Garantizar que el mensaje principal sea el primero.
//
// Evita inconsistencias si una rama futura construye
// mensajes_comerciales de forma incorrecta.
// ------------------------------------------------------

if (
  mensajesComerciales[0] !== mensajeComercial
) {

  mensajesComerciales =
    [
      mensajeComercial,
      ...mensajesComerciales.filter(
        mensaje =>
          mensaje !== mensajeComercial
      )
    ];

}


// ======================================================
// 7. TIPO DE RESPUESTA
// ======================================================

const tipoRespuesta =
  textoONull(
    input.tipo_respuesta_comercial
  ) ??
  (
    input.cotizacion_producible === false
      ? 'NO_PRODUCIBLE'
      : 'COTIZACION'
  );


// ======================================================
// 8. SALIDA COMÚN
// ======================================================

return [
  {
    json: {

      // ----------------------------------------------
      // Conservamos TODO lo recibido.
      //
      // Esto incluye también los nuevos campos:
      //
      // cierre_cotizacion
      // cotizaciones_recientes_detectadas
      // multiples_opciones_en_cotizacion
      //
      // ----------------------------------------------

      ...input,


      // ----------------------------------------------
      // Identidad normalizada
      // ----------------------------------------------

      conversacion_id:
        conversacionId,

      cliente_id:
        clienteId,

      prospecto_id:
        prospectoId,


      // ----------------------------------------------
      // Tipo de respuesta
      // ----------------------------------------------

      tipo_respuesta_comercial:
        tipoRespuesta,


      // ----------------------------------------------
      // Mensaje principal
      // ----------------------------------------------

      mensaje_comercial:
        mensajeComercial,


      // ----------------------------------------------
      // Mensaje secundario opcional
      // ----------------------------------------------

      mensaje_variacion_precio:
        mensajeVariacionPrecio,


      // ----------------------------------------------
      // Colección de mensajes
      // ----------------------------------------------

      mensajes_comerciales:
        mensajesComerciales,

      cantidad_mensajes_comerciales:
        mensajesComerciales.length,


      // ----------------------------------------------
      // Control
      // ----------------------------------------------

      cotizacion_producible:
        input.cotizacion_producible !== false,

      bloquear_cotizacion:
        input.bloquear_cotizacion === true,

      respuesta_comercial_lista:
        true

    }
  }
];

// ======================================================
// APLICAR REGLAS COMERCIALES DETERMINÍSTICAS
// PEGASO ADHESIVOS - V1.2
// ======================================================
//
// Este nodo está colocado DESPUÉS de:
//
// Resolver contexto comercial
//
// y ANTES de:
//
// Guardar contexto comercial
//
// OBJETIVO:
//
// Aplicar reglas de negocio objetivas que tienen
// prioridad sobre la decisión realizada por la IA.
//
// IMPORTANTE:
//
// Este nodo NO reconstruye el contrato comercial.
// Conserva SIEMPRE:
//   ...data
//
// De esta manera no se pierden:
//
// - conversacion_id
// - cliente_id
// - contacto_id
// - prospecto_id
// - telefono
// - intención
// - contexto_comercial
// - datos de cotización
// - estado de prospecto
// - etc.
//
// V1.2:
// - Mantiene la regla de medida mínima.
// - Limpia una restricción anterior si las nuevas medidas
//   ya son producibles.
// - Conserva el par de medidas resuelto por
//   "Resolver contexto comercial" sin volver a mezclarlo.
// - No revive ids, precios ni estados de cotizaciones viejas.
// ======================================================

const data =
  $input.first().json;


// ======================================================
// 1. HELPERS
// ======================================================

function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const t =
    String(valor).trim();

  return t !== ''
    ? t
    : null;
}


function objeto(valor) {

  if (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return valor;
  }

  return {};
}


// ======================================================
// 2. RECUPERAR DATOS COMERCIALES
// ======================================================

const anchoCm =
  numeroONull(
    data.ancho_cm
  );

const altoCm =
  numeroONull(
    data.alto_cm
  );


// ======================================================
// 3. RECUPERAR CONTEXTO
// ======================================================

const contextoAnterior =
  objeto(
    data.contexto_comercial
  );

const cotizacionAnterior =
  objeto(
    contextoAnterior.cotizacion
  );


// ======================================================
// 4. RESTRICCIONES COMERCIALES
// ======================================================
//
// Regla actual:
//
// No se producen etiquetas que tengan 1 cm o menos
// en cualquiera de sus lados.
//
// Ejemplos NO producibles:
//
// 1 x 1
// 1 x 5
// 8 x 1
// 0.5 x 10
//
// ======================================================

let solicitudProducible =
  true;

let restriccionComercial =
  null;


// ------------------------------------------------------
// REGLA: MEDIDA MÍNIMA
// ------------------------------------------------------

if (
  anchoCm !== null &&
  altoCm !== null &&
  (
    anchoCm <= 1 ||
    altoCm <= 1
  )
) {

  solicitudProducible =
    false;

  restriccionComercial = {

    codigo:
      'MEDIDA_MINIMA_NO_PRODUCIBLE',

    tipo:
      'PRODUCCION',

    ancho_cm:
      anchoCm,

    alto_cm:
      altoCm,

    mensaje:
      'No trabajamos etiquetas que tengan 1 cm o menos en cualquiera de sus lados. La medida mínima que podemos trabajar debe ser mayor a 1 cm. Si gusta, indíquenos una medida mayor y con gusto le cotizamos.'

  };

}


// ======================================================
// 5. SI LA SOLICITUD ES PRODUCIBLE
// ======================================================
//
// No basta con devolver ...data.
//
// Si anteriormente existió una medida no producible y
// ahora el cliente corrigió las medidas, debemos eliminar
// del snapshot vigente:
//
// - producible = false
// - restriccion_codigo
// - restriccion_tipo
//
// De lo contrario una restricción vieja podría contaminar
// decisiones posteriores.
//
// La memoria histórica "ultima_restriccion_comercial"
// se conserva; no representa el estado vigente.
// ======================================================

if (
  solicitudProducible === true
) {

  const tieneMedidasCompletas =
    anchoCm !== null &&
    altoCm !== null;

  const cotizacionNueva = {
    ...cotizacionAnterior
  };

  if (tieneMedidasCompletas) {
    cotizacionNueva.ancho_cm =
      anchoCm;

    cotizacionNueva.alto_cm =
      altoCm;

    cotizacionNueva.producible =
      true;

    cotizacionNueva.restriccion_codigo =
      null;

    cotizacionNueva.restriccion_tipo =
      null;
  }

  const contextoComercialNuevo = {
    ...contextoAnterior,

    cotizacion:
      cotizacionNueva
  };

  return [
    {
      json: {

        ...data,

        solicitud_producible:
          true,

        restriccion_comercial:
          null,

        contexto_comercial:
          contextoComercialNuevo

      }
    }
  ];

}


// ======================================================
// 6. ACTUALIZAR CONTEXTO COMERCIAL
// ======================================================
//
// Conservamos el contexto construido por
// Resolver contexto comercial.
//
// Solo añadimos memoria de la restricción.
//
// ======================================================

const contextoComercialNuevo = {

  ...contextoAnterior,

  cotizacion: {

    ...cotizacionAnterior,

    ancho_cm:
      anchoCm,

    alto_cm:
      altoCm,

    producible:
      false,

    restriccion_codigo:
      restriccionComercial.codigo,

    restriccion_tipo:
      restriccionComercial.tipo

  },

  ultima_restriccion_comercial: {

    codigo:
      restriccionComercial.codigo,

    tipo:
      restriccionComercial.tipo,

    ancho_cm:
      restriccionComercial.ancho_cm,

    alto_cm:
      restriccionComercial.alto_cm,

    detectada_at:
      new Date().toISOString()

  }

};


// ======================================================
// 7. SOBRESCRIBIR DECISIÓN DE IA
// ======================================================
//
// Una restricción conocida por el sistema:
//
// NO requiere humano.
// NO entra al cotizador.
// NO se notifica internamente.
// Sí debe contestarse al prospecto.
//
// ======================================================

return [
  {
    json: {

      // ------------------------------------------------
      // CONSERVAR CONTRATO COMPLETO
      // ------------------------------------------------

      ...data,


      // ------------------------------------------------
      // PRODUCIBILIDAD
      // ------------------------------------------------

      solicitud_producible:
        false,

      restriccion_comercial:
        restriccionComercial,


      // ------------------------------------------------
      // DECISIÓN COMERCIAL
      // ------------------------------------------------

      accion:
        'RESPONDER_NO_PRODUCIBLE',

      requiere_humano:
        false,

      requiere_notificacion:
        false,

      motivo_derivacion:
        null,

      prioridad_derivacion:
        null,


      // ------------------------------------------------
      // COTIZACIÓN
      // ------------------------------------------------

      datos_suficientes_para_cotizar:
        false,


      // ------------------------------------------------
      // RESPUESTA
      // ------------------------------------------------

      respuesta_sugerida:
        restriccionComercial.mensaje,


      // ------------------------------------------------
      // CONTEXTO PERSISTENTE
      // ------------------------------------------------

      contexto_comercial:
        contextoComercialNuevo

    }
  }
];

