// ======================================================
// NODO N8N: Resolver turno conversacional
// ARCHIVO: code/03-conversacion/resolver-turno-conversacional.js
// VERSION: 1.3
// RESPONSABILIDAD:
// - Tras "Esperar ventana de turno", decidir si esta ejecución sigue siendo la del último mensaje ENTRANTE de la conversación (latest-wins por mensajes.id)
// - Ignorar reenvíos del mismo mensaje_externo_id (reintentos del webhook): solo cuenta la primera fila
// - Si llegó un mensaje posterior: continuar_procesamiento = false, resultado DEBOUNCE_SUPERSEDED, motivo MENSAJE_POSTERIOR_RECIBIDO (final válido, sin error)
// - Guardia humana posterior a la espera: si hay un SALIENTE humano (eco de WhatsApp Business con mensaje_externo_id y sin
//   prefijo [AUTOMATICO WHATSAPP BUSINESS) posterior a este mensaje o de hace menos de HUMANO_ACTIVO_MINUTOS, no procesar
//   (resultado ATENCION_HUMANA): el humano escribió durante la ventana y la bandera leída antes del Wait ya no vale.
//   Los SALIENTE humanos anteriores al último marcador [BOT REACTIVADO POR ADMINISTRADOR] (comando ACTIVEBOT) no cuentan
// - Si es la última: armar el turno con los ENTRANTE con procesado = false posteriores al último SALIENTE anterior (sin contar
//   ecos automáticos de WhatsApp Business) y no más antiguos que turno_max_antiguedad_segundos
// - Entregar turno_texto (un mensaje por línea, en orden), los ids y el rango turno_desde_id / turno_hasta_id para "Preparar contexto IA" y "Confirmar turno conversacional"
// - Conservar identidad de conversación/prospecto/contacto durante toda la rama
// - Lanzar error solo si falta el id de "Guardar mensaje entrante" o esa fila no aparece en el historial (configuración rota)
// - NO escribir en PostgreSQL (la confirmación atómica la hace "Confirmar turno conversacional")
// - NO llamar a la IA ni decidir la acción comercial
// ======================================================

const TURNO_MAX_ANTIGUEDAD_SEGUNDOS_DEFECTO = 600;
const HUMANO_ACTIVO_MINUTOS = 10;
const PREFIJO_AUTOMATICO_WHATSAPP_BUSINESS = '[AUTOMATICO WHATSAPP BUSINESS';
const PREFIJO_BOT_REACTIVADO = '[BOT REACTIVADO POR ADMINISTRADOR';


// ======================================================
// 1. HELPERS
// ======================================================

function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function verdadero(valor) {
  return (
    valor === true ||
    valor === 'true' ||
    valor === 't' ||
    valor === 1 ||
    valor === '1'
  );
}


function direccion(fila) {
  return String(
    fila.direccion ?? ''
  )
    .trim()
    .toUpperCase();
}


function fechaMs(valor) {
  const ms =
    Date.parse(
      valor ?? ''
    );

  return Number.isFinite(ms)
    ? ms
    : null;
}


// Los SALIENTE del bot se guardan sin mensaje_externo_id;
// los ecos de WhatsApp Business siempre lo traen.
function origenSaliente(fila) {
  if (textoONull(fila.mensaje_externo_id) === null) {
    return 'BOT';
  }

  return String(fila.contenido ?? '')
    .trim()
    .startsWith(PREFIJO_AUTOMATICO_WHATSAPP_BUSINESS)
    ? 'AUTOMATICO'
    : 'HUMANO';
}


// ======================================================
// 2. MENSAJE DE ESTA EJECUCIÓN
// ======================================================

const guardado =
  $('Guardar mensaje entrante').first().json ?? {};

const miId =
  numeroONull(
    guardado.id
  );

if (
  miId === null ||
  miId <= 0
) {
  throw new Error(
    'Resolver turno conversacional: "Guardar mensaje entrante" no devolvió un id válido.'
  );
}


// ======================================================
// 3. RECUPERAR IDENTIDAD DEL FLUJO
// ======================================================
//
// Esta rama recibe como input principal el historial de mensajes,
// por lo que no podemos depender de $input.first().json para
// recuperar prospecto/contacto.
//
// Intentamos obtener la identidad desde nodos anteriores estables.
//
// Prioridad:
// 1. Guardar mensaje entrante
// 2. Unificar conversación
// 3. Preparar conversación
// 4. Unificar prospecto
// 5. Resolver prospecto
//
// ======================================================

let unificarConversacion = {};
let prepararConversacion = {};
let unificarProspecto = {};
let resolverProspecto = {};

try {
  unificarConversacion =
    $('Unificar conversación').first().json ?? {};
} catch (error) {
  unificarConversacion = {};
}

try {
  prepararConversacion =
    $('Preparar conversación').first().json ?? {};
} catch (error) {
  prepararConversacion = {};
}

try {
  unificarProspecto =
    $('Unificar prospecto').first().json ?? {};
} catch (error) {
  unificarProspecto = {};
}

try {
  resolverProspecto =
    $('Resolver prospecto').first().json ?? {};
} catch (error) {
  resolverProspecto = {};
}


// ------------------------------------------------------
// IDs
// ------------------------------------------------------

const prospectoId =
  numeroONull(
    guardado.prospecto_id
  ) ??
  numeroONull(
    unificarConversacion.prospecto_id
  ) ??
  numeroONull(
    prepararConversacion.prospecto_id
  ) ??
  numeroONull(
    unificarProspecto.prospecto_id
  ) ??
  numeroONull(
    unificarProspecto.id
  ) ??
  numeroONull(
    resolverProspecto.prospecto_id
  ) ??
  numeroONull(
    resolverProspecto.id
  );


const clienteId =
  numeroONull(
    guardado.cliente_id
  ) ??
  numeroONull(
    unificarConversacion.cliente_id
  ) ??
  numeroONull(
    prepararConversacion.cliente_id
  ) ??
  numeroONull(
    unificarProspecto.cliente_id
  ) ??
  numeroONull(
    resolverProspecto.cliente_id
  );


const contactoId =
  numeroONull(
    guardado.contacto_id
  ) ??
  numeroONull(
    unificarConversacion.contacto_id
  ) ??
  numeroONull(
    prepararConversacion.contacto_id
  ) ??
  numeroONull(
    unificarProspecto.contacto_id
  ) ??
  numeroONull(
    resolverProspecto.contacto_id
  );


// ------------------------------------------------------
// Datos de contacto
// ------------------------------------------------------

const telefono =
  textoONull(
    guardado.telefono
  ) ??
  textoONull(
    unificarConversacion.telefono
  ) ??
  textoONull(
    prepararConversacion.telefono
  ) ??
  textoONull(
    unificarProspecto.telefono
  ) ??
  textoONull(
    resolverProspecto.telefono
  );


const nombreWhatsapp =
  textoONull(
    guardado.nombre_whatsapp
  ) ??
  textoONull(
    unificarConversacion.nombre_whatsapp
  ) ??
  textoONull(
    prepararConversacion.nombre_whatsapp
  ) ??
  textoONull(
    unificarProspecto.nombre_whatsapp
  ) ??
  textoONull(
    resolverProspecto.nombre_whatsapp
  );


// ======================================================
// 4. CONFIGURACIÓN
// ======================================================

let config = {};

try {
  config =
    $('Resolver permiso automatización').first().json ?? {};
} catch (error) {
  config = {};
}

const turnoMaxAntiguedadSegundos =
  numeroONull(
    config.turno_max_antiguedad_segundos
  ) ??
  TURNO_MAX_ANTIGUEDAD_SEGUNDOS_DEFECTO;


// ======================================================
// 5. MENSAJES DE LA CONVERSACIÓN
// ======================================================
//
// El input principal de este nodo son las filas devueltas por:
//
// Recuperar historial conversación
//
// ======================================================

const filas =
  $input.all()
    .map(
      item => item.json
    )
    .filter(
      fila =>
        fila &&
        numeroONull(
          fila.id
        ) !== null
    )
    .map(
      fila => ({
        ...fila,
        id:
          Number(
            fila.id
          )
      })
    )
    .sort(
      (a, b) =>
        a.id - b.id
    );


const miFila =
  filas.find(
    fila =>
      fila.id === miId
  );

if (!miFila) {
  throw new Error(
    `Resolver turno conversacional: el mensaje ${miId} no aparece en "Recuperar historial conversación".`
  );
}


const conversacionId =
  numeroONull(
    guardado.conversacion_id
  ) ??
  numeroONull(
    miFila.conversacion_id
  ) ??
  numeroONull(
    unificarConversacion.conversacion_id
  ) ??
  numeroONull(
    unificarConversacion.id
  ) ??
  numeroONull(
    prepararConversacion.conversacion_id
  );


// ======================================================
// 6. VALIDACIÓN MÍNIMA DE IDENTIDAD
// ======================================================
//
// conversacion_id es indispensable.
//
// prospecto_id se conserva siempre que exista.
//
// No lanzamos error aquí por prospecto_id porque:
// - el debounce puede ser reutilizable
// - la derivación humana sí puede exigirlo después
//
// ======================================================

if (
  conversacionId === null ||
  conversacionId <= 0
) {
  throw new Error(
    'Resolver turno conversacional: no se pudo resolver conversacion_id.'
  );
}


// ======================================================
// 7. ENTRANTES VÁLIDOS
// ======================================================
//
// Eliminamos duplicados por mensaje_externo_id.
//
// ======================================================

const externosVistos =
  new Set();

const entrantes =
  [];

let miEsDuplicado =
  false;


for (const fila of filas) {

  if (
    direccion(
      fila
    ) !== 'ENTRANTE'
  ) {
    continue;
  }

  const externo =
    textoONull(
      fila.mensaje_externo_id
    );

  const duplicado =
    externo !== null &&
    externosVistos.has(
      externo
    );

  if (
    externo !== null
  ) {
    externosVistos.add(
      externo
    );
  }

  if (duplicado) {

    if (
      fila.id === miId
    ) {
      miEsDuplicado =
        true;
    }

    continue;
  }

  entrantes.push(
    fila
  );
}


const ultimoEntranteId =
  entrantes.length > 0
    ? entrantes[
        entrantes.length - 1
      ].id
    : null;


// ======================================================
// 8. CONTRATO BASE DE IDENTIDAD
// ======================================================

const identidad = {

  conversacion_id:
    conversacionId,

  prospecto_id:
    prospectoId,

  cliente_id:
    clienteId,

  contacto_id:
    contactoId,

  telefono:
    telefono,

  nombre_whatsapp:
    nombreWhatsapp
};


// ======================================================
// 9. SALIDA SIN PROCESAR
// ======================================================

function noProcesar(
  resultado,
  motivo,
  extra = {}
) {

  return [
    {
      json: {

        success:
          true,

        flujo:
          'DEBOUNCE',

        ...identidad,

        mensaje_id:
          miId,

        continuar_procesamiento:
          false,

        resultado_turno:
          resultado,

        motivo_no_procesamiento:
          motivo,

        respuesta_automatica:
          false,

        mensaje_guardado:
          true,

        ultimo_entrante_id:
          ultimoEntranteId,

        ...extra,

        turno_resuelto_at:
          new Date().toISOString()

      }
    }
  ];
}


if (miEsDuplicado) {

  return noProcesar(
    'DUPLICADO',
    'MENSAJE_DUPLICADO',
    {
      mensaje_externo_id:
        textoONull(
          miFila.mensaje_externo_id
        )
    }
  );
}


if (
  ultimoEntranteId !== miId
) {

  return noProcesar(
    'DEBOUNCE_SUPERSEDED',
    'MENSAJE_POSTERIOR_RECIBIDO',
    {
      mensaje_posterior_id:
        ultimoEntranteId
    }
  );
}


// ======================================================
// 9.1 GUARDIA HUMANA POSTERIOR A LA ESPERA
// ======================================================

const salientesHumanos =
  filas.filter(
    fila =>
      direccion(fila) === 'SALIENTE' &&
      origenSaliente(fila) === 'HUMANO'
  );

const ultimoHumano =
  salientesHumanos.length > 0
    ? salientesHumanos[salientesHumanos.length - 1]
    : null;

const ultimaReactivacionId =
  filas
    .filter(
      fila =>
        direccion(fila) === 'SALIENTE' &&
        String(fila.contenido ?? '')
          .trim()
          .startsWith(PREFIJO_BOT_REACTIVADO)
    )
    .reduce(
      (max, fila) => Math.max(max, fila.id),
      0
    );

if (
  ultimoHumano &&
  ultimoHumano.id > ultimaReactivacionId
) {

  const fechaHumano =
    fechaMs(ultimoHumano.enviado_at);

  const humanoPosterior =
    ultimoHumano.id > miId;

  const humanoReciente =
    fechaHumano !== null &&
    Date.now() - fechaHumano <= HUMANO_ACTIVO_MINUTOS * 60 * 1000;

  if (humanoPosterior || humanoReciente) {

    return noProcesar(
      'ATENCION_HUMANA',
      humanoPosterior
        ? 'HUMANO_RESPONDIO_DURANTE_ESPERA'
        : 'INTERVENCION_HUMANA_RECIENTE',
      {
        ultimo_saliente_humano_id:
          ultimoHumano.id
      }
    );
  }
}


// ======================================================
// 10. ARMAR EL TURNO
// ======================================================
//
// Turno = ENTRANTE válidos que cumplen:
//
// - id <= este mensaje
// - id > último SALIENTE anterior a este mensaje
// - procesado = false
// - no más antiguos que turno_max_antiguedad_segundos
//
// ======================================================

const ultimoSalienteAnteriorId =
  filas
    .filter(
      fila =>
        direccion(
          fila
        ) === 'SALIENTE' &&
        origenSaliente(
          fila
        ) !== 'AUTOMATICO' &&
        fila.id < miId
    )
    .reduce(
      (max, fila) =>
        Math.max(
          max,
          fila.id
        ),
      0
    );


const miFecha =
  fechaMs(
    guardado.enviado_at
  ) ??
  fechaMs(
    miFila.enviado_at
  );


let descartadosPorAntiguedad =
  0;


const turno =
  entrantes.filter(
    fila => {

      if (
        fila.id > miId ||
        fila.id <= ultimoSalienteAnteriorId
      ) {
        return false;
      }

      if (
        verdadero(
          fila.procesado
        )
      ) {
        return false;
      }

      const fecha =
        fechaMs(
          fila.enviado_at
        );

      if (
        miFecha !== null &&
        fecha !== null &&
        miFecha - fecha >
          turnoMaxAntiguedadSegundos * 1000
      ) {

        descartadosPorAntiguedad++;

        return false;
      }

      return true;
    }
  );


if (
  !turno.some(
    fila =>
      fila.id === miId
  )
) {

  return noProcesar(
    'YA_PROCESADO',
    'TURNO_YA_PROCESADO'
  );
}


// ======================================================
// 11. NORMALIZAR MENSAJES DEL TURNO
// ======================================================

const turnoMensajes =
  turno.map(
    fila => ({

      id:
        fila.id,

      contenido:
        String(
          fila.contenido ?? ''
        ).trim(),

      tipo:
        textoONull(
          fila.tipo
        ) ??
        'TEXTO',

      enviado_at:
        fila.enviado_at ??
        null

    })
  );


const turnoTexto =
  turnoMensajes
    .map(
      m =>
        m.contenido
    )
    .filter(
      Boolean
    )
    .join(
      '\n'
    );


// ======================================================
// 12. SALIDA PARA PROCESAR
// ======================================================

return [
  {
    json: {

      success:
        true,

      flujo:
        'DEBOUNCE',

      // -----------------------------------------------
      // IDENTIDAD
      // -----------------------------------------------

      ...identidad,


      // -----------------------------------------------
      // MENSAJE ACTUAL
      // -----------------------------------------------

      mensaje_id:
        miId,


      // -----------------------------------------------
      // CONTROL DE DEBOUNCE
      // -----------------------------------------------

      continuar_procesamiento:
        true,

      resultado_turno:
        'PROCESAR',

      motivo_no_procesamiento:
        null,

      ultimo_entrante_id:
        ultimoEntranteId,

      ultimo_saliente_anterior_id:
        ultimoSalienteAnteriorId ||
        null,


      // -----------------------------------------------
      // TURNO
      // -----------------------------------------------

      turno_mensaje_ids:
        turnoMensajes.map(
          m => m.id
        ),

      turno_desde_id:
        turnoMensajes[0]?.id ??
        miId,

      turno_hasta_id:
        miId,

      cantidad_mensajes_turno:
        turnoMensajes.length,

      turno_mensajes:
        turnoMensajes,

      turno_texto:
        turnoTexto,

      mensajes_descartados_por_antiguedad:
        descartadosPorAntiguedad,


      // -----------------------------------------------
      // CONTROL
      // -----------------------------------------------

      turno_resuelto_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// NODO N8N: Preparar media del turno
// ARCHIVO: code/03-conversacion/preparar-media-turno.js
// VERSION: 1.0
// RESPONSABILIDAD:
// - Tras "IF: ¿Procesar turno?" (true), buscar en el turno las imágenes todavía sin analizar (tipo IMAGEN con línea "[MEDIA_PENDIENTE] {json}")
// - Revalidar cada una: MIME JPEG/PNG/WebP y enlace https://api.ycloud.com/v2/whatsapp/media/download/ (anti-SSRF); máximo MAX_IMAGENES_POR_TURNO
// - Emitir un item por imagen a analizar (analizar_imagen = true) con mensaje_id, enlace, MIME, caption y el contexto comercial breve para la IA visual
// - Si no hay ninguna: un solo item con analizar_imagen = false (el IF siguiente va directo a "Preparar contexto IA")
// - Las imágenes que no pasan la validación o exceden el máximo quedan pendientes: "Preparar contexto IA" las marca para revisión humana
// - NO descargar, NO llamar a la IA, NO escribir en PostgreSQL
// ======================================================

const MAX_IMAGENES_POR_TURNO = 3;

const MIME_IMAGEN_SOPORTADOS = ['image/jpeg', 'image/png', 'image/webp'];

const LINK_YCLOUD_PERMITIDO =
  /^https:\/\/api\.ycloud\.com\/v2\/whatsapp\/media\/download\/[A-Za-z0-9_-]+(\?[A-Za-z0-9%._~&=+-]*)?$/;

const PREFIJO_PENDIENTE = '[MEDIA_PENDIENTE] ';

const LARGO_MAXIMO_TEXTO_TURNO = 1500;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {
  if (valor === undefined || valor === null) {
    return null;
  }

  const limpio = String(valor).trim();

  return limpio !== '' ? limpio : null;
}

function lineas(contenido) {
  return String(contenido ?? '').split('\n');
}

function esLineaDeSistema(linea) {
  return /^\[(MEDIA_PENDIENTE|CONTEXTO DE IMAGEN|ARCHIVO NO PROCESABLE)[\]\s·]/.test(linea.trim());
}

function leerPendiente(contenido) {
  const linea = lineas(contenido)
    .map(l => l.trim())
    .find(l => l.startsWith(PREFIJO_PENDIENTE));

  if (!linea) {
    return null;
  }

  try {
    const datos = JSON.parse(linea.slice(PREFIJO_PENDIENTE.length));

    return datos && typeof datos === 'object' ? datos : null;
  } catch (error) {
    return null;
  }
}

function captionDe(contenido) {
  const primera = lineas(contenido)[0] ?? '';

  return primera.replace(/^\[IMAGEN\]\s*/, '').trim();
}


// ======================================================
// 2. TURNO
// ======================================================

let turno = {};

try {
  turno = $('Resolver turno conversacional').first().json ?? {};
} catch (error) {
  turno = $input.first().json ?? {};
}

const turnoMensajes = Array.isArray(turno.turno_mensajes)
  ? turno.turno_mensajes
  : [];


// ======================================================
// 3. CONTEXTO PARA LA IA VISUAL
// ======================================================
//
// Lo que el cliente escribió en el turno (texto y captions, sin
// líneas de sistema) y lo poco de la memoria comercial que ayuda a
// interpretar la imagen. Nunca el enlace.
// ======================================================

const textoTurnoCliente = turnoMensajes
  .map(m => lineas(m.contenido)
    .filter(l => !esLineaDeSistema(l))
    .map(l => l.replace(/^\[(IMAGEN|AUDIO|VIDEO|DOCUMENTO)\]\s*/, '').trim())
    .filter(Boolean)
    .join(' '))
  .filter(Boolean)
  .join('\n')
  .slice(0, LARGO_MAXIMO_TEXTO_TURNO);

let conversacion = {};

try {
  conversacion = $('Preparar conversación').first().json ?? {};
} catch (error) {
  conversacion = {};
}

const memoria =
  conversacion.contexto_comercial &&
  typeof conversacion.contexto_comercial === 'object'
    ? conversacion.contexto_comercial
    : {};

const cotizacionPrevia = memoria.cotizacion ?? {};

const contextoComercialBreve = [
  textoONull(conversacion.prospecto_producto_interes ?? memoria.prospecto?.producto_interes)
    ? `Producto de interés: ${textoONull(conversacion.prospecto_producto_interes ?? memoria.prospecto?.producto_interes)}.`
    : null,
  cotizacionPrevia.ancho_cm && cotizacionPrevia.alto_cm
    ? `Ya conversamos de etiquetas de ${cotizacionPrevia.ancho_cm}x${cotizacionPrevia.alto_cm} cm.`
    : null
]
  .filter(Boolean)
  .join(' ') || 'Sin datos comerciales previos.';


// ======================================================
// 4. IMÁGENES A ANALIZAR
// ======================================================

const candidatas = [];
let descartadas = 0;

for (const mensaje of turnoMensajes) {
  if (String(mensaje.tipo ?? '').toUpperCase() !== 'IMAGEN') {
    continue;
  }

  const pendiente = leerPendiente(mensaje.contenido);

  if (!pendiente) {
    continue;
  }

  const mime = textoONull(pendiente.mime_type)?.toLowerCase() ?? null;
  const link = textoONull(pendiente.link);

  const valida =
    MIME_IMAGEN_SOPORTADOS.includes(mime) &&
    link !== null &&
    link.length <= 2048 &&
    LINK_YCLOUD_PERMITIDO.test(link);

  if (!valida || candidatas.length >= MAX_IMAGENES_POR_TURNO) {
    descartadas++;
    continue;
  }

  candidatas.push({
    mensaje_id: Number(mensaje.id),
    mime_type: mime,
    media_link: link,
    caption: captionDe(mensaje.contenido),
    contenido_base: lineas(mensaje.contenido)[0].trim()
  });
}


// ======================================================
// 5. SALIDA
// ======================================================

if (candidatas.length === 0) {
  return [
    {
      json: {
        analizar_imagen: false,
        imagenes_por_analizar: 0,
        imagenes_descartadas: descartadas,
        conversacion_id: turno.conversacion_id ?? null
      }
    }
  ];
}

return candidatas.map((imagen, indice) => ({
  json: {
    analizar_imagen: true,
    imagenes_por_analizar: candidatas.length,
    imagenes_descartadas: descartadas,
    indice_imagen: indice,
    conversacion_id: turno.conversacion_id ?? null,
    ...imagen,
    texto_turno_cliente: textoTurnoCliente || '(el cliente no escribió texto)',
    contexto_comercial_breve: contextoComercialBreve
  }
}));

// ======================================================
// NODO N8N: VALIDAR ANÁLISIS IMAGEN GROQ
// PEGASO ADHESIVOS
// ARCHIVO: code/03-conversacion/validar-analisis-imagen.js
// VERSION: 2.1
// ======================================================
//
// RESPONSABILIDAD:
//
// - Recibir la salida de "Analizar imagen Groq Basic LLM".
// - Validar que el análisis visual cumpla el contrato.
// - Recuperar el mensaje original desde "Preparar media del turno".
// - NO necesita recibir nuevamente el binario.
// - NO analiza la imagen.
// - NO decide la acción comercial.
// - NO deriva directamente a humano.
// - Si Groq falla, devuelve analisis_valido = false para
//   permitir que el IF envíe el flujo a DeepSeek.
// - Extraer y normalizar medidas escritas explícitamente en la imagen
//   sin estimarlas ni alterar el resto del contrato visual.
//
// IMPORTANTE:
//
// Esta misma lógica puede reutilizarse después para:
//
//   Validar análisis imagen DeepSeek
//   Validar análisis imagen OpenAI
//
// cambiando únicamente PROVEEDOR_ANALISIS.
//
// ======================================================


const PROVEEDOR_ANALISIS = 'GROQ';


// ======================================================
// 1. CONSTANTES
// ======================================================

const CONTENIDOS_VALIDOS = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS',
  'COMPROBANTE_PAGO',
  'EVIDENCIA_RECLAMO',
  'CAPTURA_DE_PANTALLA',
  'NO_RELACIONADO',
  'NO_DETERMINABLE'
];


const MOTIVOS_REVISION_VALIDOS = [
  'NINGUNO',
  'IMAGEN_ILEGIBLE',
  'IMAGEN_AMBIGUA',
  'DISENO_COMPLEJO',
  'OTRO'
];


const CONFIANZAS_VALIDAS = [
  'ALTA',
  'MEDIA',
  'BAJA'
];


const CONTENIDOS_ETIQUETA = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS'
];


const LARGO_MAXIMO_RESUMEN = 500;
const LARGO_MAXIMO_CAMPO = 250;


// ======================================================
// 2. HELPERS
// ======================================================

function textoONull(
  valor,
  largo = LARGO_MAXIMO_CAMPO
) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  if (!limpio) {
    return null;
  }

  return limpio.slice(
    0,
    largo
  );
}


function numeroONull(
  valor
) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleanoONull(
  valor
) {

  if (
    valor === true ||
    valor === false
  ) {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return null;
}


function medidaONull(
  valor
) {

  const n =
    numeroONull(valor);

  if (
    n === null ||
    n <= 0
  ) {
    return null;
  }

  return n;
}


function quitarCorchetes(
  valor
) {

  const texto =
    textoONull(valor);

  if (!texto) {
    return null;
  }

  return texto
    .replace(/\[/g, '(')
    .replace(/\]/g, ')');
}


function obtenerNodo(
  nombre
) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


// ======================================================
// 3. LEER RESPUESTA DEL LLM
// ======================================================
//
// Dependiendo del nodo de n8n y del Output Parser,
// la respuesta puede llegar:
//
// {
//   output: {...}
// }
//
// {
//   output: "{...}"
// }
//
// {
//   text: "{...}"
// }
//
// o directamente como objeto.
//
// También puede llegar:
//
// {
//   error: ...
// }
//
// si el nodo está configurado con Continue On Fail.
//
// ======================================================

function leerSalidaIA(
  json
) {

  if (
    !json ||
    typeof json !== 'object'
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  // --------------------------------------------------
  // Error explícito del nodo
  // --------------------------------------------------

  if (json.error) {

    const detalle =
      textoONull(
        json.error?.message ??
        json.error
      );

    return {
      error:
        'IA_FALLIDA',

      detalle
    };

  }


  // --------------------------------------------------
  // Buscar salida probable
  // --------------------------------------------------

  let salida =
    json.output ??
    json.text ??
    json.response ??
    json.result ??
    json.data ??
    null;


  // Algunos nodos pueden devolver directamente
  // el contrato en el root.

  if (
    salida === null &&
    json.contenido_detectado !== undefined
  ) {

    salida =
      json;

  }


  // --------------------------------------------------
  // Parsear JSON string
  // --------------------------------------------------

  if (
    typeof salida === 'string'
  ) {

    let limpio =
      salida.trim();


    limpio =
      limpio.replace(
        /^```(?:json)?\s*/i,
        ''
      );


    limpio =
      limpio.replace(
        /\s*```$/,
        ''
      );


    try {

      salida =
        JSON.parse(
          limpio
        );

    } catch (_) {

      return {
        error:
          'JSON_INVALIDO',

        detalle:
          limpio.slice(
            0,
            300
          )
      };

    }

  }


  // --------------------------------------------------
  // Validar que sea objeto
  // --------------------------------------------------

  if (
    !salida ||
    typeof salida !== 'object' ||
    Array.isArray(salida)
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  return {
    datos:
      salida
  };
}


// ======================================================
// 4. VALIDAR CONTRATO
// ======================================================

function validarContrato(
  datos
) {

  if (
    !CONTENIDOS_VALIDOS.includes(
      datos.contenido_detectado
    )
  ) {

    return (
      'contenido_detectado inválido'
    );

  }


  if (
    !CONFIANZAS_VALIDAS.includes(
      datos.confianza
    )
  ) {

    return (
      'confianza inválida'
    );

  }


  if (
    !MOTIVOS_REVISION_VALIDOS.includes(
      datos.motivo_revision
    )
  ) {

    return (
      'motivo_revision inválido'
    );

  }


  const camposBooleanos = [
    'envase_detectado',
    'etiqueta_visible',
    'diseno_visible',
    'requiere_revision_humana'
  ];


  for (
    const campo
    of camposBooleanos
  ) {

    if (
      booleanoONull(
        datos[campo]
      ) === null
    ) {

      return (
        `${campo} debe ser boolean`
      );

    }

  }


  const medidasNumericas = [
    'ancho_cm',
    'alto_cm',
    'diametro_cm'
  ];

  for (const campo of medidasNumericas) {
    const valor = datos[campo];

    if (
      valor !== undefined &&
      valor !== null &&
      medidaONull(valor) === null
    ) {
      return `${campo} debe ser number positivo o null`;
    }
  }


  if (
    !textoONull(
      datos.resumen_para_cerebro,
      LARGO_MAXIMO_RESUMEN
    )
  ) {

    return (
      'resumen_para_cerebro vacío'
    );

  }


  return null;
}


// ======================================================
// 5. RECUPERAR CONTEXTO ORIGINAL
// ======================================================
//
// El nodo LLM puede devolver únicamente:
//
// {
//   output: {...}
// }
//
// Por eso NO dependemos de que preserve:
//
// - mensaje_id
// - conversacion_id
// - caption
// - contenido_base
//
// Estos datos se recuperan desde:
//
// "Preparar media del turno"
//
// ======================================================

const origenes = (() => {

  try {

    return (
      $('Preparar media del turno')
        .all()
    );

  } catch (_) {

    return [];

  }

})();


// ======================================================
// 6. PROCESAR ITEMS
// ======================================================

const entradas =
  $input.all();


const resultados =
  entradas.map(
    (
      item,
      indice
    ) => {

      const input =
        item.json ?? {};


      const origen =
        origenes[indice]?.json ??
        origenes[0]?.json ??
        {};


      // ==================================================
      // IDENTIDAD
      // ==================================================

      const mensajeId =
        numeroONull(
          input.mensaje_id ??
          origen.mensaje_id
        );


      const conversacionId =
        numeroONull(
          input.conversacion_id ??
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base ??
          input.contenido_base,
          1500
        ) ??
        '[IMAGEN]';


      // ==================================================
      // LEER IA
      // ==================================================

      const lectura =
        leerSalidaIA(
          input
        );


      const errorContrato =
        lectura.datos
          ? validarContrato(
              lectura.datos
            )
          : null;


      // ==================================================
      // 7. ANÁLISIS INVÁLIDO
      // ==================================================
      //
      // Aquí NO derivamos humano todavía.
      //
      // Groq inválido
      //    ↓
      // IF false
      //    ↓
      // DeepSeek
      //
      // ==================================================

      if (
        lectura.error ||
        errorContrato
      ) {

        const errorAnalisis =
          lectura.error ??
          'SCHEMA_INVALIDO';


        const detalleError =
          lectura.detalle ??
          errorContrato ??
          null;


        return {
          json: {

            mensaje_id:
              mensajeId,

            conversacion_id:
              conversacionId,

            proveedor_analisis:
              PROVEEDOR_ANALISIS,


            // ------------------------------------------
            // RESULTADO
            // ------------------------------------------

            analisis_valido:
              false,

            requiere_revision:
              true,

            motivo_revision:
              'ANALISIS_NO_DISPONIBLE',


            // ------------------------------------------
            // DETECCIÓN
            // ------------------------------------------

            comprobante_detectado:
              false,

            contenido_detectado:
              null,

            confianza:
              null,

            analisis:
              null,


            // ------------------------------------------
            // ERROR
            // ------------------------------------------

            error_analisis:
              errorAnalisis,

            detalle_error:
              detalleError,


            // ------------------------------------------
            // CONTEXTO PARA SIGUIENTE FALLBACK
            // ------------------------------------------

            contenido_base:
              contenidoBase,

            contenido_actualizado:
              (
                `${contenidoBase}\n` +
                `[CONTEXTO DE IMAGEN · proveedor=${PROVEEDOR_ANALISIS} · ` +
                'revision=SI · motivo=ANALISIS_NO_DISPONIBLE] ' +
                'El análisis automático de esta imagen no estuvo disponible.'
              )

          }
        };

      }


      // ==================================================
      // 8. ANÁLISIS VÁLIDO
      // ==================================================

      const datos =
        lectura.datos;


      const contenido =
        datos.contenido_detectado;


      const confianza =
        datos.confianza;


      // ==================================================
      // 8.1 MEDIDAS ESCRITAS
      // ==================================================
      //
      // Compatibilidad:
      // - Si el schema nuevo trae medidas_detectadas, se respeta.
      // - Si un fallback antiguo solo trae medidas_visibles, se infiere.
      // - Si existen ancho/alto/diámetro explícitos, también cuenta como
      //   medida detectada.
      //
      // Nunca se calculan medidas desde proporciones de la fotografía.
      // ==================================================

      const anchoCm =
        medidaONull(
          datos.ancho_cm
        );

      const altoCm =
        medidaONull(
          datos.alto_cm
        );

      const diametroCm =
        medidaONull(
          datos.diametro_cm
        );

      const medidasVisiblesOriginales =
        textoONull(
          datos.medidas_visibles,
          180
        );

      const medidaEstructuradaExiste =
        anchoCm !== null ||
        altoCm !== null ||
        diametroCm !== null;

      const medidasDetectadas =
        booleanoONull(
          datos.medidas_detectadas
        ) === true ||
        medidasVisiblesOriginales !== null ||
        medidaEstructuradaExiste;

      const medidasVisiblesDerivadas =
        [
          anchoCm !== null
            ? `ancho ${anchoCm} cm`
            : null,
          altoCm !== null
            ? `alto ${altoCm} cm`
            : null,
          diametroCm !== null
            ? `diámetro ${diametroCm} cm`
            : null
        ]
          .filter(Boolean)
          .join(' · ');

      const medidasVisibles =
        medidasDetectadas
          ? (
              medidasVisiblesOriginales ??
              textoONull(
                medidasVisiblesDerivadas,
                180
              )
            )
          : null;


      // ==================================================
      // 9. NORMALIZAR ANÁLISIS
      // ==================================================

      const analisis = {

        contenido_detectado:
          contenido,


        producto_probable:
          contenido === 'NO_RELACIONADO'
            ? null
            : textoONull(
                datos.producto_probable
              ),


        envase_detectado:
          booleanoONull(
            datos.envase_detectado
          ) === true,


        forma_envase:
          textoONull(
            datos.forma_envase
          ),


        etiqueta_visible:
          booleanoONull(
            datos.etiqueta_visible
          ) === true,


        diseno_visible:
          booleanoONull(
            datos.diseno_visible
          ) === true,


        texto_visible_relevante:
          contenido === 'COMPROBANTE_PAGO'
            ? null
            : textoONull(
                datos.texto_visible_relevante
              ),


        colores_relevantes:
          Array.isArray(
            datos.colores_relevantes
          )
            ? datos.colores_relevantes
                .map(
                  color =>
                    textoONull(
                      color,
                      40
                    )
                )
                .filter(
                  Boolean
                )
                .slice(
                  0,
                  6
                )
            : [],


        medidas_detectadas:
          medidasDetectadas,

        ancho_cm:
          medidasDetectadas
            ? anchoCm
            : null,

        alto_cm:
          medidasDetectadas
            ? altoCm
            : null,

        diametro_cm:
          medidasDetectadas
            ? diametroCm
            : null,

        medidas_visibles:
          medidasVisibles,


        requiere_revision_humana:
          booleanoONull(
            datos.requiere_revision_humana
          ) === true,


        motivo_revision:
          datos.motivo_revision,


        confianza,


        resumen_para_cerebro:
          textoONull(
            datos.resumen_para_cerebro,
            LARGO_MAXIMO_RESUMEN
          )

      };


      // ==================================================
      // 10. DETERMINAR REVISIÓN HUMANA
      // ======================================================

      let motivoRevision =
        null;


      if (
        analisis
          .requiere_revision_humana === true
      ) {

        motivoRevision =
          analisis.motivo_revision !==
          'NINGUNO'
            ? analisis.motivo_revision
            : 'OTRO';

      }


      else if (
        confianza ===
        'BAJA'
      ) {

        motivoRevision =
          'CONFIANZA_BAJA';

      }


      else if (
        contenido ===
        'NO_DETERMINABLE'
      ) {

        motivoRevision =
          'IMAGEN_AMBIGUA';

      }


      const requiereRevision =
        motivoRevision !==
        null;


      // ==================================================
      // 11. CONSTRUIR CONTEXTO LEGIBLE
      // ======================================================

      const cabecera = [

        'CONTEXTO DE IMAGEN',

        `proveedor=${PROVEEDOR_ANALISIS}`,

        `contenido=${contenido}`,

        `confianza=${confianza}`,

        `revision=${
          requiereRevision
            ? 'SI'
            : 'NO'
        }`,

        requiereRevision
          ? `motivo=${motivoRevision}`
          : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' · '
        );


      const detalle = [

        quitarCorchetes(
          analisis
            .resumen_para_cerebro
        ),


        analisis.producto_probable
          ? (
              'Producto probable: ' +
              `${quitarCorchetes(
                analisis.producto_probable
              )}.`
            )
          : null,


        analisis.forma_envase
          ? (
              'Envase: ' +
              `${quitarCorchetes(
                analisis.forma_envase
              )}.`
            )
          : null,


        analisis.texto_visible_relevante
          ? (
              'Texto visible: "' +
              `${quitarCorchetes(
                analisis.texto_visible_relevante
              )}".`
            )
          : null,


        analisis
          .colores_relevantes
          .length > 0
            ? (
                'Colores: ' +
                `${analisis
                  .colores_relevantes
                  .join(', ')}.`
              )
            : null,


        analisis.medidas_detectadas
          ? (
              'Medidas escritas en la imagen: ' +
              [
                analisis.ancho_cm !== null
                  ? `ancho=${analisis.ancho_cm} cm`
                  : null,
                analisis.alto_cm !== null
                  ? `alto=${analisis.alto_cm} cm`
                  : null,
                analisis.diametro_cm !== null
                  ? `diámetro=${analisis.diametro_cm} cm`
                  : null,
                analisis.medidas_visibles
                  ? `texto="${quitarCorchetes(
                      analisis.medidas_visibles
                    )}"`
                  : null
              ]
                .filter(Boolean)
                .join(' · ') +
              '.'
            )
          : CONTENIDOS_ETIQUETA.includes(
              contenido
            )
              ? 'Sin medidas visibles.'
              : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' '
        );


      // ==================================================
      // 12. SALIDA
      // ======================================================

      return {
        json: {

          mensaje_id:
            mensajeId,

          conversacion_id:
            conversacionId,

          proveedor_analisis:
            PROVEEDOR_ANALISIS,


          // ------------------------------------------
          // RESULTADO
          // ------------------------------------------

          analisis_valido:
            true,

          requiere_revision:
            requiereRevision,

          motivo_revision:
            motivoRevision,


          // ------------------------------------------
          // DETECCIÓN
          // ------------------------------------------

          comprobante_detectado:
            contenido ===
            'COMPROBANTE_PAGO',

          contenido_detectado:
            contenido,

          confianza,

          medidas_detectadas:
            analisis.medidas_detectadas,

          ancho_cm:
            analisis.ancho_cm,

          alto_cm:
            analisis.alto_cm,

          diametro_cm:
            analisis.diametro_cm,

          medidas_visibles:
            analisis.medidas_visibles,

          medidas_para_cerebro: {
            detectadas:
              analisis.medidas_detectadas,

            ancho_cm:
              analisis.ancho_cm,

            alto_cm:
              analisis.alto_cm,

            diametro_cm:
              analisis.diametro_cm,

            texto_original:
              analisis.medidas_visibles,

            fuente:
              'IMAGEN'
          },


          // ------------------------------------------
          // ERROR
          // ------------------------------------------

          error_analisis:
            null,

          detalle_error:
            null,


          // ------------------------------------------
          // ANÁLISIS NORMALIZADO
          // ------------------------------------------

          analisis,


          // ------------------------------------------
          // CONTEXTO
          // ------------------------------------------

          contenido_base:
            contenidoBase,

          contenido_actualizado:
            (
              `${contenidoBase}\n` +
              `[${cabecera}] ${detalle}`
            )

        }
      };

    }
  );


return resultados;

// ======================================================
// NODO N8N: VALIDAR ANÁLISIS IMAGEN GROQ
// PEGASO ADHESIVOS
// ARCHIVO: code/03-conversacion/validar-analisis-imagen.js
// VERSION: 2.1
// ======================================================
//
// RESPONSABILIDAD:
//
// - Recibir la salida de "Analizar imagen Groq Basic LLM".
// - Validar que el análisis visual cumpla el contrato.
// - Recuperar el mensaje original desde "Preparar media del turno".
// - NO necesita recibir nuevamente el binario.
// - NO analiza la imagen.
// - NO decide la acción comercial.
// - NO deriva directamente a humano.
// - Si Groq falla, devuelve analisis_valido = false para
//   permitir que el IF envíe el flujo a DeepSeek.
// - Extraer y normalizar medidas escritas explícitamente en la imagen
//   sin estimarlas ni alterar el resto del contrato visual.
//
// IMPORTANTE:
//
// Esta misma lógica puede reutilizarse después para:
//
//   Validar análisis imagen DeepSeek
//   Validar análisis imagen OpenAI
//
// cambiando únicamente PROVEEDOR_ANALISIS.
//
// ======================================================


const PROVEEDOR_ANALISIS = 'GROQ';


// ======================================================
// 1. CONSTANTES
// ======================================================

const CONTENIDOS_VALIDOS = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS',
  'COMPROBANTE_PAGO',
  'EVIDENCIA_RECLAMO',
  'CAPTURA_DE_PANTALLA',
  'NO_RELACIONADO',
  'NO_DETERMINABLE'
];


const MOTIVOS_REVISION_VALIDOS = [
  'NINGUNO',
  'IMAGEN_ILEGIBLE',
  'IMAGEN_AMBIGUA',
  'DISENO_COMPLEJO',
  'OTRO'
];


const CONFIANZAS_VALIDAS = [
  'ALTA',
  'MEDIA',
  'BAJA'
];


const CONTENIDOS_ETIQUETA = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS'
];


const LARGO_MAXIMO_RESUMEN = 500;
const LARGO_MAXIMO_CAMPO = 250;


// ======================================================
// 2. HELPERS
// ======================================================

function textoONull(
  valor,
  largo = LARGO_MAXIMO_CAMPO
) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  if (!limpio) {
    return null;
  }

  return limpio.slice(
    0,
    largo
  );
}


function numeroONull(
  valor
) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleanoONull(
  valor
) {

  if (
    valor === true ||
    valor === false
  ) {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return null;
}


function medidaONull(
  valor
) {

  const n =
    numeroONull(valor);

  if (
    n === null ||
    n <= 0
  ) {
    return null;
  }

  return n;
}


function quitarCorchetes(
  valor
) {

  const texto =
    textoONull(valor);

  if (!texto) {
    return null;
  }

  return texto
    .replace(/\[/g, '(')
    .replace(/\]/g, ')');
}


function obtenerNodo(
  nombre
) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


// ======================================================
// 3. LEER RESPUESTA DEL LLM
// ======================================================
//
// Dependiendo del nodo de n8n y del Output Parser,
// la respuesta puede llegar:
//
// {
//   output: {...}
// }
//
// {
//   output: "{...}"
// }
//
// {
//   text: "{...}"
// }
//
// o directamente como objeto.
//
// También puede llegar:
//
// {
//   error: ...
// }
//
// si el nodo está configurado con Continue On Fail.
//
// ======================================================

function leerSalidaIA(
  json
) {

  if (
    !json ||
    typeof json !== 'object'
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  // --------------------------------------------------
  // Error explícito del nodo
  // --------------------------------------------------

  if (json.error) {

    const detalle =
      textoONull(
        json.error?.message ??
        json.error
      );

    return {
      error:
        'IA_FALLIDA',

      detalle
    };

  }


  // --------------------------------------------------
  // Buscar salida probable
  // --------------------------------------------------

  let salida =
    json.output ??
    json.text ??
    json.response ??
    json.result ??
    json.data ??
    null;


  // Algunos nodos pueden devolver directamente
  // el contrato en el root.

  if (
    salida === null &&
    json.contenido_detectado !== undefined
  ) {

    salida =
      json;

  }


  // --------------------------------------------------
  // Parsear JSON string
  // --------------------------------------------------

  if (
    typeof salida === 'string'
  ) {

    let limpio =
      salida.trim();


    limpio =
      limpio.replace(
        /^```(?:json)?\s*/i,
        ''
      );


    limpio =
      limpio.replace(
        /\s*```$/,
        ''
      );


    try {

      salida =
        JSON.parse(
          limpio
        );

    } catch (_) {

      return {
        error:
          'JSON_INVALIDO',

        detalle:
          limpio.slice(
            0,
            300
          )
      };

    }

  }


  // --------------------------------------------------
  // Validar que sea objeto
  // --------------------------------------------------

  if (
    !salida ||
    typeof salida !== 'object' ||
    Array.isArray(salida)
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  return {
    datos:
      salida
  };
}


// ======================================================
// 4. VALIDAR CONTRATO
// ======================================================

function validarContrato(
  datos
) {

  if (
    !CONTENIDOS_VALIDOS.includes(
      datos.contenido_detectado
    )
  ) {

    return (
      'contenido_detectado inválido'
    );

  }


  if (
    !CONFIANZAS_VALIDAS.includes(
      datos.confianza
    )
  ) {

    return (
      'confianza inválida'
    );

  }


  if (
    !MOTIVOS_REVISION_VALIDOS.includes(
      datos.motivo_revision
    )
  ) {

    return (
      'motivo_revision inválido'
    );

  }


  const camposBooleanos = [
    'envase_detectado',
    'etiqueta_visible',
    'diseno_visible',
    'requiere_revision_humana'
  ];


  for (
    const campo
    of camposBooleanos
  ) {

    if (
      booleanoONull(
        datos[campo]
      ) === null
    ) {

      return (
        `${campo} debe ser boolean`
      );

    }

  }


  const medidasNumericas = [
    'ancho_cm',
    'alto_cm',
    'diametro_cm'
  ];

  for (const campo of medidasNumericas) {
    const valor = datos[campo];

    if (
      valor !== undefined &&
      valor !== null &&
      medidaONull(valor) === null
    ) {
      return `${campo} debe ser number positivo o null`;
    }
  }


  if (
    !textoONull(
      datos.resumen_para_cerebro,
      LARGO_MAXIMO_RESUMEN
    )
  ) {

    return (
      'resumen_para_cerebro vacío'
    );

  }


  return null;
}


// ======================================================
// 5. RECUPERAR CONTEXTO ORIGINAL
// ======================================================
//
// El nodo LLM puede devolver únicamente:
//
// {
//   output: {...}
// }
//
// Por eso NO dependemos de que preserve:
//
// - mensaje_id
// - conversacion_id
// - caption
// - contenido_base
//
// Estos datos se recuperan desde:
//
// "Preparar media del turno"
//
// ======================================================

const origenes = (() => {

  try {

    return (
      $('Preparar media del turno')
        .all()
    );

  } catch (_) {

    return [];

  }

})();


// ======================================================
// 6. PROCESAR ITEMS
// ======================================================

const entradas =
  $input.all();


const resultados =
  entradas.map(
    (
      item,
      indice
    ) => {

      const input =
        item.json ?? {};


      const origen =
        origenes[indice]?.json ??
        origenes[0]?.json ??
        {};


      // ==================================================
      // IDENTIDAD
      // ==================================================

      const mensajeId =
        numeroONull(
          input.mensaje_id ??
          origen.mensaje_id
        );


      const conversacionId =
        numeroONull(
          input.conversacion_id ??
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base ??
          input.contenido_base,
          1500
        ) ??
        '[IMAGEN]';


      // ==================================================
      // LEER IA
      // ==================================================

      const lectura =
        leerSalidaIA(
          input
        );


      const errorContrato =
        lectura.datos
          ? validarContrato(
              lectura.datos
            )
          : null;


      // ==================================================
      // 7. ANÁLISIS INVÁLIDO
      // ==================================================
      //
      // Aquí NO derivamos humano todavía.
      //
      // Groq inválido
      //    ↓
      // IF false
      //    ↓
      // DeepSeek
      //
      // ==================================================

      if (
        lectura.error ||
        errorContrato
      ) {

        const errorAnalisis =
          lectura.error ??
          'SCHEMA_INVALIDO';


        const detalleError =
          lectura.detalle ??
          errorContrato ??
          null;


        return {
          json: {

            mensaje_id:
              mensajeId,

            conversacion_id:
              conversacionId,

            proveedor_analisis:
              PROVEEDOR_ANALISIS,


            // ------------------------------------------
            // RESULTADO
            // ------------------------------------------

            analisis_valido:
              false,

            requiere_revision:
              true,

            motivo_revision:
              'ANALISIS_NO_DISPONIBLE',


            // ------------------------------------------
            // DETECCIÓN
            // ------------------------------------------

            comprobante_detectado:
              false,

            contenido_detectado:
              null,

            confianza:
              null,

            analisis:
              null,


            // ------------------------------------------
            // ERROR
            // ------------------------------------------

            error_analisis:
              errorAnalisis,

            detalle_error:
              detalleError,


            // ------------------------------------------
            // CONTEXTO PARA SIGUIENTE FALLBACK
            // ------------------------------------------

            contenido_base:
              contenidoBase,

            contenido_actualizado:
              (
                `${contenidoBase}\n` +
                `[CONTEXTO DE IMAGEN · proveedor=${PROVEEDOR_ANALISIS} · ` +
                'revision=SI · motivo=ANALISIS_NO_DISPONIBLE] ' +
                'El análisis automático de esta imagen no estuvo disponible.'
              )

          }
        };

      }


      // ==================================================
      // 8. ANÁLISIS VÁLIDO
      // ==================================================

      const datos =
        lectura.datos;


      const contenido =
        datos.contenido_detectado;


      const confianza =
        datos.confianza;


      // ==================================================
      // 8.1 MEDIDAS ESCRITAS
      // ==================================================
      //
      // Compatibilidad:
      // - Si el schema nuevo trae medidas_detectadas, se respeta.
      // - Si un fallback antiguo solo trae medidas_visibles, se infiere.
      // - Si existen ancho/alto/diámetro explícitos, también cuenta como
      //   medida detectada.
      //
      // Nunca se calculan medidas desde proporciones de la fotografía.
      // ==================================================

      const anchoCm =
        medidaONull(
          datos.ancho_cm
        );

      const altoCm =
        medidaONull(
          datos.alto_cm
        );

      const diametroCm =
        medidaONull(
          datos.diametro_cm
        );

      const medidasVisiblesOriginales =
        textoONull(
          datos.medidas_visibles,
          180
        );

      const medidaEstructuradaExiste =
        anchoCm !== null ||
        altoCm !== null ||
        diametroCm !== null;

      const medidasDetectadas =
        booleanoONull(
          datos.medidas_detectadas
        ) === true ||
        medidasVisiblesOriginales !== null ||
        medidaEstructuradaExiste;

      const medidasVisiblesDerivadas =
        [
          anchoCm !== null
            ? `ancho ${anchoCm} cm`
            : null,
          altoCm !== null
            ? `alto ${altoCm} cm`
            : null,
          diametroCm !== null
            ? `diámetro ${diametroCm} cm`
            : null
        ]
          .filter(Boolean)
          .join(' · ');

      const medidasVisibles =
        medidasDetectadas
          ? (
              medidasVisiblesOriginales ??
              textoONull(
                medidasVisiblesDerivadas,
                180
              )
            )
          : null;


      // ==================================================
      // 9. NORMALIZAR ANÁLISIS
      // ==================================================

      const analisis = {

        contenido_detectado:
          contenido,


        producto_probable:
          contenido === 'NO_RELACIONADO'
            ? null
            : textoONull(
                datos.producto_probable
              ),


        envase_detectado:
          booleanoONull(
            datos.envase_detectado
          ) === true,


        forma_envase:
          textoONull(
            datos.forma_envase
          ),


        etiqueta_visible:
          booleanoONull(
            datos.etiqueta_visible
          ) === true,


        diseno_visible:
          booleanoONull(
            datos.diseno_visible
          ) === true,


        texto_visible_relevante:
          contenido === 'COMPROBANTE_PAGO'
            ? null
            : textoONull(
                datos.texto_visible_relevante
              ),


        colores_relevantes:
          Array.isArray(
            datos.colores_relevantes
          )
            ? datos.colores_relevantes
                .map(
                  color =>
                    textoONull(
                      color,
                      40
                    )
                )
                .filter(
                  Boolean
                )
                .slice(
                  0,
                  6
                )
            : [],


        medidas_detectadas:
          medidasDetectadas,

        ancho_cm:
          medidasDetectadas
            ? anchoCm
            : null,

        alto_cm:
          medidasDetectadas
            ? altoCm
            : null,

        diametro_cm:
          medidasDetectadas
            ? diametroCm
            : null,

        medidas_visibles:
          medidasVisibles,


        requiere_revision_humana:
          booleanoONull(
            datos.requiere_revision_humana
          ) === true,


        motivo_revision:
          datos.motivo_revision,


        confianza,


        resumen_para_cerebro:
          textoONull(
            datos.resumen_para_cerebro,
            LARGO_MAXIMO_RESUMEN
          )

      };


      // ==================================================
      // 10. DETERMINAR REVISIÓN HUMANA
      // ======================================================

      let motivoRevision =
        null;


      if (
        analisis
          .requiere_revision_humana === true
      ) {

        motivoRevision =
          analisis.motivo_revision !==
          'NINGUNO'
            ? analisis.motivo_revision
            : 'OTRO';

      }


      else if (
        confianza ===
        'BAJA'
      ) {

        motivoRevision =
          'CONFIANZA_BAJA';

      }


      else if (
        contenido ===
        'NO_DETERMINABLE'
      ) {

        motivoRevision =
          'IMAGEN_AMBIGUA';

      }


      const requiereRevision =
        motivoRevision !==
        null;


      // ==================================================
      // 11. CONSTRUIR CONTEXTO LEGIBLE
      // ======================================================

      const cabecera = [

        'CONTEXTO DE IMAGEN',

        `proveedor=${PROVEEDOR_ANALISIS}`,

        `contenido=${contenido}`,

        `confianza=${confianza}`,

        `revision=${
          requiereRevision
            ? 'SI'
            : 'NO'
        }`,

        requiereRevision
          ? `motivo=${motivoRevision}`
          : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' · '
        );


      const detalle = [

        quitarCorchetes(
          analisis
            .resumen_para_cerebro
        ),


        analisis.producto_probable
          ? (
              'Producto probable: ' +
              `${quitarCorchetes(
                analisis.producto_probable
              )}.`
            )
          : null,


        analisis.forma_envase
          ? (
              'Envase: ' +
              `${quitarCorchetes(
                analisis.forma_envase
              )}.`
            )
          : null,


        analisis.texto_visible_relevante
          ? (
              'Texto visible: "' +
              `${quitarCorchetes(
                analisis.texto_visible_relevante
              )}".`
            )
          : null,


        analisis
          .colores_relevantes
          .length > 0
            ? (
                'Colores: ' +
                `${analisis
                  .colores_relevantes
                  .join(', ')}.`
              )
            : null,


        analisis.medidas_detectadas
          ? (
              'Medidas escritas en la imagen: ' +
              [
                analisis.ancho_cm !== null
                  ? `ancho=${analisis.ancho_cm} cm`
                  : null,
                analisis.alto_cm !== null
                  ? `alto=${analisis.alto_cm} cm`
                  : null,
                analisis.diametro_cm !== null
                  ? `diámetro=${analisis.diametro_cm} cm`
                  : null,
                analisis.medidas_visibles
                  ? `texto="${quitarCorchetes(
                      analisis.medidas_visibles
                    )}"`
                  : null
              ]
                .filter(Boolean)
                .join(' · ') +
              '.'
            )
          : CONTENIDOS_ETIQUETA.includes(
              contenido
            )
              ? 'Sin medidas visibles.'
              : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' '
        );


      // ==================================================
      // 12. SALIDA
      // ======================================================

      return {
        json: {

          mensaje_id:
            mensajeId,

          conversacion_id:
            conversacionId,

          proveedor_analisis:
            PROVEEDOR_ANALISIS,


          // ------------------------------------------
          // RESULTADO
          // ------------------------------------------

          analisis_valido:
            true,

          requiere_revision:
            requiereRevision,

          motivo_revision:
            motivoRevision,


          // ------------------------------------------
          // DETECCIÓN
          // ------------------------------------------

          comprobante_detectado:
            contenido ===
            'COMPROBANTE_PAGO',

          contenido_detectado:
            contenido,

          confianza,

          medidas_detectadas:
            analisis.medidas_detectadas,

          ancho_cm:
            analisis.ancho_cm,

          alto_cm:
            analisis.alto_cm,

          diametro_cm:
            analisis.diametro_cm,

          medidas_visibles:
            analisis.medidas_visibles,

          medidas_para_cerebro: {
            detectadas:
              analisis.medidas_detectadas,

            ancho_cm:
              analisis.ancho_cm,

            alto_cm:
              analisis.alto_cm,

            diametro_cm:
              analisis.diametro_cm,

            texto_original:
              analisis.medidas_visibles,

            fuente:
              'IMAGEN'
          },


          // ------------------------------------------
          // ERROR
          // ------------------------------------------

          error_analisis:
            null,

          detalle_error:
            null,


          // ------------------------------------------
          // ANÁLISIS NORMALIZADO
          // ------------------------------------------

          analisis,


          // ------------------------------------------
          // CONTEXTO
          // ------------------------------------------

          contenido_base:
            contenidoBase,

          contenido_actualizado:
            (
              `${contenidoBase}\n` +
              `[${cabecera}] ${detalle}`
            )

        }
      };

    }
  );


return resultados;

// ======================================================
// NODO N8N: VALIDAR ANÁLISIS IMAGEN GROQ
// PEGASO ADHESIVOS
// ARCHIVO: code/03-conversacion/validar-analisis-imagen.js
// VERSION: 2.1
// ======================================================
//
// RESPONSABILIDAD:
//
// - Recibir la salida de "Analizar imagen Groq Basic LLM".
// - Validar que el análisis visual cumpla el contrato.
// - Recuperar el mensaje original desde "Preparar media del turno".
// - NO necesita recibir nuevamente el binario.
// - NO analiza la imagen.
// - NO decide la acción comercial.
// - NO deriva directamente a humano.
// - Si Groq falla, devuelve analisis_valido = false para
//   permitir que el IF envíe el flujo a DeepSeek.
// - Extraer y normalizar medidas escritas explícitamente en la imagen
//   sin estimarlas ni alterar el resto del contrato visual.
//
// IMPORTANTE:
//
// Esta misma lógica puede reutilizarse después para:
//
//   Validar análisis imagen DeepSeek
//   Validar análisis imagen OpenAI
//
// cambiando únicamente PROVEEDOR_ANALISIS.
//
// ======================================================


const PROVEEDOR_ANALISIS = 'GROQ';


// ======================================================
// 1. CONSTANTES
// ======================================================

const CONTENIDOS_VALIDOS = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS',
  'COMPROBANTE_PAGO',
  'EVIDENCIA_RECLAMO',
  'CAPTURA_DE_PANTALLA',
  'NO_RELACIONADO',
  'NO_DETERMINABLE'
];


const MOTIVOS_REVISION_VALIDOS = [
  'NINGUNO',
  'IMAGEN_ILEGIBLE',
  'IMAGEN_AMBIGUA',
  'DISENO_COMPLEJO',
  'OTRO'
];


const CONFIANZAS_VALIDAS = [
  'ALTA',
  'MEDIA',
  'BAJA'
];


const CONTENIDOS_ETIQUETA = [
  'ENVASE_O_PRODUCTO',
  'ETIQUETA_O_DISENO',
  'LOGO',
  'REFERENCIA_VISUAL',
  'MEDIDAS_ESCRITAS'
];


const LARGO_MAXIMO_RESUMEN = 500;
const LARGO_MAXIMO_CAMPO = 250;


// ======================================================
// 2. HELPERS
// ======================================================

function textoONull(
  valor,
  largo = LARGO_MAXIMO_CAMPO
) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  if (!limpio) {
    return null;
  }

  return limpio.slice(
    0,
    largo
  );
}


function numeroONull(
  valor
) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function booleanoONull(
  valor
) {

  if (
    valor === true ||
    valor === false
  ) {
    return valor;
  }

  if (
    valor === 'true' ||
    valor === 1 ||
    valor === '1'
  ) {
    return true;
  }

  if (
    valor === 'false' ||
    valor === 0 ||
    valor === '0'
  ) {
    return false;
  }

  return null;
}


function medidaONull(
  valor
) {

  const n =
    numeroONull(valor);

  if (
    n === null ||
    n <= 0
  ) {
    return null;
  }

  return n;
}


function quitarCorchetes(
  valor
) {

  const texto =
    textoONull(valor);

  if (!texto) {
    return null;
  }

  return texto
    .replace(/\[/g, '(')
    .replace(/\]/g, ')');
}


function obtenerNodo(
  nombre
) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


// ======================================================
// 3. LEER RESPUESTA DEL LLM
// ======================================================
//
// Dependiendo del nodo de n8n y del Output Parser,
// la respuesta puede llegar:
//
// {
//   output: {...}
// }
//
// {
//   output: "{...}"
// }
//
// {
//   text: "{...}"
// }
//
// o directamente como objeto.
//
// También puede llegar:
//
// {
//   error: ...
// }
//
// si el nodo está configurado con Continue On Fail.
//
// ======================================================

function leerSalidaIA(
  json
) {

  if (
    !json ||
    typeof json !== 'object'
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  // --------------------------------------------------
  // Error explícito del nodo
  // --------------------------------------------------

  if (json.error) {

    const detalle =
      textoONull(
        json.error?.message ??
        json.error
      );

    return {
      error:
        'IA_FALLIDA',

      detalle
    };

  }


  // --------------------------------------------------
  // Buscar salida probable
  // --------------------------------------------------

  let salida =
    json.output ??
    json.text ??
    json.response ??
    json.result ??
    json.data ??
    null;


  // Algunos nodos pueden devolver directamente
  // el contrato en el root.

  if (
    salida === null &&
    json.contenido_detectado !== undefined
  ) {

    salida =
      json;

  }


  // --------------------------------------------------
  // Parsear JSON string
  // --------------------------------------------------

  if (
    typeof salida === 'string'
  ) {

    let limpio =
      salida.trim();


    limpio =
      limpio.replace(
        /^```(?:json)?\s*/i,
        ''
      );


    limpio =
      limpio.replace(
        /\s*```$/,
        ''
      );


    try {

      salida =
        JSON.parse(
          limpio
        );

    } catch (_) {

      return {
        error:
          'JSON_INVALIDO',

        detalle:
          limpio.slice(
            0,
            300
          )
      };

    }

  }


  // --------------------------------------------------
  // Validar que sea objeto
  // --------------------------------------------------

  if (
    !salida ||
    typeof salida !== 'object' ||
    Array.isArray(salida)
  ) {

    return {
      error:
        'SALIDA_VACIA'
    };

  }


  return {
    datos:
      salida
  };
}


// ======================================================
// 4. VALIDAR CONTRATO
// ======================================================

function validarContrato(
  datos
) {

  if (
    !CONTENIDOS_VALIDOS.includes(
      datos.contenido_detectado
    )
  ) {

    return (
      'contenido_detectado inválido'
    );

  }


  if (
    !CONFIANZAS_VALIDAS.includes(
      datos.confianza
    )
  ) {

    return (
      'confianza inválida'
    );

  }


  if (
    !MOTIVOS_REVISION_VALIDOS.includes(
      datos.motivo_revision
    )
  ) {

    return (
      'motivo_revision inválido'
    );

  }


  const camposBooleanos = [
    'envase_detectado',
    'etiqueta_visible',
    'diseno_visible',
    'requiere_revision_humana'
  ];


  for (
    const campo
    of camposBooleanos
  ) {

    if (
      booleanoONull(
        datos[campo]
      ) === null
    ) {

      return (
        `${campo} debe ser boolean`
      );

    }

  }


  const medidasNumericas = [
    'ancho_cm',
    'alto_cm',
    'diametro_cm'
  ];

  for (const campo of medidasNumericas) {
    const valor = datos[campo];

    if (
      valor !== undefined &&
      valor !== null &&
      medidaONull(valor) === null
    ) {
      return `${campo} debe ser number positivo o null`;
    }
  }


  if (
    !textoONull(
      datos.resumen_para_cerebro,
      LARGO_MAXIMO_RESUMEN
    )
  ) {

    return (
      'resumen_para_cerebro vacío'
    );

  }


  return null;
}


// ======================================================
// 5. RECUPERAR CONTEXTO ORIGINAL
// ======================================================
//
// El nodo LLM puede devolver únicamente:
//
// {
//   output: {...}
// }
//
// Por eso NO dependemos de que preserve:
//
// - mensaje_id
// - conversacion_id
// - caption
// - contenido_base
//
// Estos datos se recuperan desde:
//
// "Preparar media del turno"
//
// ======================================================

const origenes = (() => {

  try {

    return (
      $('Preparar media del turno')
        .all()
    );

  } catch (_) {

    return [];

  }

})();


// ======================================================
// 6. PROCESAR ITEMS
// ======================================================

const entradas =
  $input.all();


const resultados =
  entradas.map(
    (
      item,
      indice
    ) => {

      const input =
        item.json ?? {};


      const origen =
        origenes[indice]?.json ??
        origenes[0]?.json ??
        {};


      // ==================================================
      // IDENTIDAD
      // ==================================================

      const mensajeId =
        numeroONull(
          input.mensaje_id ??
          origen.mensaje_id
        );


      const conversacionId =
        numeroONull(
          input.conversacion_id ??
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base ??
          input.contenido_base,
          1500
        ) ??
        '[IMAGEN]';


      // ==================================================
      // LEER IA
      // ==================================================

      const lectura =
        leerSalidaIA(
          input
        );


      const errorContrato =
        lectura.datos
          ? validarContrato(
              lectura.datos
            )
          : null;


      // ==================================================
      // 7. ANÁLISIS INVÁLIDO
      // ==================================================
      //
      // Aquí NO derivamos humano todavía.
      //
      // Groq inválido
      //    ↓
      // IF false
      //    ↓
      // DeepSeek
      //
      // ==================================================

      if (
        lectura.error ||
        errorContrato
      ) {

        const errorAnalisis =
          lectura.error ??
          'SCHEMA_INVALIDO';


        const detalleError =
          lectura.detalle ??
          errorContrato ??
          null;


        return {
          json: {

            mensaje_id:
              mensajeId,

            conversacion_id:
              conversacionId,

            proveedor_analisis:
              PROVEEDOR_ANALISIS,


            // ------------------------------------------
            // RESULTADO
            // ------------------------------------------

            analisis_valido:
              false,

            requiere_revision:
              true,

            motivo_revision:
              'ANALISIS_NO_DISPONIBLE',


            // ------------------------------------------
            // DETECCIÓN
            // ------------------------------------------

            comprobante_detectado:
              false,

            contenido_detectado:
              null,

            confianza:
              null,

            analisis:
              null,


            // ------------------------------------------
            // ERROR
            // ------------------------------------------

            error_analisis:
              errorAnalisis,

            detalle_error:
              detalleError,


            // ------------------------------------------
            // CONTEXTO PARA SIGUIENTE FALLBACK
            // ------------------------------------------

            contenido_base:
              contenidoBase,

            contenido_actualizado:
              (
                `${contenidoBase}\n` +
                `[CONTEXTO DE IMAGEN · proveedor=${PROVEEDOR_ANALISIS} · ` +
                'revision=SI · motivo=ANALISIS_NO_DISPONIBLE] ' +
                'El análisis automático de esta imagen no estuvo disponible.'
              )

          }
        };

      }


      // ==================================================
      // 8. ANÁLISIS VÁLIDO
      // ==================================================

      const datos =
        lectura.datos;


      const contenido =
        datos.contenido_detectado;


      const confianza =
        datos.confianza;


      // ==================================================
      // 8.1 MEDIDAS ESCRITAS
      // ==================================================
      //
      // Compatibilidad:
      // - Si el schema nuevo trae medidas_detectadas, se respeta.
      // - Si un fallback antiguo solo trae medidas_visibles, se infiere.
      // - Si existen ancho/alto/diámetro explícitos, también cuenta como
      //   medida detectada.
      //
      // Nunca se calculan medidas desde proporciones de la fotografía.
      // ==================================================

      const anchoCm =
        medidaONull(
          datos.ancho_cm
        );

      const altoCm =
        medidaONull(
          datos.alto_cm
        );

      const diametroCm =
        medidaONull(
          datos.diametro_cm
        );

      const medidasVisiblesOriginales =
        textoONull(
          datos.medidas_visibles,
          180
        );

      const medidaEstructuradaExiste =
        anchoCm !== null ||
        altoCm !== null ||
        diametroCm !== null;

      const medidasDetectadas =
        booleanoONull(
          datos.medidas_detectadas
        ) === true ||
        medidasVisiblesOriginales !== null ||
        medidaEstructuradaExiste;

      const medidasVisiblesDerivadas =
        [
          anchoCm !== null
            ? `ancho ${anchoCm} cm`
            : null,
          altoCm !== null
            ? `alto ${altoCm} cm`
            : null,
          diametroCm !== null
            ? `diámetro ${diametroCm} cm`
            : null
        ]
          .filter(Boolean)
          .join(' · ');

      const medidasVisibles =
        medidasDetectadas
          ? (
              medidasVisiblesOriginales ??
              textoONull(
                medidasVisiblesDerivadas,
                180
              )
            )
          : null;


      // ==================================================
      // 9. NORMALIZAR ANÁLISIS
      // ==================================================

      const analisis = {

        contenido_detectado:
          contenido,


        producto_probable:
          contenido === 'NO_RELACIONADO'
            ? null
            : textoONull(
                datos.producto_probable
              ),


        envase_detectado:
          booleanoONull(
            datos.envase_detectado
          ) === true,


        forma_envase:
          textoONull(
            datos.forma_envase
          ),


        etiqueta_visible:
          booleanoONull(
            datos.etiqueta_visible
          ) === true,


        diseno_visible:
          booleanoONull(
            datos.diseno_visible
          ) === true,


        texto_visible_relevante:
          contenido === 'COMPROBANTE_PAGO'
            ? null
            : textoONull(
                datos.texto_visible_relevante
              ),


        colores_relevantes:
          Array.isArray(
            datos.colores_relevantes
          )
            ? datos.colores_relevantes
                .map(
                  color =>
                    textoONull(
                      color,
                      40
                    )
                )
                .filter(
                  Boolean
                )
                .slice(
                  0,
                  6
                )
            : [],


        medidas_detectadas:
          medidasDetectadas,

        ancho_cm:
          medidasDetectadas
            ? anchoCm
            : null,

        alto_cm:
          medidasDetectadas
            ? altoCm
            : null,

        diametro_cm:
          medidasDetectadas
            ? diametroCm
            : null,

        medidas_visibles:
          medidasVisibles,


        requiere_revision_humana:
          booleanoONull(
            datos.requiere_revision_humana
          ) === true,


        motivo_revision:
          datos.motivo_revision,


        confianza,


        resumen_para_cerebro:
          textoONull(
            datos.resumen_para_cerebro,
            LARGO_MAXIMO_RESUMEN
          )

      };


      // ==================================================
      // 10. DETERMINAR REVISIÓN HUMANA
      // ======================================================

      let motivoRevision =
        null;


      if (
        analisis
          .requiere_revision_humana === true
      ) {

        motivoRevision =
          analisis.motivo_revision !==
          'NINGUNO'
            ? analisis.motivo_revision
            : 'OTRO';

      }


      else if (
        confianza ===
        'BAJA'
      ) {

        motivoRevision =
          'CONFIANZA_BAJA';

      }


      else if (
        contenido ===
        'NO_DETERMINABLE'
      ) {

        motivoRevision =
          'IMAGEN_AMBIGUA';

      }


      const requiereRevision =
        motivoRevision !==
        null;


      // ==================================================
      // 11. CONSTRUIR CONTEXTO LEGIBLE
      // ======================================================

      const cabecera = [

        'CONTEXTO DE IMAGEN',

        `proveedor=${PROVEEDOR_ANALISIS}`,

        `contenido=${contenido}`,

        `confianza=${confianza}`,

        `revision=${
          requiereRevision
            ? 'SI'
            : 'NO'
        }`,

        requiereRevision
          ? `motivo=${motivoRevision}`
          : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' · '
        );


      const detalle = [

        quitarCorchetes(
          analisis
            .resumen_para_cerebro
        ),


        analisis.producto_probable
          ? (
              'Producto probable: ' +
              `${quitarCorchetes(
                analisis.producto_probable
              )}.`
            )
          : null,


        analisis.forma_envase
          ? (
              'Envase: ' +
              `${quitarCorchetes(
                analisis.forma_envase
              )}.`
            )
          : null,


        analisis.texto_visible_relevante
          ? (
              'Texto visible: "' +
              `${quitarCorchetes(
                analisis.texto_visible_relevante
              )}".`
            )
          : null,


        analisis
          .colores_relevantes
          .length > 0
            ? (
                'Colores: ' +
                `${analisis
                  .colores_relevantes
                  .join(', ')}.`
              )
            : null,


        analisis.medidas_detectadas
          ? (
              'Medidas escritas en la imagen: ' +
              [
                analisis.ancho_cm !== null
                  ? `ancho=${analisis.ancho_cm} cm`
                  : null,
                analisis.alto_cm !== null
                  ? `alto=${analisis.alto_cm} cm`
                  : null,
                analisis.diametro_cm !== null
                  ? `diámetro=${analisis.diametro_cm} cm`
                  : null,
                analisis.medidas_visibles
                  ? `texto="${quitarCorchetes(
                      analisis.medidas_visibles
                    )}"`
                  : null
              ]
                .filter(Boolean)
                .join(' · ') +
              '.'
            )
          : CONTENIDOS_ETIQUETA.includes(
              contenido
            )
              ? 'Sin medidas visibles.'
              : null

      ]
        .filter(
          Boolean
        )
        .join(
          ' '
        );


      // ==================================================
      // 12. SALIDA
      // ======================================================

      return {
        json: {

          mensaje_id:
            mensajeId,

          conversacion_id:
            conversacionId,

          proveedor_analisis:
            PROVEEDOR_ANALISIS,


          // ------------------------------------------
          // RESULTADO
          // ------------------------------------------

          analisis_valido:
            true,

          requiere_revision:
            requiereRevision,

          motivo_revision:
            motivoRevision,


          // ------------------------------------------
          // DETECCIÓN
          // ------------------------------------------

          comprobante_detectado:
            contenido ===
            'COMPROBANTE_PAGO',

          contenido_detectado:
            contenido,

          confianza,

          medidas_detectadas:
            analisis.medidas_detectadas,

          ancho_cm:
            analisis.ancho_cm,

          alto_cm:
            analisis.alto_cm,

          diametro_cm:
            analisis.diametro_cm,

          medidas_visibles:
            analisis.medidas_visibles,

          medidas_para_cerebro: {
            detectadas:
              analisis.medidas_detectadas,

            ancho_cm:
              analisis.ancho_cm,

            alto_cm:
              analisis.alto_cm,

            diametro_cm:
              analisis.diametro_cm,

            texto_original:
              analisis.medidas_visibles,

            fuente:
              'IMAGEN'
          },


          // ------------------------------------------
          // ERROR
          // ------------------------------------------

          error_analisis:
            null,

          detalle_error:
            null,


          // ------------------------------------------
          // ANÁLISIS NORMALIZADO
          // ------------------------------------------

          analisis,


          // ------------------------------------------
          // CONTEXTO
          // ------------------------------------------

          contenido_base:
            contenidoBase,

          contenido_actualizado:
            (
              `${contenidoBase}\n` +
              `[${cabecera}] ${detalle}`
            )

        }
      };

    }
  );


return resultados;

// ======================================================
// NODO N8N: PREPARAR DERIVACIÓN IMAGEN FALLIDA
// PEGASO ADHESIVOS
// VERSION: 2.0
// ======================================================
//
// Se ejecuta únicamente cuando:
//
// Groq       -> análisis inválido
// DeepSeek   -> análisis inválido
