// Preparar derivación humana
//
// ======================================================


const input =
  $input.first().json ?? {};


// ======================================================
// 1. HELPERS
// ======================================================

function texto(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\s+/g, ' ')
      .trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function obtenerNodo(nombre) {

  try {

    return (
      $(nombre)
        .first()
        .json ??
      {}
    );

  } catch (_) {

    return {};

  }
}


function primerNumero(...valores) {

  for (const valor of valores) {

    const n =
      numeroONull(valor);

    if (
      n !== null &&
      n > 0
    ) {
      return n;
    }

  }

  return null;
}


function primerTexto(...valores) {

  for (const valor of valores) {

    const t =
      texto(valor);

    if (t !== null) {
      return t;
    }

  }

  return null;
}


// ======================================================
// 2. RECUPERAR CONTEXTO DE NODOS ANTERIORES
// ======================================================
