function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n =
    Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function objetoSeguro(valor) {

  return (
    valor &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  )
    ? valor
    : {};
}


// ======================================================
// 2. RECUPERAR CONTEXTO DE NODOS ANTERIORES
