      .json ?? {};

} catch (_) {

  conversacion = {};

}


// ======================================================
// 3. IDENTIFICACIÓN
// ======================================================

const conversacionId =
  numeroONull(
    input.conversacion_id ??
    input.id_conversacion ??
    turno.conversacion_id ??
    mediaAudio.conversacion_id ??
    conversacion.conversacion_id ??
    conversacion.id
  );


const prospectoId =
  numeroONull(
    input.prospecto_id ??
    turno.prospecto_id ??
    mediaAudio.prospecto_id ??
    conversacion.prospecto_id
  );


const clienteId =
  numeroONull(
    input.cliente_id ??
    turno.cliente_id ??
    mediaAudio.cliente_id ??
    conversacion.cliente_id
  );


const contactoId =
  numeroONull(
    input.contacto_id ??
    turno.contacto_id ??
    mediaAudio.contacto_id ??
    conversacion.contacto_id
  );


// ======================================================
// 4. TELÉFONO / NOMBRE
// ======================================================

const telefono =
  texto(
    input.telefono ??
    turno.telefono ??
    mediaAudio.telefono ??
    normalizado.telefono ??
    entradaWhatsApp.telefono ??
    conversacion.telefono
  );


const nombreWhatsApp =
  texto(
    input.nombre_whatsapp ??
    input.prospecto_nombre ??
    turno.nombre_whatsapp ??
    mediaAudio.nombre_whatsapp ??
    normalizado.nombre_whatsapp ??
    entradaWhatsApp.nombre_whatsapp ??
    conversacion.nombre_whatsapp ??
    conversacion.prospecto_nombre
  );


// ======================================================
// 5. TIPO DE ENTRADA
// ======================================================

const tipoEntrada =
  (
    texto(
      input.tipo ??
      input.tipo_mensaje ??
      input.tipo_original ??
      input.meta_whatsapp?.tipo_original ??
      mediaAudio.tipo ??
      mediaAudio.tipo_media ??
      normalizado.tipo ??
      entradaWhatsApp.tipo ??
      entradaWhatsApp.meta_whatsapp?.tipo_original
    ) ??
    'DESCONOCIDO'
  ).toUpperCase();


// ======================================================
// 6. MENSAJE ORIGINAL DEL CLIENTE
// ======================================================

let mensajeActual =
  texto(
    input.mensaje_actual
  ) ??
  texto(
    input.mensaje_cliente_original
  ) ??
  texto(
    input.mensaje
  ) ??
  texto(
    input.contenido
  ) ??
  texto(
    input.texto_asociado
  ) ??
  texto(
    input.caption
  ) ??
  texto(
    input.meta_whatsapp?.media?.caption
  ) ??
  texto(
    mediaAudio.texto_asociado
  ) ??
  texto(
    mediaAudio.contenido_base
  ) ??
  texto(
    normalizado.mensaje
  ) ??
  texto(
    entradaWhatsApp.mensaje
  ) ??
  '';


// Si el mensaje quedó únicamente como descriptor de sistema,
// construimos una representación más humana.

if (
  mensajeActual === '[AUDIO]' ||
  mensajeActual === '[VIDEO]' ||
  mensajeActual === '[DOCUMENTO]'
) {

  const descripcionTipo =
    tipoEntrada === 'AUDIO'
      ? 'Audio enviado por el prospecto'
      : tipoEntrada === 'VIDEO'
        ? 'Video enviado por el prospecto'
        : tipoEntrada === 'DOCUMENTO'
          ? 'Documento enviado por el prospecto'
          : 'Archivo enviado por el prospecto';

  mensajeActual =
    `[${descripcionTipo}]`;
}


// ======================================================
// 7. DETECTAR FALLO DE TRANSCRIPCIÓN DE AUDIO
// ======================================================
//
// Esta detección permite que este mismo nodo reciba:
//
// - false de "IF: ¿Transcripción válida Deepgram?"
// - error de "Transcribir audio Deepgram"
// - error de descarga del audio fallback
//
// sin confundirlo con una entrada simplemente no soportada.
// ======================================================

const errorActual =
  texto(
    input.error_transcripcion ??
    input.detalle_error ??
    input.details?.message ??
    input.error?.message ??
    input.error
  );


const proveedorTranscripcion =
  texto(
    input.proveedor_transcripcion ??
    input.proveedor_fallback
  );


const pareceAudio =
  tipoEntrada === 'AUDIO' ||
  tipoEntrada === 'VOICE' ||
  input.audio_preparado === true ||
  input.fallback_audio === true ||
  input.media_id !== undefined ||
  mediaAudio.audio_preparado === true ||
  mediaAudio.media_id !== undefined;


const transcripcionMarcadaInvalida =
  input.transcripcion_valida === false;


const falloDeepgram =
  proveedorTranscripcion === 'DEEPGRAM' ||
  input.proveedor_fallback === 'DEEPGRAM';


const falloTranscripcionAudio =
  pareceAudio &&
  (
    transcripcionMarcadaInvalida ||
    falloDeepgram ||
    errorActual !== null
  );


// ======================================================
// 8. MOTIVO DE HANDOFF
// ======================================================

let motivo =
  'ENTRADA_NO_SOPORTADA';


let prioridad =
  'NORMAL';


let mensajeTransicion =
  'Permítame un momento por favor, ya revisamos lo que nos envió.';


// ------------------------------------------------------
// FALLO TOTAL DE TRANSCRIPCIÓN
// ------------------------------------------------------

if (falloTranscripcionAudio) {

  motivo =
    'AUDIO_REQUIERE_REVISION';

  prioridad =
    'MEDIA';

  mensajeTransicion =
    'Permítame un momento por favor, no pudimos interpretar correctamente el audio que nos envió y vamos a revisarlo manualmente.';

}


// ------------------------------------------------------
// ENTRADA NO SOPORTADA NORMAL
// ------------------------------------------------------

else {

  switch (tipoEntrada) {

    case 'AUDIO':
    case 'VOICE':

      motivo =
        'AUDIO_REQUIERE_REVISION';

      prioridad =
        'MEDIA';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos el audio que nos envió.';

      break;


    case 'VIDEO':

      motivo =
        'VIDEO_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos el video que nos envió.';

      break;


    case 'DOCUMENTO':
    case 'DOCUMENT':

      motivo =
        'DOCUMENTO_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos el archivo que nos envió.';

      break;


    case 'STICKER':

      motivo =
        'STICKER_NO_PROCESABLE';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos su mensaje.';

      break;


    case 'LOCATION':
    case 'UBICACION':

      motivo =
        'UBICACION_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos la ubicación que nos envió.';

      break;


    case 'CONTACT':
    case 'CONTACTO':
    case 'CONTACTS':

      motivo =
        'CONTACTO_REQUIERE_REVISION';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos la información que nos envió.';

      break;


    default:

      motivo =
        'ENTRADA_NO_SOPORTADA';

      mensajeTransicion =
        'Permítame un momento por favor, ya revisamos lo que nos envió.';
  }
}


// ======================================================
// 9. DATOS TÉCNICOS DE AUDIO
// ======================================================

const mediaId =
  texto(
    input.media_id ??
    mediaAudio.media_id ??
    entradaWhatsApp.meta_whatsapp?.media?.id
  );


const mimeType =
  texto(
    input.mime_type ??
    mediaAudio.mime_type ??
    entradaWhatsApp.meta_whatsapp?.media?.mime_type
  );


const indiceAudio =
  numeroONull(
    input.indice_audio ??
    mediaAudio.indice_audio
  );


// ======================================================
// 10. CLASIFICACIÓN DEL ORIGEN DEL HANDOFF
// ======================================================

let origenHandoff =
  'ENTRADA_NO_SOPORTADA';


if (falloTranscripcionAudio) {

  origenHandoff =
    'FALLO_TRANSCRIPCION_AUDIO';

}


// ======================================================
// 11. VALIDACIONES MÍNIMAS
// ======================================================
//
// No obligamos prospecto_id aquí porque existen rutas
// donde podría tratarse de un cliente registrado.
//
// La ruta estándar de derivación decidirá después qué
// identidad debe persistir.
//
// Sí necesitamos conversación para no crear un handoff
// huérfano.
// ======================================================

if (
  conversacionId === null ||
  conversacionId <= 0
) {

  throw new Error(
    'PREPARAR HANDOFF ENTRADA NO SOPORTADA: no se pudo resolver conversacion_id.'
  );

}


// ======================================================
// 12. SALIDA
// ======================================================

return [
  {
    json: {

      // ------------------------------------------------
      // CONSERVAR CONTRATO ORIGINAL
      // ------------------------------------------------

      ...input,


      // ------------------------------------------------
      // IDENTIDAD
      // ------------------------------------------------

      conversacion_id:
        conversacionId,

      prospecto_id:
        prospectoId,

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      telefono,

      nombre_whatsapp:
        nombreWhatsApp,

      prospecto_nombre:
        nombreWhatsApp,


      // ------------------------------------------------
      // DECISIÓN
      // ------------------------------------------------

      intencion:
        'SOLICITAR_HUMANO',

      accion:
        'DERIVAR_HUMANO',

      requiere_humano:
        true,

      requiere_notificacion:
        true,

      handoff_requiere_notificacion:
        true,


      // ------------------------------------------------
      // HANDOFF
      // ------------------------------------------------

      handoff_motivo:
        motivo,

      motivo_derivacion:
        motivo,

      handoff_prioridad:
        prioridad,

      prioridad_derivacion:
        prioridad,

      origen_handoff:
        origenHandoff,

      clasificacion_handoff:
        falloTranscripcionAudio
          ? 'REVISION_AUDIO'
          : 'REVISION_ENTRADA',


      // ------------------------------------------------
      // MENSAJE DEL CLIENTE
      // ------------------------------------------------

      mensaje_actual:
        mensajeActual,

      mensaje_cliente_original:
        mensajeActual,

      handoff_mensaje_cliente:
        mensajeActual,


      // ------------------------------------------------
      // RESPUESTA DE TRANSICIÓN
      // ------------------------------------------------

      respuesta_sugerida:
        mensajeTransicion,

      mensaje_transicion:
        mensajeTransicion,


      // ------------------------------------------------
      // TIPO DE ENTRADA
      // ------------------------------------------------

      tipo_entrada_no_soportada:
        tipoEntrada,


      // ------------------------------------------------
      // AUDIO / TRANSCRIPCIÓN
      // ------------------------------------------------

      fallo_transcripcion_audio:
        falloTranscripcionAudio,

      proveedor_transcripcion:
        proveedorTranscripcion,

      media_id:
        mediaId,

      mime_type:
        mimeType,

      indice_audio:
        indiceAudio,

      error_transcripcion_handoff:
        errorActual,


      // ------------------------------------------------
      // CONTROL
      // ------------------------------------------------

      derivacion_directa_entrada:
        true,

      derivacion_directa:
        true,

      derivacion_directa_motivo:
        falloTranscripcionAudio
          ? 'FALLO_TOTAL_TRANSCRIPCION_AUDIO'
          : 'ENTRADA_NO_SOPORTADA',

      handoff_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// NODO N8N: Preparar audio del turno
// ARCHIVO: code/03-conversacion/preparar-audio-turno.js
// VERSION: 1.0
// RESPONSABILIDAD:
// - Tras resolver el turno conversacional, buscar audios
//   pendientes de transcripción.
// - Leer el descriptor [MEDIA_PENDIENTE] persistido en
//   mensajes.contenido.
// - Revalidar MIME y enlace YCloud.
// - Emitir un item por audio válido.
// - Limitar la cantidad de audios procesados por turno.
// - Conservar identidad y contexto del turno.
// - NO descargar audio.
// - NO transcribir.
// - NO llamar al cerebro comercial.
// - NO escribir PostgreSQL.
// ======================================================


// ======================================================
// 0. CONFIGURACIÓN
// ======================================================

const MAX_AUDIOS_POR_TURNO = 3;

const MAX_LINK_LENGTH = 2048;

const PREFIJO_PENDIENTE =
  '[MEDIA_PENDIENTE] ';


// MIME admitidos para STT.
//
// WhatsApp/YCloud normalmente entrega notas de voz como:
// audio/ogg; codecs=opus
//
// En Preparar entrada WhatsApp el MIME debería llegar
// normalizado sin parámetros:
// audio/ogg
// ======================================================

const MIME_AUDIO_SOPORTADOS = [
  'audio/ogg',
  'audio/opus',
  'audio/mpeg',
  'audio/mp3',
  'audio/mp4',
  'audio/x-m4a',
  'audio/m4a',
  'audio/wav',
  'audio/x-wav',
  'audio/webm'
];


// ======================================================
// ANTI-SSRF
// ======================================================

const LINK_YCLOUD_PERMITIDO =
  /^https:\/\/api\.ycloud\.com\/v2\/whatsapp\/media\/download\/[A-Za-z0-9_-]+(\?[A-Za-z0-9%._~&=+-]*)?$/;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero =
    Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function normalizarMime(valor) {

  const mime =
    textoONull(valor);

  if (!mime) {
    return null;
  }

  return mime
    .toLowerCase()
    .split(';')[0]
    .trim();
}


function lineas(contenido) {

  return String(
    contenido ?? ''
  ).split('\n');
}


// ======================================================
// 2. LEER [MEDIA_PENDIENTE]
// ======================================================

function leerPendiente(contenido) {

  const linea =
    lineas(contenido)
      .map(
        valor =>
          valor.trim()
      )
      .find(
        valor =>
          valor.startsWith(
            PREFIJO_PENDIENTE
          )
      );

  if (!linea) {
    return null;
  }

  const jsonTexto =
    linea.slice(
      PREFIJO_PENDIENTE.length
    );

  try {

    const datos =
      JSON.parse(
        jsonTexto
      );

    if (
      !datos ||
      typeof datos !== 'object' ||
      Array.isArray(datos)
    ) {
      return null;
    }

    return datos;

  } catch (error) {

    return null;
  }
}


// ======================================================
// 3. TEXTO/CAPTION DEL AUDIO
// ======================================================

function textoAudioDe(contenido) {

  const primeraLinea =
    lineas(contenido)[0] ?? '';

  return String(
    primeraLinea
  )
    .replace(
      /^\[AUDIO\]\s*/i,
      ''
    )
    .trim();
}


// ======================================================
// 4. RECUPERAR TURNO GANADOR
// ======================================================
//
// IMPORTANTE:
//
// No dependemos del item que llega inmediatamente
// desde la rama de imágenes.
//
// Leemos directamente el contrato original de:
//
// Resolver turno conversacional
//
// De esta forma audio funciona:
// - haya imágenes o no
// - haya pasado por Groq visual
// - haya pasado por DeepSeek visual
// - haya pasado por OpenAI visual
//
// ======================================================

let turno = {};

try {

  turno =
    $('Resolver turno conversacional')
      .first()
      .json ?? {};

} catch (error) {

  turno =
    $input.first().json ?? {};
}


const turnoMensajes =
  Array.isArray(
    turno.turno_mensajes
  )
    ? turno.turno_mensajes
    : [];


// ======================================================
// 5. IDENTIDAD
// ======================================================

const conversacionId =
  numeroONull(
    turno.conversacion_id
  );


const prospectoId =
  numeroONull(
    turno.prospecto_id
  );


const clienteId =
  numeroONull(
    turno.cliente_id
  );


const contactoId =
  numeroONull(
    turno.contacto_id
  );


const telefono =
  textoONull(
    turno.telefono
  );


const nombreWhatsapp =
  textoONull(
    turno.nombre_whatsapp
  );


// ======================================================
// 6. BUSCAR AUDIOS PENDIENTES
// ======================================================

const candidatos = [];

let descartados = 0;


for (
  const mensaje of turnoMensajes
) {

  const tipo =
    String(
      mensaje.tipo ?? ''
    )
      .trim()
      .toUpperCase();


  // --------------------------------------------------
  // Solo AUDIO
  // --------------------------------------------------

  if (
    tipo !== 'AUDIO'
  ) {
    continue;
  }


  // --------------------------------------------------
  // Descriptor multimedia
  // --------------------------------------------------

  const pendiente =
    leerPendiente(
      mensaje.contenido
    );


  if (!pendiente) {

    descartados++;

    continue;
  }


  const mime =
    normalizarMime(
      pendiente.mime_type
    );


  const link =
    textoONull(
      pendiente.link
    );


  const mediaId =
    textoONull(
      pendiente.media_id
    );


  // --------------------------------------------------
  // Validar formato
  // --------------------------------------------------

  const mimeValido =
    mime !== null &&
    MIME_AUDIO_SOPORTADOS.includes(
      mime
    );


  const linkValido =
    link !== null &&
    link.length <=
      MAX_LINK_LENGTH &&
    LINK_YCLOUD_PERMITIDO.test(
      link
    );


  if (
    !mimeValido ||
    !linkValido
  ) {

    descartados++;

    continue;
  }


  // --------------------------------------------------
  // Límite por turno
  // --------------------------------------------------

  if (
    candidatos.length >=
    MAX_AUDIOS_POR_TURNO
  ) {

    descartados++;

    continue;
  }


  const mensajeId =
    numeroONull(
      mensaje.id
    );


  candidatos.push({

    mensaje_id:
      mensajeId,

    media_id:
      mediaId,

    mime_type:
      mime,

    media_link:
      link,

    texto_asociado:
      textoAudioDe(
        mensaje.contenido
      ),

    contenido_base:
      lineas(
        mensaje.contenido
      )[0]?.trim() ??
      '[AUDIO]',

    enviado_at:
      mensaje.enviado_at ??
      null
  });
}


// ======================================================
// 7. NO HAY AUDIOS
// ======================================================
//
// Emitimos SIEMPRE un item.
//
// Así el IF:
//
// ¿Hay audios por transcribir?
//
// puede evaluar:
//
// {{$json.transcribir_audio}}
//
// ======================================================

if (
  candidatos.length === 0
) {

  return [
    {
      json: {

        transcribir_audio:
          false,

        audios_por_transcribir:
          0,

        audios_descartados:
          descartados,


        // ----------------------------------------------
        // IDENTIDAD
        // ----------------------------------------------

        conversacion_id:
          conversacionId,

        prospecto_id:
          prospectoId,

        cliente_id:
          clienteId,

        contacto_id:
          contactoId,

        telefono,

        nombre_whatsapp:
          nombreWhatsapp,


        // ----------------------------------------------
        // TURNO
        // ----------------------------------------------

        turno_mensaje_ids:
          Array.isArray(
            turno.turno_mensaje_ids
          )
            ? turno.turno_mensaje_ids
            : [],

        turno_desde_id:
          numeroONull(
            turno.turno_desde_id
          ),

        turno_hasta_id:
          numeroONull(
            turno.turno_hasta_id
          ),

        turno_texto:
          textoONull(
            turno.turno_texto
          ),


        // ----------------------------------------------
        // CONTROL
        // ----------------------------------------------

        audio_preparado:
          true
      }
    }
  ];
}


// ======================================================
// 8. HAY AUDIOS
// ======================================================
//
// Un item por audio.
//
// Eso permite que:
//
// Descargar audio YCloud
//
// procese cada archivo individualmente.
//
// ======================================================

return candidatos.map(
  (audio, indice) => ({
    json: {

      // ----------------------------------------------
      // CONTROL AUDIO
      // ----------------------------------------------

      transcribir_audio:
        true,

      audios_por_transcribir:
        candidatos.length,

      audios_descartados:
        descartados,

      indice_audio:
        indice,


      // ----------------------------------------------
      // IDENTIDAD
      // ----------------------------------------------

      conversacion_id:
        conversacionId,

      prospecto_id:
        prospectoId,

      cliente_id:
        clienteId,

      contacto_id:
        contactoId,

      telefono,

      nombre_whatsapp:
        nombreWhatsapp,


      // ----------------------------------------------
      // AUDIO
      // ----------------------------------------------

      ...audio,


      // ----------------------------------------------
      // TURNO
      // ----------------------------------------------

      turno_mensaje_ids:
        Array.isArray(
          turno.turno_mensaje_ids
        )
          ? turno.turno_mensaje_ids
          : [],

      turno_desde_id:
        numeroONull(
          turno.turno_desde_id
        ),

      turno_hasta_id:
        numeroONull(
          turno.turno_hasta_id
        ),

      turno_texto:
        textoONull(
          turno.turno_texto
        ),


      // ----------------------------------------------
      // CONTROL
      // ----------------------------------------------

      audio_preparado:
        true
    }
  })
);

// ======================================================
// NODO N8N: Validar transcripción audio
// ARCHIVO: code/03-conversacion/validar-transcripcion-audio.js
// VERSION: 2.0
// ======================================================
//
// RESPONSABILIDAD:
//
// - Validar transcripciones provenientes de:
//
//   1. Groq Whisper
//   2. Deepgram Nova
//
// - Detectar automáticamente qué proveedor respondió.
// - Recuperar identidad del audio desde
//   "Preparar audio del turno".
// - Emparejar por posición:
//      indice_audio
//      mensaje_id
//      media_id
//      conversacion_id
// - Entregar un contrato uniforme para:
//
//      IF: ¿Transcripción válida?
//      Aplicar transcripciones al turno
//
// - NO interpretar comercialmente.
// - NO llamar al cerebro comercial.
// - NO escribir PostgreSQL.
// - NO lanzar error por fallo de STT.
//
// ======================================================


const LARGO_MAXIMO_TRANSCRIPCION = 12000;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor, limite = null) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  let limpio = String(valor)
    .replace(/\u0000/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s*\n\s*/g, ' ')
    .trim();

  if (!limpio) {
    return null;
  }

  if (
    limite !== null &&
    Number.isFinite(limite) &&
    limite > 0
  ) {
    limpio = limpio.slice(0, limite);
  }

  return limpio;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero = Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function normalizarError(valor) {

  if (!valor) {
    return null;
  }

  if (typeof valor === 'string') {
    return textoONull(valor, 1500);
  }

  if (typeof valor === 'object') {

    try {
      return textoONull(
        JSON.stringify(valor),
        1500
      );
    } catch (_) {
      return 'ERROR_NO_SERIALIZABLE';
    }

  }

  return textoONull(
    valor,
    1500
  );
}


// ======================================================
// 2. DETECTAR ERROR HTTP / N8N
// ======================================================

function detectarErrorRespuesta(json) {

  if (
    !json ||
    typeof json !== 'object'
  ) {
    return {
      existe: true,
      motivo: 'RESPUESTA_VACIA',
      error: 'La respuesta del proveedor STT está vacía.'
    };
  }


  // --------------------------------------------------
// Errores n8n HTTP Request
// --------------------------------------------------

  if (json.error) {

    return {
      existe: true,
      motivo: 'ERROR_TRANSCRIPCION',
      error:
        normalizarError(
          json.error
        ) ??
        'El proveedor de transcripción devolvió un error.'
    };

  }


  if (
    numeroONull(
      json.statusCode
    ) !== null &&
    Number(
      json.statusCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.message ??
          json.body ??
          json
        )
    };

  }


  if (
    numeroONull(
      json.details?.httpCode
    ) !== null &&
    Number(
      json.details.httpCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.details
        )
    };

  }


  return {
    existe: false,
    motivo: null,
    error: null
  };
}


// ======================================================
// 3. LEER RESPUESTA GROQ
// ======================================================
//
// Groq:
//
// {
//   "text": "..."
// }
//
// ======================================================

function leerGroq(json) {

  const texto =
    textoONull(
      json.text ??
      json.body?.text ??
      json.data?.text ??
      json.response?.text,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  if (!texto) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'GROQ',

    modelo:
      'whisper-large-v3-turbo',

    texto,

    confianza:
      null,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 4. LEER RESPUESTA DEEPGRAM
// ======================================================
//
// Deepgram:
//
// {
//   results: {
//     channels: [
//       {
//         alternatives: [
//           {
//             transcript: "...",
//             confidence: 0.99
//           }
//         ]
//       }
//     ]
//   }
// }
//
// ======================================================

function leerDeepgram(json) {

  const alternativa =
    json.results
      ?.channels
      ?.[0]
      ?.alternatives
      ?.[0] ??
    null;


  const texto =
    textoONull(
      alternativa?.transcript ??
      json.results
        ?.utterances
        ?.[0]
        ?.transcript ??
      json.results
        ?.channels
        ?.[0]
        ?.alternatives
        ?.[0]
        ?.paragraphs
        ?.transcript,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  const confianza =
    numeroONull(
      alternativa?.confidence
    );


  const pareceDeepgram =
    !!json.metadata ||
    !!json.results?.channels ||
    !!json.results?.utterances;


  if (!pareceDeepgram) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  if (!texto) {

    return {
      reconocido: true,
      valido: false,

      proveedor:
        'DEEPGRAM',

      modelo:
        json.metadata?.model_info
          ? Object.values(
              json.metadata.model_info
            )[0]?.name ?? 'nova-3'
          : 'nova-3',

      texto:
        null,

      confianza,

      motivo:
        'TRANSCRIPCION_VACIA',

      error:
        'Deepgram respondió correctamente pero no devolvió texto utilizable.'
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'DEEPGRAM',

    modelo:
      json.metadata?.model_info
        ? Object.values(
            json.metadata.model_info
          )[0]?.name ?? 'nova-3'
        : 'nova-3',

    texto,

    confianza,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 5. LEER RESPUESTA STT
// ======================================================

function leerRespuestaSTT(json) {

  const error =
    detectarErrorRespuesta(
      json
    );


  if (
    error.existe
  ) {

    return {
      valido:
        false,

      proveedor:
        null,

      modelo:
        null,

      texto:
        null,

      confianza:
        null,

      motivo:
        error.motivo,

      error:
        error.error
    };

  }


  // --------------------------------------------------
// 5.1 DEEPGRAM
// --------------------------------------------------

  const deepgram =
    leerDeepgram(
      json
    );


  if (
    deepgram.reconocido
  ) {
    return deepgram;
  }


  // --------------------------------------------------
// 5.2 GROQ
// --------------------------------------------------

  const groq =
    leerGroq(
      json
    );


  if (
    groq.reconocido
  ) {
    return groq;
  }


  // --------------------------------------------------
// 5.3 DESCONOCIDO
// --------------------------------------------------

  return {
    valido:
      false,

    proveedor:
      null,

    modelo:
      null,

    texto:
      null,

    confianza:
      null,

    motivo:
      'FORMATO_RESPUESTA_DESCONOCIDO',

    error:
      'El proveedor STT respondió, pero el formato de respuesta no coincide con Groq ni Deepgram.'
  };
}


