        ),

      contacto_id:
        numeroONull(
          audioOrigen.contacto_id ??
          turno.contacto_id
        ),

      telefono:
        textoONull(
          audioOrigen.telefono ??
          turno.telefono
        ),

      nombre_whatsapp:
        textoONull(
          audioOrigen.nombre_whatsapp ??
          turno.nombre_whatsapp
        ),


      // ==================================================
      // TURNO ENRIQUECIDO
      // ==================================================

      turno_mensajes:
        mensajesActualizados,

      turno_texto:
        turnoTextoActualizado,

      turno_mensaje_ids:
        mensajesActualizados
          .map(m => numeroONull(m.id))
          .filter(id => id !== null),

      cantidad_mensajes_turno:
        mensajesActualizados.length,


      // ==================================================
      // TRANSCRIPCIONES
      // ==================================================

      transcripciones_audio:
        transcripciones,

      audios_en_turno:
        audiosEnTurno,

      transcripciones_validas:
        transcripcionesValidas,

      transcripciones_fallidas:
        transcripcionesFallidas,

      audios_sin_resultado:
        audiosSinResultado,


      // ==================================================
      // CONTROL GLOBAL
      // ==================================================

      audio_procesado:
        true,

      audio_listo_para_cerebro:
        audioListoParaCerebro,

      requiere_revision_audio:
        requiereRevisionAudio,

      motivos_revision_audio:
        Array.from(
          motivosRevision
        ),

      transcripciones_aplicadas:
        transcripcionesValidas > 0,

      procesado_audio_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// NODO N8N: Preparar fallback Deepgram
// PEGASO ADHESIVOS
// VERSION: 1.0
// ======================================================
//
// Se ejecuta cuando la transcripción primaria con Groq
// no fue válida.
//
// RESPONSABILIDAD:
//
// - Recibir uno o varios audios fallidos.
// - Recuperar su metadata original desde
//   "Preparar audio del turno".
// - Emparejar por mensaje_id / media_id.
// - Preparar nuevamente media_link para volver a
//   descargar el archivo desde YCloud.
// - NO transcribir.
// - NO decidir handoff.
// ======================================================

const fallidos = $input.all();


// ======================================================
// 1. HELPERS
// ======================================================

function numeroONull(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const n = Number(valor);

  return Number.isFinite(n)
    ? n
    : null;
}


function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const t = String(valor).trim();

  return t !== ''
    ? t
    : null;
}


// ======================================================
// 2. RECUPERAR AUDIOS ORIGINALES
// ======================================================

let originales = [];

try {
  originales =
    $('Preparar audio del turno')
      .all()
      .map(item => item.json ?? {});
} catch (_) {
  originales = [];
}


// ======================================================
// 3. EMPAREJAR FALLIDOS CON AUDIO ORIGINAL
// ======================================================

const resultados = fallidos.map((item, indice) => {

  const fallido =
    item.json ?? {};

  const mensajeId =
    numeroONull(fallido.mensaje_id);

  const mediaId =
    textoONull(fallido.media_id);


  // --------------------------------------------------
  // Buscar preferentemente por mensaje_id.
  // Si no existe, por media_id.
  // Último fallback: posición.
  // --------------------------------------------------

  let original =
    originales.find(o =>
      mensajeId !== null &&
      numeroONull(o.mensaje_id) === mensajeId
    );

  if (!original && mediaId) {
    original =
      originales.find(o =>
        textoONull(o.media_id) === mediaId
      );
  }

  if (!original) {
    original =
      originales[indice] ?? {};
  }


  // ==================================================
  // 4. DATOS DEL AUDIO
  // ==================================================

  const mediaLink =
    textoONull(
      original.media_link ??
      fallido.media_link
    );

  const mimeType =
    textoONull(
      original.mime_type ??
      fallido.mime_type
    ) ??
    'audio/ogg';

  const mediaIdFinal =
    textoONull(
      original.media_id ??
      fallido.media_id
    );

  const mensajeIdFinal =
    numeroONull(
      original.mensaje_id ??
      fallido.mensaje_id
    );


  if (!mediaLink) {
    throw new Error(
      `PREPARAR FALLBACK DEEPGRAM: no se pudo recuperar media_link para mensaje_id=${mensajeIdFinal ?? 'null'}.`
    );
  }


  // ==================================================
  // 5. SALIDA
  // ==================================================

  return {
    json: {

      ...fallido,

      mensaje_id:
        mensajeIdFinal,

      media_id:
        mediaIdFinal,

      media_link:
        mediaLink,

      mime_type:
        mimeType,

      indice_audio:
        numeroONull(
          original.indice_audio ??
          fallido.indice_audio
        ) ?? indice,

      conversacion_id:
        numeroONull(
          original.conversacion_id ??
          fallido.conversacion_id
        ),

      prospecto_id:
        numeroONull(
          original.prospecto_id ??
          fallido.prospecto_id
        ),

      telefono:
        textoONull(
          original.telefono ??
          fallido.telefono
        ),

      nombre_whatsapp:
        textoONull(
          original.nombre_whatsapp ??
          fallido.nombre_whatsapp
        ),

      proveedor_fallback:
        'DEEPGRAM',

      fallback_audio:
        true,

      fallback_preparado_at:
        new Date().toISOString()
    }
  };
});

return resultados;

// ======================================================
// NODO N8N: Validar transcripción audio
// ARCHIVO: code/03-conversacion/validar-transcripcion-audio.js
// VERSION: 2.0
// ======================================================
//
// RESPONSABILIDAD:
//
// - Validar transcripciones provenientes de:
//
//   1. Groq Whisper
//   2. Deepgram Nova
//
// - Detectar automáticamente qué proveedor respondió.
// - Recuperar identidad del audio desde
//   "Preparar audio del turno".
// - Emparejar por posición:
//      indice_audio
//      mensaje_id
//      media_id
//      conversacion_id
// - Entregar un contrato uniforme para:
//
//      IF: ¿Transcripción válida?
//      Aplicar transcripciones al turno
//
// - NO interpretar comercialmente.
// - NO llamar al cerebro comercial.
// - NO escribir PostgreSQL.
// - NO lanzar error por fallo de STT.
//
// ======================================================


const LARGO_MAXIMO_TRANSCRIPCION = 12000;


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor, limite = null) {

  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  let limpio = String(valor)
    .replace(/\u0000/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s*\n\s*/g, ' ')
    .trim();

  if (!limpio) {
    return null;
  }

  if (
    limite !== null &&
    Number.isFinite(limite) &&
    limite > 0
  ) {
    limpio = limpio.slice(0, limite);
  }

  return limpio;
}


function numeroONull(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  const numero = Number(valor);

  return Number.isFinite(numero)
    ? numero
    : null;
}


function normalizarError(valor) {

  if (!valor) {
    return null;
  }

  if (typeof valor === 'string') {
    return textoONull(valor, 1500);
  }

  if (typeof valor === 'object') {

    try {
      return textoONull(
        JSON.stringify(valor),
        1500
      );
    } catch (_) {
      return 'ERROR_NO_SERIALIZABLE';
    }

  }

  return textoONull(
    valor,
    1500
  );
}


// ======================================================
// 2. DETECTAR ERROR HTTP / N8N
// ======================================================

function detectarErrorRespuesta(json) {

  if (
    !json ||
    typeof json !== 'object'
  ) {
    return {
      existe: true,
      motivo: 'RESPUESTA_VACIA',
      error: 'La respuesta del proveedor STT está vacía.'
    };
  }


  // --------------------------------------------------
// Errores n8n HTTP Request
// --------------------------------------------------

  if (json.error) {

    return {
      existe: true,
      motivo: 'ERROR_TRANSCRIPCION',
      error:
        normalizarError(
          json.error
        ) ??
        'El proveedor de transcripción devolvió un error.'
    };

  }


  if (
    numeroONull(
      json.statusCode
    ) !== null &&
    Number(
      json.statusCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.message ??
          json.body ??
          json
        )
    };

  }


  if (
    numeroONull(
      json.details?.httpCode
    ) !== null &&
    Number(
      json.details.httpCode
    ) >= 400
  ) {

    return {
      existe: true,
      motivo: 'ERROR_HTTP_TRANSCRIPCION',
      error:
        normalizarError(
          json.details
        )
    };

  }


  return {
    existe: false,
    motivo: null,
    error: null
  };
}


// ======================================================
// 3. LEER RESPUESTA GROQ
// ======================================================
//
// Groq:
//
// {
//   "text": "..."
// }
//
// ======================================================

function leerGroq(json) {

  const texto =
    textoONull(
      json.text ??
      json.body?.text ??
      json.data?.text ??
      json.response?.text,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  if (!texto) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'GROQ',

    modelo:
      'whisper-large-v3-turbo',

    texto,

    confianza:
      null,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 4. LEER RESPUESTA DEEPGRAM
// ======================================================
//
// Deepgram:
//
// {
//   results: {
//     channels: [
//       {
//         alternatives: [
//           {
//             transcript: "...",
//             confidence: 0.99
//           }
//         ]
//       }
//     ]
//   }
// }
//
// ======================================================

function leerDeepgram(json) {

  const alternativa =
    json.results
      ?.channels
      ?.[0]
      ?.alternatives
      ?.[0] ??
    null;


  const texto =
    textoONull(
      alternativa?.transcript ??
      json.results
        ?.utterances
        ?.[0]
        ?.transcript ??
      json.results
        ?.channels
        ?.[0]
        ?.alternatives
        ?.[0]
        ?.paragraphs
        ?.transcript,
      LARGO_MAXIMO_TRANSCRIPCION
    );


  const confianza =
    numeroONull(
      alternativa?.confidence
    );


  const pareceDeepgram =
    !!json.metadata ||
    !!json.results?.channels ||
    !!json.results?.utterances;


  if (!pareceDeepgram) {

    return {
      reconocido: false,
      valido: false,
      proveedor: null,
      modelo: null,
      texto: null,
      confianza: null,
      motivo: null,
      error: null
    };

  }


  if (!texto) {

    return {
      reconocido: true,
      valido: false,

      proveedor:
        'DEEPGRAM',

      modelo:
        json.metadata?.model_info
          ? Object.values(
              json.metadata.model_info
            )[0]?.name ?? 'nova-3'
          : 'nova-3',

      texto:
        null,

      confianza,

      motivo:
        'TRANSCRIPCION_VACIA',

      error:
        'Deepgram respondió correctamente pero no devolvió texto utilizable.'
    };

  }


  return {
    reconocido: true,
    valido: true,

    proveedor:
      'DEEPGRAM',

    modelo:
      json.metadata?.model_info
        ? Object.values(
            json.metadata.model_info
          )[0]?.name ?? 'nova-3'
        : 'nova-3',

    texto,

    confianza,

    motivo:
      null,

    error:
      null
  };
}


// ======================================================
// 5. LEER RESPUESTA STT
// ======================================================

function leerRespuestaSTT(json) {

  const error =
    detectarErrorRespuesta(
      json
    );


  if (
    error.existe
  ) {

    return {
      valido:
        false,

      proveedor:
        null,

      modelo:
        null,

      texto:
        null,

      confianza:
        null,

      motivo:
        error.motivo,

      error:
        error.error
    };

  }


  // --------------------------------------------------
// 5.1 DEEPGRAM
// --------------------------------------------------

  const deepgram =
    leerDeepgram(
      json
    );


  if (
    deepgram.reconocido
  ) {
    return deepgram;
  }


  // --------------------------------------------------
// 5.2 GROQ
// --------------------------------------------------

  const groq =
    leerGroq(
      json
    );


  if (
    groq.reconocido
  ) {
    return groq;
  }


  // --------------------------------------------------
// 5.3 DESCONOCIDO
// --------------------------------------------------

  return {
    valido:
      false,

    proveedor:
      null,

    modelo:
      null,

    texto:
      null,

    confianza:
      null,

    motivo:
      'FORMATO_RESPUESTA_DESCONOCIDO',

    error:
      'El proveedor STT respondió, pero el formato de respuesta no coincide con Groq ni Deepgram.'
  };
}


// ======================================================
// 6. RECUPERAR AUDIOS ORIGINALES
// ======================================================
//
// "Preparar audio del turno" sigue siendo la fuente
// principal de identidad.
//
// ======================================================

let origenes = [];

try {

  origenes =
    $('Preparar audio del turno')
      .all()
      .map(
        item =>
          item.json ?? {}
      )
      .filter(
        item =>
          item.transcribir_audio === true
      );

} catch (_) {

  origenes = [];

}


const entradas =
  $input.all();


// ======================================================
// 7. CONSISTENCIA DEL LOTE
// ======================================================

const loteConsistente =
  origenes.length ===
  entradas.length;


// ======================================================
// 8. PROCESAR RESPUESTAS
// ======================================================

const resultados =
  entradas.map(
    (item, indice) => {

      const respuesta =
        item.json ?? {};


      const origen =
        origenes[indice] ?? {};


      const lectura =
