        ) ??
        indice;


      const mediaId =
        textoONull(
          origen.media_id
        );


      const conversacionId =
        numeroONull(
          origen.conversacion_id
        );


      const contenidoBase =
        textoONull(
          origen.contenido_base,
          1500
        ) ??
        '[AUDIO]';


      const prospectoId =
        numeroONull(
          origen.prospecto_id
        );


      const clienteId =
        numeroONull(
          origen.cliente_id
        );


      const contactoId =
        numeroONull(
          origen.contacto_id
        );


      const telefono =
        textoONull(
          origen.telefono
        );


      const nombreWhatsApp =
        textoONull(
          origen.nombre_whatsapp
        );


      const mimeType =
        textoONull(
          origen.mime_type
        );


      const textoAsociado =
        textoONull(
          origen.texto_asociado
        );


      // ==================================================
      // 8.1 ERROR DE CORRELACIÓN
      // ==================================================

      if (
        !loteConsistente
      ) {

        return {
          json: {

            mensaje_id:
              mensajeId,

            indice_audio:
              indiceAudio,

            media_id:
              mediaId,

            conversacion_id:
              conversacionId,

            prospecto_id:
              prospectoId,

            cliente_id:
              clienteId,

            contacto_id:
              contactoId,

