            contenido_actualizado:
              `${contenidoBase}\n` +
              '[TRANSCRIPCION DE AUDIO · revision=SI · motivo=LOTE_AUDIO_INCONSISTENTE] ' +
              'No fue posible asociar de forma segura la transcripción con el audio original.',

            transcripcion_validada_at:
              new Date().toISOString()

          }
        };

      }


      // ==================================================
      // 8.2 IDENTIDAD INSUFICIENTE
      // ==================================================

      if (
        mensajeId === null ||
        conversacionId === null
      ) {

        return {
          json: {

            mensaje_id:
              mensajeId,

            indice_audio:
              indiceAudio,

            media_id:
              mediaId,

            conversacion_id:
              conversacionId,

            prospecto_id:
              prospectoId,

            cliente_id:
              clienteId,

