            proveedor_transcripcion:
              lectura.proveedor,

            modelo_transcripcion:
              lectura.modelo,

            transcripcion_valida:
              false,

            requiere_revision:
              true,

            motivo_revision:
              'IDENTIDAD_AUDIO_INCOMPLETA',

            texto_transcrito:
              null,

            confianza_transcripcion:
              lectura.confianza,

            error_transcripcion:
