            contenido_actualizado:
              `${contenidoBase}\n` +
              `[TRANSCRIPCION DE AUDIO · proveedor=${proveedor} · revision=SI · motivo=${motivo}] ` +
              'No fue posible transcribir automáticamente este audio.',

            transcripcion_validada_at:
              new Date().toISOString()

          }
        };

      }


      // ==================================================
      // 8.4 TRANSCRIPCIÓN VÁLIDA
      // ==================================================

      const textoTranscrito =
        lectura.texto;


      return {
        json: {

          // ----------------------------------------------
          // IDENTIDAD
          // ----------------------------------------------

          mensaje_id:
            mensajeId,

          indice_audio:
            indiceAudio,

          media_id:
            mediaId,

          conversacion_id:
            conversacionId,

          prospecto_id:
            prospectoId,

          cliente_id:
            clienteId,

          contacto_id:
            contactoId,

          telefono,

          nombre_whatsapp:
            nombreWhatsApp,


          // ----------------------------------------------
          // TRANSCRIPCIÓN
          // ----------------------------------------------

          proveedor_transcripcion:
            lectura.proveedor,

          modelo_transcripcion:
            lectura.modelo,

          transcripcion_valida:
            true,

          requiere_revision:
            false,

          motivo_revision:
            null,

          texto_transcrito:
            textoTranscrito,

          confianza_transcripcion:
            lectura.confianza,

          error_transcripcion:
            null,


          // ----------------------------------------------
          // CONTEXTO ORIGINAL
          // ----------------------------------------------

          mime_type:
            mimeType,

          texto_asociado:
            textoAsociado,

          contenido_base:
            contenidoBase,


          // ----------------------------------------------
          // CONTENIDO SEGURO PARA IA
          // ----------------------------------------------

          contenido_actualizado:
            `${contenidoBase}\n` +
            `[TRANSCRIPCION DE AUDIO · proveedor=${lectura.proveedor}] ${textoTranscrito}`,


          // ----------------------------------------------
          // CONTROL
          // ----------------------------------------------

          transcripcion_validada_at:
            new Date().toISOString()

        }
      };

    }
  );


// ======================================================
// 9. SALIDA
// ======================================================

return resultados;

