// ======================================================
// NODO N8N: PROCESAR COMANDO BOT
// PEGASO ADHESIVOS
// VERSION: 2.0
// ======================================================
//
// Objetivo:
//
// Interpretar comandos administrativos enviados por
// teléfonos autorizados:
//
// STOP  -> activa MODO_PRUEBA
// START -> desactiva MODO_PRUEBA
// ACTIVEBOT 0999999999 -> el bot vuelve a atender a ese
//   prospecto (requiere_humano = false), lo ejecuta
//   "Reactivar bot prospecto"
//
// Este nodo:
// - NO procesa conversaciones comerciales
// - NO busca prospectos
// - NO responde al cerebro comercial
// - NO modifica PostgreSQL
// - Entrega telefono_objetivo solo con dígitos y prefijo
//   593 (0999999999 -> 593999999999)
//
// ======================================================

const input = $input.first().json ?? {};


// ======================================================
// 1. HELPERS
// ======================================================

function textoONull(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor).trim();

  return limpio !== ''
    ? limpio
    : null;
}

function limpiarTelefono(valor) {
  if (
    valor === undefined ||
    valor === null
  ) {
    return null;
  }

  const limpio =
    String(valor)
      .replace(/\D/g, '')
      .trim();

  return limpio || null;
}


// ======================================================
// 2. RECUPERAR EVENTO
// ======================================================

const evento =
  input.evento_whatsapp ??
  input;


// ======================================================
// 3. ADMINISTRADORES AUTORIZADOS
// ======================================================

const ADMINISTRADORES = [
  '593996588558',
  '593999217750'
];


// ======================================================
// 4. RESOLVER DATOS
// ======================================================

const telefonoAdmin =
  limpiarTelefono(
    evento.telefono_cliente ??
    evento.from
  );

const textoRecibido =
  textoONull(
    evento.texto ??
    evento.text?.body
  );

const textoComando =
  textoRecibido
    ? textoRecibido.toUpperCase().replace(/\s+/g, ' ')
    : null;

const coincidenciaActivebot =
  textoComando
    ? textoComando.match(/^ACTIVEBOT ([+\d][\d\s\-().]*)$/)
    : null;

const comando =
  coincidenciaActivebot
    ? 'ACTIVEBOT'
    : textoComando;


// Ecuador: 0999999999 / 999999999 / +593 99 999 9999 -> 593999999999
function telefonoEcuador(valor) {
  const digitos =
    limpiarTelefono(valor);

  if (!digitos) {
    return null;
  }

  if (digitos.startsWith('593')) {
    return digitos;
  }

  if (digitos.startsWith('0')) {
    return '593' + digitos.substring(1);
  }

  if (digitos.length === 9) {
    return '593' + digitos;
  }

  return digitos;
}


// ======================================================
// 5. VALIDAR ADMINISTRADOR
// ======================================================

if (
  !telefonoAdmin ||
  !ADMINISTRADORES.includes(telefonoAdmin)
) {
  throw new Error(
    'PROCESAR COMANDO BOT: teléfono no autorizado.'
  );
}


// ======================================================
// 6. VALIDAR COMANDO
// ======================================================

if (
  comando !== 'STOP' &&
  comando !== 'START' &&
  comando !== 'ACTIVEBOT'
) {
  throw new Error(
    `PROCESAR COMANDO BOT: comando no soportado: ${comando ?? 'NULL'}.`
  );
}

const telefonoObjetivo =
  coincidenciaActivebot
    ? telefonoEcuador(coincidenciaActivebot[1])
    : null;

if (
  comando === 'ACTIVEBOT' &&
  !/^\d{11,15}$/.test(telefonoObjetivo ?? '')
) {
  throw new Error(
    `PROCESAR COMANDO BOT: teléfono inválido en ACTIVEBOT: ${coincidenciaActivebot?.[1] ?? 'NULL'}.`
  );
}


// ======================================================
// 7. RESOLVER NUEVO ESTADO
// ======================================================

const modoPruebaNuevo =
  comando === 'STOP';

const botHabilitado =
  comando === 'START';

const MOTIVOS = {
  STOP: 'COMANDO_ADMIN_STOP',
  START: 'COMANDO_ADMIN_START',
  ACTIVEBOT: 'COMANDO_ADMIN_ACTIVEBOT'
};


// ======================================================
// 8. SALIDA
// ======================================================

return [
  {
    json: {
      comando_bot:
        comando,

      telefono_admin:
        telefonoAdmin,

      modo_prueba_nuevo:
        modoPruebaNuevo,

      bot_habilitado:
        botHabilitado,

      telefono_objetivo:
        telefonoObjetivo,

      motivo_cambio:
        MOTIVOS[comando],

      mensaje_externo_id:
        evento.mensaje_id ??
        evento.wamid ??
        null,

      proveedor_evento_id:
        evento.proveedor_evento_id ??
        null,

      comando_valido:
        true,

      procesado_at:
        new Date().toISOString()
    }
  }
];

// ======================================================
// NORMALIZAR INTERVENCIÓN HUMANA
// PEGASO ADHESIVOS
// VERSION 1.1
// RESPONSABILIDAD:
// - Normalizar todo mensaje SALIENTE enviado desde la app
//   WhatsApp Business (echo YCloud) para registrarlo.
// - intervencion_humana = false cuando el echo es una
//   automatización de la app (clasificacion_mensaje =
//   SALIENTE_AUTOMATICO): se registra pero no marca
//   atención humana.
// - El contenido de un automático se guarda con el prefijo
//   [AUTOMATICO WHATSAPP BUSINESS · accion=...] para que
//   el historial lo distinga de un mensaje humano.
// ======================================================

const PREFIJO_AUTOMATICO =
  '[AUTOMATICO WHATSAPP BUSINESS';

const input = $input.first()?.json ?? {};

function textoONull(valor) {
  if (valor === undefined || valor === null) {
    return null;
  }

  const t = String(valor).trim();
  return t !== '' ? t : null;
}

function telefono(valor) {
  if (valor === undefined || valor === null) {
    return null;
  }

  const t = String(valor)
    .replace(/\D/g, '')
    .trim();

  return t || null;
}


// ======================================================
// EVENTO NORMALIZADO
// ======================================================

const evento =
  input.evento_whatsapp ??
  input;


// ======================================================
// TELÉFONO CLIENTE
// ======================================================
//
// Para mensajes enviados por Pegaso:
//
// Pegaso = FROM
// Cliente = TO
//
// Si el normalizador ya resolvió telefono_cliente,
// lo usamos primero.
// ======================================================

const telefonoCliente =
  telefono(
    evento.telefono_cliente ??
    evento.to ??
    evento.destino ??
    null
  );

if (!telefonoCliente) {
  throw new Error(
    'INTERVENCION HUMANA: no se pudo resolver telefono_cliente.'
  );
}


// ======================================================
// TELÉFONO PEGASO
// ======================================================

const telefonoPegaso =
  telefono(
    evento.display_phone_number ??
    evento.from ??
    null
  );


// ======================================================
// TIPO
// ======================================================

const tipoOriginal =
  String(
    evento.tipo_mensaje ??
    evento.tipo ??
    'text'
  )
    .trim()
    .toLowerCase();

let tipo = 'DESCONOCIDO';

switch (tipoOriginal) {
  case 'text':
    tipo = 'TEXTO';
    break;

  case 'image':
    tipo = 'IMAGEN';
    break;

  case 'audio':
    tipo = 'AUDIO';
    break;

  case 'video':
    tipo = 'VIDEO';
    break;

  case 'document':
    tipo = 'DOCUMENTO';
    break;

  case 'sticker':
    tipo = 'STICKER';
    break;

  case 'location':
    tipo = 'UBICACION';
    break;
}


// ======================================================
// CONTENIDO
// ======================================================

let contenido = null;

if (tipo === 'TEXTO') {
  contenido =
    textoONull(
      evento.texto ??
      evento.text?.body ??
      evento.mensaje
    );
}

else if (tipo === 'IMAGEN') {
  const caption =
    textoONull(
      evento.caption
    );

  contenido =
    caption
      ? `[IMAGEN] ${caption}`
      : '[IMAGEN]';
}

else if (tipo === 'AUDIO') {
  contenido = '[AUDIO]';
}

else if (tipo === 'VIDEO') {
  const caption =
    textoONull(
      evento.caption
    );

  contenido =
    caption
      ? `[VIDEO] ${caption}`
      : '[VIDEO]';
}

else if (tipo === 'DOCUMENTO') {
  const caption =
    textoONull(
      evento.caption
    );

  contenido =
    caption
      ? `[DOCUMENTO] ${caption}`
      : '[DOCUMENTO]';
}

else {
  contenido =
    `[MENSAJE MANUAL ${tipo}]`;
}


// ======================================================
// AUTOMATIZACIÓN WHATSAPP BUSINESS
// ======================================================

const esAutomatico =
  evento.es_mensaje_automatico_pegaso === true;

const accionEquivalente =
  textoONull(
    evento.accion_equivalente
  );

if (esAutomatico) {
  contenido =
    `${PREFIJO_AUTOMATICO} · accion=${accionEquivalente ?? 'NINGUNA'}] ${contenido ?? ''}`.trim();
}


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      intervencion_humana:
        !esAutomatico,

      origen_mensaje:
        esAutomatico
          ? 'AUTOMATICO_WHATSAPP_BUSINESS'
          : 'HUMANO',

      clasificacion_mensaje:
        esAutomatico
          ? 'SALIENTE_AUTOMATICO'
          : 'SALIENTE_HUMANO',

      automatizacion_codigo:
        textoONull(
          evento.automatizacion_codigo
        ),

      accion_equivalente:
        accionEquivalente,

      enviado_por_bot: false,

      canal: 'WHATSAPP',

      proveedor: 'YCLOUD',

      telefono_cliente:
        telefonoCliente,

      telefono_pegaso:
        telefonoPegaso,

      tipo,

      tipo_original:
        tipoOriginal,

      contenido,

      mensaje_externo_id:
        evento.mensaje_id ??
        evento.wamid ??
        null,

      proveedor_evento_id:
        evento.proveedor_evento_id ??
        null,

      enviado_at:
        evento.fecha_mensaje ??
        (
          evento.timestamp
            ? new Date(
                Number(evento.timestamp) * 1000
              ).toISOString()
            : new Date().toISOString()
        ),

      normalizado_at:
        new Date().toISOString()

    }
  }
];

// ======================================================
// PREPARAR MENSAJE HUMANO SALIENTE
// PEGASO ADHESIVOS
// VERSION 1.2
// RESPONSABILIDAD:
// - Armar la fila SALIENTE del echo de WhatsApp Business
//   (humano o automatización) para "Guardar mensaje humano
//   saliente", conservando mensaje_externo_id.
// - origen_mensaje / intervencion_humana vienen de
//   "Normalizar intervención humana", salvo que "Buscar
//   prospecto intervención humana" marque
//   respuesta_rapida_apertura: el eco es la respuesta
//   automática de una pregunta rápida del anuncio y se
//   guarda como AUTOMATICO (no humano).
// ======================================================

const PREFIJO_AUTOMATICO =
  '[AUTOMATICO WHATSAPP BUSINESS';

const conversacion =
  $input.first()?.json ?? {};

const evento =
  $('Normalizar intervención humana')
    .first()
    .json ?? {};

let respuestaRapidaApertura = false;

try {
  respuestaRapidaApertura =
    $('Buscar prospecto intervención humana')
      .first()
      .json
      ?.respuesta_rapida_apertura === true;
} catch (_) {
  respuestaRapidaApertura = false;
}

const automaticoPorApertura =
  evento.intervencion_humana !== false &&
  respuestaRapidaApertura;

const contenidoBase =
  evento.contenido ??
  '[MENSAJE ENVIADO MANUALMENTE]';


const conversacionId =
  Number(
    conversacion.conversacion_id
  );

if (
  !Number.isFinite(conversacionId) ||
  conversacionId <= 0
) {
  throw new Error(
    'MENSAJE HUMANO: conversacion_id inválido.'
  );
}


return [
  {
    json: {

      conversacion_id:
        conversacionId,

      cliente_id:
        conversacion.cliente_id ?? null,

      prospecto_id:
        conversacion.prospecto_id ?? null,

      telefono:
        conversacion.telefono ??
        evento.telefono_cliente ??
        null,

      direccion:
        'SALIENTE',

      tipo:
        evento.tipo ??
        'TEXTO',

      contenido:
        automaticoPorApertura
          ? `${PREFIJO_AUTOMATICO} · accion=NINGUNA · motivo=RESPUESTA_RAPIDA_APERTURA] ${contenidoBase}`
          : contenidoBase,

      mensaje_externo_id:
        evento.mensaje_externo_id ??
        null,

      enviado_at:
        evento.enviado_at ??
        new Date().toISOString(),

      procesado:
        true,

      origen_mensaje:
        automaticoPorApertura
          ? 'AUTOMATICO_WHATSAPP_BUSINESS'
          : evento.origen_mensaje ?? 'HUMANO',

      intervencion_humana:
        evento.intervencion_humana !== false &&
        !automaticoPorApertura,

      respuesta_rapida_apertura:
        automaticoPorApertura

    }
  }
];
